window.FATHOM_ENTITIES = {"a-coruna":{"id":"a-coruna","name":"A Coruña","aliases":["La Coruña","Corunna"],"kind":"place","group":"ports","fact":"A Coruña's Tower of Hercules is the oldest Roman lighthouse still in use, guiding ships on Spain's Atlantic coast."},"abalone":{"id":"abalone","name":"Abalone","aliases":["ormer","paua","ear shell","Haliotis","awabi","sea ear","red abalone"],"kind":"creature","group":"molluscs","fact":"Abalone shells are lined with iridescent mother-of-pearl and have a row of holes through which the animal breathes."},"abidjan":{"id":"abidjan","name":"Abidjan","aliases":[],"kind":"place","group":"ports","fact":"Abidjan, Ivory Coast's economic capital, became a major Atlantic port in the early 1950s when the Vridi Canal was cut through to its lagoon."},"abrolhos-bank":{"id":"abrolhos-bank","name":"Abrolhos Bank","aliases":["Abrolhos","Abrolhos reefs","Abrolhos Archipelago"],"kind":"place","group":"reefs","fact":"The Abrolhos Bank off Brazil holds the largest coral reefs in the South Atlantic, built into mushroom-shaped pillars found nowhere else."},"abyssal-grenadier":{"id":"abyssal-grenadier","name":"Abyssal grenadier","aliases":["Coryphaenoides armatus","armed grenadier"],"kind":"creature","group":"fish","fact":"The abyssal grenadier roams abyssal plains worldwide between about 2,000 and 5,000 metres, following its nose to carcasses that sink from above."},"abyssobrotula":{"id":"abyssobrotula","name":"Abyssobrotula","aliases":["Abyssobrotula galatheae"],"kind":"creature","group":"fish","fact":"Abyssobrotula galatheae is a pale cusk-eel with tiny eyes, recorded from 8,370 metres in the Puerto Rico Trench in 1970, a depth record that stood for decades."},"acanthephyra-shrimp":{"id":"acanthephyra-shrimp","name":"Acanthephyra shrimp","aliases":["Acanthephyra","Acanthephyra purpurea","deep-sea shrimp"],"kind":"creature","group":"crustaceans","fact":"Deep-sea Acanthephyra shrimp are blood-red, which looks black in the depths, and spit a cloud of glowing blue liquid into a predator's face."},"achilles-tang":{"id":"achilles-tang","name":"Achilles tang","aliases":["Achilles surgeonfish","Acanthurus achilles"],"kind":"creature","group":"fish","fact":"The Achilles tang is a black surgeonfish with a teardrop of bright orange around its tail blade, living in the surge zone of Pacific reefs."},"acropora":{"id":"acropora","name":"Acropora","aliases":["Acropora coral"],"kind":"creature","group":"corals","fact":"Acropora is the largest genus of reef-building corals, including the staghorn and table corals, and is among the first to bleach when the water warms."},"adelie-penguin":{"id":"adelie-penguin","name":"Adélie penguin","aliases":["Pygoscelis adeliae"],"kind":"creature","group":"seabirds","fact":"Adélie penguins eat mostly krill, and the pink stains of their guano show up from space, letting scientists count colonies by satellite."},"admiral-graf-spee":{"id":"admiral-graf-spee","name":"Admiral Graf Spee","aliases":["Graf Spee"],"kind":"vessel","group":"wrecks","fact":"The German pocket battleship Admiral Graf Spee was scuttled by its own crew off Montevideo in December 1939 after the Battle of the River Plate."},"adriatic-sea":{"id":"adriatic-sea","name":"Adriatic Sea","aliases":["Adriatic"],"kind":"place","group":"seas","fact":"The Adriatic Sea separates Italy from the Balkans and is the arm of the Mediterranean on which Venice was built."},"adriatic-trout":{"id":"adriatic-trout","name":"Adriatic trout","aliases":["softmouth trout","Salmo obtusirostris"],"kind":"creature","group":"fish","fact":"The Adriatic, or softmouth, trout of the Balkans has a soft fleshy snout unlike any other trout and lives in a few rivers draining to the Adriatic."},"aegean-sea":{"id":"aegean-sea","name":"Aegean Sea","aliases":["Aegean"],"kind":"place","group":"seas","fact":"The Aegean Sea between Greece and Turkey is scattered with hundreds of islands, and its ancient trade routes made it the cradle of Greek civilisation."},"african-lungfish":{"id":"african-lungfish","name":"African lungfish","aliases":["lungfish","Protopterus","marbled lungfish","Protopterus annectens"],"kind":"creature","group":"fish","fact":"When its pool dries up the African lungfish burrows into mud, wraps itself in a mucus cocoon and breathes air for months, even years, until rain returns."},"african-penguin":{"id":"african-penguin","name":"African penguin","aliases":["jackass penguin","Cape penguin","Spheniscus demersus"],"kind":"creature","group":"seabirds","fact":"The African penguin of South Africa and Namibia was declared critically endangered in 2024 as its sardine and anchovy prey dwindled."},"african-sharptooth-catfish":{"id":"african-sharptooth-catfish","name":"African sharptooth catfish","aliases":["sharptooth catfish","African catfish","Clarias gariepinus","North African catfish"],"kind":"creature","group":"fish","fact":"The African sharptooth catfish can breathe air and crawl between pools, and is farmed widely across Africa and Asia as a cheap protein."},"african-tigerfish":{"id":"african-tigerfish","name":"African tigerfish","aliases":["tigerfish","Hydrocynus vittatus"],"kind":"creature","group":"fish","fact":"The African tigerfish has been filmed leaping from the water to snatch swallows out of the air, the first freshwater fish confirmed to catch birds in flight."},"aggregating-anemone":{"id":"aggregating-anemone","name":"Aggregating anemone","aliases":["Anthopleura elegantissima"],"kind":"creature","group":"cnidarians","fact":"Aggregating anemones clone themselves by splitting in two, forming dense carpets where rival clone armies fight along their borders."},"agulhas-current":{"id":"agulhas-current","name":"Agulhas Current","aliases":[],"kind":"place","group":"currents","fact":"The Agulhas Current races south along the east coast of South Africa and, meeting opposing winds, produces some of the world's most dangerous rogue waves."},"akademik-mstislav-keldysh":{"id":"akademik-mstislav-keldysh","name":"Akademik Mstislav Keldysh","aliases":["Keldysh"],"kind":"vessel","group":"vessels","fact":"The Russian research ship Akademik Mstislav Keldysh carries the Mir submersibles and appears as itself in the opening scenes of the film Titanic."},"akagi":{"id":"akagi","name":"Akagi","aliases":["IJN Akagi"],"kind":"vessel","group":"wrecks","fact":"The Japanese carrier Akagi, flagship of the Pearl Harbor attack, was sunk at Midway in 1942 and found in 2019 more than 5,000 metres down."},"akiami-paste-shrimp":{"id":"akiami-paste-shrimp","name":"Akiami paste shrimp","aliases":["Acetes japonicus","Acetes"],"kind":"creature","group":"crustaceans","fact":"The thumbnail-sized Akiami paste shrimp is caught in bigger tonnages than any other shrimp species, mostly for shrimp paste and dried shrimp in Asia."},"alaska-current":{"id":"alaska-current","name":"Alaska Current","aliases":[],"kind":"place","group":"currents","fact":"The Alaska Current carries relatively warm water anticlockwise around the Gulf of Alaska, keeping the coast of the Alaska panhandle milder and wetter."},"alaska-pollock":{"id":"alaska-pollock","name":"Alaska pollock","aliases":["pollock","walleye pollock","Alaskan pollock","Gadus chalcogrammus","Theragra chalcogramma"],"kind":"creature","group":"fish","fact":"Alaska pollock is the most-caught fish in the United States and the fish inside most fish fingers, fast-food fish sandwiches and surimi crab sticks."},"albacore":{"id":"albacore","name":"Albacore","aliases":["white tuna","Thunnus alalunga","longfin tuna","tombo","albacore tuna"],"kind":"creature","group":"fish","fact":"Albacore, the 'white tuna' of canned tuna, has the longest pectoral fins of any tuna and is served as shiro maguro in sushi bars."},"albatross":{"id":"albatross","name":"Albatross","aliases":[],"kind":"creature","group":"seabirds","fact":"Albatrosses lock their wings open with a special shoulder tendon and can glide for hours over the ocean without a single flap."},"alboran-sea":{"id":"alboran-sea","name":"Alboran Sea","aliases":[],"kind":"place","group":"seas","fact":"The Alboran Sea is the westernmost part of the Mediterranean, just inside the Strait of Gibraltar, where Atlantic water first flows in."},"aldabra-atoll":{"id":"aldabra-atoll","name":"Aldabra Atoll","aliases":["Aldabra"],"kind":"place","group":"reefs","fact":"Aldabra Atoll in the Seychelles is one of the largest raised coral atolls in the world and home to about 100,000 giant tortoises."},"aleutian-islands":{"id":"aleutian-islands","name":"Aleutian Islands","aliases":["Aleutians","Unalaska","Attu"],"kind":"place","group":"islands","fact":"The Aleutian Islands are a chain of volcanic islands stretching about 1,900 kilometres west from Alaska towards Russia."},"aleutian-trench":{"id":"aleutian-trench","name":"Aleutian Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Aleutian Trench curves for about 3,400 kilometres south of Alaska's Aleutian Islands and reaches more than 7,600 metres deep."},"alewife":{"id":"alewife","name":"Alewife","aliases":["gaspereau","Alosa pseudoharengus"],"kind":"creature","group":"fish","fact":"The alewife is a small herring that migrates from the sea into rivers to spawn, and landlocked populations invaded the Great Lakes through canals."},"algae-octopus":{"id":"algae-octopus","name":"Algae octopus","aliases":["Abdopus aculeatus"],"kind":"creature","group":"cephalopods","fact":"The algae octopus disguises itself as a shell overgrown with weed and can walk away on two arms while holding the other six in a ball."},"aliwal-shoal":{"id":"aliwal-shoal","name":"Aliwal Shoal","aliases":[],"kind":"place","group":"divesites","fact":"Aliwal Shoal off South Africa's KwaZulu-Natal coast is famous for baited dives with tiger sharks and the winter gathering of ragged-tooth sharks."},"allards-clownfish":{"id":"allards-clownfish","name":"Allard's clownfish","aliases":["Allard's anemonefish","Amphiprion allardi","twobar anemonefish"],"kind":"creature","group":"fish","fact":"Allard's clownfish is a dark anemonefish with two white bars and a yellow tail found only off East Africa, from Kenya to South Africa."},"alligator-gar":{"id":"alligator-gar","name":"Alligator gar","aliases":["Atractosteus spatula","gar"],"kind":"creature","group":"fish","fact":"The alligator gar can grow well over 2 metres long and gulps air at the surface through a swim bladder that works like a lung."},"alligator-pipefish":{"id":"alligator-pipefish","name":"Alligator pipefish","aliases":["double-ended pipefish","Syngnathoides biaculeatus"],"kind":"creature","group":"fish","fact":"The alligator pipefish drifts among seagrass and floating weed in the Indo-Pacific and has a prehensile tail with no tail fin at all."},"alvin":{"id":"alvin","name":"Alvin","aliases":["DSV Alvin"],"kind":"vessel","group":"submersibles","fact":"Alvin is the US deep-diving submersible that explored the wreck of the Titanic in 1986 and found the first hydrothermal vent communities in 1977."},"alvinocaris-shrimp":{"id":"alvinocaris-shrimp","name":"Alvinocaris shrimp","aliases":["Alvinocaris","Alvinocaris lusca"],"kind":"creature","group":"crustaceans","fact":"Alvinocaris shrimp were among the first animals described from the Galápagos Rift vents after their discovery in 1977, scavenging among tube worms and clams."},"amazon-reef":{"id":"amazon-reef","name":"Amazon Reef","aliases":[],"kind":"place","group":"reefs","fact":"The Amazon Reef was only fully described in 2016, a reef system hidden under the muddy plume of the Amazon River where few thought reefs could grow."},"amazon-river-dolphin":{"id":"amazon-river-dolphin","name":"Amazon river dolphin","aliases":["boto","pink river dolphin","Amazon dolphin","bufeo","Inia geoffrensis"],"kind":"creature","group":"dolphins","fact":"The Amazon river dolphin turns pink with age and has an unfused neck that lets it turn its head to hunt among flooded trees."},"american-bullfrog":{"id":"american-bullfrog","name":"American bullfrog","aliases":["bullfrog","Lithobates catesbeianus"],"kind":"creature","group":"amphibians","fact":"The American bullfrog, farmed for frogs' legs, has invaded ponds across Europe, Asia and the western USA, eating anything that fits in its mouth."},"american-crocodile":{"id":"american-crocodile","name":"American crocodile","aliases":["Crocodylus acutus"],"kind":"creature","group":"reptiles","fact":"American crocodiles live in coastal mangroves and lagoons from Florida to Peru and have salt glands that let them tolerate the sea."},"american-eel":{"id":"american-eel","name":"American eel","aliases":["Anguilla rostrata"],"kind":"creature","group":"fish","fact":"The American eel grows up in rivers from Greenland to Brazil and returns to the Sargasso Sea to spawn, like its European cousin."},"american-lobster":{"id":"american-lobster","name":"American lobster","aliases":["Maine lobster","Homarus americanus","Canadian lobster","northern lobster","Atlantic lobster"],"kind":"creature","group":"crustaceans","fact":"The American lobster is the heaviest crustacean ever recorded, with a 20-kilogram giant caught off Nova Scotia in 1977."},"american-plaice":{"id":"american-plaice","name":"American plaice","aliases":["Hippoglossoides platessoides","long rough dab","Canadian plaice"],"kind":"creature","group":"fish","fact":"The American plaice, called the long rough dab in Europe, is a cold-water flatfish with a large mouth that lives on both sides of the North Atlantic."},"american-shad":{"id":"american-shad","name":"American shad","aliases":["shad","Alosa sapidissima"],"kind":"creature","group":"fish","fact":"American shad live at sea and surge up east-coast rivers each spring to spawn, and the shad is the official state fish of Connecticut."},"ammonite":{"id":"ammonite","name":"Ammonite","aliases":["ammonoid"],"kind":"creature","group":"cephalopods","fact":"Ammonites were coiled-shelled relatives of squid that filled the seas for over 300 million years and vanished with the dinosaurs."},"amphipod":{"id":"amphipod","name":"Amphipod","aliases":["hadal amphipod","scavenging amphipod"],"kind":"creature","group":"crustaceans","fact":"Scavenging amphipods swarm onto any bait lowered to the floor of the Mariana Trench within minutes, even at the very bottom of the Challenger Deep."},"amundsen-sea":{"id":"amundsen-sea","name":"Amundsen Sea","aliases":[],"kind":"place","group":"seas","fact":"The Amundsen Sea off West Antarctica is named after the Norwegian explorer Roald Amundsen and is where the fast-melting Thwaites Glacier flows into the sea."},"anchovy":{"id":"anchovy","name":"Anchovy","aliases":["European anchovy","Peruvian anchoveta","anchoveta","Engraulis","Engraulis encrasicolus"],"kind":"creature","group":"fish","fact":"Anchovies swim with their mouths wide open to sieve plankton with their gill rakers, and the Peruvian anchoveta is the most heavily fished species on Earth."},"andrea-doria":{"id":"andrea-doria","name":"Andrea Doria","aliases":["SS Andrea Doria"],"kind":"vessel","group":"wrecks","fact":"The Italian liner Andrea Doria sank in 1956 after colliding with the Stockholm off Nantucket, and its wreck at about 73 metres is called the Mount Everest of wreck diving."},"andrews-beaked-whale":{"id":"andrews-beaked-whale","name":"Andrews' beaked whale","aliases":["Andrews's beaked whale","Bowdoin's beaked whale","Mesoplodon bowdoini"],"kind":"creature","group":"whales","fact":"Andrews' beaked whale is known almost entirely from strandings in Australia and New Zealand and is named after explorer Roy Chapman Andrews."},"andros-barrier-reef":{"id":"andros-barrier-reef","name":"Andros Barrier Reef","aliases":["Andros Reef","Andros Island reef"],"kind":"place","group":"reefs","fact":"The Andros Barrier Reef in the Bahamas runs about 190 kilometres and drops away into the Tongue of the Ocean, a deep ocean trench."},"anemone-porcelain-crab":{"id":"anemone-porcelain-crab","name":"Anemone porcelain crab","aliases":["spotted porcelain crab","Neopetrolisthes maculatus"],"kind":"creature","group":"crustaceans","fact":"The spotted porcelain crab lives among the tentacles of large sea anemones, filtering plankton from the water with its feathery mouthparts."},"anemone-shrimp":{"id":"anemone-shrimp","name":"Anemone shrimp","aliases":["glass anemone shrimp","Periclimenes brevicarpalis","peacock-tail anemone shrimp","sexy shrimp","Thor amboinensis","Periclimenes"],"kind":"creature","group":"crustaceans","fact":"The glass anemone shrimp is transparent apart from a few white and orange spots, and lives unharmed among the stinging tentacles of its host anemone."},"angel-shark":{"id":"angel-shark","name":"Angel shark","aliases":["angelshark","Squatina","Squatina squatina","monkfish shark"],"kind":"creature","group":"sharks","fact":"The angel shark is a flattened ambush predator that buries itself in sand for days, then snaps up passing fish in a tenth of a second."},"angelfish":{"id":"angelfish","name":"Angelfish","aliases":["marine angelfish","Pomacanthidae"],"kind":"creature","group":"fish","fact":"Marine angelfish are among the most colourful reef fish, and many change their pattern completely as they grow from juvenile to adult."},"anglerfish":{"id":"anglerfish","name":"Anglerfish","aliases":["angler fish","deep-sea anglerfish","sea devil","black seadevil","angler"],"kind":"creature","group":"fish","fact":"The female deep-sea anglerfish dangles a glowing lure of bacteria in front of her mouth, and in some species the tiny male fuses onto her body for life."},"angular-roughshark":{"id":"angular-roughshark","name":"Angular roughshark","aliases":["angular rough shark","Oxynotus centrina"],"kind":"creature","group":"sharks","fact":"The angular roughshark has tall sail-like dorsal fins and a stocky, triangular body, and lives on muddy slopes down to around 700 metres."},"annulated-sea-snake":{"id":"annulated-sea-snake","name":"Annulated sea snake","aliases":["blue-banded sea snake","Hydrophis cyanocinctus"],"kind":"creature","group":"reptiles","fact":"The annulated sea snake can take in oxygen through a network of blood vessels on top of its head, which works a little like a snorkel."},"anomalocaris":{"id":"anomalocaris","name":"Anomalocaris","aliases":[],"kind":"creature","group":"arthropods","fact":"Anomalocaris was the top predator of the Cambrian seas about 500 million years ago, a metre-long hunter with grasping front limbs and a circular mouth."},"antarctic-circumpolar-current":{"id":"antarctic-circumpolar-current","name":"Antarctic Circumpolar Current","aliases":["ACC","West Wind Drift","Circumpolar Current"],"kind":"place","group":"currents","fact":"The Antarctic Circumpolar Current circles the whole of Antarctica unbroken by land and is the largest ocean current on Earth, carrying more water than any other."},"antarctic-fur-seal":{"id":"antarctic-fur-seal","name":"Antarctic fur seal","aliases":["Kerguelen fur seal","Arctocephalus gazella"],"kind":"creature","group":"seals","fact":"Antarctic fur seals were nearly wiped out by 19th-century sealers but now breed by the millions on South Georgia."},"antarctic-minke-whale":{"id":"antarctic-minke-whale","name":"Antarctic minke whale","aliases":["southern minke whale","Balaenoptera bonaerensis","minke whale","minke"],"kind":"creature","group":"whales","fact":"Antarctic minke whales live among the pack ice and were the main target of Japan's so-called scientific whaling in the Southern Ocean."},"antarctic-petrel":{"id":"antarctic-petrel","name":"Antarctic petrel","aliases":["Thalassoica antarctica"],"kind":"creature","group":"seabirds","fact":"The Antarctic petrel breeds in huge colonies on inland Antarctic mountains, some about 200 kilometres from the open sea."},"antarctic-prion":{"id":"antarctic-prion","name":"Antarctic prion","aliases":["Pachyptila desolata","whalebird","dove prion"],"kind":"creature","group":"seabirds","fact":"The Antarctic prion filters krill through comb-like plates in its bill, like a tiny flying baleen whale, which is why sailors called prions whalebirds."},"antarctic-silverfish":{"id":"antarctic-silverfish","name":"Antarctic silverfish","aliases":["Pleuragramma antarctica","Pleuragramma"],"kind":"creature","group":"fish","fact":"The Antarctic silverfish is the key fish of the Antarctic food web, eating krill and copepods and in turn feeding penguins, seals and toothfish."},"antarctic-toothfish":{"id":"antarctic-toothfish","name":"Antarctic toothfish","aliases":["Dissostichus mawsoni"],"kind":"creature","group":"fish","fact":"The Antarctic toothfish grows to 2 metres in the Ross Sea, and its blood carries antifreeze proteins that stop ice crystals forming."},"anthias":{"id":"anthias","name":"Anthias","aliases":["sea goldie","lyretail anthias","scalefin anthias","Pseudanthias squamipinnis"],"kind":"creature","group":"fish","fact":"Anthias are the small orange fish that shimmer in clouds above Indo-Pacific reefs, each male guarding a harem of females."},"antilles-current":{"id":"antilles-current","name":"Antilles Current","aliases":[],"kind":"place","group":"currents","fact":"The Antilles Current flows north-west along the outer edge of the Caribbean islands and joins the Florida Current to form the Gulf Stream."},"apache-trout":{"id":"apache-trout","name":"Apache trout","aliases":["Arizona trout","Oncorhynchus apache"],"kind":"creature","group":"fish","fact":"The Apache trout is found only in the White Mountains of Arizona and is the official state fish of Arizona."},"apo-reef":{"id":"apo-reef","name":"Apo Reef","aliases":[],"kind":"place","group":"reefs","fact":"Apo Reef off Mindoro in the Philippines is the largest atoll-like reef in the country and is often described as the second-largest contiguous coral reef in the world."},"ara-san-juan":{"id":"ara-san-juan","name":"ARA San Juan","aliases":["San Juan","San Juan submarine"],"kind":"vessel","group":"wrecks","fact":"The Argentine submarine ARA San Juan vanished in November 2017 with 44 crew and was found a year later about 900 metres down in the South Atlantic."},"arabian-picasso-triggerfish":{"id":"arabian-picasso-triggerfish","name":"Arabian Picasso triggerfish","aliases":["Assasi triggerfish","Rhinecanthus assasi"],"kind":"creature","group":"fish","fact":"The Arabian Picasso triggerfish, with its painted-on stripes, is found only in the Red Sea and the seas around Arabia."},"araguaian-river-dolphin":{"id":"araguaian-river-dolphin","name":"Araguaian river dolphin","aliases":["Araguaian boto","Inia araguaiaensis"],"kind":"creature","group":"dolphins","fact":"The Araguaian river dolphin of Brazil was described in 2014, the first new river dolphin species recognised in almost a century."},"arapaima":{"id":"arapaima","name":"Arapaima","aliases":["pirarucu","paiche","Arapaima gigas"],"kind":"creature","group":"fish","fact":"The arapaima of the Amazon must surface regularly to gulp air and has been verified at just over 3 metres long."},"archelon":{"id":"archelon","name":"Archelon","aliases":[],"kind":"creature","group":"turtles","fact":"Archelon was the largest turtle ever, about 4 metres long, and swam the inland sea of Cretaceous North America."},"archerfish":{"id":"archerfish","name":"Archerfish","aliases":["archer fish","Toxotes"],"kind":"creature","group":"fish","fact":"Archerfish shoot down insects with a jet of water spat from the mouth, correcting for the bending of light at the surface, and will also leap out to grab prey."},"archimede":{"id":"archimede","name":"Archimède","aliases":["Bathyscaphe Archimède"],"kind":"vessel","group":"submersibles","fact":"The French bathyscaphe Archimède dived to about 9,500 metres in the Kuril Trench in 1962 and later explored the Mid-Atlantic Ridge in Project FAMOUS."},"arctic-char":{"id":"arctic-char","name":"Arctic char","aliases":["Arctic charr","char","charr","Salvelinus alpinus"],"kind":"creature","group":"fish","fact":"Arctic char live further north than any other freshwater fish, and sea-run char feed in Arctic coastal waters each summer."},"arctic-cod":{"id":"arctic-cod","name":"Arctic cod","aliases":["polar cod","Boreogadus saida"],"kind":"creature","group":"fish","fact":"Arctic cod carry antifreeze proteins in their blood and live right under the sea ice, feeding seals, whales and seabirds."},"arctic-skate":{"id":"arctic-skate","name":"Arctic skate","aliases":["Amblyraja hyperborea"],"kind":"creature","group":"rays","fact":"The Arctic skate lives on deep, cold seabeds across the Arctic basin and lays its eggs in tough leathery cases."},"arctic-tern":{"id":"arctic-tern","name":"Arctic tern","aliases":["Sterna paradisaea"],"kind":"creature","group":"seabirds","fact":"The Arctic tern flies from the Arctic to the Antarctic and back each year, the longest migration of any animal, around 70,000 kilometres or more."},"argentine-hake":{"id":"argentine-hake","name":"Argentine hake","aliases":["Merluccius hubbsi"],"kind":"creature","group":"fish","fact":"The Argentine hake is the most important fish of Argentina's fisheries, trawled over the Patagonian shelf."},"argentine-shortfin-squid":{"id":"argentine-shortfin-squid","name":"Argentine shortfin squid","aliases":["Illex argentinus","Argentine squid"],"kind":"creature","group":"cephalopods","fact":"Hundreds of jigging boats light up the night off Argentina to catch this squid, one of the most heavily fished squid species on Earth."},"argonaut":{"id":"argonaut","name":"Argonaut","aliases":["paper nautilus","Argonauta","Argonauta argo","greater argonaut"],"kind":"creature","group":"cephalopods","fact":"The female argonaut, an octopus, secretes a thin, papery shell that she uses as a floating egg case and buoyancy aid."},"arnouxs-beaked-whale":{"id":"arnouxs-beaked-whale","name":"Arnoux's beaked whale","aliases":["southern four-toothed whale","Berardius arnuxii"],"kind":"creature","group":"whales","fact":"Arnoux's beaked whale lives in the cold Southern Ocean and has been seen diving beneath Antarctic sea ice."},"arowana":{"id":"arowana","name":"Arowana","aliases":["aruana","Asian arowana","silver arowana","dragon fish","Osteoglossum bicirrhosum"],"kind":"creature","group":"fish","fact":"Arowanas can breathe air using their swim bladder and are famous for leaping out of the water to snatch insects from overhanging branches."},"arrow-crab":{"id":"arrow-crab","name":"Arrow crab","aliases":["yellowline arrow crab","Stenorhynchus seticornis"],"kind":"creature","group":"crustaceans","fact":"The arrow crab of Caribbean reefs has spindly legs and a pointed head, and is kept in aquariums to eat bristle worms."},"arrow-worm":{"id":"arrow-worm","name":"Arrow worm","aliases":["chaetognath","Sagitta","Chaetognatha"],"kind":"creature","group":"worms","fact":"Arrow worms are glassy, torpedo-shaped predators of the plankton that grab copepods with hooked spines and a venom like that of pufferfish."},"arrowtooth-flounder":{"id":"arrowtooth-flounder","name":"Arrowtooth flounder","aliases":["Atheresthes stomias"],"kind":"creature","group":"fish","fact":"The arrowtooth flounder is the most abundant groundfish in the Gulf of Alaska, but an enzyme turns its flesh to mush when cooked, so it was long discarded."},"ascension-island":{"id":"ascension-island","name":"Ascension Island","aliases":["Ascension"],"kind":"place","group":"islands","fact":"Ascension Island is a volcanic island in the mid-Atlantic to which green turtles swim about 2,000 kilometres from Brazil to nest on its beaches."},"asian-carp":{"id":"asian-carp","name":"Asian carp","aliases":[],"kind":"creature","group":"fish","fact":"Asian carp, a group of imported Chinese carp species, have overrun the Mississippi basin, and electric barriers try to keep them out of the Great Lakes."},"asian-clam":{"id":"asian-clam","name":"Asian clam","aliases":["Corbicula fluminea","Corbicula"],"kind":"creature","group":"molluscs","fact":"The Asian clam has spread through rivers across North America, South America and Europe and fouls the cooling systems of power stations."},"asian-shore-crab":{"id":"asian-shore-crab","name":"Asian shore crab","aliases":["Japanese shore crab","Hemigrapsus sanguineus"],"kind":"creature","group":"crustaceans","fact":"The Asian shore crab turned up in New Jersey in 1988 and is now the most common crab on many rocky shores from Maine to North Carolina."},"asian-tiger-shrimp":{"id":"asian-tiger-shrimp","name":"Asian tiger shrimp","aliases":["giant tiger prawn","black tiger shrimp","Penaeus monodon"],"kind":"creature","group":"crustaceans","fact":"The Asian tiger shrimp, a farmed prawn up to 30 centimetres long, has escaped into the Gulf of Mexico and the south-eastern US coast."},"atlantic-blue-tang":{"id":"atlantic-blue-tang","name":"Atlantic blue tang","aliases":["Acanthurus coeruleus","blue tang surgeonfish","blue doctorfish"],"kind":"creature","group":"fish","fact":"The Atlantic blue tang is a Caribbean surgeonfish that is bright yellow as a juvenile and turns deep blue as it grows."},"atlantic-bonito":{"id":"atlantic-bonito","name":"Atlantic bonito","aliases":["Sarda sarda","palamut"],"kind":"creature","group":"fish","fact":"The Atlantic bonito is a fast, striped, tuna-like schooling fish of the Atlantic and Mediterranean, eaten salted or grilled in Turkey as palamut."},"atlantic-croaker":{"id":"atlantic-croaker","name":"Atlantic croaker","aliases":["croaker","Micropogonias undulatus"],"kind":"creature","group":"fish","fact":"The Atlantic croaker croaks by rapidly contracting muscles against its swim bladder, loudly enough to be heard when it is hauled into a boat."},"atlantic-halibut":{"id":"atlantic-halibut","name":"Atlantic halibut","aliases":["Hippoglossus hippoglossus"],"kind":"creature","group":"fish","fact":"Atlantic halibut can live for 50 years and females take about 10 years to mature, so the species is easily overfished."},"atlantic-horse-mackerel":{"id":"atlantic-horse-mackerel","name":"Atlantic horse mackerel","aliases":["horse mackerel","Trachurus trachurus"],"kind":"creature","group":"fish","fact":"The Atlantic horse mackerel is a schooling jack of the North Sea and eastern Atlantic with a line of bony scutes along its side."},"atlantic-humpback-dolphin":{"id":"atlantic-humpback-dolphin","name":"Atlantic humpback dolphin","aliases":["Sousa teuszii"],"kind":"creature","group":"dolphins","fact":"The Atlantic humpback dolphin lives in estuaries and shallow coasts of West Africa and is critically endangered, with fewer than 3,000 left."},"atlantic-mackerel":{"id":"atlantic-mackerel","name":"Atlantic mackerel","aliases":["Scomber scombrus","mackerel","Boston mackerel"],"kind":"creature","group":"fish","fact":"Atlantic mackerel feed on copepods and krill as they swim constantly to breathe, and are the species the British fleet catches in the largest quantity."},"atlantic-puffin":{"id":"atlantic-puffin","name":"Atlantic puffin","aliases":["puffin","common puffin","sea parrot","Fratercula arctica"],"kind":"creature","group":"seabirds","fact":"Atlantic puffins can carry a dozen or more small fish crosswise in their beaks at once and spend the winter alone far out at sea."},"atlantic-pygmy-octopus":{"id":"atlantic-pygmy-octopus","name":"Atlantic pygmy octopus","aliases":["Octopus joubini"],"kind":"creature","group":"cephalopods","fact":"The Atlantic pygmy octopus is small enough to live inside an empty clam shell, which it pulls shut around itself with its suckers."},"atlantic-salmon":{"id":"atlantic-salmon","name":"Atlantic salmon","aliases":["Salmo salar"],"kind":"creature","group":"fish","fact":"Atlantic salmon return from the sea to the river where they hatched, and unlike Pacific salmon some survive spawning and go back to sea to spawn again."},"atlantic-sharpnose-shark":{"id":"atlantic-sharpnose-shark","name":"Atlantic sharpnose shark","aliases":["Rhizoprionodon terraenovae"],"kind":"creature","group":"sharks","fact":"The Atlantic sharpnose shark is a small, common shark of the US Atlantic and Gulf coasts, often the first shark a beach angler catches."},"atlantic-silverside":{"id":"atlantic-silverside","name":"Atlantic silverside","aliases":["silverside","Menidia menidia"],"kind":"creature","group":"fish","fact":"The Atlantic silverside is a small schooling fish of US Atlantic estuaries whose sex is decided by the water temperature its eggs develop in."},"atlantic-spotted-dolphin":{"id":"atlantic-spotted-dolphin","name":"Atlantic spotted dolphin","aliases":["Stenella frontalis"],"kind":"creature","group":"dolphins","fact":"Atlantic spotted dolphins are born spotless and gain more spots with age, and the Bahamas population has been studied for over 30 years."},"atlantic-stingray":{"id":"atlantic-stingray","name":"Atlantic stingray","aliases":["Hypanus sabinus","Dasyatis sabina"],"kind":"creature","group":"rays","fact":"The Atlantic stingray tolerates fresh water and has a permanent population in Florida's St Johns River."},"atlantic-sturgeon":{"id":"atlantic-sturgeon","name":"Atlantic sturgeon","aliases":["Acipenser oxyrinchus"],"kind":"creature","group":"fish","fact":"The Atlantic sturgeon lives in coastal seas and swims up rivers to spawn, and in the past grew to more than 4 metres long."},"atlantic-thread-herring":{"id":"atlantic-thread-herring","name":"Atlantic thread herring","aliases":["thread herring","Opisthonema oglinum"],"kind":"creature","group":"fish","fact":"The Atlantic thread herring, named for a long trailing ray on its dorsal fin, schools along the Gulf of Mexico coast and is netted for bait."},"atlantic-tomcod":{"id":"atlantic-tomcod","name":"Atlantic tomcod","aliases":["tomcod","Microgadus tomcod","frostfish"],"kind":"creature","group":"fish","fact":"The Atlantic tomcod is a small cod of North American estuaries; those in the Hudson River evolved resistance to PCB pollution in just a few decades."},"atlantic-torpedo":{"id":"atlantic-torpedo","name":"Atlantic torpedo","aliases":["Atlantic torpedo ray","great torpedo ray","Tetronarce nobiliana","Torpedo nobiliana"],"kind":"creature","group":"rays","fact":"The Atlantic torpedo is the largest electric ray, up to about 1.8 metres and 90 kilograms, and delivers shocks of around 220 volts."},"atlantic-white-sided-dolphin":{"id":"atlantic-white-sided-dolphin","name":"Atlantic white-sided dolphin","aliases":["Lagenorhynchus acutus"],"kind":"creature","group":"dolphins","fact":"The Atlantic white-sided dolphin has a bold yellow-ochre streak on its tail stock and lives in cool North Atlantic waters."},"atlantis":{"id":"atlantis","name":"Atlantis","aliases":["RV Atlantis","R/V Atlantis"],"kind":"vessel","group":"vessels","fact":"Atlantis is the Woods Hole research ship that serves as the mothership for the submersible Alvin."},"auguste-piccard":{"id":"auguste-piccard","name":"Auguste Piccard","aliases":[],"kind":"person","group":"people","fact":"Auguste Piccard invented the bathyscaphe, a free-diving deep submersible, after first setting altitude records in a stratospheric balloon."},"australian-humpback-dolphin":{"id":"australian-humpback-dolphin","name":"Australian humpback dolphin","aliases":["Sousa sahulensis"],"kind":"creature","group":"dolphins","fact":"The Australian humpback dolphin was described in 2014 and lives in shallow coastal waters and estuaries of northern Australia and New Guinea."},"australian-lungfish":{"id":"australian-lungfish","name":"Australian lungfish","aliases":["Queensland lungfish","Neoceratodus forsteri"],"kind":"creature","group":"fish","fact":"The Australian lungfish has a single lung and surfaces to gulp air when its river water runs low in oxygen."},"australian-sea-lion":{"id":"australian-sea-lion","name":"Australian sea lion","aliases":["Neophoca cinerea"],"kind":"creature","group":"seals","fact":"The Australian sea lion is one of the rarest sea lions and has an unusual 17- to 18-month breeding cycle."},"australian-snubfin-dolphin":{"id":"australian-snubfin-dolphin","name":"Australian snubfin dolphin","aliases":["snubfin dolphin","Orcaella heinsohni"],"kind":"creature","group":"dolphins","fact":"The Australian snubfin dolphin was only recognised as a species in 2005 and spits water to herd fish in northern Australia's estuaries."},"ayu":{"id":"ayu","name":"Ayu","aliases":["sweetfish","Plecoglossus altivelis"],"kind":"creature","group":"fish","fact":"The ayu, or sweetfish, hatches in Japanese rivers, spends the winter at sea, and returns to the river to graze algae from the rocks."},"azores":{"id":"azores","name":"Azores","aliases":["Açores","São Miguel","Pico","Terceira","Faial"],"kind":"place","group":"islands","fact":"The Azores are nine volcanic Portuguese islands in the mid-Atlantic, about 1,500 kilometres west of Lisbon, and a famous whale-watching spot."},"bab-el-mandeb":{"id":"bab-el-mandeb","name":"Bab-el-Mandeb","aliases":["Bab al-Mandab","Mandeb Strait","Gate of Tears","Gate of Grief"],"kind":"place","group":"straits","fact":"The Bab-el-Mandeb, whose name means Gate of Tears, joins the Red Sea to the Gulf of Aden between Yemen and Djibouti."},"baffin-bay":{"id":"baffin-bay","name":"Baffin Bay","aliases":[],"kind":"place","group":"bays","fact":"Baffin Bay between Greenland and Baffin Island is named after William Baffin, the English navigator who explored it in 1616."},"bahamas":{"id":"bahamas","name":"Bahamas","aliases":["Bahama Islands","Andros","Eleuthera","Grand Bahama","Bimini","Exumas"],"kind":"place","group":"islands","fact":"The Bahamas are about 700 islands and cays on shallow banks in the Atlantic, where Columbus made his first landfall in 1492."},"baiji":{"id":"baiji","name":"Baiji","aliases":["Yangtze river dolphin","Chinese river dolphin","white-fin dolphin","Yangtze dolphin","Lipotes vexillifer"],"kind":"creature","group":"dolphins","fact":"The baiji of the Yangtze was declared functionally extinct in 2006 after a survey failed to find a single animal."},"baikal-seal":{"id":"baikal-seal","name":"Baikal seal","aliases":["nerpa","Pusa sibirica"],"kind":"creature","group":"seals","fact":"The Baikal seal lives only in Lake Baikal in Siberia and is the only seal that spends its whole life in fresh water."},"bairds-beaked-whale":{"id":"bairds-beaked-whale","name":"Baird's beaked whale","aliases":["giant beaked whale","Berardius bairdii"],"kind":"creature","group":"whales","fact":"Baird's beaked whale is the largest beaked whale, up to about 13 metres, and is still hunted off Japan in small numbers."},"bald-eagle":{"id":"bald-eagle","name":"Bald eagle","aliases":["Haliaeetus leucocephalus"],"kind":"creature","group":"birds","fact":"Bald eagles snatch fish from the surface with their talons and gather by the hundred on Alaskan coasts when salmon and herring run."},"balearic-sea":{"id":"balearic-sea","name":"Balearic Sea","aliases":[],"kind":"place","group":"seas","fact":"The Balearic Sea lies between the east coast of Spain and the Balearic Islands of Majorca, Minorca and Ibiza."},"baleen-whale":{"id":"baleen-whale","name":"Baleen whale","aliases":["mysticete"],"kind":"creature","group":"whales","fact":"Baleen whales have no teeth; instead they strain krill and small fish from mouthfuls of water through fringed plates of baleen."},"ballan-wrasse":{"id":"ballan-wrasse","name":"Ballan wrasse","aliases":["Labrus bergylta"],"kind":"creature","group":"fish","fact":"The ballan wrasse is the largest wrasse in British waters, used in salmon farms to eat sea lice off the salmon."},"baltic-sea":{"id":"baltic-sea","name":"Baltic Sea","aliases":["Baltic"],"kind":"place","group":"seas","fact":"The Baltic Sea is a brackish arm of the Atlantic so diluted by rivers that parts of it freeze over every winter."},"bamboo-coral":{"id":"bamboo-coral","name":"Bamboo coral","aliases":["Isididae"],"kind":"creature","group":"corals","fact":"Bamboo corals of the deep sea have skeletons of limestone segments joined by dark, flexible nodes, like a bamboo stem."},"bamboo-shark":{"id":"bamboo-shark","name":"Bamboo shark","aliases":["bamboo catshark","whitespotted bamboo shark","Chiloscyllium"],"kind":"creature","group":"sharks","fact":"Bamboo sharks are small, slender reef sharks that lay eggs, and their egg cases are a staple of public and home aquariums."},"banda-sea":{"id":"banda-sea","name":"Banda Sea","aliases":[],"kind":"place","group":"seas","fact":"The Banda Sea in eastern Indonesia is a deep basin surrounding the Banda Islands, the original source of nutmeg and mace."},"banded-coral-shrimp":{"id":"banded-coral-shrimp","name":"Banded coral shrimp","aliases":["coral banded shrimp","Stenopus hispidus","banded cleaner shrimp","barber pole shrimp"],"kind":"creature","group":"crustaceans","fact":"The banded coral shrimp waves long white antennae from reef crevices to attract fish, which it then cleans of parasites."},"banded-pipefish":{"id":"banded-pipefish","name":"Banded pipefish","aliases":["ringed pipefish","Dunckerocampus dactyliophorus"],"kind":"creature","group":"fish","fact":"The banded pipefish has red and white rings and a paddle-shaped tail, and pairs of them work as cleaner fish on Indo-Pacific reefs."},"banded-sea-krait":{"id":"banded-sea-krait","name":"Banded sea krait","aliases":["yellow-lipped sea krait","colubrine sea krait","Laticauda colubrina"],"kind":"creature","group":"reptiles","fact":"Banded sea kraits hunt eels on reefs but return to land to digest their meals, shed their skins and lay eggs."},"banggai-cardinalfish":{"id":"banggai-cardinalfish","name":"Banggai cardinalfish","aliases":["Pterapogon kauderni"],"kind":"creature","group":"fish","fact":"The male Banggai cardinalfish broods the eggs and then the hatched young in his mouth for weeks, so the species never has a drifting larval stage."},"banjo-catfish":{"id":"banjo-catfish","name":"Banjo catfish","aliases":["Bunocephalus","Aspredinidae","Bunocephalus coracoideus"],"kind":"creature","group":"fish","fact":"The banjo catfish is a flat, lumpy South American catfish shaped like a banjo that lies buried in sand and leaf litter by day."},"bar-tailed-godwit":{"id":"bar-tailed-godwit","name":"Bar-tailed godwit","aliases":["godwit","Limosa lapponica"],"kind":"creature","group":"shorebirds","fact":"In 2022 a young bar-tailed godwit flew non-stop from Alaska to Tasmania, 13,560 kilometres in 11 days, the longest non-stop flight ever recorded for a bird."},"barbel":{"id":"barbel","name":"Barbel","aliases":["Barbus barbus"],"kind":"creature","group":"fish","fact":"The barbel is a bottom-feeding fish of fast European rivers, named for the four whiskers around its mouth."},"barents-sea":{"id":"barents-sea","name":"Barents Sea","aliases":[],"kind":"place","group":"seas","fact":"The Barents Sea north of Norway and Russia is named after the Dutch navigator Willem Barentsz, who died there in 1597 after wintering on Novaya Zemlya."},"bargibants-pygmy-seahorse":{"id":"bargibants-pygmy-seahorse","name":"Bargibant's pygmy seahorse","aliases":["Hippocampus bargibanti","Bargibant's seahorse","pygmy seahorse"],"kind":"creature","group":"fish","fact":"Bargibant's pygmy seahorse grows to about 2 centimetres and lives only on Muricella sea fans, matching their colour and knobbly texture so well it was found by accident in 1969."},"barnacle":{"id":"barnacle","name":"Barnacle","aliases":["acorn barnacle","goose barnacle","gooseneck barnacle"],"kind":"creature","group":"crustaceans","fact":"Barnacles are crustaceans, relatives of crabs, that glue their heads to rocks and build limestone shells around themselves."},"barndoor-skate":{"id":"barndoor-skate","name":"Barndoor skate","aliases":["Dipturus laevis"],"kind":"creature","group":"rays","fact":"The barndoor skate is one of the largest skates of the north-west Atlantic, reaching 1.5 metres, and was nearly wiped out as bycatch."},"barracuda":{"id":"barracuda","name":"Barracuda","aliases":["great barracuda","Sphyraena barracuda","Sphyraena"],"kind":"creature","group":"fish","fact":"The great barracuda is a torpedo-shaped reef predator with fang-like teeth that hunts in sudden short bursts of speed."},"barramundi":{"id":"barramundi","name":"Barramundi","aliases":["barra","Asian sea bass","Lates calcarifer","giant perch"],"kind":"creature","group":"fish","fact":"Barramundi hatch in estuaries, grow up in fresh water and return to the sea to spawn, with most starting life as males and later changing into females."},"barrel-jellyfish":{"id":"barrel-jellyfish","name":"Barrel jellyfish","aliases":["Rhizostoma pulmo","dustbin-lid jellyfish","Rhizostoma octopus","frilly-mouthed jellyfish"],"kind":"creature","group":"jellies","fact":"The barrel jellyfish, the largest jellyfish in British waters, can reach the size of a dustbin lid and is harmless enough to be food for leatherback turtles."},"barreleye":{"id":"barreleye","name":"Barreleye","aliases":["Macropinna microstoma","Pacific barreleye"],"kind":"creature","group":"fish","fact":"The barreleye has a transparent dome over its head and tubular green eyes that rotate inside it to look up through its own skull."},"basilosaurus":{"id":"basilosaurus","name":"Basilosaurus","aliases":["Zeuglodon"],"kind":"creature","group":"whales","fact":"Basilosaurus was an early whale about 18 metres long with tiny hind legs, and its name means 'king lizard' because it was first mistaken for a reptile."},"basket-star":{"id":"basket-star","name":"Basket star","aliases":["Gorgonocephalus"],"kind":"creature","group":"echinoderms","fact":"A basket star is a brittle star whose arms branch again and again into a tangled net that it spreads at night to catch plankton."},"basking-shark":{"id":"basking-shark","name":"Basking shark","aliases":["Cetorhinus maximus"],"kind":"creature","group":"sharks","fact":"The basking shark is the second-largest fish and filters plankton through a gaping mouth as it cruises slowly along."},"bass-strait":{"id":"bass-strait","name":"Bass Strait","aliases":[],"kind":"place","group":"straits","fact":"Bass Strait separates Tasmania from mainland Australia and is named after George Bass, the ship's surgeon who proved Tasmania was an island in 1798."},"bat-ray":{"id":"bat-ray","name":"Bat ray","aliases":["Myliobatis californica"],"kind":"creature","group":"rays","fact":"Bat rays flap over the sandy bottoms of California bays, digging up clams with their wings, and can span nearly 2 metres."},"bat-star":{"id":"bat-star","name":"Bat star","aliases":["sea bat","Patiria miniata"],"kind":"creature","group":"echinoderms","fact":"The bat star has webbing between its arms like a bat's wing and comes in almost every colour from red to purple to mottled."},"batavia":{"id":"batavia","name":"Batavia","aliases":[],"kind":"vessel","group":"wrecks","fact":"The Dutch East India Company ship Batavia was wrecked on a reef off Western Australia in 1629, and a bloody mutiny followed among the survivors."},"bathysphere":{"id":"bathysphere","name":"Bathysphere","aliases":[],"kind":"vessel","group":"submersibles","fact":"The bathysphere was a steel ball on a cable in which William Beebe and Otis Barton descended to about 920 metres off Bermuda in 1934, a record that stood for 15 years."},"bay-anchovy":{"id":"bay-anchovy","name":"Bay anchovy","aliases":["Anchoa mitchilli"],"kind":"creature","group":"fish","fact":"The bay anchovy is probably the most abundant fish on the US Atlantic and Gulf of Mexico coasts, yet few people have ever seen one."},"bay-of-all-saints":{"id":"bay-of-all-saints","name":"Bay of All Saints","aliases":["All Saints Bay","Baía de Todos os Santos","Todos os Santos Bay"],"kind":"place","group":"bays","fact":"The Bay of All Saints at Salvador is the largest bay in Brazil and was named by Portuguese explorers who arrived on All Saints' Day in 1501."},"bay-of-biscay":{"id":"bay-of-biscay","name":"Bay of Biscay","aliases":["Biscay"],"kind":"place","group":"bays","fact":"The Bay of Biscay, between France and Spain, is notorious among sailors for its violent Atlantic storms."},"bay-of-campeche":{"id":"bay-of-campeche","name":"Bay of Campeche","aliases":["Campeche Bay"],"kind":"place","group":"bays","fact":"The Bay of Campeche is the southern bight of the Gulf of Mexico, site of the huge Cantarell oil field and part of the Chicxulub impact crater."},"bay-of-fundy":{"id":"bay-of-fundy","name":"Bay of Fundy","aliases":["Fundy"],"kind":"place","group":"bays","fact":"The Bay of Fundy between Nova Scotia and New Brunswick has the highest tides in the world, rising and falling by as much as 16 metres."},"bay-of-pigs":{"id":"bay-of-pigs","name":"Bay of Pigs","aliases":["Bahía de Cochinos"],"kind":"place","group":"bays","fact":"The Bay of Pigs is an inlet on Cuba's southern Caribbean coast, famous for the failed 1961 invasion by CIA-trained Cuban exiles."},"bay-of-plenty":{"id":"bay-of-plenty","name":"Bay of Plenty","aliases":[],"kind":"place","group":"bays","fact":"The Bay of Plenty on New Zealand's North Island was named by Captain Cook in 1769 for the friendly welcome and abundant supplies he found there."},"bay-pipefish":{"id":"bay-pipefish","name":"Bay pipefish","aliases":["Syngnathus leptorhynchus"],"kind":"creature","group":"fish","fact":"The bay pipefish hides upright among eelgrass blades along North America's Pacific coast, from Alaska to Baja California."},"beadlet-anemone":{"id":"beadlet-anemone","name":"Beadlet anemone","aliases":["Actinia equina"],"kind":"creature","group":"cnidarians","fact":"The beadlet anemone of British rock pools is a red blob at low tide, and fights its neighbours with a ring of blue stinging beads under its tentacles."},"beaked-sea-snake":{"id":"beaked-sea-snake","name":"Beaked sea snake","aliases":["hook-nosed sea snake","common sea snake","Hydrophis schistosus","Enhydrina schistosa"],"kind":"creature","group":"reptiles","fact":"The beaked sea snake causes most sea snake bites and deaths, especially among fishermen pulling nets in South and Southeast Asia."},"beaked-whale":{"id":"beaked-whale","name":"Beaked whale","aliases":[],"kind":"creature","group":"whales","fact":"Beaked whales are deep-diving, elusive whales with just one or two pairs of teeth, and some species are known only from stranded animals."},"bearded-seal":{"id":"bearded-seal","name":"Bearded seal","aliases":["Erignathus barbatus"],"kind":"creature","group":"seals","fact":"Bearded seals have long white whiskers for finding clams and crabs on the Arctic seabed, and males sing long trilling songs under the ice."},"beaufort-gyre":{"id":"beaufort-gyre","name":"Beaufort Gyre","aliases":[],"kind":"place","group":"currents","fact":"The Beaufort Gyre is a wind-driven clockwise circulation in the Arctic Ocean north of Alaska that stores a huge volume of fresh water from melting ice."},"beaufort-sea":{"id":"beaufort-sea","name":"Beaufort Sea","aliases":[],"kind":"place","group":"seas","fact":"The Beaufort Sea north of Alaska and Canada is named after Sir Francis Beaufort, the British admiral who devised the Beaufort wind scale."},"beaugregory":{"id":"beaugregory","name":"Beaugregory","aliases":["Stegastes leucostictus"],"kind":"creature","group":"fish","fact":"The beaugregory is a Caribbean damselfish, yellow below and blue above as a juvenile, that fiercely defends a small patch of reef."},"belchers-sea-snake":{"id":"belchers-sea-snake","name":"Belcher's sea snake","aliases":["faint-banded sea snake","Hydrophis belcheri"],"kind":"creature","group":"reptiles","fact":"Belcher's sea snake is often wrongly called the world's most venomous snake; its venom is potent, but it is docile and rarely bites."},"belemnite":{"id":"belemnite","name":"Belemnite","aliases":[],"kind":"creature","group":"cephalopods","fact":"Belemnites were squid-like animals with an internal bullet-shaped shell, and their fossils were once thought to be thunderbolts."},"belize-barrier-reef":{"id":"belize-barrier-reef","name":"Belize Barrier Reef","aliases":["Belize Reef","Belize Barrier Reef Reserve System"],"kind":"place","group":"reefs","fact":"The Belize Barrier Reef runs about 300 kilometres along the coast of Belize and is the largest section of the Mesoamerican Reef."},"bellingshausen-sea":{"id":"bellingshausen-sea","name":"Bellingshausen Sea","aliases":[],"kind":"place","group":"seas","fact":"The Bellingshausen Sea off Antarctica is named after Fabian Gottlieb von Bellingshausen, the Russian officer whose expedition sighted the continent in 1820."},"beluga-sturgeon":{"id":"beluga-sturgeon","name":"Beluga sturgeon","aliases":["Huso huso","great sturgeon","beluga"],"kind":"creature","group":"fish","fact":"The beluga sturgeon of the Caspian and Black Seas can live for more than 100 years and is the source of the most expensive caviar."},"beluga-whale":{"id":"beluga-whale","name":"Beluga whale","aliases":["beluga","white whale","sea canary","Delphinapterus leucas"],"kind":"creature","group":"whales","fact":"Belugas are nicknamed sea canaries for their chirps and whistles, and they can turn their heads because their neck bones are not fused."},"ben-franklin":{"id":"ben-franklin","name":"Ben Franklin","aliases":["PX-15","Ben Franklin submersible"],"kind":"vessel","group":"submersibles","fact":"In 1969 the submersible Ben Franklin drifted silently for 30 days inside the Gulf Stream with six men aboard, a mission NASA studied as a model for long space flights."},"bengal-tiger":{"id":"bengal-tiger","name":"Bengal tiger","aliases":["tiger","Sundarbans tiger","Panthera tigris tigris"],"kind":"creature","group":"mammals","fact":"Bengal tigers of the Sundarbans, the world's largest mangrove forest, swim between islands and hunt along the tidal creeks."},"benguela-current":{"id":"benguela-current","name":"Benguela Current","aliases":[],"kind":"place","group":"currents","fact":"The Benguela Current carries cold, nutrient-rich water north along the coast of Namibia and South Africa, supporting vast shoals of sardines and the Namib coast's fogs."},"benthesicymus":{"id":"benthesicymus","name":"Benthesicymus","aliases":["Benthesicymus crenatus","hadal shrimp"],"kind":"creature","group":"crustaceans","fact":"The prawn Benthesicymus crenatus was filmed in the Kermadec and Japan trenches at about 7,700 metres, the first decapod seen in the hadal zone."},"bering-sea":{"id":"bering-sea","name":"Bering Sea","aliases":[],"kind":"place","group":"seas","fact":"The Bering Sea separates Alaska from Siberia and is named after Vitus Bering, the Danish navigator who sailed through it for Russia in 1728."},"bering-strait":{"id":"bering-strait","name":"Bering Strait","aliases":[],"kind":"place","group":"straits","fact":"The Bering Strait, named after the Danish navigator Vitus Bering, separates Russia from Alaska by about 82 kilometres and links the Pacific to the Arctic."},"bermuda":{"id":"bermuda","name":"Bermuda","aliases":[],"kind":"place","group":"islands","fact":"Bermuda is a lone group of islands in the North Atlantic about 1,000 kilometres from the US coast, with the most northerly coral reefs in the world."},"bermuda-fireworm":{"id":"bermuda-fireworm","name":"Bermuda fireworm","aliases":["Odontosyllis enopla"],"kind":"creature","group":"worms","fact":"Bermuda fireworms rise to the surface a few nights after each summer full moon and spin in glowing green circles to mate, a display Columbus may have seen in 1492."},"betta":{"id":"betta","name":"Betta","aliases":["Siamese fighting fish","fighting fish","Betta splendens","betta fish"],"kind":"creature","group":"fish","fact":"Bettas have a labyrinth organ above the gills that lets them gulp air at the surface, which is why they survive in still, oxygen-poor water."},"bichir":{"id":"bichir","name":"Bichir","aliases":["Polypterus","Senegal bichir"],"kind":"creature","group":"fish","fact":"Bichirs have paired lungs and can breathe air, and young bichirs even have external gills like a salamander larva."},"bicolor-damselfish":{"id":"bicolor-damselfish","name":"Bicolor damselfish","aliases":["Stegastes partitus","bicolour damselfish"],"kind":"creature","group":"fish","fact":"The bicolor damselfish of the Caribbean is dark in front and pale behind, and tends algae gardens that it guards from other grazers."},"big-belly-seahorse":{"id":"big-belly-seahorse","name":"Big-belly seahorse","aliases":["pot-bellied seahorse","bigbelly seahorse","pot-belly seahorse","Hippocampus abdominalis"],"kind":"creature","group":"fish","fact":"The big-belly seahorse of Australia and New Zealand is one of the largest seahorses, reaching about 35 centimetres, and the male's pouch swells hugely with eggs."},"big-red-jellyfish":{"id":"big-red-jellyfish","name":"Big red jellyfish","aliases":["Tiburonia granrojo","granrojo"],"kind":"creature","group":"jellies","fact":"Big red is a metre-wide deep-sea jellyfish discovered in 2003 that has no tentacles at all, feeding instead with four to seven thick fleshy arms."},"bigeye-thresher-shark":{"id":"bigeye-thresher-shark","name":"Bigeye thresher shark","aliases":["bigeye thresher","Alopias superciliosus"],"kind":"creature","group":"sharks","fact":"The bigeye thresher has huge upward-facing eyes for hunting in dim water hundreds of metres down, where it spends its days."},"bigeye-tuna":{"id":"bigeye-tuna","name":"Bigeye tuna","aliases":["Thunnus obesus","mebachi","bigeye"],"kind":"creature","group":"fish","fact":"The bigeye tuna, with large eyes for hunting in dim deep water, is a major catch for longline fleets and is sold as sashimi-grade ahi in Hawaii."},"bigfin-reef-squid":{"id":"bigfin-reef-squid","name":"Bigfin reef squid","aliases":["Sepioteuthis lessoniana","oval squid","aori-ika"],"kind":"creature","group":"cephalopods","fact":"Bigfin reef squid have one of the fastest growth rates of any large invertebrate, reaching well over half a kilogram within about four months."},"bigfin-squid":{"id":"bigfin-squid","name":"Bigfin squid","aliases":["Magnapinna","long-arm squid","elbow squid"],"kind":"creature","group":"cephalopods","fact":"Bigfin squid dangle ten thin, elbowed arms that stretch to a total length of about 8 metres, and one was filmed 6,212 metres down in the Philippine Trench."},"bighead-carp":{"id":"bighead-carp","name":"Bighead carp","aliases":["Hypophthalmichthys nobilis"],"kind":"creature","group":"fish","fact":"The bighead carp is farmed in huge quantities in China, where its large head is prized for soups."},"bight-of-benin":{"id":"bight-of-benin","name":"Bight of Benin","aliases":[],"kind":"place","group":"bays","fact":"The Bight of Benin is a bay in the Gulf of Guinea whose shore was once known as the Slave Coast."},"bight-of-biafra":{"id":"bight-of-biafra","name":"Bight of Biafra","aliases":["Bight of Bonny"],"kind":"place","group":"bays","fact":"The Bight of Biafra, now officially the Bight of Bonny, is the easternmost corner of the Gulf of Guinea, off Nigeria and Cameroon."},"bikini-atoll":{"id":"bikini-atoll","name":"Bikini Atoll","aliases":["Bikini"],"kind":"place","group":"reefs","fact":"Bikini Atoll's reef was blasted by 23 nuclear tests between 1946 and 1958, yet its corals have since grown back vigorously."},"bilbao":{"id":"bilbao","name":"Bilbao","aliases":["Bilbo"],"kind":"place","group":"ports","fact":"Bilbao's port on the Bay of Biscay is one of Spain's busiest, and the city was reinvented by the Guggenheim museum in 1997."},"bioko":{"id":"bioko","name":"Bioko","aliases":["Fernando Po"],"kind":"place","group":"islands","fact":"Bioko is a volcanic island in the Gulf of Guinea that holds Malabo, the capital of Equatorial Guinea, far from the country's mainland."},"bird-wrasse":{"id":"bird-wrasse","name":"Bird wrasse","aliases":["Gomphosus varius","green bird wrasse","brown bird wrasse"],"kind":"creature","group":"fish","fact":"The bird wrasse has a long, curved beak-like snout that it uses to pluck small animals from crevices on Indo-Pacific reefs."},"birdbeak-dogfish":{"id":"birdbeak-dogfish","name":"Birdbeak dogfish","aliases":["Deania calcea"],"kind":"creature","group":"sharks","fact":"The birdbeak dogfish has an extremely long, flattened snout and lives on continental slopes down to around 1,500 metres."},"bismarck":{"id":"bismarck","name":"Bismarck","aliases":["battleship Bismarck","German battleship Bismarck"],"kind":"vessel","group":"wrecks","fact":"The battleship Bismarck was sunk in May 1941 after a three-day chase, and Robert Ballard found the wreck in 1989 standing upright about 4,700 metres down."},"bismarck-sea":{"id":"bismarck-sea","name":"Bismarck Sea","aliases":[],"kind":"place","group":"seas","fact":"The Bismarck Sea lies north-east of New Guinea and is named, like the Bismarck Archipelago, after the German chancellor Otto von Bismarck."},"black-banded-sea-krait":{"id":"black-banded-sea-krait","name":"Black-banded sea krait","aliases":["Chinese sea snake","erabu","erabu sea krait","Laticauda semifasciata"],"kind":"creature","group":"reptiles","fact":"The black-banded sea krait, or erabu, is caught and smoked in Okinawa to make a traditional soup called irabu-jiru."},"black-blotched-stingray":{"id":"black-blotched-stingray","name":"Black-blotched stingray","aliases":["blotched fantail ray","round ribbontail ray","giant reef ray","Taeniurops meyeni","Taeniura meyeni"],"kind":"creature","group":"rays","fact":"The blotched fantail ray can grow nearly 2 metres across and is often seen at cleaning stations on Indo-Pacific reefs."},"black-coral":{"id":"black-coral","name":"Black coral","aliases":["antipatharian","Antipatharia","Leiopathes"],"kind":"creature","group":"corals","fact":"Black coral has a dark, flexible skeleton that has been carved into jewellery, and some colonies are more than 4,000 years old."},"black-crappie":{"id":"black-crappie","name":"Black crappie","aliases":["crappie","Pomoxis nigromaculatus"],"kind":"creature","group":"fish","fact":"Crappie are schooling sunfish of North American lakes, and anglers catch them in numbers around sunken brush in spring."},"black-dogfish":{"id":"black-dogfish","name":"Black dogfish","aliases":["Centroscyllium fabricii"],"kind":"creature","group":"sharks","fact":"The black dogfish is a small glowing shark of the deep North Atlantic that gathers in large schools on the continental slope."},"black-drum":{"id":"black-drum","name":"Black drum","aliases":["Pogonias cromis"],"kind":"creature","group":"fish","fact":"Black drum make such loud, low booming calls while spawning that Florida residents have complained of a mysterious hum coming through their walls."},"black-ghost-knifefish":{"id":"black-ghost-knifefish","name":"Black ghost knifefish","aliases":["black ghost","Apteronotus albifrons"],"kind":"creature","group":"fish","fact":"The black ghost knifefish swims backwards as easily as forwards by rippling one long fin and senses its world with a weak electric field."},"black-grouper":{"id":"black-grouper","name":"Black grouper","aliases":["Mycteroperca bonaci"],"kind":"creature","group":"fish","fact":"The black grouper is a large grouper of the western Atlantic, growing to about 1.5 metres, with rectangular dark blotches on its sides."},"black-marlin":{"id":"black-marlin","name":"Black marlin","aliases":["Istiompax indica","Makaira indica"],"kind":"creature","group":"fish","fact":"The black marlin of the Indo-Pacific is often claimed to be the fastest fish of all, and its rigid pectoral fins cannot be folded flat against the body."},"black-molly":{"id":"black-molly","name":"Black molly","aliases":["Poecilia sphenops"],"kind":"creature","group":"fish","fact":"The black molly is a jet-black aquarium strain of a Central American livebearer that gives birth to free-swimming fry."},"black-scabbardfish":{"id":"black-scabbardfish","name":"Black scabbardfish","aliases":["Aphanopus carbo","espada","black scabbard"],"kind":"creature","group":"fish","fact":"The black scabbardfish is a jet-black, eel-like deep-sea fish with fangs, hauled up from about 1,000 metres on long lines off Madeira, where it is served with banana."},"black-sea":{"id":"black-sea","name":"Black Sea","aliases":[],"kind":"place","group":"seas","fact":"The Black Sea connects to the Mediterranean only through the Bosporus and Dardanelles, and below about 150 metres its water contains no oxygen at all."},"black-sea-bass":{"id":"black-sea-bass","name":"Black sea bass","aliases":["Centropristis striata"],"kind":"creature","group":"fish","fact":"The black sea bass of the US east coast starts life as a female and later changes into a male with a bright blue hump on its nape."},"black-sea-nettle":{"id":"black-sea-nettle","name":"Black sea nettle","aliases":["Chrysaora achlyos"],"kind":"creature","group":"jellies","fact":"The black sea nettle has a bell up to a metre across and oral arms about 8 metres long, yet it was not formally described until 1997."},"black-skimmer":{"id":"black-skimmer","name":"Black skimmer","aliases":["skimmer","Rynchops niger"],"kind":"creature","group":"seabirds","fact":"The black skimmer flies low with its longer lower beak slicing the water, snapping shut the instant it touches a fish."},"black-swallower":{"id":"black-swallower","name":"Black swallower","aliases":["Chiasmodon niger","great swallower"],"kind":"creature","group":"fish","fact":"The black swallower can gulp down fish more than twice its own length, stretching its stomach so far that it sometimes bursts."},"black-turban-snail":{"id":"black-turban-snail","name":"Black turban snail","aliases":["turban snail","Tegula funebralis","tegula"],"kind":"creature","group":"molluscs","fact":"The black turban snail is a common grazer of Pacific tide pools whose empty shells are favourite homes for hermit crabs."},"blackfin-tuna":{"id":"blackfin-tuna","name":"Blackfin tuna","aliases":["Thunnus atlanticus"],"kind":"creature","group":"fish","fact":"The blackfin tuna is the smallest of the true tunas, rarely over a metre long, and is found only in the western Atlantic."},"blacknose-shark":{"id":"blacknose-shark","name":"Blacknose shark","aliases":["Carcharhinus acronotus"],"kind":"creature","group":"sharks","fact":"The small blacknose shark has a dark smudge on its snout tip and is common in the warm shallows of the western Atlantic."},"blacksmith":{"id":"blacksmith","name":"Blacksmith","aliases":["blacksmith damselfish","Chromis punctipinnis","blacksmith chromis"],"kind":"creature","group":"fish","fact":"The blacksmith is a blue-grey damselfish of California's kelp forests that shelters in rock crevices at night and feeds on plankton by day."},"blackspot-tuskfish":{"id":"blackspot-tuskfish","name":"Blackspot tuskfish","aliases":["Choerodon schoenleinii","blackspot tusk"],"kind":"creature","group":"fish","fact":"The blackspot tuskfish was filmed on the Great Barrier Reef smashing clams against a rock anvil, one of the first documented cases of tool use in a fish."},"blackspotted-puffer":{"id":"blackspotted-puffer","name":"Blackspotted puffer","aliases":["dog-faced puffer","dogface puffer","Arothron nigropunctatus"],"kind":"creature","group":"fish","fact":"The blackspotted puffer, nicknamed the dog-faced puffer, has a grey body with black spots and a muzzle like a puppy's."},"blacktip-reef-shark":{"id":"blacktip-reef-shark","name":"Blacktip reef shark","aliases":["Carcharhinus melanopterus","black tip reef shark"],"kind":"creature","group":"sharks","fact":"Blacktip reef sharks patrol reef flats so shallow that their black-tipped dorsal fins often poke above the surface."},"blacktip-shark":{"id":"blacktip-shark","name":"Blacktip shark","aliases":["blacktip","Carcharhinus limbatus"],"kind":"creature","group":"sharks","fact":"Blacktip sharks leap and spin out of the water when chasing fish and migrate along the Florida coast in large numbers each year."},"bladderwrack":{"id":"bladderwrack","name":"Bladderwrack","aliases":["bladder wrack","Fucus vesiculosus"],"kind":"plant","group":"plants","fact":"Bladderwrack is the brown seaweed with paired air bladders along its fronds, common on rocky shores and the original source of iodine."},"blainvilles-beaked-whale":{"id":"blainvilles-beaked-whale","name":"Blainville's beaked whale","aliases":["dense-beaked whale","Mesoplodon densirostris"],"kind":"creature","group":"whales","fact":"Blainville's beaked whale has the densest bone known in any animal, in its beak, and is named after French zoologist Henri de Blainville."},"blanket-octopus":{"id":"blanket-octopus","name":"Blanket octopus","aliases":["Tremoctopus","Tremoctopus violaceus"],"kind":"creature","group":"cephalopods","fact":"A female blanket octopus can be 2 metres long while the male is barely 2 centimetres, and they rip stinging tentacles from Portuguese man o' war to use as weapons."},"blenny":{"id":"blenny","name":"Blenny","aliases":["Blenniidae"],"kind":"creature","group":"fish","fact":"Blennies are small scaleless fish that wedge themselves into cracks in rock pools, and some can hop between pools over wet rock."},"blind-shark":{"id":"blind-shark","name":"Blind shark","aliases":["Brachaelurus waddi"],"kind":"creature","group":"sharks","fact":"The blind shark is not blind at all; it got its name because it closes its eyelids when lifted out of the water."},"blobfish":{"id":"blobfish","name":"Blobfish","aliases":["Psychrolutes marcidus","smooth-head blobfish"],"kind":"creature","group":"fish","fact":"The blobfish looks normal at its home depth of 600 to 1,200 metres; its famous droopy face is what happens when its jelly-like flesh is hauled to the surface."},"blood-star":{"id":"blood-star","name":"Blood star","aliases":["Pacific blood star","Henricia"],"kind":"creature","group":"echinoderms","fact":"The blood star is a small, slender sea star of rocky northern shores, usually a vivid orange-red, with arms much longer than its body is wide."},"bloodybelly-comb-jelly":{"id":"bloodybelly-comb-jelly","name":"Bloodybelly comb jelly","aliases":["Lampocteis cruentiventer","bloody-belly comb jelly"],"kind":"creature","group":"jellies","fact":"The bloodybelly comb jelly is deep red so that the glowing prey in its stomach cannot be seen by predators in the dark depths."},"blue-antimora":{"id":"blue-antimora","name":"Blue antimora","aliases":["Antimora rostrata","blue hake","violet cod"],"kind":"creature","group":"fish","fact":"The blue antimora is a deep-sea cod relative with a violet sheen, common on continental slopes from about 800 to 3,000 metres."},"blue-blubber-jellyfish":{"id":"blue-blubber-jellyfish","name":"Blue blubber jellyfish","aliases":["Catostylus mosaicus","jelly blubber","blubber jellyfish"],"kind":"creature","group":"jellies","fact":"The blue blubber of Australian estuaries has no trailing tentacles, feeding with eight stubby arms, and is fished and dried for export to Asia."},"blue-button":{"id":"blue-button","name":"Blue button","aliases":["Porpita porpita","Porpita"],"kind":"creature","group":"jellies","fact":"The blue button is a coin-sized floating colony of hydroids with a hard golden disc and a fringe of blue tentacles, often washed up with by-the-wind sailors."},"blue-catfish":{"id":"blue-catfish","name":"Blue catfish","aliases":["Ictalurus furcatus","blue cat"],"kind":"creature","group":"fish","fact":"The blue catfish is the largest catfish in North America, reaching over 60 kilograms, and has become an invasive species in Chesapeake Bay."},"blue-chromis":{"id":"blue-chromis","name":"Blue chromis","aliases":["Chromis cyanea"],"kind":"creature","group":"fish","fact":"The blue chromis is a brilliant blue Caribbean damselfish that feeds on plankton in open water above the reef."},"blue-cod":{"id":"blue-cod","name":"Blue cod","aliases":["Parapercis colias","rawaru"],"kind":"creature","group":"fish","fact":"The blue cod is not a cod but a sandperch found only around New Zealand, where it is the favourite catch of shore anglers."},"blue-coral":{"id":"blue-coral","name":"Blue coral","aliases":["Heliopora coerulea"],"kind":"creature","group":"corals","fact":"Blue coral is the only living coral with a blue skeleton, coloured by iron salts, and is the sole survivor of an ancient group."},"blue-corner":{"id":"blue-corner","name":"Blue Corner","aliases":["Blue Corner Palau"],"kind":"place","group":"divesites","fact":"Blue Corner in Palau is a current-swept reef wall where divers hook onto the rock to watch sharks and schooling fish stream past."},"blue-crab":{"id":"blue-crab","name":"Blue crab","aliases":["Atlantic blue crab","Chesapeake blue crab","Callinectes sapidus","Maryland blue crab"],"kind":"creature","group":"crustaceans","fact":"The blue crab's scientific name means 'beautiful savoury swimmer', and freshly moulted ones are eaten whole as soft-shell crabs."},"blue-devil-damselfish":{"id":"blue-devil-damselfish","name":"Blue devil damselfish","aliases":["blue devil","Chrysiptera cyanea","sapphire devil","blue damsel"],"kind":"creature","group":"fish","fact":"The blue devil damselfish, a brilliant electric-blue fish of the western Pacific, is a hardy aquarium favourite with a devilish temper for its size."},"blue-dragon":{"id":"blue-dragon","name":"Blue dragon","aliases":["Glaucus atlanticus","blue sea slug","blue glaucus","sea swallow","blue angel"],"kind":"creature","group":"molluscs","fact":"The blue dragon sea slug floats upside down at the surface, eats Portuguese man o' war and stores their stinging cells in its finger-like tips to fire at attackers."},"blue-footed-booby":{"id":"blue-footed-booby","name":"Blue-footed booby","aliases":["Sula nebouxii","booby"],"kind":"creature","group":"seabirds","fact":"Blue-footed boobies fold their wings and plunge-dive into shoals of sardines, and the males show off their bright blue feet in a high-stepping dance."},"blue-green-chromis":{"id":"blue-green-chromis","name":"Blue-green chromis","aliases":["green chromis","Chromis viridis","blue-green damselfish"],"kind":"creature","group":"fish","fact":"The blue-green chromis is a shimmering damselfish that hovers in large shoals above branching corals, darting in when danger threatens."},"blue-lipped-sea-krait":{"id":"blue-lipped-sea-krait","name":"Blue-lipped sea krait","aliases":["blue-banded sea krait","brown-lipped sea krait","Laticauda laticaudata"],"kind":"creature","group":"reptiles","fact":"The blue-lipped sea krait comes ashore on Pacific and Indian Ocean islands to rest and lay its eggs in caves and crevices."},"blue-mackerel":{"id":"blue-mackerel","name":"Blue mackerel","aliases":["Scomber australasicus","slimy mackerel","spotted chub mackerel"],"kind":"creature","group":"fish","fact":"The blue mackerel, or slimy mackerel, is a spotted mackerel of Australian and New Zealand waters, mostly used as bait and for canning."},"blue-marlin":{"id":"blue-marlin","name":"Blue marlin","aliases":["Atlantic blue marlin","Makaira nigricans","marlin"],"kind":"creature","group":"fish","fact":"The Atlantic blue marlin can top 4 metres and is one of the fastest, hardest-fighting fish in the sea; females grow far larger than males."},"blue-mussel":{"id":"blue-mussel","name":"Blue mussel","aliases":["common mussel","mussel","Mytilus edulis"],"kind":"creature","group":"molluscs","fact":"Blue mussels carpet rocky shores and sandbanks of the North and Baltic seas, anchored by tough threads they spin themselves."},"blue-parrotfish":{"id":"blue-parrotfish","name":"Blue parrotfish","aliases":["Scarus coeruleus"],"kind":"creature","group":"fish","fact":"The blue parrotfish is a uniform powder-blue Caribbean parrotfish that spends most of its day grinding sand and rock for algae."},"blue-ringed-octopus":{"id":"blue-ringed-octopus","name":"Blue-ringed octopus","aliases":["blue ring octopus","Hapalochlaena"],"kind":"creature","group":"cephalopods","fact":"A golf-ball-sized blue-ringed octopus carries enough tetrodotoxin to kill several adults, and its blue rings flash as a warning when it is alarmed."},"blue-rockfish":{"id":"blue-rockfish","name":"Blue rockfish","aliases":["Sebastes mystinus"],"kind":"creature","group":"fish","fact":"Blue rockfish school in the water column of California kelp forests and are among the fish divers see most often there."},"blue-shark":{"id":"blue-shark","name":"Blue shark","aliases":["Prionace glauca","blue dog"],"kind":"creature","group":"sharks","fact":"Blue sharks cross whole oceans, with tagged individuals travelling from New England to Spain and back."},"blue-spotted-ribbontail-ray":{"id":"blue-spotted-ribbontail-ray","name":"Blue-spotted ribbontail ray","aliases":["bluespotted ribbontail ray","bluespotted ray","blue-spotted ray","ribbontail ray","bluespotted lagoon ray","Taeniura lymma"],"kind":"creature","group":"rays","fact":"The bluespotted ribbontail ray's bright blue spots warn predators that its tail carries two venomous spines."},"blue-starfish":{"id":"blue-starfish","name":"Blue starfish","aliases":["blue sea star","blue Linckia","Linckia laevigata","Linckia"],"kind":"creature","group":"echinoderms","fact":"The blue starfish of Indo-Pacific reefs is a vivid blue and can regrow lost arms; its close relative Linckia multifora can even grow a whole new star from a single severed arm."},"blue-stingray":{"id":"blue-stingray","name":"Blue stingray","aliases":["Dasyatis chrysonota"],"kind":"creature","group":"rays","fact":"The blue stingray of southern African waters has blue markings on its back and is a favourite of shore anglers."},"blue-tang":{"id":"blue-tang","name":"Blue tang","aliases":["regal tang","palette surgeonfish","hippo tang","Paracanthurus hepatus","regal blue tang","Dory","blue hippo tang","Pacific blue tang","flagtail surgeonfish"],"kind":"creature","group":"fish","fact":"The blue tang, the fish behind Dory, has a razor-sharp spine on each side of its tail that it flicks out in defence."},"blue-whale":{"id":"blue-whale","name":"Blue whale","aliases":["Balaenoptera musculus"],"kind":"creature","group":"whales","fact":"The blue whale is the largest animal known to have ever lived, reaching about 30 metres and well over 150 tonnes."},"blue-whiting":{"id":"blue-whiting","name":"Blue whiting","aliases":["Micromesistius poutassou"],"kind":"creature","group":"fish","fact":"Blue whiting is a small cod relative of the North Atlantic caught by the million tonnes for fishmeal and surimi."},"blueback-herring":{"id":"blueback-herring","name":"Blueback herring","aliases":["Alosa aestivalis"],"kind":"creature","group":"fish","fact":"The blueback herring runs up rivers from Florida to Nova Scotia each spring to spawn and is hard to tell from the alewife."},"bluefin-tuna":{"id":"bluefin-tuna","name":"Bluefin tuna","aliases":["Atlantic bluefin tuna","bluefin","Thunnus thynnus","hon-maguro","northern bluefin tuna"],"kind":"creature","group":"fish","fact":"The Atlantic bluefin tuna can weigh more than 600 kilograms and is warm-blooded, keeping its muscles warmer than the sea so it can sprint after prey."},"bluefish":{"id":"bluefish","name":"Bluefish","aliases":["tailor","Pomatomus saltatrix"],"kind":"creature","group":"fish","fact":"Bluefish hunt in savage packs along the US Atlantic coast and will keep biting even after they are full."},"bluegill":{"id":"bluegill","name":"Bluegill","aliases":["Lepomis macrochirus","bream","brim"],"kind":"creature","group":"fish","fact":"Male bluegill dig saucer-shaped nests in colonies and guard the eggs, while small 'sneaker' males dart in to fertilise some on the sly."},"bluehead-wrasse":{"id":"bluehead-wrasse","name":"Bluehead wrasse","aliases":["blue-headed wrasse","Thalassoma bifasciatum","bluehead"],"kind":"creature","group":"fish","fact":"The bluehead wrasse of the Caribbean can change from female to male in days, and the big blue-headed males defend spawning sites."},"bluespotted-maskray":{"id":"bluespotted-maskray","name":"Bluespotted maskray","aliases":["blue-spotted maskray","bluespotted stingray","blue-spotted stingray","Kuhl's stingray","Kuhl's maskray","Neotrygon kuhlii"],"kind":"creature","group":"rays","fact":"The bluespotted maskray has a dark mask across its eyes and is often confused with the bluespotted ribbontail ray."},"bluespotted-ribbontail-ray":{"id":"bluespotted-ribbontail-ray","name":"Bluespotted ribbontail ray","aliases":["bluespotted ray","blue-spotted stingray","Taeniura lymma"],"kind":"creature","group":"rays","fact":"The bluespotted ribbontail ray has electric-blue spots and two venomous tail spines, and hides under table corals on Red Sea reefs."},"bluestripe-snapper":{"id":"bluestripe-snapper","name":"Bluestripe snapper","aliases":["blue-striped snapper","Lutjanus kasmira"],"kind":"creature","group":"fish","fact":"The bluestripe snapper, yellow with four blue stripes, schools in hundreds on Indian Ocean and Red Sea reefs."},"bluntnose-stingray":{"id":"bluntnose-stingray","name":"Bluntnose stingray","aliases":["Hypanus say","Dasyatis say"],"kind":"creature","group":"rays","fact":"The bluntnose stingray of the western Atlantic has a rounded snout and glides over sandy flats from Massachusetts to Brazil."},"boaty-mcboatface":{"id":"boaty-mcboatface","name":"Boaty McBoatface","aliases":["Boaty"],"kind":"vessel","group":"submersibles","fact":"Boaty McBoatface is a yellow robot submarine that won its name in a public vote and has since made long journeys under Antarctic sea ice and deep in the Southern Ocean."},"bobbit-worm":{"id":"bobbit-worm","name":"Bobbit worm","aliases":["sand striker","Eunice aphroditois"],"kind":"creature","group":"worms","fact":"The bobbit worm lurks buried in sand with only its jaws showing and ambushes fish at night, growing up to about 3 metres long."},"bobtail-snipe-eel":{"id":"bobtail-snipe-eel","name":"Bobtail snipe eel","aliases":["Cyema atrum","bobtail eel"],"kind":"creature","group":"fish","fact":"The bobtail snipe eel is a stubby, dart-shaped deep-sea eel with long thin jaws, found in the dark waters below 1,000 metres."},"bobtail-squid":{"id":"bobtail-squid","name":"Bobtail squid","aliases":["bobtail","dumpling squid","stubby squid","Hawaiian bobtail squid","Euprymna scolopes"],"kind":"creature","group":"cephalopods","fact":"Bobtail squid are small, round cephalopods that bury themselves in sand by day and hunt shrimp at night, and many carry glowing bacteria."},"bohai-sea":{"id":"bohai-sea","name":"Bohai Sea","aliases":["Bo Hai","Bohai Gulf","Gulf of Chihli"],"kind":"place","group":"seas","fact":"The Bohai Sea is the innermost gulf of the Yellow Sea, almost enclosed by China's coast, and the sea approach to the port of Tianjin."},"bolivian-river-dolphin":{"id":"bolivian-river-dolphin","name":"Bolivian river dolphin","aliases":["Bolivian bufeo","Inia boliviensis"],"kind":"creature","group":"dolphins","fact":"The Bolivian river dolphin lives in the upper Madeira basin, cut off from the Amazon by rapids, and was declared part of Bolivia's natural heritage in 2012."},"bombay-duck":{"id":"bombay-duck","name":"Bombay duck","aliases":["bummalo","Harpadon nehereus","bombil"],"kind":"creature","group":"fish","fact":"Bombay duck is not a duck but a lizardfish caught in huge numbers off western India, where it is dried in the open air and fried."},"bonaire-national-marine-park":{"id":"bonaire-national-marine-park","name":"Bonaire National Marine Park","aliases":["Bonaire"],"kind":"place","group":"parks","fact":"Bonaire's entire coastline has been a marine park since 1979, and divers simply walk in from shore to reach its reefs."},"bonefish":{"id":"bonefish","name":"Bonefish","aliases":["Albula vulpes","Albula"],"kind":"creature","group":"fish","fact":"The bonefish is the 'grey ghost' of tropical flats, a shy, fast-sprinting fish that can strip line from a fly reel in seconds."},"bonito":{"id":"bonito","name":"Bonito","aliases":["Sarda"],"kind":"creature","group":"fish","fact":"Bonitos are striped, tuna-like fish of the mackerel family; in Japan 'bonito' usually means the skipjack, seared as katsuo tataki or dried into bonito flakes."},"bonnethead":{"id":"bonnethead","name":"Bonnethead","aliases":["bonnethead shark","shovelhead shark","Sphyrna tiburo"],"kind":"creature","group":"sharks","fact":"The bonnethead is the only shark known to eat and digest seagrass, which can make up over half of its diet."},"bony-eared-assfish":{"id":"bony-eared-assfish","name":"Bony-eared assfish","aliases":["Acanthonus armatus"],"kind":"creature","group":"fish","fact":"The bony-eared assfish is a cusk-eel from 1,000 to 4,400 metres with the smallest brain for its body size of any known vertebrate, and an unfortunate name."},"booby":{"id":"booby","name":"Booby","aliases":[],"kind":"creature","group":"seabirds","fact":"Boobies are tropical plunge-divers named from the Spanish 'bobo', meaning foolish, because they were so easy for sailors to catch."},"bootlace-worm":{"id":"bootlace-worm","name":"Bootlace worm","aliases":["Lineus longissimus"],"kind":"creature","group":"worms","fact":"The bootlace worm is a ribbon worm of North Sea shores; one found in Scotland in 1864 measured about 55 metres, the longest animal ever recorded."},"bora-bora":{"id":"bora-bora","name":"Bora Bora","aliases":[],"kind":"place","group":"islands","fact":"Bora Bora is a volcanic island in French Polynesia surrounded by a turquoise lagoon and a ring of reef islets."},"bosporus":{"id":"bosporus","name":"Bosporus","aliases":["Bosphorus","Istanbul Strait","Strait of Istanbul"],"kind":"place","group":"straits","fact":"The Bosporus runs through the middle of Istanbul, linking the Black Sea to the Sea of Marmara and dividing Europe from Asia."},"boston":{"id":"boston","name":"Boston","aliases":[],"kind":"place","group":"ports","fact":"Boston's harbour on the Atlantic was the scene of the Boston Tea Party in 1773, when colonists dumped tea into the water in protest at British taxes."},"botany-bay":{"id":"botany-bay","name":"Botany Bay","aliases":[],"kind":"place","group":"bays","fact":"Botany Bay south of Sydney is where Captain Cook first landed in Australia in 1770, named for the plants collected there by Joseph Banks."},"bottlenose-dolphin":{"id":"bottlenose-dolphin","name":"Bottlenose dolphin","aliases":["bottlenose","common bottlenose dolphin","Atlantic bottlenose dolphin","Tursiops truncatus"],"kind":"creature","group":"dolphins","fact":"Bottlenose dolphins call each other by name using signature whistles that each dolphin invents as a calf."},"bougainville-trench":{"id":"bougainville-trench","name":"Bougainville Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Bougainville Trench curves through the northern Solomon Sea west of Bougainville Island, continuing the New Britain Trench, whose Planet Deep exceeds 9,000 metres."},"bouvet-island":{"id":"bouvet-island","name":"Bouvet Island","aliases":["Bouvet","Bouvetoya"],"kind":"place","group":"islands","fact":"Bouvet Island is the most remote island on Earth, an ice-covered volcanic island in the South Atlantic about 1,700 kilometres from Antarctica with no permanent inhabitants."},"bowfin":{"id":"bowfin","name":"Bowfin","aliases":["grindle","choupique","Amia calva","dogfish","grinnel"],"kind":"creature","group":"fish","fact":"The bowfin can breathe air using its swim bladder and is the only living member of a lineage dating back to the age of dinosaurs."},"bowhead-whale":{"id":"bowhead-whale","name":"Bowhead whale","aliases":["bowhead","Greenland right whale","Arctic whale","polar whale","Balaena mysticetus"],"kind":"creature","group":"whales","fact":"Bowhead whales can live more than 200 years and use their huge heads to break through sea ice."},"bowie-seamount":{"id":"bowie-seamount","name":"Bowie Seamount","aliases":["SGaan Kinghlas"],"kind":"place","group":"features","fact":"Bowie Seamount off British Columbia rises from about 3,000 metres to within roughly 25 metres of the surface and is a Canadian marine protected area."},"bowmouth-guitarfish":{"id":"bowmouth-guitarfish","name":"Bowmouth guitarfish","aliases":["shark ray","mud skate","Rhina ancylostoma"],"kind":"creature","group":"rays","fact":"The bowmouth guitarfish, or shark ray, has ridges of spiky thorns over its eyes and back and looks like a cross between a shark and a ray."},"box-jellyfish":{"id":"box-jellyfish","name":"Box jellyfish","aliases":["sea wasp","Chironex fleckeri","Australian box jellyfish","box jelly","cubozoan","Chironex"],"kind":"creature","group":"jellies","fact":"The Australian box jellyfish has 24 eyes and a sting that can stop a human heart within minutes, and it is almost invisible in the water."},"boxfish":{"id":"boxfish","name":"Boxfish","aliases":["trunkfish","cowfish","Ostraciidae"],"kind":"creature","group":"fish","fact":"Boxfish are encased in a rigid bony box and, when stressed, release a poisonous mucus that can kill every other fish in an aquarium."},"brain-coral":{"id":"brain-coral","name":"Brain coral","aliases":["Diploria","Colpophyllia","grooved brain coral"],"kind":"creature","group":"corals","fact":"Brain coral grows into a dome furrowed with grooves like a human brain, and single colonies can live for centuries."},"bramble-shark":{"id":"bramble-shark","name":"Bramble shark","aliases":["Echinorhinus brucus"],"kind":"creature","group":"sharks","fact":"The bramble shark is covered in large thorn-like denticles and is so rarely encountered that little is known about its life."},"bransfield-strait":{"id":"bransfield-strait","name":"Bransfield Strait","aliases":[],"kind":"place","group":"straits","fact":"Bransfield Strait between the South Shetland Islands and the Antarctic Peninsula is named after Edward Bransfield, who charted the area in 1820."},"brant-goose":{"id":"brant-goose","name":"Brant goose","aliases":["brant","brent goose","Branta bernicla"],"kind":"creature","group":"seabirds","fact":"The brant is a small sea goose that depends on eelgrass; when disease wiped out eelgrass on both sides of the Atlantic in the 1930s, brant numbers crashed."},"brazil-current":{"id":"brazil-current","name":"Brazil Current","aliases":[],"kind":"place","group":"currents","fact":"The Brazil Current carries warm tropical water south along the coast of Brazil until it meets the cold Falkland Current off Argentina."},"brest":{"id":"brest","name":"Brest","aliases":[],"kind":"place","group":"ports","fact":"Brest, on the far western tip of Brittany, is one of France's two main naval bases, with a huge natural harbour opening onto the Atlantic."},"brill":{"id":"brill","name":"Brill","aliases":["Scophthalmus rhombus"],"kind":"creature","group":"fish","fact":"Brill are close relatives of turbot with a more oval body and a frilled front edge to the dorsal fin."},"bristle-worm":{"id":"bristle-worm","name":"Bristle worm","aliases":["polychaete","polychaete worm","bristleworm"],"kind":"creature","group":"worms","fact":"Bristle worms are segmented worms with paddle-like feet fringed with bristles, and they have been collected from trench floors more than 10,000 metres down."},"bristlemouth":{"id":"bristlemouth","name":"Bristlemouth","aliases":["Cyclothone","Gonostomatidae","lightfish"],"kind":"creature","group":"fish","fact":"Bristlemouths are tiny, glowing deep-sea fish that may number in the hundreds of trillions, making them the most abundant vertebrates on Earth."},"bristlenose-pleco":{"id":"bristlenose-pleco","name":"Bristlenose pleco","aliases":["bristlenose catfish","bushynose pleco","Ancistrus","bristlenose"],"kind":"creature","group":"fish","fact":"The bristlenose pleco is a small armoured catfish whose males grow a bush of fleshy tentacles on the snout; it is a popular aquarium algae eater."},"britannic":{"id":"britannic","name":"Britannic","aliases":["HMHS Britannic","RMS Britannic"],"kind":"vessel","group":"wrecks","fact":"The Britannic, Titanic's larger sister, struck a mine while serving as a hospital ship in 1916 and lies on its side at about 120 metres off the Greek island of Kea."},"brittle-star":{"id":"brittle-star","name":"Brittle star","aliases":["ophiuroid","serpent star","brittlestar"],"kind":"creature","group":"echinoderms","fact":"Brittle stars snap off arms to escape predators and grow them back, and they have been seen in large numbers on the floor of the South Sandwich Trench below 6,000 metres."},"broadclub-cuttlefish":{"id":"broadclub-cuttlefish","name":"Broadclub cuttlefish","aliases":["Sepia latimanus"],"kind":"creature","group":"cephalopods","fact":"The broadclub cuttlefish hypnotises crabs by flashing moving bands of dark colour down its arms before striking."},"broadnose-sevengill-shark":{"id":"broadnose-sevengill-shark","name":"Broadnose sevengill shark","aliases":["sevengill shark","sevengill","Notorynchus cepedianus"],"kind":"creature","group":"sharks","fact":"Broadnose sevengill sharks have seven gill slits rather than five and have been seen hunting seals in groups off South Africa."},"brook-trout":{"id":"brook-trout","name":"Brook trout","aliases":["brookie","speckled trout","brook char","Salvelinus fontinalis"],"kind":"creature","group":"fish","fact":"The brook trout is actually a char, with light spots on a dark background, and is the official state fish of several US states."},"brown-pelican":{"id":"brown-pelican","name":"Brown pelican","aliases":["Pelecanus occidentalis"],"kind":"creature","group":"seabirds","fact":"The brown pelican dives head-first into the sea from 10 to 20 metres up, unlike most pelicans, which fish from the surface."},"brown-shrimp":{"id":"brown-shrimp","name":"Brown shrimp","aliases":["common shrimp","Crangon crangon","North Sea shrimp","Morecambe Bay shrimp"],"kind":"creature","group":"crustaceans","fact":"The brown shrimp of the North Sea is caught by horseback shrimpers in Belgium and potted in butter around Morecambe Bay."},"brown-trout":{"id":"brown-trout","name":"Brown trout","aliases":["sea trout","Salmo trutta"],"kind":"creature","group":"fish","fact":"Brown trout that migrate to sea come back silver and much larger, and are then known as sea trout."},"brownbanded-bamboo-shark":{"id":"brownbanded-bamboo-shark","name":"Brownbanded bamboo shark","aliases":["brown-banded bamboo shark","Chiloscyllium punctatum","bamboo shark"],"kind":"creature","group":"sharks","fact":"The brownbanded bamboo shark is born with dark bands that fade with age and can survive for hours out of water on exposed reef flats."},"brydes-whale":{"id":"brydes-whale","name":"Bryde's whale","aliases":["tropical whale","Balaenoptera brydei","Balaenoptera edeni"],"kind":"creature","group":"whales","fact":"Bryde's whale is named after Johan Bryde, a Norwegian who set up South Africa's first whaling stations, and it stays in warm waters all year."},"bryozoan":{"id":"bryozoan","name":"Bryozoan","aliases":["moss animal","sea mat"],"kind":"creature","group":"invertebrates","fact":"Bryozoans, or moss animals, are colonies of tiny filter feeders that form crusts and fronds, each individual catching food with a ring of tentacles."},"bubble-coral":{"id":"bubble-coral","name":"Bubble coral","aliases":["grape coral","pearl coral","Plerogyra sinuosa"],"kind":"creature","group":"corals","fact":"Bubble coral inflates grape-like bladders by day to catch sunlight for its algae and withdraws them at night to feed with its tentacles."},"bubblegum-coral":{"id":"bubblegum-coral","name":"Bubblegum coral","aliases":["bubble gum coral","Paragorgia arborea"],"kind":"creature","group":"corals","fact":"Bubblegum coral is a deep-sea soft coral that grows into pink, tree-like colonies up to several metres tall, with branch tips like blobs of chewed gum."},"buenos-aires":{"id":"buenos-aires","name":"Buenos Aires","aliases":[],"kind":"place","group":"ports","fact":"Buenos Aires sits on the Río de la Plata estuary, which opens into the Atlantic, and its name means 'fair winds'."},"bull-kelp":{"id":"bull-kelp","name":"Bull kelp","aliases":["Nereocystis luetkeana","Nereocystis","bullwhip kelp"],"kind":"plant","group":"plants","fact":"Bull kelp grows a single long stem topped by a gas-filled float the size of a grapefruit, and can reach more than 30 metres in a single season."},"bull-shark":{"id":"bull-shark","name":"Bull shark","aliases":["Zambezi shark","Lake Nicaragua shark","Carcharhinus leucas"],"kind":"creature","group":"sharks","fact":"Bull sharks can live in fresh water and have been found far up the Mississippi and Amazon rivers."},"bull-trout":{"id":"bull-trout","name":"Bull trout","aliases":["Salvelinus confluentus"],"kind":"creature","group":"fish","fact":"The bull trout is a char of cold, clean rivers in north-west North America and is so sensitive to warm water that it is listed as threatened."},"bullet-tuna":{"id":"bullet-tuna","name":"Bullet tuna","aliases":["Auxis rochei","bullet mackerel"],"kind":"creature","group":"fish","fact":"The bullet tuna is one of the smallest members of the tuna family, found worldwide in warm seas and rarely more than 50 centimetres long."},"bullethead-parrotfish":{"id":"bullethead-parrotfish","name":"Bullethead parrotfish","aliases":["Chlorurus spilurus","Pacific bullethead parrotfish"],"kind":"creature","group":"fish","fact":"The bullethead parrotfish is one of the most common Pacific parrotfish, with a blunt bullet-shaped head and a green male phase."},"bullhead-catfish":{"id":"bullhead-catfish","name":"Bullhead catfish","aliases":["bullhead","brown bullhead","black bullhead","yellow bullhead","Ameiurus","horned pout"],"kind":"creature","group":"fish","fact":"Bullheads are small, dark catfish of North American ponds and slow rivers that can survive in warm, low-oxygen water that kills other fish."},"bumblebee-goby":{"id":"bumblebee-goby","name":"Bumblebee goby","aliases":["Brachygobius","Brachygobius doriae","bumble bee goby"],"kind":"creature","group":"fish","fact":"The bumblebee goby is a banded black-and-yellow goby of Southeast Asian estuaries that grows to under 4 centimetres."},"bumphead-parrotfish":{"id":"bumphead-parrotfish","name":"Bumphead parrotfish","aliases":["green humphead parrotfish","humphead parrotfish","Bolbometopon muricatum","giant parrotfish","double-headed parrotfish"],"kind":"creature","group":"fish","fact":"The bumphead parrotfish is the largest parrotfish, reaching about 1.3 metres, and rams its forehead into coral to break it up for feeding."},"bunaken-national-park":{"id":"bunaken-national-park","name":"Bunaken National Park","aliases":["Bunaken"],"kind":"place","group":"parks","fact":"Bunaken, off Sulawesi in Indonesia, is known for coral walls that drop almost vertically into deep water right beside the shore."},"buoy-barnacle":{"id":"buoy-barnacle","name":"Buoy barnacle","aliases":["Dosima fascicularis","float barnacle"],"kind":"creature","group":"crustaceans","fact":"The buoy barnacle makes its own float, a foam of cement bubbles, and drifts across the open ocean hanging beneath it."},"burbot":{"id":"burbot","name":"Burbot","aliases":["Lota lota","lawyer","freshwater cod","eelpout cod","lawyer fish"],"kind":"creature","group":"fish","fact":"The burbot is the only member of the cod family that lives in fresh water, a bottom-dwelling, eel-like fish that spawns under the ice in midwinter."},"burmeisters-porpoise":{"id":"burmeisters-porpoise","name":"Burmeister's porpoise","aliases":["black porpoise","Phocoena spinipinnis"],"kind":"creature","group":"dolphins","fact":"Burmeister's porpoise of South America is named after German zoologist Hermann Burmeister and has a strange backward-leaning dorsal fin."},"butterfly-kingfish":{"id":"butterfly-kingfish","name":"Butterfly kingfish","aliases":["Gasterochisma melampus","butterfly mackerel","bigscale mackerel"],"kind":"creature","group":"fish","fact":"The butterfly kingfish is the oddest member of the tuna family, a cold-water Southern Ocean fish with big scales and a heater organ that warms its brain and eyes."},"butterfly-ray":{"id":"butterfly-ray","name":"Butterfly ray","aliases":["spiny butterfly ray","smooth butterfly ray","Gymnura"],"kind":"creature","group":"rays","fact":"Butterfly rays are much wider than they are long, with a very short tail, and bury themselves in sand in warm shallows."},"butterflyfish":{"id":"butterflyfish","name":"Butterflyfish","aliases":["butterfly fish","Chaetodontidae","Chaetodon"],"kind":"creature","group":"fish","fact":"Butterflyfish are thin, bright reef fish that often pair for life and use their pointed snouts to pick at coral polyps."},"by-the-wind-sailor":{"id":"by-the-wind-sailor","name":"By-the-wind sailor","aliases":["Velella velella","Velella","sea raft","purple sail","little sail"],"kind":"creature","group":"jellies","fact":"The by-the-wind sailor floats on the surface under a stiff diagonal sail, so whole fleets of them are blown ashore in the same storm."},"cabezon":{"id":"cabezon","name":"Cabezon","aliases":["Scorpaenichthys marmoratus"],"kind":"creature","group":"fish","fact":"The cabezon is a big-headed, scaleless sculpin of Pacific kelp beds whose eggs are poisonous to eat; the male guards them until they hatch."},"cabo-pulmo-national-park":{"id":"cabo-pulmo-national-park","name":"Cabo Pulmo National Park","aliases":["Cabo Pulmo"],"kind":"place","group":"parks","fact":"Cabo Pulmo in Baja California saw its fish biomass rise more than fourfold within a decade after fishing was banned, a celebrated conservation success."},"cabot-strait":{"id":"cabot-strait","name":"Cabot Strait","aliases":[],"kind":"place","group":"straits","fact":"Cabot Strait between Newfoundland and Cape Breton Island is named after the explorer John Cabot and is the main entrance to the Gulf of St Lawrence."},"cadiz":{"id":"cadiz","name":"Cádiz","aliases":[],"kind":"place","group":"ports","fact":"Cádiz, on a narrow spit into the Atlantic, was founded by the Phoenicians and is one of the oldest continuously inhabited cities in western Europe."},"calanus":{"id":"calanus","name":"Calanus","aliases":["Calanus finmarchicus"],"kind":"creature","group":"crustaceans","fact":"Calanus finmarchicus is a rice-grain-sized copepod so rich in oil that it is the main food of herring, mackerel and the North Atlantic right whale."},"california-current":{"id":"california-current","name":"California Current","aliases":[],"kind":"place","group":"currents","fact":"The California Current flows south along the US west coast, bringing cold water and the fog for which San Francisco is famous."},"california-halibut":{"id":"california-halibut","name":"California halibut","aliases":["Paralichthys californicus"],"kind":"creature","group":"fish","fact":"The California halibut is a left-eyed flounder, yet nearly half of all individuals turn out right-eyed, a quirk almost unique among flatfish."},"california-sea-lion":{"id":"california-sea-lion","name":"California sea lion","aliases":["Zalophus californianus","sea lion"],"kind":"creature","group":"seals","fact":"California sea lions are the trained 'seals' of circuses and aquarium shows and haul out in noisy crowds on San Francisco's Pier 39."},"california-sheephead":{"id":"california-sheephead","name":"California sheephead","aliases":["sheephead","Semicossyphus pulcher","Bodianus pulcher"],"kind":"creature","group":"fish","fact":"The California sheephead is a big-toothed wrasse of kelp forests that crushes sea urchins; all start life as females and the largest turn into black-and-red males."},"california-two-spot-octopus":{"id":"california-two-spot-octopus","name":"California two-spot octopus","aliases":["Octopus bimaculoides","bimac"],"kind":"creature","group":"cephalopods","fact":"The California two-spot octopus has a false blue eye-spot under each real eye and was the first octopus to have its full genome sequenced."},"calypso":{"id":"calypso","name":"Calypso","aliases":["RV Calypso"],"kind":"vessel","group":"vessels","fact":"Calypso was a former minesweeper that Jacques Cousteau turned into the floating base for his films and expeditions from 1950 until it sank in Singapore harbour in 1996."},"canary-current":{"id":"canary-current","name":"Canary Current","aliases":[],"kind":"place","group":"currents","fact":"The Canary Current flows south past north-west Africa and the Canary Islands and helped carry Columbus's ships towards the Caribbean."},"canary-islands":{"id":"canary-islands","name":"Canary Islands","aliases":["Canaries","Tenerife","Gran Canaria","Lanzarote","Fuerteventura","La Palma","La Gomera","El Hierro"],"kind":"place","group":"islands","fact":"The Canary Islands are Spanish volcanic islands off north-west Africa, named not after birds but probably after dogs, from the Latin canaria."},"candiru":{"id":"candiru","name":"Candiru","aliases":["toothpick fish","Vandellia cirrhosa","cañero","vampire catfish"],"kind":"creature","group":"fish","fact":"The candiru is a tiny, slender Amazon catfish that slips under the gill covers of larger fish to drink their blood, and is feared far out of proportion to its size."},"cannonball-jellyfish":{"id":"cannonball-jellyfish","name":"Cannonball jellyfish","aliases":["Stomolophus meleagris","cabbagehead jellyfish","jellyball"],"kind":"creature","group":"jellies","fact":"The cannonball jellyfish is fished off Georgia and Florida, dried and exported to Asia as a crunchy salad ingredient."},"canoe":{"id":"canoe","name":"Canoe","aliases":["voyaging canoe","dugout canoe","dugout"],"kind":"vessel","group":"boats","fact":"Polynesian voyagers crossed thousands of kilometres of open Pacific in double-hulled sailing canoes, settling islands as far apart as Hawaii and New Zealand."},"cape-fur-seal":{"id":"cape-fur-seal","name":"Cape fur seal","aliases":["brown fur seal","South African fur seal","Australian fur seal","Arctocephalus pusillus"],"kind":"creature","group":"seals","fact":"Cape fur seals breed in huge colonies on the coasts of South Africa and Namibia, where great whites ambush them at Seal Island."},"cape-hake":{"id":"cape-hake","name":"Cape hake","aliases":["Merluccius capensis","South African hake","shallow-water Cape hake"],"kind":"creature","group":"fish","fact":"The Cape hake is the backbone of the South African and Namibian fishing industries, caught by trawlers over the continental shelf."},"cape-town":{"id":"cape-town","name":"Cape Town","aliases":["Kaapstad"],"kind":"place","group":"ports","fact":"Cape Town's harbour on Table Bay faces the Atlantic, where the cold Benguela Current keeps the sea far chillier than on the Indian Ocean side of the Cape."},"cape-verde":{"id":"cape-verde","name":"Cape Verde","aliases":["Cabo Verde","Cape Verde Islands"],"kind":"place","group":"islands","fact":"Cape Verde is a group of ten volcanic islands off the coast of Senegal, and many Atlantic hurricanes begin as storms passing nearby."},"capelin":{"id":"capelin","name":"Capelin","aliases":["Mallotus villosus"],"kind":"creature","group":"fish","fact":"Capelin are small silvery fish that spawn on Arctic and sub-Arctic beaches in their millions and feed cod, whales and puffins."},"caravel":{"id":"caravel","name":"Caravel","aliases":[],"kind":"vessel","group":"boats","fact":"The caravel was the small, nimble Portuguese ship of the 1400s used by explorers along the African coast; Columbus's Niña and Pinta were caravels."},"cardigan-bay":{"id":"cardigan-bay","name":"Cardigan Bay","aliases":[],"kind":"place","group":"bays","fact":"Cardigan Bay is the largest bay in Wales and home to a resident population of bottlenose dolphins."},"cardinal-tetra":{"id":"cardinal-tetra","name":"Cardinal tetra","aliases":["Paracheirodon axelrodi"],"kind":"creature","group":"fish","fact":"The cardinal tetra, with red running the full length of its body, is still mostly caught wild in the Rio Negro for the aquarium trade."},"cardinalfish":{"id":"cardinalfish","name":"Cardinalfish","aliases":["cardinal fish","Apogonidae","Apogon"],"kind":"creature","group":"fish","fact":"Cardinalfish are small nocturnal reef fish, and in most species the male broods the eggs in his mouth without eating until they hatch."},"caribbean-monk-seal":{"id":"caribbean-monk-seal","name":"Caribbean monk seal","aliases":["West Indian monk seal","Neomonachus tropicalis"],"kind":"creature","group":"seals","fact":"The Caribbean monk seal was hunted for its oil and was declared extinct in 2008, the last confirmed sighting having been in 1952."},"caribbean-reef-octopus":{"id":"caribbean-reef-octopus","name":"Caribbean reef octopus","aliases":["Octopus briareus"],"kind":"creature","group":"cephalopods","fact":"The Caribbean reef octopus spreads its webbed arms like a parachute over coral heads to trap crabs and shrimp underneath."},"caribbean-reef-shark":{"id":"caribbean-reef-shark","name":"Caribbean reef shark","aliases":["Carcharhinus perezi"],"kind":"creature","group":"sharks","fact":"The Caribbean reef shark is the shark most often seen on feeding dives in the Bahamas and is rarely found outside the western Atlantic."},"caribbean-reef-squid":{"id":"caribbean-reef-squid","name":"Caribbean reef squid","aliases":["Sepioteuthis sepioidea","reef squid"],"kind":"creature","group":"cephalopods","fact":"Caribbean reef squid talk with rapidly shifting skin patterns and can show one display to a mate and another to a rival at the same time."},"caribbean-sea":{"id":"caribbean-sea","name":"Caribbean Sea","aliases":["Caribbean"],"kind":"place","group":"seas","fact":"The Caribbean Sea is a marginal sea of the Atlantic enclosed by the Antilles and Central America, and its Cayman Trough is more than 7,000 metres deep."},"caribbean-spiny-lobster":{"id":"caribbean-spiny-lobster","name":"Caribbean spiny lobster","aliases":["Panulirus argus","Florida spiny lobster","spiny lobster"],"kind":"creature","group":"crustaceans","fact":"The Caribbean spiny lobster can navigate home using the Earth's magnetic field, the first invertebrate shown to have a magnetic map sense."},"carnation-coral":{"id":"carnation-coral","name":"Carnation coral","aliases":["tree coral","Dendronephthya"],"kind":"creature","group":"corals","fact":"Carnation corals are soft corals that puff up into brilliant pink, red and purple bushes at night and collapse into limp blobs by day."},"carp":{"id":"carp","name":"Carp","aliases":["common carp","Cyprinus carpio"],"kind":"creature","group":"fish","fact":"Common carp has been farmed for food for more than 2,000 years and is still the traditional Christmas Eve dish in Poland and the Czech Republic."},"carpathia":{"id":"carpathia","name":"Carpathia","aliases":["RMS Carpathia"],"kind":"vessel","group":"wrecks","fact":"Carpathia, the ship that rescued Titanic's survivors, was itself torpedoed and sunk in the Atlantic in 1918."},"carrack":{"id":"carrack","name":"Carrack","aliases":["nao","nau"],"kind":"vessel","group":"boats","fact":"The carrack was the big, round-hulled ocean ship of the 1400s and 1500s; Columbus's Santa María and Magellan's Victoria were carracks."},"casablanca":{"id":"casablanca","name":"Casablanca","aliases":[],"kind":"place","group":"ports","fact":"Casablanca is Morocco's biggest city and its main Atlantic port, famous around the world thanks to the 1942 film."},"casper-octopus":{"id":"casper-octopus","name":"Casper octopus","aliases":["Casper the octopus","ghost octopus"],"kind":"creature","group":"cephalopods","fact":"A ghost-white octopus nicknamed Casper was discovered off Hawaii in 2016 at about 4,000 metres, laying its eggs on dead sponge stalks attached to metal nodules."},"caspian-seal":{"id":"caspian-seal","name":"Caspian seal","aliases":["Pusa caspica"],"kind":"creature","group":"seals","fact":"The Caspian seal lives only in the landlocked Caspian Sea, where it breeds on winter ice in the north."},"catamaran":{"id":"catamaran","name":"Catamaran","aliases":[],"kind":"vessel","group":"boats","fact":"A catamaran has two parallel hulls joined by a frame, a design borrowed from the fishing craft of southern India; the name comes from the Tamil for 'tied wood'."},"catfish":{"id":"catfish","name":"Catfish","aliases":["Siluriformes","cat fish"],"kind":"creature","group":"fish","fact":"Catfish are whiskered bottom-dwellers; the channel catfish is the most farmed fish in the United States, and Vietnamese basa fills supermarket freezers worldwide."},"caulerpa-taxifolia":{"id":"caulerpa-taxifolia","name":"Caulerpa taxifolia","aliases":["killer alga","killer algae","aquarium caulerpa","Caulerpa"],"kind":"plant","group":"plants","fact":"Caulerpa taxifolia, the 'killer alga', escaped from an aquarium into the Mediterranean in the 1980s and smothered thousands of hectares of seabed."},"cauliflower-coral":{"id":"cauliflower-coral","name":"Cauliflower coral","aliases":["Pocillopora","Pocillopora damicornis"],"kind":"creature","group":"corals","fact":"Cauliflower coral grows in knobbly clumps and is one of the first corals to settle on new reef, but also one of the first to bleach."},"cayman-trough":{"id":"cayman-trough","name":"Cayman Trough","aliases":["Cayman Trench","Bartlett Deep","Bartlett Trough"],"kind":"place","group":"trenches","fact":"The Cayman Trough is the deepest part of the Caribbean Sea, at about 7,500 metres, and holds the deepest known hydrothermal vents, the Beebe vent field."},"celebes-sea":{"id":"celebes-sea","name":"Celebes Sea","aliases":["Sulawesi Sea"],"kind":"place","group":"seas","fact":"The Celebes Sea between Indonesia and the Philippines is a deep basin of more than 6,000 metres, famous for the rich reefs around Sipadan."},"celestial-pearl-danio":{"id":"celestial-pearl-danio","name":"Celestial pearl danio","aliases":["galaxy rasbora","Danio margaritatus","Celestichthys margaritatus"],"kind":"creature","group":"fish","fact":"The celestial pearl danio, a 2-centimetre fish spangled with pearly spots, was found in Myanmar in 2006 and caused such a craze that it was nearly collected to extinction."},"celtic-sea":{"id":"celtic-sea","name":"Celtic Sea","aliases":[],"kind":"place","group":"seas","fact":"The Celtic Sea lies south of Ireland and west of Cornwall and was only given its name in 1921."},"cenderawasih-bay":{"id":"cenderawasih-bay","name":"Cenderawasih Bay","aliases":["Cendrawasih Bay","Teluk Cenderawasih","Geelvink Bay"],"kind":"place","group":"bays","fact":"Cenderawasih Bay in Indonesian New Guinea is famous for whale sharks that gather beneath fishing platforms to feed on baitfish."},"cero":{"id":"cero","name":"Cero","aliases":["cero mackerel","Scomberomorus regalis"],"kind":"creature","group":"fish","fact":"The cero is a Spanish mackerel of the Caribbean with a row of yellow-orange streaks and spots along its sides."},"chagos-marine-protected-area":{"id":"chagos-marine-protected-area","name":"Chagos Marine Protected Area","aliases":["Chagos","Chagos Archipelago","British Indian Ocean Territory"],"kind":"place","group":"parks","fact":"The Chagos Archipelago in the Indian Ocean was declared a no-take marine reserve in 2010 around some of the cleanest coral reefs in the world."},"chain-moray":{"id":"chain-moray","name":"Chain moray","aliases":["chain eel","Echidna catenata"],"kind":"creature","group":"fish","fact":"The chain moray of the Caribbean, patterned with yellow chain links, can leave the water to hunt crabs on rocks at low tide."},"chalk-bass":{"id":"chalk-bass","name":"Chalk bass","aliases":["Serranus tortugarum"],"kind":"creature","group":"fish","fact":"The chalk bass is a tiny Caribbean sea bass, barely 8 centimetres long, that is both male and female at once and takes turns laying eggs with its partner."},"challenger-deep":{"id":"challenger-deep","name":"Challenger Deep","aliases":[],"kind":"place","group":"trenches","fact":"Challenger Deep, the floor of the Mariana Trench, was first reached by Jacques Piccard and Don Walsh in the bathyscaphe Trieste in 1960."},"chambered-nautilus":{"id":"chambered-nautilus","name":"Chambered nautilus","aliases":["Nautilus pompilius","pearly nautilus","emperor nautilus"],"kind":"creature","group":"cephalopods","fact":"The chambered nautilus adds new chambers to its spiral shell as it grows and adjusts the gas inside them to rise and sink."},"channel-catfish":{"id":"channel-catfish","name":"Channel catfish","aliases":["Ictalurus punctatus","channel cat","catfish"],"kind":"creature","group":"fish","fact":"The channel catfish is the most farmed fish in the United States and the official state fish of several southern and midwestern states."},"channel-islands":{"id":"channel-islands","name":"Channel Islands","aliases":["Jersey","Guernsey","Sark","Alderney"],"kind":"place","group":"islands","fact":"The Channel Islands of Jersey, Guernsey, Alderney and Sark lie off Normandy and were the only British soil occupied by Germany in the Second World War."},"channel-islands-national-marine-sanctuary":{"id":"channel-islands-national-marine-sanctuary","name":"Channel Islands National Marine Sanctuary","aliases":["Channel Islands"],"kind":"place","group":"parks","fact":"The Channel Islands National Marine Sanctuary off southern California protects kelp forests where cold northern and warm southern currents meet."},"channelled-wrack":{"id":"channelled-wrack","name":"Channelled wrack","aliases":["channel wrack","Pelvetia canaliculata","Pelvetia"],"kind":"plant","group":"plants","fact":"Channelled wrack lives at the very top of the shore, where it can dry out for days between tides and still revive."},"charles-wyville-thomson":{"id":"charles-wyville-thomson","name":"Charles Wyville Thomson","aliases":["Wyville Thomson"],"kind":"person","group":"people","fact":"Charles Wyville Thomson was the chief scientist of the Challenger expedition of 1872 to 1876, which laid the foundations of oceanography."},"charleston":{"id":"charleston","name":"Charleston","aliases":[],"kind":"place","group":"ports","fact":"Charleston's harbour, where the Ashley and Cooper rivers meet the Atlantic, saw the first shots of the American Civil War at Fort Sumter in 1861."},"chatham-islands":{"id":"chatham-islands","name":"Chatham Islands","aliases":["Chathams","Rekohu"],"kind":"place","group":"islands","fact":"The Chatham Islands east of New Zealand are among the first inhabited places on Earth to see each new day."},"chatham-rise":{"id":"chatham-rise","name":"Chatham Rise","aliases":[],"kind":"place","group":"features","fact":"The Chatham Rise is a broad submarine plateau east of New Zealand that supports one of the country's most important fishing grounds, including hoki."},"chemosynthetic-bacteria":{"id":"chemosynthetic-bacteria","name":"Chemosynthetic bacteria","aliases":["bacteria","vent bacteria","sulphur bacteria","chemosynthetic microbes","sulfur bacteria"],"kind":"creature","group":"microbes","fact":"Chemosynthetic bacteria make food from the hydrogen sulphide in vent water instead of from sunlight, feeding every animal at a hydrothermal vent."},"cherry-barb":{"id":"cherry-barb","name":"Cherry barb","aliases":["Puntius titteya"],"kind":"creature","group":"fish","fact":"The cherry barb, a small red fish from Sri Lankan streams, is far more common in aquariums than in the wild."},"chesapeake-bay":{"id":"chesapeake-bay","name":"Chesapeake Bay","aliases":["Chesapeake"],"kind":"place","group":"bays","fact":"Chesapeake Bay is the largest estuary in the United States and is famous for its blue crabs and oysters."},"chikyu":{"id":"chikyu","name":"Chikyu","aliases":[],"kind":"vessel","group":"vessels","fact":"Chikyu is a Japanese drilling ship with a derrick about 120 metres above the water, built to drill deeper into the sea floor than any ship before it."},"chilean-dolphin":{"id":"chilean-dolphin","name":"Chilean dolphin","aliases":["black dolphin","tonina","Cephalorhynchus eutropia"],"kind":"creature","group":"dolphins","fact":"The Chilean dolphin is a small, shy dolphin of Chile's fjords, channels and estuaries and is found nowhere else."},"chilean-jack-mackerel":{"id":"chilean-jack-mackerel","name":"Chilean jack mackerel","aliases":["jack mackerel","jurel","Trachurus murphyi","Inca scad"],"kind":"creature","group":"fish","fact":"The Chilean jack mackerel supported one of the largest fisheries in the world in the 1990s, with catches of about 5 million tonnes, before the stock crashed."},"chili-rasbora":{"id":"chili-rasbora","name":"Chili rasbora","aliases":["chilli rasbora","mosquito rasbora","Boraras brigittae"],"kind":"creature","group":"fish","fact":"The chili rasbora of Borneo's blackwater streams is a brilliant red fish barely 2 centimetres long, one of the smallest aquarium fish."},"chimaera":{"id":"chimaera","name":"Chimaera","aliases":["ghost shark","chimera","ratfish","spotted ratfish","Chimaeriformes"],"kind":"creature","group":"fish","fact":"Chimaeras, or ghost sharks, are cartilaginous deep-water relatives of sharks with electric-sensing pores on their rabbit-like heads."},"chinese-mitten-crab":{"id":"chinese-mitten-crab","name":"Chinese mitten crab","aliases":["Eriocheir sinensis","mitten crab","hairy crab","Shanghai hairy crab"],"kind":"creature","group":"crustaceans","fact":"The Chinese mitten crab has furry claws, lives in rivers but breeds in the sea, and has invaded the Thames, the Elbe and San Francisco Bay."},"chinese-sturgeon":{"id":"chinese-sturgeon","name":"Chinese sturgeon","aliases":["Acipenser sinensis"],"kind":"creature","group":"fish","fact":"The Chinese sturgeon, which migrates between the sea and the Yangtze, is critically endangered since dams blocked its spawning grounds."},"chinook-salmon":{"id":"chinook-salmon","name":"Chinook salmon","aliases":["chinook","king salmon","spring salmon","Oncorhynchus tshawytscha"],"kind":"creature","group":"fish","fact":"The chinook, or king salmon, is the largest Pacific salmon and some swim about 3,000 kilometres up the Yukon River to spawn."},"chinstrap-penguin":{"id":"chinstrap-penguin","name":"Chinstrap penguin","aliases":["Pygoscelis antarcticus"],"kind":"creature","group":"seabirds","fact":"Chinstrap penguins feed almost entirely on krill, and their numbers have crashed as warming has thinned the krill swarms near the Antarctic Peninsula."},"chiton":{"id":"chiton","name":"Chiton","aliases":["coat-of-mail shell","sea cradle","Polyplacophora"],"kind":"creature","group":"molluscs","fact":"Chitons wear a shell of eight overlapping plates and can roll into a ball like a woodlouse when prised from a rock."},"chocolate-chip-sea-star":{"id":"chocolate-chip-sea-star","name":"Chocolate chip sea star","aliases":["chocolate chip starfish","horned sea star","Protoreaster nodosus"],"kind":"creature","group":"echinoderms","fact":"The chocolate chip sea star gets its name from the dark, knobbly spines dotted across its back like chocolate chips."},"chokka-squid":{"id":"chokka-squid","name":"Chokka squid","aliases":["Loligo reynaudii","Cape Hope squid","chokka"],"kind":"creature","group":"cephalopods","fact":"Chokka squid gather in huge spawning swarms off South Africa's southern coast, where they are hand-jigged for export as calamari."},"christmas-island-red-crab":{"id":"christmas-island-red-crab","name":"Christmas Island red crab","aliases":["red crab","Gecarcoidea natalis"],"kind":"creature","group":"crustaceans","fact":"Tens of millions of Christmas Island red crabs march from the forest to the sea each year to breed, closing roads across the island."},"christmas-tree-worm":{"id":"christmas-tree-worm","name":"Christmas tree worm","aliases":["Spirobranchus giganteus","Spirobranchus"],"kind":"creature","group":"worms","fact":"The Christmas tree worm lives in a tube bored into coral and unfurls two spiral crowns of tentacles that snap back inside in a blink."},"christopher-columbus":{"id":"christopher-columbus","name":"Christopher Columbus","aliases":["Columbus","Cristoforo Colombo","Cristóbal Colón"],"kind":"person","group":"people","fact":"Christopher Columbus crossed the Atlantic in 1492 on a voyage that opened lasting contact between Europe and the Americas."},"chub":{"id":"chub","name":"Chub","aliases":["European chub","Squalius cephalus"],"kind":"creature","group":"fish","fact":"The chub is a big-mouthed European river fish that will eat almost anything, from cherries to small fish."},"chub-mackerel":{"id":"chub-mackerel","name":"Chub mackerel","aliases":["Pacific mackerel","Scomber japonicus","Pacific chub mackerel"],"kind":"creature","group":"fish","fact":"The chub mackerel is one of the world's biggest fish catches, taken in huge numbers off Japan, Chile and Peru, and is the saba of Japanese sushi bars."},"chum-salmon":{"id":"chum-salmon","name":"Chum salmon","aliases":["dog salmon","keta salmon","keta","Oncorhynchus keta"],"kind":"creature","group":"fish","fact":"Chum salmon have the widest range of any Pacific salmon, from California to Korea, and spawning males develop tiger-like purple stripes."},"cichlid":{"id":"cichlid","name":"Cichlid","aliases":["Cichlidae","African cichlid"],"kind":"creature","group":"fish","fact":"Many cichlids, from African lakes to the Amazon, brood their eggs and fry in their mouths or guard them fiercely as a pair."},"cinnamon-clownfish":{"id":"cinnamon-clownfish","name":"Cinnamon clownfish","aliases":["fire clownfish","red and black anemonefish","Amphiprion melanopus","cinnamon anemonefish"],"kind":"creature","group":"fish","fact":"The cinnamon clownfish, or fire clownfish, is a dark red-brown anemonefish with one white head bar and a bluish tint, from the western Pacific."},"cisco":{"id":"cisco","name":"Cisco","aliases":["lake herring","Coregonus artedi"],"kind":"creature","group":"fish","fact":"The cisco, or lake herring, schools in cold North American lakes and is a whitefish rather than a true herring."},"cladoselache":{"id":"cladoselache","name":"Cladoselache","aliases":[],"kind":"creature","group":"sharks","fact":"Cladoselache is one of the earliest well-known sharks, preserved in Devonian shales around Cleveland, Ohio, about 370 million years old."},"clam":{"id":"clam","name":"Clam","aliases":["bivalve","hard clam","soft-shell clam","littleneck"],"kind":"creature","group":"molluscs","fact":"Clams pull themselves through sand with a muscular foot and draw in water through a siphon to filter out food."},"clarion-angelfish":{"id":"clarion-angelfish","name":"Clarion angelfish","aliases":["Holacanthus clarionensis"],"kind":"creature","group":"fish","fact":"The clarion angelfish lives only around Mexico's Revillagigedo Islands and Clipperton, where it cleans parasites from giant manta rays."},"clarks-anemonefish":{"id":"clarks-anemonefish","name":"Clark's anemonefish","aliases":["Clark's clownfish","yellowtail clownfish","Amphiprion clarkii","clarkii"],"kind":"creature","group":"fish","fact":"Clark's anemonefish is the least fussy clownfish, able to live in all ten species of host anemone, and ranges from the Persian Gulf to Japan."},"clawed-armhook-squid":{"id":"clawed-armhook-squid","name":"Clawed armhook squid","aliases":["Gonatus onyx","black-eyed squid"],"kind":"creature","group":"cephalopods","fact":"The clawed armhook squid was the first squid seen brooding its eggs, carrying a sac of thousands of eggs in its arms for months in the deep."},"cleaner-shrimp":{"id":"cleaner-shrimp","name":"Cleaner shrimp","aliases":["Pacific cleaner shrimp","skunk cleaner shrimp","Lysmata amboinensis","scarlet skunk cleaner shrimp","scarlet cleaner shrimp"],"kind":"creature","group":"crustaceans","fact":"Cleaner shrimp wave their white antennae to advertise a cleaning service, and reef fish queue up and open their mouths to have parasites picked off."},"cleaner-wrasse":{"id":"cleaner-wrasse","name":"Cleaner wrasse","aliases":["bluestreak cleaner wrasse","cleaner fish","Labroides dimidiatus","blue streak cleaner wrasse","common cleaner wrasse"],"kind":"creature","group":"fish","fact":"The bluestreak cleaner wrasse runs a cleaning station where bigger fish queue to have parasites picked from their skin, gills and even mouths."},"climbing-perch":{"id":"climbing-perch","name":"Climbing perch","aliases":["climbing gourami","Anabas testudineus"],"kind":"creature","group":"fish","fact":"The climbing perch breathes air and can travel over land between ponds, pulling itself along with its gill covers and fins."},"clingfish":{"id":"clingfish","name":"Clingfish","aliases":["northern clingfish"],"kind":"creature","group":"fish","fact":"The northern clingfish grips wet, slimy rock with a suction disc on its belly strong enough to hold many times its own weight."},"clipper-ship":{"id":"clipper-ship","name":"Clipper ship","aliases":["clipper","tea clipper"],"kind":"vessel","group":"boats","fact":"Clipper ships were the fast sailing ships of the mid-1800s, built for speed on the tea and wool runs; Cutty Sark is the most famous survivor."},"clipperton-island":{"id":"clipperton-island","name":"Clipperton Island","aliases":["Clipperton","Île de la Passion"],"kind":"place","group":"islands","fact":"Clipperton Island is a tiny uninhabited French atoll in the eastern Pacific, more than 1,000 kilometres from Mexico, ringed by a lagoon and overrun by land crabs."},"clown-killifish":{"id":"clown-killifish","name":"Clown killifish","aliases":["clown killie","banded panchax","rocket killifish","Epiplatys annulatus","Pseudepiplatys annulatus"],"kind":"creature","group":"fish","fact":"The clown killifish is a 3-centimetre West African fish with a banded body and a rocket-flame tail that spends its life just under the surface."},"clown-loach":{"id":"clown-loach","name":"Clown loach","aliases":["Chromobotia macracanthus"],"kind":"creature","group":"fish","fact":"The clown loach, orange with black bands, clicks audibly, sleeps on its side and can grow to 30 centimetres."},"clown-triggerfish":{"id":"clown-triggerfish","name":"Clown triggerfish","aliases":["Balistoides conspicillum"],"kind":"creature","group":"fish","fact":"The clown triggerfish has large white spots on its black belly and a yellow mouth, making it one of the most recognisable reef fish."},"clownfish":{"id":"clownfish","name":"Clownfish","aliases":["anemonefish","clown anemonefish","Nemo","Amphiprion","clown fish","ocellaris clownfish","false percula","Amphiprion ocellaris"],"kind":"creature","group":"fish","fact":"Clownfish are immune to the stings of their host anemone, and if the female of a group dies the largest male changes sex to take her place."},"clymene-dolphin":{"id":"clymene-dolphin","name":"Clymene dolphin","aliases":["short-snouted spinner dolphin","Stenella clymene"],"kind":"creature","group":"dolphins","fact":"The Clymene dolphin of the Atlantic is the only confirmed case of a marine mammal species that arose as a hybrid, from spinner and striped dolphins."},"cobb-seamount":{"id":"cobb-seamount","name":"Cobb Seamount","aliases":[],"kind":"place","group":"features","fact":"Cobb Seamount, about 500 kilometres off Washington State, is a flat-topped underwater volcano whose summit lies just a few dozen metres below the surface."},"cobia":{"id":"cobia","name":"Cobia","aliases":["Rachycentron canadum","black kingfish","ling cobia","lemonfish"],"kind":"creature","group":"fish","fact":"Cobia is a fast-growing open-water fish now farmed in sea cages in Vietnam, Taiwan and Panama for its firm white flesh."},"coccolithophore":{"id":"coccolithophore","name":"Coccolithophore","aliases":["coccolith"],"kind":"plant","group":"plankton","fact":"Coccolithophores are single-celled algae armoured with chalk discs, and their blooms can turn whole seas milky white in satellite images."},"cockle":{"id":"cockle","name":"Cockle","aliases":["common cockle","Cerastoderma edule","Cerastoderma"],"kind":"creature","group":"molluscs","fact":"Cockles live buried just under the sand of tidal flats and can leap away from predators by flexing their foot."},"coconut-crab":{"id":"coconut-crab","name":"Coconut crab","aliases":["robber crab","Birgus latro","palm thief"],"kind":"creature","group":"crustaceans","fact":"The coconut crab is the largest land-living arthropod, climbs trees and cracks coconuts with claws whose pinch, estimated at up to about 3,300 newtons, is stronger than most animals' bites."},"coconut-octopus":{"id":"coconut-octopus","name":"Coconut octopus","aliases":["veined octopus","Amphioctopus marginatus"],"kind":"creature","group":"cephalopods","fact":"The coconut octopus carries coconut shells across the seabed to use as a portable shelter, one of the clearest examples of tool use in an invertebrate."},"cocos-island":{"id":"cocos-island","name":"Cocos Island","aliases":["Isla del Coco","Cocos Island National Park"],"kind":"place","group":"parks","fact":"Cocos Island, about 550 kilometres off Costa Rica, is a World Heritage site where divers come for huge schools of scalloped hammerheads."},"cod":{"id":"cod","name":"Cod","aliases":["Atlantic cod","Gadus morhua","codfish"],"kind":"creature","group":"fish","fact":"Atlantic cod built the economies of Newfoundland and New England and is the classic fish of British fish and chips; its stocks collapsed off Canada in 1992."},"coelacanth":{"id":"coelacanth","name":"Coelacanth","aliases":["Latimeria","Latimeria chalumnae","gombessa","West Indian Ocean coelacanth"],"kind":"creature","group":"fish","fact":"The coelacanth was thought extinct for 66 million years until a fisherman landed one off South Africa in 1938; it lives in caves around 200 metres down."},"cog":{"id":"cog","name":"Cog","aliases":["Hanseatic cog"],"kind":"vessel","group":"boats","fact":"The cog was the sturdy single-masted cargo ship of the medieval Hanseatic League, trading across the North Sea and the Baltic."},"coho-salmon":{"id":"coho-salmon","name":"Coho salmon","aliases":["coho","silver salmon","Oncorhynchus kisutch"],"kind":"creature","group":"fish","fact":"Coho, or silver salmon, spend about a year in fresh water and roughly 18 months at sea before returning to spawn with hooked jaws and red flanks."},"cold-seep-tubeworm":{"id":"cold-seep-tubeworm","name":"Cold-seep tubeworm","aliases":["Lamellibrachia","Lamellibrachia luymesi","seep tubeworm"],"kind":"creature","group":"worms","fact":"Tubeworms at cold seeps in the Gulf of Mexico grow so slowly that some are estimated to be more than 200 years old, among the longest-lived of all animals."},"coleman-shrimp":{"id":"coleman-shrimp","name":"Coleman shrimp","aliases":["Periclimenes colemani"],"kind":"creature","group":"crustaceans","fact":"Coleman shrimps live in pairs on the venomous fire urchin, clearing a patch of spines to sit among its brilliant colours."},"colossal-squid":{"id":"colossal-squid","name":"Colossal squid","aliases":["Mesonychoteuthis hamiltoni","Antarctic colossal squid","Antarctic squid"],"kind":"creature","group":"cephalopods","fact":"The colossal squid of the Southern Ocean is the heaviest invertebrate on Earth, reaching about 500 kilograms, with swivelling hooks on its tentacles."},"columbus-crab":{"id":"columbus-crab","name":"Columbus crab","aliases":["Planes minutus","gulfweed crab"],"kind":"creature","group":"crustaceans","fact":"The Columbus crab lives on floating sargassum and on the backs of loggerhead turtles, hitching rides across the open Atlantic."},"comb-jelly":{"id":"comb-jelly","name":"Comb jelly","aliases":["ctenophore","sea gooseberry","sea walnut","Ctenophora"],"kind":"creature","group":"jellies","fact":"Comb jellies are not true jellyfish: they swim with eight rows of beating cilia that scatter light into rainbows, and most species also glow blue in the dark."},"commersons-dolphin":{"id":"commersons-dolphin","name":"Commerson's dolphin","aliases":["panda dolphin","skunk dolphin","jacobita","Cephalorhynchus commersonii"],"kind":"creature","group":"dolphins","fact":"Commerson's dolphin, with its black-and-white panda colouring, lives off Patagonia and, oddly, in the far-off Kerguelen Islands."},"common-cuttlefish":{"id":"common-cuttlefish","name":"Common cuttlefish","aliases":["European common cuttlefish","Sepia officinalis","cuttlefish","European cuttlefish"],"kind":"creature","group":"cephalopods","fact":"The common cuttlefish has W-shaped pupils and can send rippling waves of colour across its skin even though it is thought to be colour-blind."},"common-dolphin":{"id":"common-dolphin","name":"Common dolphin","aliases":["short-beaked common dolphin","saddleback dolphin","Delphinus delphis"],"kind":"creature","group":"dolphins","fact":"Common dolphins have a bold hourglass pattern on their sides and gather in superpods of thousands."},"common-guillemot":{"id":"common-guillemot","name":"Common guillemot","aliases":["guillemot","common murre","murre","Uria aalge"],"kind":"creature","group":"seabirds","fact":"Common guillemots, called murres in North America, swim down after fish to depths of over 100 metres and lay a single pointed egg on a bare cliff ledge."},"common-loon":{"id":"common-loon","name":"Common loon","aliases":["loon","great northern diver","diver","Gavia immer"],"kind":"creature","group":"birds","fact":"The common loon, or great northern diver, breeds on lakes but winters on the sea, chasing fish underwater with powerful kicks of its feet."},"common-octopus":{"id":"common-octopus","name":"Common octopus","aliases":["Octopus vulgaris","octopus"],"kind":"creature","group":"cephalopods","fact":"The common octopus can squeeze through any gap larger than its beak and is a famous escape artist in aquariums and research labs."},"common-prawn":{"id":"common-prawn","name":"Common prawn","aliases":["Palaemon serratus"],"kind":"creature","group":"crustaceans","fact":"The common prawn of European rock pools is almost transparent with faint stripes, and is netted along British and Irish coasts for the table."},"common-skate":{"id":"common-skate","name":"Common skate","aliases":["blue skate","Dipturus batis"],"kind":"creature","group":"rays","fact":"The common skate, once abundant in European seas, can grow over 2 metres long and is now critically endangered."},"common-starfish":{"id":"common-starfish","name":"Common starfish","aliases":["common sea star","Asterias rubens"],"kind":"creature","group":"echinoderms","fact":"The common starfish of the North Atlantic pries open mussels and pushes its stomach out through its mouth to digest them inside the shell."},"common-stingray":{"id":"common-stingray","name":"Common stingray","aliases":["Dasyatis pastinaca"],"kind":"creature","group":"rays","fact":"The common stingray of the eastern Atlantic and Mediterranean was described by ancient Greek and Roman writers, who feared its venomous spine."},"common-sunstar":{"id":"common-sunstar","name":"Common sunstar","aliases":["sunstar","sun star","Crossaster papposus"],"kind":"creature","group":"echinoderms","fact":"The common sunstar has between about 8 and 14 arms ringed in red and white and preys on other starfish."},"common-thresher-shark":{"id":"common-thresher-shark","name":"Common thresher shark","aliases":["common thresher","Atlantic thresher","fox shark","Alopias vulpinus"],"kind":"creature","group":"sharks","fact":"The common thresher's scythe-like upper tail lobe can make up half of its total length."},"compass-jellyfish":{"id":"compass-jellyfish","name":"Compass jellyfish","aliases":["Chrysaora hysoscella"],"kind":"creature","group":"jellies","fact":"The compass jellyfish has brown V-shaped markings radiating across its bell like the points of a compass, and it starts life male and becomes female."},"conch":{"id":"conch","name":"Conch","aliases":["queen conch","Lobatus gigas","Aliger gigas","Strombus gigas","pink conch"],"kind":"creature","group":"molluscs","fact":"The queen conch builds a heavy pink-lipped shell and hops along the seabed by pole-vaulting on a claw-like foot."},"cone-snail":{"id":"cone-snail","name":"Cone snail","aliases":["cone shell","geography cone","Conus"],"kind":"creature","group":"molluscs","fact":"Cone snails fire a venomous harpoon from their beautiful shells, and a few species can kill a person."},"conger-eel":{"id":"conger-eel","name":"Conger eel","aliases":["conger","anago","Congridae","European conger","Conger conger"],"kind":"creature","group":"fish","fact":"Conger eel, anago, is a saltwater eel simmered until soft and served with a sweet sauce in sushi; it is leaner than freshwater unagi."},"conodont":{"id":"conodont","name":"Conodont","aliases":[],"kind":"creature","group":"fish","fact":"Conodonts were eel-like early vertebrates known mainly from tiny tooth-like fossils, which geologists use to date rocks."},"container-ship":{"id":"container-ship","name":"Container ship","aliases":["containership","box ship","box boat"],"kind":"vessel","group":"boats","fact":"The biggest container ships are about 400 metres long and can carry more than 20,000 standard shipping containers."},"convict-cichlid":{"id":"convict-cichlid","name":"Convict cichlid","aliases":["zebra cichlid","Amatitlania nigrofasciata"],"kind":"creature","group":"fish","fact":"The convict cichlid, striped like a prison uniform, breeds so readily that it is used to study parental care in fish."},"convict-tang":{"id":"convict-tang","name":"Convict tang","aliases":["convict surgeonfish","Acanthurus triostegus","manini"],"kind":"creature","group":"fish","fact":"The convict tang is a pale surgeonfish with black bars like a prisoner's uniform that grazes in huge schools that overwhelm territorial damselfish."},"cook-islands":{"id":"cook-islands","name":"Cook Islands","aliases":["Rarotonga","Aitutaki"],"kind":"place","group":"islands","fact":"The Cook Islands are 15 islands in the South Pacific named after Captain James Cook and self-governing in free association with New Zealand."},"cook-strait":{"id":"cook-strait","name":"Cook Strait","aliases":[],"kind":"place","group":"straits","fact":"Cook Strait separates New Zealand's North and South Islands and is named after Captain James Cook, who sailed through it in 1770."},"cookiecutter-shark":{"id":"cookiecutter-shark","name":"Cookiecutter shark","aliases":["cookie cutter shark","cigar shark","Isistius brasiliensis"],"kind":"creature","group":"sharks","fact":"The small cookiecutter shark bites neat round plugs of flesh out of whales, tuna and even the rubber domes of submarines."},"copepod":{"id":"copepod","name":"Copepod","aliases":["Copepoda"],"kind":"creature","group":"crustaceans","fact":"Copepods are the most numerous animals in the sea by a wide margin, and have been found in the mud at the bottom of the Challenger Deep."},"copperband-butterflyfish":{"id":"copperband-butterflyfish","name":"Copperband butterflyfish","aliases":["copperband","beaked coralfish","Chelmon rostratus","beaked butterflyfish"],"kind":"creature","group":"fish","fact":"The copperband butterflyfish has a long snout for picking food from crevices and a false eyespot on its dorsal fin; aquarists use it to eat pest anemones."},"coracle":{"id":"coracle","name":"Coracle","aliases":[],"kind":"vessel","group":"boats","fact":"A coracle is a small, round boat of woven wood covered in hide or canvas, still used by a few fishermen in Wales and India."},"coral":{"id":"coral","name":"Coral","aliases":["stony coral","hard coral"],"kind":"creature","group":"corals","fact":"Coral is built by tiny animals called polyps, each a ring of stinging tentacles around a mouth, which together lay down reefs visible from space."},"coral-beauty":{"id":"coral-beauty","name":"Coral beauty","aliases":["coral beauty angelfish","Centropyge bispinosa","twospined angelfish","dusky angelfish"],"kind":"creature","group":"fish","fact":"The coral beauty is a hardy dwarf angelfish, purple-blue with an orange belly, that is one of the most commonly kept marine angelfish."},"coral-catshark":{"id":"coral-catshark","name":"Coral catshark","aliases":["Atelomycterus marmoratus"],"kind":"creature","group":"sharks","fact":"The coral catshark hides in reef crevices by day and is small enough that it is often kept in home aquariums."},"coral-goby":{"id":"coral-goby","name":"Coral goby","aliases":["clown goby","Gobiodon"],"kind":"creature","group":"fish","fact":"Coral gobies are tiny fish that live their whole lives among the branches of a single Acropora coral colony, which they defend from seaweed."},"coral-hind":{"id":"coral-hind","name":"Coral hind","aliases":["miniata grouper","Cephalopholis miniata","coral cod","jewel grouper"],"kind":"creature","group":"fish","fact":"The coral hind is a vivid orange-red grouper covered in bright blue spots, common on Indo-Pacific and Red Sea reefs."},"coral-sea":{"id":"coral-sea","name":"Coral Sea","aliases":[],"kind":"place","group":"seas","fact":"The Coral Sea off north-east Australia contains the Great Barrier Reef, and a 1942 battle fought there was the first in which opposing ships never sighted each other."},"coral-trout":{"id":"coral-trout","name":"Coral trout","aliases":["leopard coral grouper","leopard coralgrouper","Plectropomus leopardus","common coral trout","coral grouper"],"kind":"creature","group":"fish","fact":"The coral trout is a red, blue-spotted grouper of the Great Barrier Reef, not a trout at all, and one of the most valuable fish in Queensland's reef fishery."},"coralline-algae":{"id":"coralline-algae","name":"Coralline algae","aliases":["coralline alga","coralline seaweed","Corallinales"],"kind":"plant","group":"plants","fact":"Coralline algae are red seaweeds that lay down hard limestone skeletons, cementing coral reefs together like pink mortar."},"cork":{"id":"cork","name":"Cork","aliases":[],"kind":"place","group":"ports","fact":"Cork harbour is one of the largest natural harbours in the world, and Cobh at its mouth was the Titanic's last port of call."},"corkwing-wrasse":{"id":"corkwing-wrasse","name":"Corkwing wrasse","aliases":["Symphodus melops","corkwing"],"kind":"creature","group":"fish","fact":"The corkwing wrasse of European coasts builds a nest of seaweed in a rock crevice, which the male guards until the eggs hatch."},"cormorant":{"id":"cormorant","name":"Cormorant","aliases":["shag"],"kind":"creature","group":"seabirds","fact":"Cormorants have feathers that soak up water, which helps them dive after fish, so they stand with wings spread to dry afterwards."},"cornetfish":{"id":"cornetfish","name":"Cornetfish","aliases":["flutemouth","Fistularia"],"kind":"creature","group":"fish","fact":"The cornetfish is an extremely slender reef fish up to 1.5 metres long, with a tubular snout and a whip-like filament trailing from its tail."},"corvina":{"id":"corvina","name":"Corvina","aliases":["corvina drum","Cilus gilberti"],"kind":"creature","group":"fish","fact":"Corvinas are drum fish of the eastern Pacific and elsewhere that croak with swim-bladder muscles, and some gather in deafening spawning choruses."},"corydoras":{"id":"corydoras","name":"Corydoras","aliases":["cory catfish","cory","corydoras catfish","cory cat"],"kind":"creature","group":"fish","fact":"Corydoras catfish dart to the surface to gulp air and absorb the oxygen through the lining of the gut."},"costa-concordia":{"id":"costa-concordia","name":"Costa Concordia","aliases":[],"kind":"vessel","group":"wrecks","fact":"The cruise ship Costa Concordia struck rocks and capsized off the Italian island of Giglio in January 2012; it was refloated two years later and scrapped."},"cownose-ray":{"id":"cownose-ray","name":"Cownose ray","aliases":["cownose","Rhinoptera bonasus","cow-nosed ray"],"kind":"creature","group":"rays","fact":"Cownose rays migrate in schools of thousands along the US east coast and feed by digging clams out of the sand."},"cowrie":{"id":"cowrie","name":"Cowrie","aliases":["cowry","money cowrie","tiger cowrie","Cypraea"],"kind":"creature","group":"molluscs","fact":"Cowrie shells stay smooth and glossy because the living animal wraps its mantle over the outside, and they once served as money across Africa and Asia."},"cowtail-stingray":{"id":"cowtail-stingray","name":"Cowtail stingray","aliases":["feathertail stingray","Pastinachus sephen"],"kind":"creature","group":"rays","fact":"The cowtail stingray has a flap of skin under its tail like a feather, and its rough skin has been used to make shagreen leather."},"cozumel-reefs-national-park":{"id":"cozumel-reefs-national-park","name":"Cozumel Reefs National Park","aliases":["Cozumel","Palancar Reef"],"kind":"place","group":"parks","fact":"Cozumel's reefs off Mexico's Yucatán are known for drift diving, where the current carries divers along walls such as Palancar and Santa Rosa."},"crab":{"id":"crab","name":"Crab","aliases":["kani"],"kind":"creature","group":"crustaceans","fact":"Crabs must shed their hard shells to grow, hiding away while the soft new shell underneath hardens."},"crab-boat":{"id":"crab-boat","name":"Crab boat","aliases":["crabber","crab fishing boat"],"kind":"vessel","group":"boats","fact":"Crab boats work the Bering Sea in winter, hauling heavy steel pots in freezing seas, a job made famous by the television series Deadliest Catch."},"crab-eating-macaque":{"id":"crab-eating-macaque","name":"Crab-eating macaque","aliases":["long-tailed macaque","Macaca fascicularis"],"kind":"creature","group":"mammals","fact":"Crab-eating macaques forage in South-East Asian mangroves at low tide, cracking crabs and shellfish, and some use stone tools to do it."},"crab-larva":{"id":"crab-larva","name":"Crab larva","aliases":["crab larvae","zoea","megalopa"],"kind":"creature","group":"plankton","fact":"Crab larvae, called zoea, drift in the plankton wearing a spiky helmet and look nothing like the adults they will become."},"crabeater-seal":{"id":"crabeater-seal","name":"Crabeater seal","aliases":["Lobodon carcinophaga","crabeater"],"kind":"creature","group":"seals","fact":"Crabeater seals do not eat crabs at all; they strain krill through their intricately lobed teeth and are probably the most numerous seal on Earth."},"crayfish":{"id":"crayfish","name":"Crayfish","aliases":["crawfish","crawdad","mudbug","freshwater crayfish","red swamp crayfish","Louisiana crayfish","Procambarus clarkii"],"kind":"creature","group":"crustaceans","fact":"Crayfish are freshwater relatives of lobsters, and Louisiana alone boils up tens of thousands of tonnes of them every year."},"creole-wrasse":{"id":"creole-wrasse","name":"Creole wrasse","aliases":["Clepticus parrae"],"kind":"creature","group":"fish","fact":"The creole wrasse is a purple Caribbean wrasse that, unlike most wrasses, feeds in schools on plankton high above the reef."},"cretoxyrhina":{"id":"cretoxyrhina","name":"Cretoxyrhina","aliases":["ginsu shark"],"kind":"creature","group":"sharks","fact":"Cretoxyrhina, the 'ginsu shark', was a 7-metre Cretaceous shark whose bite marks are found on mosasaur and plesiosaur bones."},"crinoid-shrimp":{"id":"crinoid-shrimp","name":"Crinoid shrimp","aliases":["feather star shrimp"],"kind":"creature","group":"crustaceans","fact":"Crinoid shrimps live hidden among the arms of feather stars and match their host's colours exactly, from yellow to black."},"crinoid-squat-lobster":{"id":"crinoid-squat-lobster","name":"Crinoid squat lobster","aliases":["feather star squat lobster","Allogalathea elegans"],"kind":"creature","group":"crustaceans","fact":"The crinoid squat lobster lives among the arms of feather stars, striped to match its host."},"crocodile-icefish":{"id":"crocodile-icefish","name":"Crocodile icefish","aliases":["icefish","Antarctic icefish","white-blooded fish","Channichthyidae"],"kind":"creature","group":"fish","fact":"Icefish of the Southern Ocean are the only vertebrates with no red blood cells or haemoglobin, so their blood runs clear and their hearts are oversized."},"crocodile-shark":{"id":"crocodile-shark","name":"Crocodile shark","aliases":["Pseudocarcharias kamoharai"],"kind":"creature","group":"sharks","fact":"The crocodile shark, the smallest of the mackerel sharks, has huge eyes for hunting in dim water and snaps hard when hauled aboard."},"crocodilefish":{"id":"crocodilefish","name":"Crocodilefish","aliases":["crocodile fish","crocodile flathead","Papilloculiceps longiceps"],"kind":"creature","group":"fish","fact":"The crocodilefish lies flat on the sand with a crocodile-like head and lacy eyelids that break up the outline of its eyes."},"cromwell-current":{"id":"cromwell-current","name":"Cromwell Current","aliases":["Equatorial Undercurrent","Pacific Equatorial Undercurrent"],"kind":"place","group":"currents","fact":"The Cromwell Current is a hidden river of water flowing east beneath the surface of the equatorial Pacific, discovered only in 1952."},"crown-jellyfish":{"id":"crown-jellyfish","name":"Crown jellyfish","aliases":["Atolla","Atolla wyvillei","Atolla jellyfish","alarm jellyfish","coronate medusa"],"kind":"creature","group":"jellies","fact":"The deep-sea crown jellyfish Atolla sets off a spinning blue 'burglar alarm' of light when attacked, calling in bigger predators to eat its attacker."},"crown-of-thorns-starfish":{"id":"crown-of-thorns-starfish","name":"Crown-of-thorns starfish","aliases":["crown of thorns","Acanthaster planci","crown-of-thorns sea star","COTS"],"kind":"creature","group":"echinoderms","fact":"The crown-of-thorns starfish is covered in venomous spines and eats living coral, and outbreaks of it have stripped large areas of the Great Barrier Reef."},"cruise-ship":{"id":"cruise-ship","name":"Cruise ship","aliases":["cruise liner"],"kind":"vessel","group":"boats","fact":"The largest cruise ships today carry more than 5,000 passengers and are longer than three football pitches laid end to end."},"crusty-nautilus":{"id":"crusty-nautilus","name":"Crusty nautilus","aliases":["Allonautilus scrobiculatus","fuzzy nautilus"],"kind":"creature","group":"cephalopods","fact":"The crusty nautilus of Papua New Guinea has a shell coated in a hairy, slimy layer and was not seen alive for about 30 years until 2015."},"crystal-goby":{"id":"crystal-goby","name":"Crystal goby","aliases":["Crystallogobius linearis"],"kind":"creature","group":"fish","fact":"The crystal goby is an almost invisible, glass-bodied fish that lives in open water off European coasts rather than on the seabed like most gobies."},"crystal-jelly":{"id":"crystal-jelly","name":"Crystal jelly","aliases":["crystal jellyfish","Aequorea victoria","Aequorea"],"kind":"creature","group":"jellies","fact":"The transparent crystal jelly is the source of green fluorescent protein, which won a Nobel Prize and now lights up cells in labs worldwide."},"cuba":{"id":"cuba","name":"Cuba","aliases":[],"kind":"place","group":"islands","fact":"Cuba is the largest island in the Caribbean, sitting where the Atlantic, the Gulf of Mexico and the Caribbean Sea meet."},"cubera-snapper":{"id":"cubera-snapper","name":"Cubera snapper","aliases":["Lutjanus cyanopterus","Cuban snapper"],"kind":"creature","group":"fish","fact":"The cubera snapper is the largest snapper in the Atlantic, reaching over 1.5 metres, with thick canine teeth like a dog's."},"cuckoo-ray":{"id":"cuckoo-ray","name":"Cuckoo ray","aliases":["Leucoraja naevus"],"kind":"creature","group":"rays","fact":"The cuckoo ray has a big dark-and-yellow eye spot on each wing and lives on sandy bottoms of the north-east Atlantic."},"cuckoo-wrasse":{"id":"cuckoo-wrasse","name":"Cuckoo wrasse","aliases":["Labrus mixtus"],"kind":"creature","group":"fish","fact":"The cuckoo wrasse male is one of Britain's most colourful fish, vivid blue and orange, while the female is pink; all start life as females."},"cunner":{"id":"cunner","name":"Cunner","aliases":["Tautogolabrus adspersus","bergall"],"kind":"creature","group":"fish","fact":"The cunner is a small wrasse of the northwest Atlantic that becomes torpid in winter, hiding in crevices and barely moving in the cold."},"curled-octopus":{"id":"curled-octopus","name":"Curled octopus","aliases":["Eledone cirrhosa","horned octopus","lesser octopus"],"kind":"creature","group":"cephalopods","fact":"The curled octopus, common around Britain, holds its arms curled upward at the tips and has just a single row of suckers on each arm."},"currach":{"id":"currach","name":"Currach","aliases":["curragh","naomhóg"],"kind":"vessel","group":"boats","fact":"The currach is an Irish boat of tarred canvas or hide stretched over a wooden frame, used for fishing in the Atlantic off the west coast."},"cushion-sea-star":{"id":"cushion-sea-star","name":"Cushion sea star","aliases":["cushion star","red cushion sea star","Bahama star","Oreaster reticulatus"],"kind":"creature","group":"echinoderms","fact":"The cushion sea star is the big orange starfish of Caribbean seagrass beds, often stacked up by snorkellers for photos."},"cusk":{"id":"cusk","name":"Cusk","aliases":["tusk","torsk","Brosme brosme"],"kind":"creature","group":"fish","fact":"The cusk, or tusk, is a single-dorsal-finned cod relative of deep North Atlantic waters, eaten in Norway and New England."},"cusk-eel":{"id":"cusk-eel","name":"Cusk-eel","aliases":["Ophidiidae"],"kind":"creature","group":"fish","fact":"Cusk-eels back tail-first into burrows in sand, and one species was trawled from 8,370 metres in the Puerto Rico Trench, long the record for the deepest fish."},"cutthroat-eel":{"id":"cutthroat-eel","name":"Cutthroat eel","aliases":["Synaphobranchidae","Synaphobranchus"],"kind":"creature","group":"fish","fact":"Cutthroat eels are deep-sea eels named for the slit-like gill openings low on the throat, found on the seabed down to several thousand metres."},"cutthroat-trout":{"id":"cutthroat-trout","name":"Cutthroat trout","aliases":["coastal cutthroat trout","Oncorhynchus clarkii"],"kind":"creature","group":"fish","fact":"Cutthroat trout are named for the red slash under the jaw, and coastal populations migrate down to the sea and back."},"cuttlefish":{"id":"cuttlefish","name":"Cuttlefish","aliases":["cuttle","sumi-ika","Sepia","Sepiida"],"kind":"creature","group":"cephalopods","fact":"Cuttlefish control their buoyancy with a porous internal shell, the cuttlebone, and can change colour and skin texture in a fraction of a second."},"cuviers-beaked-whale":{"id":"cuviers-beaked-whale","name":"Cuvier's beaked whale","aliases":["goose-beaked whale","goosebeak whale","Ziphius cavirostris"],"kind":"creature","group":"whales","fact":"Cuvier's beaked whale holds the mammal diving records, with dives to nearly 3,000 metres and lasting over three hours."},"cyanobacteria":{"id":"cyanobacteria","name":"Cyanobacteria","aliases":["blue-green algae","cyanobacterium"],"kind":"creature","group":"microbes","fact":"Cyanobacteria are photosynthetic bacteria whose ancestors first filled the atmosphere with oxygen more than 2 billion years ago."},"dab":{"id":"dab","name":"Dab","aliases":["common dab","Limanda limanda"],"kind":"creature","group":"fish","fact":"The dab is a small, common flatfish of north European sandy seabeds, with rough skin and a lateral line that curves over the pectoral fin."},"dahab-blue-hole":{"id":"dahab-blue-hole","name":"Dahab Blue Hole","aliases":["Blue Hole Dahab","Blue Hole of Dahab"],"kind":"place","group":"divesites","fact":"The Blue Hole at Dahab in Egypt is a 100-metre-deep sinkhole in the Red Sea reef whose deep arch has claimed many divers' lives."},"dakar":{"id":"dakar","name":"Dakar","aliases":[],"kind":"place","group":"ports","fact":"Dakar, on the Cap-Vert peninsula, is the westernmost city on the African mainland and a major Atlantic port."},"dalls-porpoise":{"id":"dalls-porpoise","name":"Dall's porpoise","aliases":["Phocoenoides dalli"],"kind":"creature","group":"dolphins","fact":"Dall's porpoise is one of the fastest small cetaceans, throwing up a rooster tail of spray, and Japan's hunt of it was for decades the largest direct hunt of any cetacean."},"dampier-strait":{"id":"dampier-strait","name":"Dampier Strait","aliases":[],"kind":"place","group":"straits","fact":"Dampier Strait in Papua New Guinea is named after William Dampier, the English buccaneer and naturalist who sailed through it in 1700."},"damselfish":{"id":"damselfish","name":"Damselfish","aliases":["damsel","Pomacentridae"],"kind":"creature","group":"fish","fact":"Damselfish are small, feisty reef fish; some farm patches of algae on the reef and chase off intruders many times their size."},"dana-octopus-squid":{"id":"dana-octopus-squid","name":"Dana octopus squid","aliases":["Taningia danae","Taningia"],"kind":"creature","group":"cephalopods","fact":"The Dana octopus squid carries the largest light organs in the animal kingdom, lemon-sized photophores on two of its arms that it flashes to stun prey."},"dandelion-siphonophore":{"id":"dandelion-siphonophore","name":"Dandelion siphonophore","aliases":["Thermopalia taraxaca","dandelion"],"kind":"creature","group":"jellies","fact":"The dandelion siphonophore tethers itself to rocks at Pacific vents with fine threads, looking like a dandelion seed head, and eats scraps from the vent community."},"danionella-cerebrum":{"id":"danionella-cerebrum","name":"Danionella cerebrum","aliases":["Danionella translucida","Danionella"],"kind":"creature","group":"fish","fact":"Danionella cerebrum, a transparent 12-millimetre fish from Myanmar, makes drumming sounds as loud as a pneumatic drill and has the smallest known vertebrate brain."},"dardanelles":{"id":"dardanelles","name":"Dardanelles","aliases":["Hellespont","Strait of Çanakkale","Çanakkale Strait"],"kind":"place","group":"straits","fact":"The Dardanelles, known in ancient times as the Hellespont, link the Sea of Marmara to the Aegean and were the scene of the Gallipoli campaign in 1915."},"darwins-arch":{"id":"darwins-arch","name":"Darwin's Arch","aliases":["Darwin Arch","Darwin's Pillars","Darwin Island"],"kind":"place","group":"divesites","fact":"Darwin's Arch in the northern Galápagos was a natural rock arch above a legendary hammerhead dive site until it collapsed into the sea in 2021."},"davidson-seamount":{"id":"davidson-seamount","name":"Davidson Seamount","aliases":[],"kind":"place","group":"features","fact":"Davidson Seamount off central California is a huge extinct volcano whose deep flanks hold forests of ancient corals and an 'octopus garden' of brooding mothers."},"davis-strait":{"id":"davis-strait","name":"Davis Strait","aliases":[],"kind":"place","group":"straits","fact":"Davis Strait between Baffin Island and Greenland is named after the English explorer John Davis, who sailed through it in the 1580s seeking the Northwest Passage."},"day-octopus":{"id":"day-octopus","name":"Day octopus","aliases":["Octopus cyanea","big blue octopus"],"kind":"creature","group":"cephalopods","fact":"The day octopus hunts on tropical reefs in daylight, changing colour and texture many times a minute as it crosses different backgrounds."},"dead-mans-fingers":{"id":"dead-mans-fingers","name":"Dead man's fingers","aliases":["Codium fragile","Codium","green sea fingers","sputnik weed"],"kind":"plant","group":"plants","fact":"Dead man's fingers is a dark green, spongy, finger-shaped seaweed that is really a single giant cell with many nuclei."},"deans-blue-hole":{"id":"deans-blue-hole","name":"Dean's Blue Hole","aliases":[],"kind":"place","group":"divesites","fact":"Dean's Blue Hole in the Bahamas plunges to about 200 metres from a shallow beach and is a favourite venue for world-record freediving."},"decorator-crab":{"id":"decorator-crab","name":"Decorator crab","aliases":[],"kind":"creature","group":"crustaceans","fact":"Decorator crabs snip bits of sponge, seaweed and anemone and hook them onto bristles on their shell as living camouflage."},"deep-sea-lizardfish":{"id":"deep-sea-lizardfish","name":"Deep-sea lizardfish","aliases":["Bathysaurus","Bathysaurus ferox","deepsea lizardfish"],"kind":"creature","group":"fish","fact":"The deep-sea lizardfish is a toothy ambush predator of abyssal plains between about 1,000 and 3,500 metres, and is both male and female at once."},"deepsea-challenger":{"id":"deepsea-challenger","name":"Deepsea Challenger","aliases":[],"kind":"vessel","group":"submersibles","fact":"Deepsea Challenger carried the film director James Cameron alone to the bottom of the Challenger Deep in 2012."},"deepstaria":{"id":"deepstaria","name":"Deepstaria","aliases":["Deepstaria enigmatica","Deepstaria jellyfish","Deepstaria reticulum"],"kind":"creature","group":"jellies","fact":"Deepstaria is a deep-sea jellyfish like a loose, bag-shaped sheet that closes around prey the way a drawstring sack does."},"delaware-bay":{"id":"delaware-bay","name":"Delaware Bay","aliases":[],"kind":"place","group":"bays","fact":"Delaware Bay hosts the world's largest spawning gathering of horseshoe crabs each spring, feeding millions of migrating shorebirds."},"denises-pygmy-seahorse":{"id":"denises-pygmy-seahorse","name":"Denise's pygmy seahorse","aliases":["Hippocampus denise","Denise's seahorse","yellow pygmy seahorse"],"kind":"creature","group":"fish","fact":"Denise's pygmy seahorse is a 2-centimetre orange seahorse found on sea fans across the Coral Triangle, named after the photographer Denise Tackett."},"denmark-strait":{"id":"denmark-strait","name":"Denmark Strait","aliases":[],"kind":"place","group":"straits","fact":"The Denmark Strait between Greenland and Iceland is where the Bismarck sank HMS Hood in 1941, and it carries the world's biggest underwater waterfall."},"dentex":{"id":"dentex","name":"Dentex","aliases":["common dentex","Dentex dentex"],"kind":"creature","group":"fish","fact":"The common dentex is a big-toothed Mediterranean bream prized by spearfishers and famous on Croatian and Greek menus."},"devil-ray":{"id":"devil-ray","name":"Devil ray","aliases":["mobula","mobula ray","devilfish","Munk's devil ray"],"kind":"creature","group":"rays","fact":"Devil rays leap metres into the air and belly-flop back down in spectacular group displays off Mexico."},"dhow":{"id":"dhow","name":"Dhow","aliases":["Arab dhow"],"kind":"vessel","group":"boats","fact":"Dhows are the traditional lateen-rigged sailing vessels of the Arabian Sea and Indian Ocean, used for centuries in trade between Arabia, East Africa and India."},"diamond-squid":{"id":"diamond-squid","name":"Diamond squid","aliases":["Thysanoteuthis rhombus","diamondback squid","rhomboid squid"],"kind":"creature","group":"cephalopods","fact":"The diamond squid swims in lifelong pairs and gets its name from the rhombus shape of fins that run the full length of its body."},"diamond-stingray":{"id":"diamond-stingray","name":"Diamond stingray","aliases":["Hypanus dipterurus","Dasyatis dipterura"],"kind":"creature","group":"rays","fact":"The diamond stingray of the eastern Pacific has a diamond-shaped disc and a tail longer than its body armed with a venomous spine."},"diatom":{"id":"diatom","name":"Diatom","aliases":["Bacillariophyta"],"kind":"plant","group":"plankton","fact":"Diatoms are single-celled algae encased in glass-like shells of silica, and they carry out roughly a fifth of all photosynthesis on Earth."},"dinghy":{"id":"dinghy","name":"Dinghy","aliases":["tender","rubber dinghy","inflatable dinghy"],"kind":"vessel","group":"boats","fact":"A dinghy is a small open boat, often carried aboard or towed behind a larger vessel as a tender to reach the shore."},"dinoflagellate":{"id":"dinoflagellate","name":"Dinoflagellate","aliases":["Dinoflagellata"],"kind":"plant","group":"plankton","fact":"Dinoflagellates are single-celled plankton with two whip-like tails; some cause red tides and others light up the sea at night."},"discus":{"id":"discus","name":"Discus","aliases":["discus fish","Symphysodon"],"kind":"creature","group":"fish","fact":"Discus parents feed their fry with a nutritious mucus secreted from their own skin, and the young graze on both parents for weeks."},"dog-whelk":{"id":"dog-whelk","name":"Dog whelk","aliases":["whelk","dogwhelk","Nucella lapillus"],"kind":"creature","group":"molluscs","fact":"The dog whelk drills through the shells of mussels and barnacles with its tongue-like radula and was once used to make purple dye."},"dogger-bank":{"id":"dogger-bank","name":"Dogger Bank","aliases":[],"kind":"place","group":"features","fact":"Dogger Bank is a large sandbank in the middle of the North Sea that was dry land, part of Doggerland, when sea levels were lower after the last ice age."},"dogtooth-tuna":{"id":"dogtooth-tuna","name":"Dogtooth tuna","aliases":["Gymnosarda unicolor"],"kind":"creature","group":"fish","fact":"The dogtooth tuna is a reef-hunting member of the tuna family with large, conical teeth; it is a bonito rather than a true tuna."},"doliolid":{"id":"doliolid","name":"Doliolid","aliases":["Doliolum","Doliolida"],"kind":"creature","group":"plankton","fact":"Doliolids are transparent, barrel-shaped plankton with muscle bands like hoops, and a single founder can bud a chain of hundreds of clones."},"dolly-varden":{"id":"dolly-varden","name":"Dolly Varden","aliases":["Dolly Varden trout","Salvelinus malma"],"kind":"creature","group":"fish","fact":"The Dolly Varden is a char named after a brightly dressed character in a Charles Dickens novel, and many populations migrate to sea and back."},"dolphin":{"id":"dolphin","name":"Dolphin","aliases":["Delphinidae"],"kind":"creature","group":"dolphins","fact":"Dolphins are toothed whales with cone-shaped teeth and a beak, and they hunt using echolocation clicks."},"domino-damselfish":{"id":"domino-damselfish","name":"Domino damselfish","aliases":["threespot dascyllus","three-spot damselfish","Dascyllus trimaculatus","domino damsel","three-spot dascyllus"],"kind":"creature","group":"fish","fact":"Young domino damselfish shelter among the tentacles of sea anemones, like clownfish, before moving onto coral heads as adults."},"don-walsh":{"id":"don-walsh","name":"Don Walsh","aliases":[],"kind":"person","group":"people","fact":"Don Walsh, a US Navy lieutenant, piloted the bathyscaphe Trieste to the bottom of the Challenger Deep with Jacques Piccard in 1960."},"dona-paz":{"id":"dona-paz","name":"Doña Paz","aliases":["MV Doña Paz"],"kind":"vessel","group":"wrecks","fact":"The Philippine ferry Doña Paz collided with a tanker and sank in December 1987, the deadliest peacetime shipwreck ever, with more than 4,000 dead."},"dorudon":{"id":"dorudon","name":"Dorudon","aliases":[],"kind":"creature","group":"whales","fact":"Dorudon was a 5-metre early whale whose skeletons lie by the hundred in Egypt's Wadi Al-Hitan, the Valley of the Whales."},"dory":{"id":"dory","name":"Dory","aliases":["Grand Banks dory","Banks dory"],"kind":"vessel","group":"boats","fact":"The dory is a flat-bottomed, high-sided rowing boat once launched from fishing schooners on the Grand Banks to set cod lines."},"dottyback":{"id":"dottyback","name":"Dottyback","aliases":["Pseudochromis"],"kind":"creature","group":"fish","fact":"Dottybacks are small, often vividly coloured reef fish that lurk in crevices, and the orchid dottyback is bred in captivity for aquariums."},"dover-sole":{"id":"dover-sole","name":"Dover sole","aliases":["sole","common sole","black sole","Solea solea"],"kind":"creature","group":"fish","fact":"Dover sole hide in sand by day and hunt worms and small crustaceans at night across the north-east Atlantic."},"dragon-hole":{"id":"dragon-hole","name":"Dragon Hole","aliases":["Sansha Yongle Blue Hole","Longdong"],"kind":"place","group":"features","fact":"The Dragon Hole in the South China Sea plunges roughly 300 metres into the reef and was the deepest known blue hole until the Taam Ja' Blue Hole off Mexico was measured deeper in 2024."},"dragon-moray":{"id":"dragon-moray","name":"Dragon moray","aliases":["Hawaiian dragon eel","Enchelycore pardalis","leopard moray","dragon eel"],"kind":"creature","group":"fish","fact":"The dragon moray has curved fangs and horn-like nostril tubes, making it one of the most striking eels of Indo-Pacific reefs."},"dragon-wrasse":{"id":"dragon-wrasse","name":"Dragon wrasse","aliases":["rockmover wrasse","rockmover","Novaculichthys taeniourus","reindeer wrasse"],"kind":"creature","group":"fish","fact":"The dragon wrasse, or rockmover, flips over rocks with its mouth to find prey; as a juvenile it mimics a drifting piece of seaweed."},"dragonet":{"id":"dragonet","name":"Dragonet","aliases":["common dragonet","Callionymus lyra","Callionymidae"],"kind":"creature","group":"fish","fact":"Dragonets are small, scaleless fish that bury themselves in sand with only their eyes showing; the male common dragonet has a huge sail-like fin."},"dragonfish":{"id":"dragonfish","name":"Dragonfish","aliases":["barbeled dragonfish","Stomiidae","black dragonfish","Idiacanthus"],"kind":"creature","group":"fish","fact":"Deep-sea dragonfish have transparent teeth, a glowing chin barbel, and jaws that can open past 100 degrees."},"drake-passage":{"id":"drake-passage","name":"Drake Passage","aliases":["Drake Strait","Mar de Hoces"],"kind":"place","group":"straits","fact":"The Drake Passage between Cape Horn and Antarctica, named after Sir Francis Drake, has some of the roughest seas on Earth."},"drum":{"id":"drum","name":"Drum","aliases":["drumfish","drum fish","Sciaenidae"],"kind":"creature","group":"fish","fact":"Drums are named for the drumming sound they make by vibrating special muscles against their swim bladder, mostly to call mates."},"dubois-sea-snake":{"id":"dubois-sea-snake","name":"Dubois' sea snake","aliases":["Dubois's sea snake","reef shallows sea snake","Aipysurus duboisii"],"kind":"creature","group":"reptiles","fact":"Dubois' sea snake of northern Australia has one of the most toxic venoms of any snake, yet it bites only when provoked and hunts fish and moray eels on the seabed."},"dugong":{"id":"dugong","name":"Dugong","aliases":["Dugong dugon"],"kind":"creature","group":"mammals","fact":"Dugongs graze on seagrass meadows and have a fluked tail like a whale's, unlike the manatee's rounded paddle."},"dulse":{"id":"dulse","name":"Dulse","aliases":["Palmaria palmata","dillisk"],"kind":"plant","group":"plants","fact":"Dulse is a red seaweed eaten for centuries in Ireland, Scotland and Iceland, often dried and sold as a salty snack."},"dumbo-octopus":{"id":"dumbo-octopus","name":"Dumbo octopus","aliases":["Grimpoteuthis","dumbo"],"kind":"creature","group":"cephalopods","fact":"Dumbo octopuses flap ear-like fins to swim and have been filmed nearly 7,000 metres down in the Java Trench, deeper than any other octopus."},"dungeness-crab":{"id":"dungeness-crab","name":"Dungeness crab","aliases":["Metacarcinus magister","Cancer magister"],"kind":"creature","group":"crustaceans","fact":"The Dungeness crab, named after a small town in Washington State, is one of the most valuable fisheries on the US West Coast."},"dunkleosteus":{"id":"dunkleosteus","name":"Dunkleosteus","aliases":[],"kind":"creature","group":"fish","fact":"Dunkleosteus was an armoured fish of the Devonian seas that sliced prey with bony blades instead of teeth."},"dusky-dolphin":{"id":"dusky-dolphin","name":"Dusky dolphin","aliases":["Lagenorhynchus obscurus"],"kind":"creature","group":"dolphins","fact":"Dusky dolphins of New Zealand, South Africa and South America are famous for high, acrobatic leaps and somersaults."},"dusky-farmerfish":{"id":"dusky-farmerfish","name":"Dusky farmerfish","aliases":["Stegastes nigricans","dusky gregory","farmer damselfish"],"kind":"creature","group":"fish","fact":"The dusky farmerfish is a damselfish that cultivates a single species of red alga in its territory, weeding out everything else, in one of the only known cases of farming by a fish."},"dusky-grouper":{"id":"dusky-grouper","name":"Dusky grouper","aliases":["Epinephelus marginatus","Mediterranean grouper","merou"],"kind":"creature","group":"fish","fact":"The dusky grouper is the big grouper of Mediterranean rocky reefs, a favourite of divers in marine reserves after decades of spearfishing made it scarce."},"dusky-shark":{"id":"dusky-shark","name":"Dusky shark","aliases":["Carcharhinus obscurus"],"kind":"creature","group":"sharks","fact":"Dusky sharks grow slowly and do not breed until about 20 years old, which makes them very vulnerable to overfishing."},"dwarf-cuttlefish":{"id":"dwarf-cuttlefish","name":"Dwarf cuttlefish","aliases":["Sepia bandensis","stumpy-spined cuttlefish"],"kind":"creature","group":"cephalopods","fact":"The dwarf cuttlefish grows to only about 7 centimetres and is a favourite in research labs and home aquariums for its rapid colour changes."},"dwarf-gourami":{"id":"dwarf-gourami","name":"Dwarf gourami","aliases":["Trichogaster lalius"],"kind":"creature","group":"fish","fact":"The dwarf gourami breathes air with a labyrinth organ, and the male builds a floating nest of bubbles for the eggs."},"dwarf-lanternshark":{"id":"dwarf-lanternshark","name":"Dwarf lanternshark","aliases":["dwarf lantern shark","Etmopterus perryi"],"kind":"creature","group":"sharks","fact":"The dwarf lanternshark is probably the smallest shark in the world, fully grown at around 20 centimetres long."},"dwarf-minke-whale":{"id":"dwarf-minke-whale","name":"Dwarf minke whale","aliases":[],"kind":"creature","group":"whales","fact":"Dwarf minke whales gather on the northern Great Barrier Reef every winter, the only place in the world with licensed tours to swim with them."},"dwarf-pencilfish":{"id":"dwarf-pencilfish","name":"Dwarf pencilfish","aliases":["Nannostomus marginatus"],"kind":"creature","group":"fish","fact":"The dwarf pencilfish is a slender 3.5-centimetre fish of Amazon blackwater streams with bold horizontal stripes."},"dwarf-pygmy-goby":{"id":"dwarf-pygmy-goby","name":"Dwarf pygmy goby","aliases":["Pandaka pygmaea","Philippine dwarf pygmy goby","Philippine goby"],"kind":"creature","group":"fish","fact":"The dwarf pygmy goby of Philippine mangrove streams is about 1 centimetre long as an adult and was long considered the smallest fish in the world."},"dwarf-rasbora":{"id":"dwarf-rasbora","name":"Dwarf rasbora","aliases":["Boraras maculatus","spotted rasbora","pygmy rasbora"],"kind":"creature","group":"fish","fact":"The dwarf rasbora, Boraras maculatus, is a 2-centimetre spotted fish of Malaysian peat swamps."},"dwarf-seahorse":{"id":"dwarf-seahorse","name":"Dwarf seahorse","aliases":["Hippocampus zosterae"],"kind":"creature","group":"fish","fact":"The dwarf seahorse of Florida's seagrass beds is about 2.5 centimetres long and was once listed as the slowest-moving fish in the world."},"dwarf-sperm-whale":{"id":"dwarf-sperm-whale","name":"Dwarf sperm whale","aliases":["Kogia sima"],"kind":"creature","group":"whales","fact":"The dwarf sperm whale is the smallest animal commonly called a whale, at about 2.7 metres long, and releases a cloud of dark fluid when alarmed."},"eagle-ray":{"id":"eagle-ray","name":"Eagle ray","aliases":[],"kind":"creature","group":"rays","fact":"Eagle rays flap their pointed wings to fly through the water and sometimes leap clear of the surface."},"east-australian-current":{"id":"east-australian-current","name":"East Australian Current","aliases":["EAC"],"kind":"place","group":"currents","fact":"The East Australian Current sweeps warm water south along Australia's east coast and was the EAC ridden by the turtles in Finding Nemo."},"east-china-sea":{"id":"east-china-sea","name":"East China Sea","aliases":[],"kind":"place","group":"seas","fact":"The East China Sea lies between China and Japan's Ryukyu Islands and receives the muddy outflow of the Yangtze River."},"east-greenland-current":{"id":"east-greenland-current","name":"East Greenland Current","aliases":[],"kind":"place","group":"currents","fact":"The East Greenland Current carries cold water and sea ice south from the Arctic along Greenland's east coast and through the Denmark Strait."},"east-pacific-red-octopus":{"id":"east-pacific-red-octopus","name":"East Pacific red octopus","aliases":["Octopus rubescens","Pacific red octopus","ruby octopus"],"kind":"creature","group":"cephalopods","fact":"The East Pacific red octopus is the most common shallow-water octopus from Alaska to Baja California, though its body is only about 10 centimetres long."},"east-pacific-rise":{"id":"east-pacific-rise","name":"East Pacific Rise","aliases":[],"kind":"place","group":"features","fact":"The East Pacific Rise is a fast-spreading mid-ocean ridge where the first black-smoker hydrothermal vents were discovered in 1979."},"easter-island":{"id":"easter-island","name":"Easter Island","aliases":["Rapa Nui","Isla de Pascua"],"kind":"place","group":"islands","fact":"Easter Island is one of the most remote inhabited islands on Earth, more than 3,500 kilometres from Chile, and is famous for its giant stone moai."},"eastern-emerald-elysia":{"id":"eastern-emerald-elysia","name":"Eastern emerald elysia","aliases":["Elysia chlorotica","solar-powered sea slug","emerald sea slug"],"kind":"creature","group":"molluscs","fact":"The eastern emerald elysia steals chloroplasts from the alga it eats and can then live for months on photosynthesis alone, like a leaf that crawls."},"eastern-oyster":{"id":"eastern-oyster","name":"Eastern oyster","aliases":["oyster","American oyster","Gulf oyster","Crassostrea virginica"],"kind":"creature","group":"molluscs","fact":"The eastern oyster builds reefs along the Gulf of Mexico, and the Gulf produces most of the oysters eaten in the United States."},"eastern-pacific-bonito":{"id":"eastern-pacific-bonito","name":"Eastern Pacific bonito","aliases":["Pacific bonito","Sarda chiliensis","Sarda lineolata"],"kind":"creature","group":"fish","fact":"The eastern Pacific bonito ranges from Chile to Alaska and is a common catch for anglers off California."},"edible-crab":{"id":"edible-crab","name":"Edible crab","aliases":["brown crab","Cancer pagurus"],"kind":"creature","group":"crustaceans","fact":"The edible or brown crab, with its pie-crust shell edge, is the most heavily fished crab in Western Europe."},"edible-sea-urchin":{"id":"edible-sea-urchin","name":"Edible sea urchin","aliases":["European edible sea urchin","Echinus esculentus"],"kind":"creature","group":"echinoderms","fact":"The edible sea urchin is a large pinkish urchin of the north-east Atlantic that grazes kelp and is harvested for its roe."},"eel":{"id":"eel","name":"Eel","aliases":["freshwater eel","unagi"],"kind":"creature","group":"fish","fact":"Freshwater eels hatch in the open ocean, spend years growing in rivers and lakes, and then return to the sea to spawn and die."},"eelgrass":{"id":"eelgrass","name":"Eelgrass","aliases":["Zostera marina","Zostera","eel grass"],"kind":"plant","group":"plants","fact":"Eelgrass is a seagrass of cool northern coasts whose meadows are nurseries for young cod, herring and crabs."},"eelpout":{"id":"eelpout","name":"Eelpout","aliases":["Zoarcidae","zoarcid"],"kind":"creature","group":"fish","fact":"Eelpouts are blunt-headed, eel-shaped fish of cold seas; some live at hydrothermal vents and others on abyssal plains below 4,000 metres."},"el-faro":{"id":"el-faro","name":"El Faro","aliases":["SS El Faro"],"kind":"vessel","group":"wrecks","fact":"The cargo ship El Faro sank in Hurricane Joaquin in October 2015 with all 33 crew, and was found about 4,600 metres down near the Bahamas."},"elasmosaurus":{"id":"elasmosaurus","name":"Elasmosaurus","aliases":["elasmosaur"],"kind":"creature","group":"reptiles","fact":"Elasmosaurus had a neck of more than 70 vertebrae, and its first describer famously mounted the skull on the wrong end."},"electric-catfish":{"id":"electric-catfish","name":"Electric catfish","aliases":["Malapterurus electricus","Malapterurus"],"kind":"creature","group":"fish","fact":"The electric catfish of African rivers can deliver shocks of about 350 volts and was pictured in ancient Egyptian tomb art."},"electric-eel":{"id":"electric-eel","name":"Electric eel","aliases":["Electrophorus electricus","Electrophorus"],"kind":"creature","group":"fish","fact":"The electric eel takes about 80 per cent of its oxygen from the air and must surface to breathe every few minutes."},"electric-ray":{"id":"electric-ray","name":"Electric ray","aliases":["torpedo ray","torpedo","numbfish","crampfish"],"kind":"creature","group":"rays","fact":"Electric rays can deliver shocks of up to about 220 volts from kidney-shaped organs on either side of their head."},"elegant-sea-snake":{"id":"elegant-sea-snake","name":"Elegant sea snake","aliases":["Hydrophis elegans"],"kind":"creature","group":"reptiles","fact":"The elegant sea snake is one of the longest sea snakes, reaching about 2 metres, and lives in the turbid waters off northern Australia."},"elephant-fish":{"id":"elephant-fish","name":"Elephant fish","aliases":["elephantfish","Australian ghostshark","plough-nose chimaera","Callorhinchus milii"],"kind":"creature","group":"fish","fact":"The elephant fish of Australia and New Zealand is a chimaera that probes the seabed with its trunk-like snout, sensing the electric fields of buried shellfish."},"elephant-seal":{"id":"elephant-seal","name":"Elephant seal","aliases":["sea elephant"],"kind":"creature","group":"seals","fact":"Elephant seals are named for the huge inflatable nose of the males, which amplifies their roars during breeding fights."},"elephant-shark":{"id":"elephant-shark","name":"Elephant shark","aliases":["Australian ghostshark","elephant fish","Callorhinchus milii"],"kind":"creature","group":"sharks","fact":"The elephant shark of Australia and New Zealand has the slowest-evolving genome of any vertebrate yet studied."},"elephantnose-fish":{"id":"elephantnose-fish","name":"Elephantnose fish","aliases":["elephant nose fish","Peters's elephantnose fish","Gnathonemus petersii"],"kind":"creature","group":"fish","fact":"Peters's elephantnose fish of African rivers has a finger-like chin extension packed with electric sensors, used to probe the mud for food."},"elkhorn-coral":{"id":"elkhorn-coral","name":"Elkhorn coral","aliases":["Acropora palmata"],"kind":"creature","group":"corals","fact":"Elkhorn coral's thick branches once built the shallow crests of Caribbean reefs, and it was among the first corals listed as threatened in the United States."},"elpidia":{"id":"elpidia","name":"Elpidia","aliases":["Elpidia sea cucumber"],"kind":"creature","group":"echinoderms","fact":"Elpidia are small, stubby sea cucumbers that plough the mud of trench floors in herds, among the most numerous large animals at hadal depths."},"elysia-sea-slug":{"id":"elysia-sea-slug","name":"Elysia sea slug","aliases":["Elysia marginata","Elysia","sap-sucking sea slug","self-decapitating sea slug"],"kind":"creature","group":"molluscs","fact":"The sea slug Elysia marginata can shed its own head, which then regrows an entire new body, heart included, within weeks."},"ember-tetra":{"id":"ember-tetra","name":"Ember tetra","aliases":["Hyphessobrycon amandae"],"kind":"creature","group":"fish","fact":"The ember tetra is a fiery orange fish from Brazil's Araguaia river basin that grows to only about 2 centimetres."},"emiliania-huxleyi":{"id":"emiliania-huxleyi","name":"Emiliania huxleyi","aliases":["Ehux","E. huxleyi"],"kind":"plant","group":"plankton","fact":"Emiliania huxleyi is the most widespread coccolithophore, a chalk-plated alga whose blooms stretch for hundreds of kilometres and turn the sea turquoise."},"emperor-angelfish":{"id":"emperor-angelfish","name":"Emperor angelfish","aliases":["Pomacanthus imperator","imperial angelfish"],"kind":"creature","group":"fish","fact":"The emperor angelfish of Indo-Pacific reefs is striped blue and yellow as an adult, but its juvenile is dark blue with white rings, so different it was once thought a separate species."},"emperor-penguin":{"id":"emperor-penguin","name":"Emperor penguin","aliases":["Aptenodytes forsteri"],"kind":"creature","group":"seabirds","fact":"Emperor penguins dive deeper than 500 metres for fish, squid and krill, and the males fast for about four months while incubating an egg on their feet."},"emperor-shrimp":{"id":"emperor-shrimp","name":"Emperor shrimp","aliases":["Periclimenes imperator","Zenopontonia rex","imperial shrimp"],"kind":"creature","group":"crustaceans","fact":"The emperor shrimp rides on sea cucumbers and Spanish dancer nudibranchs, picking food from the sand as its host crawls along."},"endlers-livebearer":{"id":"endlers-livebearer","name":"Endler's livebearer","aliases":["Endler's guppy","Poecilia wingei","Endler guppy","Endler"],"kind":"creature","group":"fish","fact":"Endler's livebearer is a tiny, brilliantly coloured relative of the guppy from Venezuela, with males under 3 centimetres long."},"endurance":{"id":"endurance","name":"Endurance","aliases":["Shackleton's Endurance"],"kind":"vessel","group":"wrecks","fact":"Shackleton's ship Endurance, crushed by ice in 1915, was found in March 2022 at 3,008 metres in the Weddell Sea, with its name still legible on the stern."},"enewetak-atoll":{"id":"enewetak-atoll","name":"Enewetak Atoll","aliases":["Enewetak","Eniwetok","Eniwetok Atoll"],"kind":"place","group":"reefs","fact":"Enewetak Atoll in the Marshall Islands was the site of 43 nuclear tests, and deep drilling into its reef in 1952 proved Darwin's theory of how atolls form."},"english-channel":{"id":"english-channel","name":"English Channel","aliases":["the Channel","La Manche"],"kind":"place","group":"straits","fact":"The English Channel separates England from France and joins the Atlantic to the North Sea; it is about 34 kilometres across at the Strait of Dover."},"epaulette-shark":{"id":"epaulette-shark","name":"Epaulette shark","aliases":["walking shark","Hemiscyllium ocellatum"],"kind":"creature","group":"sharks","fact":"The epaulette shark can walk across exposed reef flats on its fins and survive for hours with almost no oxygen."},"equatorial-counter-current":{"id":"equatorial-counter-current","name":"Equatorial Counter Current","aliases":["Equatorial Countercurrent","North Equatorial Countercurrent"],"kind":"place","group":"currents","fact":"The Equatorial Counter Current flows eastward against the trade winds in a narrow band near the equator, between the westward-flowing equatorial currents."},"escolar":{"id":"escolar","name":"Escolar","aliases":["Lepidocybium flavobrunneum"],"kind":"creature","group":"fish","fact":"Escolar lives deep in the open ocean, and its flesh is so rich in indigestible wax that eating it can cause oily stomach upsets."},"ethereal-snailfish":{"id":"ethereal-snailfish","name":"Ethereal snailfish","aliases":[],"kind":"creature","group":"fish","fact":"The ethereal snailfish was filmed at 8,145 metres in the Mariana Trench in 2014, a wispy, nearly transparent fish known only from video, as none has yet been caught."},"eugenie-clark":{"id":"eugenie-clark","name":"Eugenie Clark","aliases":["Shark Lady"],"kind":"person","group":"people","fact":"Eugenie Clark, the Shark Lady, studied shark behaviour for decades and discovered a Red Sea fish whose secretions repel sharks."},"eulachon":{"id":"eulachon","name":"Eulachon","aliases":["candlefish","ooligan","hooligan","Thaleichthys pacificus"],"kind":"creature","group":"fish","fact":"The eulachon is a small smelt so oily that a dried fish can be lit like a candle, and it runs from the sea up Pacific north-west rivers each spring."},"european-conger":{"id":"european-conger","name":"European conger","aliases":["Conger conger"],"kind":"creature","group":"fish","fact":"The European conger is one of the largest eels, reaching about 3 metres and more than 100 kilograms, and lurks in wrecks and rocky holes."},"european-eel":{"id":"european-eel","name":"European eel","aliases":["common eel","Anguilla anguilla","eel"],"kind":"creature","group":"fish","fact":"The European eel can spend 20 years or more in rivers before swimming about 5,000 kilometres to spawn in the Sargasso Sea."},"european-flat-oyster":{"id":"european-flat-oyster","name":"European flat oyster","aliases":["Belon oyster","native oyster","Ostrea edulis","Colchester native"],"kind":"creature","group":"molluscs","fact":"The European flat oyster was once so common that it was poor people's food in Victorian London; reefs of it are now being restored around Britain."},"european-flounder":{"id":"european-flounder","name":"European flounder","aliases":["Platichthys flesus","flounder"],"kind":"creature","group":"fish","fact":"The European flounder moves far up rivers into fresh water and returns to the sea to spawn."},"european-flying-squid":{"id":"european-flying-squid","name":"European flying squid","aliases":["Todarodes sagittatus"],"kind":"creature","group":"cephalopods","fact":"The European flying squid ranges from the Arctic to West Africa, and in some years swarms into Norwegian fjords in vast numbers."},"european-hake":{"id":"european-hake","name":"European hake","aliases":["Merluccius merluccius","merluza"],"kind":"creature","group":"fish","fact":"The European hake is a slim, sharp-toothed cod relative fished from Norway to West Africa; Spain eats more of it than any other country."},"european-lobster":{"id":"european-lobster","name":"European lobster","aliases":["common lobster","Homarus gammarus"],"kind":"creature","group":"crustaceans","fact":"The European lobster is dark blue when alive and only turns red when it is cooked, as heat breaks down the pigment that masks the red."},"european-perch":{"id":"european-perch","name":"European perch","aliases":["redfin perch","Perca fluviatilis"],"kind":"creature","group":"fish","fact":"The European perch lives in lakes and rivers and in the brackish Baltic Sea, and has become invasive in Australia as the redfin."},"european-spiny-lobster":{"id":"european-spiny-lobster","name":"European spiny lobster","aliases":["spiny lobster","langouste","crawfish","Palinurus elephas"],"kind":"creature","group":"crustaceans","fact":"The European spiny lobster, or langouste, has no claws but long spiny antennae, and is the prized lobster of Mediterranean kitchens."},"european-squid":{"id":"european-squid","name":"European squid","aliases":["common squid","Loligo vulgaris"],"kind":"creature","group":"cephalopods","fact":"The European squid, the classic calamari of Mediterranean menus, has a body about 30 to 40 centimetres long and hunts fish in coastal waters."},"eurythenes-plasticus":{"id":"eurythenes-plasticus","name":"Eurythenes plasticus","aliases":["Eurythenes","plastic amphipod"],"kind":"creature","group":"crustaceans","fact":"This amphipod from nearly 7,000 metres down in the Mariana Trench was named 'plasticus' in 2020 because microplastic fibres were found in its gut."},"ev-nautilus":{"id":"ev-nautilus","name":"Nautilus (research vessel)","aliases":["EV Nautilus","E/V Nautilus","Exploration Vessel Nautilus","Nautilus"],"kind":"vessel","group":"vessels","fact":"The exploration vessel Nautilus, run by Titanic discoverer Robert Ballard's Ocean Exploration Trust, streams its deep-sea dives live to the public."},"fabien-cousteau":{"id":"fabien-cousteau","name":"Fabien Cousteau","aliases":[],"kind":"person","group":"people","fact":"Fabien Cousteau, grandson of Jacques, spent 31 days living in the undersea laboratory Aquarius in 2014, beating his grandfather's record."},"fairy-wrasse":{"id":"fairy-wrasse","name":"Fairy wrasse","aliases":["Cirrhilabrus"],"kind":"creature","group":"fish","fact":"Fairy wrasses are small, dazzling wrasses of Indo-Pacific reefs; males flash their colours in courtship displays, and new species are still being named."},"falkland-current":{"id":"falkland-current","name":"Falkland Current","aliases":["Malvinas Current"],"kind":"place","group":"currents","fact":"The Falkland Current carries cold Antarctic water north along the coast of Argentina, bringing Magellanic penguins as far north as Brazil."},"falkland-islands":{"id":"falkland-islands","name":"Falkland Islands","aliases":["Falklands","Malvinas","Islas Malvinas"],"kind":"place","group":"islands","fact":"The Falkland Islands lie in the South Atlantic about 500 kilometres east of Argentina and have far more sheep and penguins than people."},"falkor":{"id":"falkor","name":"Falkor","aliases":["RV Falkor","Falkor (too)"],"kind":"vessel","group":"vessels","fact":"Falkor and its successor Falkor (too) are research ships run by the Schmidt Ocean Institute that offer free ship time to scientists and have mapped vast areas of sea floor."},"false-catshark":{"id":"false-catshark","name":"False catshark","aliases":["false cat shark","sofa shark","Pseudotriakis microdon"],"kind":"creature","group":"sharks","fact":"The false catshark is a flabby deep-water shark with a long, low dorsal fin and has been found down to about 1,500 metres."},"false-killer-whale":{"id":"false-killer-whale","name":"False killer whale","aliases":["Pseudorca crassidens"],"kind":"creature","group":"dolphins","fact":"False killer whales are large dark dolphins known for sharing prey with each other and for hunting alongside bottlenose dolphins."},"fangtooth":{"id":"fangtooth","name":"Fangtooth","aliases":["Anoplogaster cornuta","ogrefish","common fangtooth"],"kind":"creature","group":"fish","fact":"The fangtooth has the largest teeth of any fish relative to its body size, so big that it has sockets in its skull for them to fit into."},"fangtooth-moray":{"id":"fangtooth-moray","name":"Fangtooth moray","aliases":["tiger moray","Enchelycore anatina"],"kind":"creature","group":"fish","fact":"The fangtooth moray, with glassy, needle-like teeth and a bright yellow head, lives in the warmer rocky waters of the eastern Atlantic, including the Canaries and Madeira."},"farallon-islands":{"id":"farallon-islands","name":"Farallon Islands","aliases":["Farallones","Farallons"],"kind":"place","group":"islands","fact":"The Farallon Islands off San Francisco are a wildlife refuge where great white sharks gather each autumn to hunt seals."},"faroe-islands":{"id":"faroe-islands","name":"Faroe Islands","aliases":["Faroes","Faeroe Islands"],"kind":"place","group":"islands","fact":"The Faroe Islands are 18 rugged islands between Norway and Iceland, where sheep outnumber people and the cliffs host huge seabird colonies."},"feather-duster-worm":{"id":"feather-duster-worm","name":"Feather duster worm","aliases":["fan worm","Sabellastarte","sabellid worm","feather duster"],"kind":"creature","group":"worms","fact":"Feather duster worms spread a fan of feathery tentacles from a parchment tube to trap plankton, and many have eyes on the tentacles to spot shadows."},"feather-star":{"id":"feather-star","name":"Feather star","aliases":[],"kind":"creature","group":"echinoderms","fact":"Feather stars are crinoids that cling to reefs with tiny claw-like legs and can swim short distances by waving their feathery arms."},"felucca":{"id":"felucca","name":"Felucca","aliases":[],"kind":"vessel","group":"boats","fact":"The felucca is a traditional wooden sailing boat with one or two lateen sails, used on the Nile and along the Red Sea and Mediterranean coasts."},"fendouzhe":{"id":"fendouzhe","name":"Fendouzhe","aliases":["Striver"],"kind":"vessel","group":"submersibles","fact":"Fendouzhe, meaning Striver, is the Chinese submersible that carried three people to the bottom of the Challenger Deep in 2020."},"ferdinand-magellan":{"id":"ferdinand-magellan","name":"Ferdinand Magellan","aliases":["Magellan","Fernão de Magalhães"],"kind":"person","group":"people","fact":"Ferdinand Magellan led the first expedition to cross the Pacific, which he named for its calm waters, though he was killed in the Philippines before it completed the first circumnavigation."},"fernando-de-noronha":{"id":"fernando-de-noronha","name":"Fernando de Noronha","aliases":[],"kind":"place","group":"islands","fact":"Fernando de Noronha is a volcanic archipelago off north-east Brazil famous for its spinner dolphins and strictly limited number of visitors."},"ferry":{"id":"ferry","name":"Ferry","aliases":["ferryboat","car ferry","ro-ro ferry"],"kind":"vessel","group":"boats","fact":"Ferries carry passengers and vehicles on regular routes across the water, and some of the busiest in the world cross the English Channel and the Baltic."},"fiddler-crab":{"id":"fiddler-crab","name":"Fiddler crab","aliases":["Uca"],"kind":"creature","group":"crustaceans","fact":"A male fiddler crab has one claw far bigger than the other and waves it to attract females and warn off rivals."},"fiji":{"id":"fiji","name":"Fiji","aliases":["Fiji Islands","Viti Levu"],"kind":"place","group":"islands","fact":"Fiji is a nation of more than 300 islands in the South Pacific, and its Great Sea Reef is one of the longest barrier reefs in the world."},"filefish":{"id":"filefish","name":"Filefish","aliases":["leatherjacket","foolfish"],"kind":"creature","group":"fish","fact":"Filefish have skin so rough that it was once used as sandpaper, and a single stout spine on the head that they can lock upright."},"fin-whale":{"id":"fin-whale","name":"Fin whale","aliases":["finback","finback whale","razorback","common rorqual","Balaenoptera physalus"],"kind":"creature","group":"whales","fact":"The fin whale is the second-largest animal and has odd asymmetric colouring, with a white lower right jaw and a dark left one."},"finger-coral":{"id":"finger-coral","name":"Finger coral","aliases":[],"kind":"creature","group":"corals","fact":"Finger coral grows in stubby, finger-like branches and is a sturdy, common coral in the shallows of Caribbean and Pacific reefs."},"finless-porpoise":{"id":"finless-porpoise","name":"Finless porpoise","aliases":["Neophocaena"],"kind":"creature","group":"dolphins","fact":"Finless porpoises have no dorsal fin and live in shallow coastal waters, estuaries and rivers of Asia, including the Yangtze."},"fire-coral":{"id":"fire-coral","name":"Fire coral","aliases":["Millepora"],"kind":"creature","group":"corals","fact":"Fire coral is not a true coral but a relative of jellyfish, and brushing its yellow-brown branches leaves a burning sting."},"firefly-squid":{"id":"firefly-squid","name":"Firefly squid","aliases":["Watasenia scintillans","sparkling enope squid","hotaru-ika"],"kind":"creature","group":"cephalopods","fact":"Every spring millions of firefly squid rise to the surface of Toyama Bay in Japan, lighting the water blue with thousands of tiny photophores."},"fish-larva":{"id":"fish-larva","name":"Fish larva","aliases":["fish larvae","fish egg","ichthyoplankton"],"kind":"creature","group":"plankton","fact":"Most sea fish start life as transparent larvae a few millimetres long, drifting in the plankton for weeks before they can swim properly."},"fishing-cat":{"id":"fishing-cat","name":"Fishing cat","aliases":["Prionailurus viverrinus"],"kind":"creature","group":"mammals","fact":"The fishing cat of South Asia's wetlands and Sundarbans mangroves dives into the water to catch fish and is a strong swimmer."},"fishing-smack":{"id":"fishing-smack","name":"Fishing smack","aliases":["smack","sailing smack"],"kind":"vessel","group":"boats","fact":"A fishing smack was a sailing boat, often with a wet well to keep the catch alive, used around the British coast into the 20th century."},"flabby-whalefish":{"id":"flabby-whalefish","name":"Flabby whalefish","aliases":["Cetomimidae","whalefish","Cetomimus"],"kind":"creature","group":"fish","fact":"Flabby whalefish live below about 1,500 metres and look so different from their own larvae and males that the three were once classed as separate families."},"flamboyant-cuttlefish":{"id":"flamboyant-cuttlefish","name":"Flamboyant cuttlefish","aliases":["Pfeffer's flamboyant cuttlefish","Metasepia pfefferi"],"kind":"creature","group":"cephalopods","fact":"The flamboyant cuttlefish walks along the seabed on its arms and is the only cuttlefish known to have poisonous flesh."},"flame-angelfish":{"id":"flame-angelfish","name":"Flame angelfish","aliases":["flame angel","Centropyge loriculus"],"kind":"creature","group":"fish","fact":"The flame angelfish is a small, fiery red-orange dwarf angelfish with black bars from the Pacific islands, a prized aquarium fish."},"flamingo-tongue":{"id":"flamingo-tongue","name":"Flamingo tongue","aliases":["flamingo tongue snail","Cyphoma gibbosum"],"kind":"creature","group":"molluscs","fact":"The flamingo tongue is a small Caribbean snail whose leopard-spotted colours are on a living mantle wrapped over a plain white shell, and it eats sea fans."},"flapjack-octopus":{"id":"flapjack-octopus","name":"Flapjack octopus","aliases":["Opisthoteuthis californiana","Opisthoteuthis"],"kind":"creature","group":"cephalopods","fact":"The flapjack octopus, a deep-sea dumbo relative that inspired Pearl in Finding Nemo, can flatten its webbed body into a pancake shape."},"flapper-skate":{"id":"flapper-skate","name":"Flapper skate","aliases":["Dipturus intermedius"],"kind":"creature","group":"rays","fact":"The flapper skate is the largest skate in the world, reaching about 2.5 metres long, and lays egg cases up to about 25 centimetres long."},"flashlight-fish":{"id":"flashlight-fish","name":"Flashlight fish","aliases":["Anomalops","Anomalops katoptron","Photoblepharon","lantern-eye fish","flashlightfish"],"kind":"creature","group":"fish","fact":"Flashlight fish have bean-shaped pouches of glowing bacteria under each eye, which they blink by rolling or shuttering the organ."},"flatback-turtle":{"id":"flatback-turtle","name":"Flatback turtle","aliases":["flatback","flatback sea turtle","Natator depressus"],"kind":"creature","group":"turtles","fact":"The flatback turtle nests only on Australian beaches and never leaves the continental shelf, so it is the only sea turtle without an ocean-crossing stage."},"flatfish":{"id":"flatfish","name":"Flatfish","aliases":[],"kind":"creature","group":"fish","fact":"Flatfish lie on one side on the seabed, and the side facing down loses its colour while the upper side matches the sand."},"flathead":{"id":"flathead","name":"Flathead","aliases":["dusky flathead","Platycephalus","Platycephalidae"],"kind":"creature","group":"fish","fact":"Flatheads are flattened Australian fish with a wide, bony head that lie half-buried in sand waiting for prey."},"flathead-catfish":{"id":"flathead-catfish","name":"Flathead catfish","aliases":["flathead","Pylodictis olivaris","yellow cat","mud cat","shovelhead cat"],"kind":"creature","group":"fish","fact":"The flathead catfish is a big, mottled yellow-brown predator that eats only live prey, and is caught by 'noodling' with bare hands in the southern United States."},"flemish-cap":{"id":"flemish-cap","name":"Flemish Cap","aliases":[],"kind":"place","group":"features","fact":"The Flemish Cap is an underwater plateau east of the Grand Banks, a fishing ground immortalised in the film The Perfect Storm."},"flightless-cormorant":{"id":"flightless-cormorant","name":"Flightless cormorant","aliases":["Galapagos cormorant","Phalacrocorax harrisi","Nannopterum harrisi","cormorant"],"kind":"creature","group":"seabirds","fact":"The flightless cormorant of the Galápagos has stubby wings about a third the size needed for flight and dives for fish and octopus close to shore."},"florida-current":{"id":"florida-current","name":"Florida Current","aliases":[],"kind":"place","group":"currents","fact":"The Florida Current squeezes between Florida and the Bahamas as the start of the Gulf Stream and carries far more water than all the world's rivers combined."},"florida-keys-national-marine-sanctuary":{"id":"florida-keys-national-marine-sanctuary","name":"Florida Keys National Marine Sanctuary","aliases":["Florida Keys","Key Largo","John Pennekamp Coral Reef State Park"],"kind":"place","group":"parks","fact":"The Florida Keys National Marine Sanctuary protects the only living coral barrier reef in the continental United States."},"florida-pompano":{"id":"florida-pompano","name":"Florida pompano","aliases":["pompano","Trachinotus carolinus"],"kind":"creature","group":"fish","fact":"The Florida pompano is caught in the Gulf of Mexico surf with sand fleas and is one of the most expensive fish on American menus."},"florida-reef":{"id":"florida-reef","name":"Florida Reef","aliases":["Florida Reef Tract","Florida Keys Reef Tract","Florida Keys reef","Great Florida Reef"],"kind":"place","group":"reefs","fact":"The Florida Reef is the only living coral barrier reef in the continental United States, running from near Miami to the Dry Tortugas."},"flounder":{"id":"flounder","name":"Flounder","aliases":["Pleuronectiformes","fluke"],"kind":"creature","group":"fish","fact":"Flounders start life with an eye on each side, then one eye migrates across the head as the fish settles flat on the seabed."},"flower-garden-banks":{"id":"flower-garden-banks","name":"Flower Garden Banks","aliases":["Flower Gardens","Flower Garden Banks National Marine Sanctuary"],"kind":"place","group":"reefs","fact":"The Flower Garden Banks are coral reefs growing on top of salt domes in the Gulf of Mexico, about 160 kilometres off the Texas coast."},"flower-hat-jelly":{"id":"flower-hat-jelly","name":"Flower hat jelly","aliases":["Olindias formosus","flower hat jellyfish"],"kind":"creature","group":"jellies","fact":"The flower hat jelly of Japan has fluorescent pink-tipped tentacles coiled around its rim and spends the day resting on the seabed."},"flower-urchin":{"id":"flower-urchin","name":"Flower urchin","aliases":["Toxopneustes pileolus"],"kind":"creature","group":"echinoderms","fact":"The flower urchin is the most dangerous sea urchin: its flower-like pincers inject a venom that can cause paralysis and has been blamed for diver deaths."},"flying-fish":{"id":"flying-fish","name":"Flying fish","aliases":["flyingfish","tobiko","Exocoetidae"],"kind":"creature","group":"fish","fact":"Flying fish sprint to about 60 kilometres per hour to burst from the water, then glide up to 200 metres on wing-like fins; their roe is tobiko in sushi."},"football-octopus":{"id":"football-octopus","name":"Football octopus","aliases":["Ocythoe tuberculata","tuberculate pelagic octopus"],"kind":"creature","group":"cephalopods","fact":"The football octopus is the only cephalopod with a true swim bladder, and its tiny males ride inside empty salp barrels in the open ocean."},"footballfish":{"id":"footballfish","name":"Footballfish","aliases":["Himantolophus","Pacific footballfish","Himantolophus sagamius","football fish"],"kind":"creature","group":"fish","fact":"Footballfish are round-bodied deep-sea anglers; several have washed up on California beaches, a rare sight of a fish from about 1,000 metres down."},"foraminifera":{"id":"foraminifera","name":"Foraminifera","aliases":["foram","foraminifer","foraminiferan"],"kind":"creature","group":"microbes","fact":"Foraminifera are single-celled, shell-building organisms, and soft-walled species live in the mud at the very bottom of the Challenger Deep."},"four-eyed-fish":{"id":"four-eyed-fish","name":"Four-eyed fish","aliases":["four-eyes","Anableps"],"kind":"creature","group":"fish","fact":"The four-eyed fish of Central and South American estuaries has eyes divided in two, letting it see above and below the surface at the same time."},"foureye-butterflyfish":{"id":"foureye-butterflyfish","name":"Foureye butterflyfish","aliases":["four-eyed butterflyfish","Chaetodon capistratus","foureyed butterflyfish"],"kind":"creature","group":"fish","fact":"The foureye butterflyfish of the Caribbean has a large false eye near the tail, so predators strike at the wrong end."},"foxe-basin":{"id":"foxe-basin","name":"Foxe Basin","aliases":[],"kind":"place","group":"bays","fact":"Foxe Basin north of Hudson Bay is named after Luke Foxe, the English explorer who searched it for the Northwest Passage in 1631."},"fram":{"id":"fram","name":"Fram","aliases":[],"kind":"vessel","group":"vessels","fact":"Fram was built for Fridtjof Nansen to be frozen into the Arctic ice and drift across the polar sea, and later carried Roald Amundsen to Antarctica."},"francis-drake":{"id":"francis-drake","name":"Francis Drake","aliases":["Sir Francis Drake","Drake"],"kind":"person","group":"people","fact":"Sir Francis Drake was the first captain to complete a circumnavigation of the globe, from 1577 to 1580, and the stormy passage below Cape Horn is named after him."},"franciscana":{"id":"franciscana","name":"Franciscana","aliases":["La Plata dolphin","toninha","Pontoporia blainvillei"],"kind":"creature","group":"dolphins","fact":"The franciscana, or La Plata dolphin, lives in the Río de la Plata estuary and nearby coasts and has the longest beak for its size of any dolphin."},"frasers-dolphin":{"id":"frasers-dolphin","name":"Fraser's dolphin","aliases":["Sarawak dolphin","Lagenodelphis hosei"],"kind":"creature","group":"dolphins","fact":"Fraser's dolphin was described in 1956 from a skeleton found in Sarawak and was not seen alive by scientists until the 1970s."},"freetown":{"id":"freetown","name":"Freetown","aliases":[],"kind":"place","group":"ports","fact":"Freetown, Sierra Leone, was founded in 1792 as a home for freed slaves and has one of the largest natural harbours in the world."},"french-angelfish":{"id":"french-angelfish","name":"French angelfish","aliases":["Pomacanthus paru"],"kind":"creature","group":"fish","fact":"The French angelfish is black with golden scale edges, mates for life and often approaches divers; its juveniles clean parasites from other fish."},"french-grunt":{"id":"french-grunt","name":"French grunt","aliases":["Haemulon flavolineatum"],"kind":"creature","group":"fish","fact":"French grunts shelter in dense schools on Caribbean reefs by day and spread out over the sand at night to feed."},"freshwater-angelfish":{"id":"freshwater-angelfish","name":"Freshwater angelfish","aliases":["angelfish","scalare","Pterophyllum scalare"],"kind":"creature","group":"fish","fact":"The freshwater angelfish is an Amazon cichlid with tall triangular fins that pairs for life and guards its eggs on a leaf."},"freshwater-drum":{"id":"freshwater-drum","name":"Freshwater drum","aliases":["Aplodinotus grunniens"],"kind":"creature","group":"fish","fact":"The freshwater drum of North American rivers grunts with swim-bladder muscles, and its ear bones, 'lucky stones', have been found in ancient sites."},"freshwater-eel":{"id":"freshwater-eel","name":"Freshwater eel","aliases":["river eel","Anguilla","anguillid eel"],"kind":"creature","group":"fish","fact":"Freshwater eels spend most of their lives in rivers and lakes, then make a single journey to the sea to spawn and die."},"fridtjof-nansen":{"id":"fridtjof-nansen","name":"Fridtjof Nansen","aliases":["Nansen"],"kind":"person","group":"people","fact":"Fridtjof Nansen let his ship Fram freeze into the Arctic ice to drift across the polar sea and later invented the Nansen bottle for sampling seawater at depth."},"fried-egg-jellyfish":{"id":"fried-egg-jellyfish","name":"Fried egg jellyfish","aliases":["Mediterranean jellyfish","Cotylorhiza tuberculata","fried egg jelly"],"kind":"creature","group":"jellies","fact":"The fried egg jellyfish of the Mediterranean looks exactly like its name, with a yellow dome on a white bell, and small fish shelter among its arms."},"frigate-tuna":{"id":"frigate-tuna","name":"Frigate tuna","aliases":["Auxis thazard","frigate mackerel"],"kind":"creature","group":"fish","fact":"The frigate tuna is a small, torpedo-shaped tuna found worldwide in warm seas, important both as food and as bait."},"frigatebird":{"id":"frigatebird","name":"Frigatebird","aliases":["frigate bird","man-o'-war bird","magnificent frigatebird","great frigatebird"],"kind":"creature","group":"seabirds","fact":"Frigatebirds avoid landing on water because their feathers are not waterproof, so they snatch flying fish and squid from the surface in flight or steal from other birds."},"frilled-shark":{"id":"frilled-shark","name":"Frilled shark","aliases":["Chlamydoselachus anguineus"],"kind":"creature","group":"sharks","fact":"The eel-like frilled shark has around 300 needle-like teeth and may carry its young for over three years before giving birth."},"frobisher-bay":{"id":"frobisher-bay","name":"Frobisher Bay","aliases":[],"kind":"place","group":"bays","fact":"Frobisher Bay on Baffin Island is named after Martin Frobisher, who sailed into it in 1576 searching for the Northwest Passage and brought home worthless ore he took for gold."},"frogfish":{"id":"frogfish","name":"Frogfish","aliases":["Antennariidae"],"kind":"creature","group":"fish","fact":"Frogfish are lumpy, camouflaged anglerfish of the reef that lure prey with a fleshy rod on their head and walk on their fins."},"frogspawn-coral":{"id":"frogspawn-coral","name":"Frogspawn coral","aliases":["Euphyllia divisa"],"kind":"creature","group":"corals","fact":"Frogspawn coral is named for its bubbly tentacle tips, which look like a mass of frog's eggs."},"fur-seal":{"id":"fur-seal","name":"Fur seal","aliases":[],"kind":"creature","group":"seals","fact":"Fur seals have a dense double layer of fur that once made them a target for hunters, and they are more closely related to sea lions than to true seals."},"gafftopsail-catfish":{"id":"gafftopsail-catfish","name":"Gafftopsail catfish","aliases":["gafftopsail","gafftop","sail catfish","Bagre marinus","gafftopsail sea catfish","sail cat"],"kind":"creature","group":"fish","fact":"The gafftopsail catfish is a sea catfish of the western Atlantic with long, sail-like fin filaments and venomous spines."},"gag-grouper":{"id":"gag-grouper","name":"Gag grouper","aliases":["gag","Mycteroperca microlepis"],"kind":"creature","group":"fish","fact":"The gag grouper is the most commonly caught grouper off Florida's Gulf coast, a grey fish with wavy markings that forms spawning groups offshore."},"gakkel-ridge":{"id":"gakkel-ridge","name":"Gakkel Ridge","aliases":[],"kind":"place","group":"features","fact":"The Gakkel Ridge beneath the Arctic ice is the slowest-spreading mid-ocean ridge known, yet it still hosts active hydrothermal vents."},"galapagos-bullhead-shark":{"id":"galapagos-bullhead-shark","name":"Galápagos bullhead shark","aliases":["Heterodontus quoyi"],"kind":"creature","group":"sharks","fact":"The Galápagos bullhead shark is a small spotted shark that rests on the rocks by day and crunches crabs and molluscs at night."},"galapagos-fur-seal":{"id":"galapagos-fur-seal","name":"Galápagos fur seal","aliases":["Arctocephalus galapagoensis","fur seal"],"kind":"creature","group":"seals","fact":"The Galápagos fur seal is the smallest fur seal and lives further north than any other, right on the equator."},"galapagos-garden-eel":{"id":"galapagos-garden-eel","name":"Galápagos garden eel","aliases":["garden eel","Heteroconger klausewitzi"],"kind":"creature","group":"fish","fact":"Galápagos garden eels live in colonies of burrows on sandy slopes, swaying in the current like grass and vanishing when divers approach."},"galapagos-grouper":{"id":"galapagos-grouper","name":"Galápagos grouper","aliases":["bacalao","sailfin grouper","Mycteroperca olfax"],"kind":"creature","group":"fish","fact":"The Galápagos grouper, known locally as bacalao, is found almost only around the islands and is the most valued fish of the local fishery."},"galapagos-islands":{"id":"galapagos-islands","name":"Galápagos Islands","aliases":["Galapagos","Archipiélago de Colón"],"kind":"place","group":"islands","fact":"The Galápagos Islands straddle the equator about 1,000 kilometres off Ecuador, and their finches and tortoises helped inspire Darwin's theory of evolution."},"galapagos-marine-reserve":{"id":"galapagos-marine-reserve","name":"Galápagos Marine Reserve","aliases":["Galapagos","Galápagos Islands"],"kind":"place","group":"parks","fact":"The Galápagos Marine Reserve covers well over 130,000 square kilometres around the islands and is famous for schooling hammerheads and marine iguanas."},"galapagos-penguin":{"id":"galapagos-penguin","name":"Galápagos penguin","aliases":["penguin","Spheniscus mendiculus"],"kind":"creature","group":"seabirds","fact":"The Galápagos penguin is the only penguin living on the equator and is endangered, with fewer than about 2,000 birds."},"galapagos-sea-lion":{"id":"galapagos-sea-lion","name":"Galápagos sea lion","aliases":["Zalophus wollebaeki","sea lion"],"kind":"creature","group":"seals","fact":"Galápagos sea lions are so unafraid of people that they sleep on park benches and fish-market floors in the islands' towns."},"galapagos-shark":{"id":"galapagos-shark","name":"Galápagos shark","aliases":["Carcharhinus galapagensis"],"kind":"creature","group":"sharks","fact":"Despite its name, the Galápagos shark is found around oceanic islands worldwide, including Bermuda and Ascension in the Atlantic."},"galathea":{"id":"galathea","name":"Galathea","aliases":[],"kind":"vessel","group":"vessels","fact":"The Danish ship Galathea dredged living animals from more than 10,000 metres in the Philippine Trench in 1951, proving that life exists at the ocean's greatest depths."},"gall-crab":{"id":"gall-crab","name":"Gall crab","aliases":["Cryptochiridae"],"kind":"creature","group":"crustaceans","fact":"Gall crabs settle on living coral as larvae and let the coral grow around them, sealing the female inside a chamber for life."},"galleon":{"id":"galleon","name":"Galleon","aliases":["Spanish galleon","treasure galleon"],"kind":"vessel","group":"boats","fact":"Galleons were the big, multi-decked sailing ships that carried Spain's silver across the Atlantic in the 16th and 17th centuries."},"galley":{"id":"galley","name":"Galley","aliases":["war galley"],"kind":"vessel","group":"boats","fact":"Galleys were oar-driven warships that dominated the Mediterranean from ancient times until the Battle of Lepanto in 1571."},"ganges-river-dolphin":{"id":"ganges-river-dolphin","name":"Ganges river dolphin","aliases":["Ganges dolphin","susu","South Asian river dolphin","Platanista gangetica"],"kind":"creature","group":"dolphins","fact":"The Ganges river dolphin is effectively blind, with eyes that lack a lens, and finds its way through muddy rivers by echolocation."},"gar":{"id":"gar","name":"Gar","aliases":["garpike","garfish","longnose gar","alligator gar","spotted gar","Lepisosteidae"],"kind":"creature","group":"fish","fact":"Gars can gulp air into a lung-like swim bladder, letting them survive in warm, stagnant water with little oxygen."},"garden-eel":{"id":"garden-eel","name":"Garden eel","aliases":["spotted garden eel","Heteroconger hassi","Heteroconger","Heterocongrinae"],"kind":"creature","group":"fish","fact":"Garden eels live in colonies of hundreds, each in its own sand burrow, swaying like grass to catch plankton and sinking out of sight when approached."},"garfish":{"id":"garfish","name":"Garfish","aliases":["garpike","sea needle","Belone belone"],"kind":"creature","group":"fish","fact":"The garfish of the North Sea and Baltic has a needle-like beak and bones that are naturally green."},"garibaldi":{"id":"garibaldi","name":"Garibaldi","aliases":["Hypsypops rubicundus","garibaldi damselfish"],"kind":"creature","group":"fish","fact":"The garibaldi is a bright orange damselfish of California's kelp forests, the state's official marine fish, and the males fiercely guard nests of red algae."},"general-belgrano":{"id":"general-belgrano","name":"General Belgrano","aliases":["ARA General Belgrano","Belgrano"],"kind":"vessel","group":"wrecks","fact":"The Argentine cruiser General Belgrano was torpedoed by a British submarine and sank during the Falklands War in 1982."},"gentoo-penguin":{"id":"gentoo-penguin","name":"Gentoo penguin","aliases":["Pygoscelis papua"],"kind":"creature","group":"seabirds","fact":"The gentoo is the fastest-swimming penguin, reaching about 36 kilometres per hour, and feeds on krill and fish close to shore."},"geoduck":{"id":"geoduck","name":"Geoduck","aliases":["Pacific geoduck","Panopea generosa","king clam","mirugai","elephant trunk clam"],"kind":"creature","group":"molluscs","fact":"The geoduck's siphon is so long that it cannot fit inside its shell, and the clam can live for over 150 years buried in the seabed."},"geography-cone":{"id":"geography-cone","name":"Geography cone","aliases":["Conus geographus","cigarette snail","geographer cone"],"kind":"creature","group":"molluscs","fact":"The geography cone is the deadliest cone snail, nicknamed the cigarette snail because a stung person was said to have time for one cigarette before dying."},"georges-bank":{"id":"georges-bank","name":"Georges Bank","aliases":[],"kind":"place","group":"features","fact":"Georges Bank is a shallow, fish-rich bank between Cape Cod and Nova Scotia that was once above sea level and later disputed between the USA and Canada."},"gerlache-strait":{"id":"gerlache-strait","name":"Gerlache Strait","aliases":["de Gerlache Strait"],"kind":"place","group":"straits","fact":"The Gerlache Strait along the Antarctic Peninsula is named after Adrien de Gerlache, the Belgian whose expedition was the first to winter in the Antarctic, in 1898."},"gervais-beaked-whale":{"id":"gervais-beaked-whale","name":"Gervais' beaked whale","aliases":["Gervais's beaked whale","Gulf Stream beaked whale","Antillean beaked whale","Mesoplodon europaeus"],"kind":"creature","group":"whales","fact":"Gervais' beaked whale lives in the deep Atlantic and was first described from a carcass found floating in the English Channel in 1840."},"ghost-crab":{"id":"ghost-crab","name":"Ghost crab","aliases":["Ocypode"],"kind":"creature","group":"crustaceans","fact":"Ghost crabs are pale beach crabs that dig deep burrows and are among the fastest crustaceans on land, sprinting at more than 2 metres per second."},"giant-antarctic-octopus":{"id":"giant-antarctic-octopus","name":"Giant Antarctic octopus","aliases":["Megaleledone setebos","Megaleledone"],"kind":"creature","group":"cephalopods","fact":"The giant Antarctic octopus, the largest octopus in the Southern Ocean, has venom that keeps working at freezing temperatures."},"giant-barrel-sponge":{"id":"giant-barrel-sponge","name":"Giant barrel sponge","aliases":["Xestospongia muta","barrel sponge"],"kind":"creature","group":"sponges","fact":"The giant barrel sponge of Caribbean reefs, the 'redwood of the reef', can live for more than 2,000 years."},"giant-clam":{"id":"giant-clam","name":"Giant clam","aliases":["Tridacna gigas","Tridacna"],"kind":"creature","group":"molluscs","fact":"Giant clams can grow over a metre across and get much of their food from algae living in their colourful mantle tissue."},"giant-cuttlefish":{"id":"giant-cuttlefish","name":"Giant cuttlefish","aliases":["Australian giant cuttlefish","Sepia apama"],"kind":"creature","group":"cephalopods","fact":"Australian giant cuttlefish gather in their tens of thousands each winter to breed at Whyalla, where small males disguise themselves as females to sneak past rivals."},"giant-devil-ray":{"id":"giant-devil-ray","name":"Giant devil ray","aliases":["Mobula mobular","Mediterranean devil ray"],"kind":"creature","group":"rays","fact":"The giant devil ray of the Mediterranean can span over 5 metres and gives birth to a single pup after a pregnancy of about two years."},"giant-freshwater-stingray":{"id":"giant-freshwater-stingray","name":"Giant freshwater stingray","aliases":["giant freshwater whipray","Urogymnus polylepis","Himantura polylepis","Himantura chaophraya","freshwater whipray"],"kind":"creature","group":"rays","fact":"A giant freshwater stingray caught in the Mekong in 2022 weighed about 300 kilograms, the largest freshwater fish ever recorded."},"giant-gourami":{"id":"giant-gourami","name":"Giant gourami","aliases":["Osphronemus goramy"],"kind":"creature","group":"fish","fact":"The giant gourami can grow to about 70 centimetres and uses a labyrinth organ to breathe air."},"giant-green-anemone":{"id":"giant-green-anemone","name":"Giant green anemone","aliases":["Anthopleura xanthogrammica"],"kind":"creature","group":"cnidarians","fact":"The giant green anemone of the Pacific coast gets its colour partly from algae living in its tissues and can grow to about 30 centimetres across."},"giant-grenadier":{"id":"giant-grenadier","name":"Giant grenadier","aliases":["Albatrossia pectoralis","Coryphaenoides pectoralis"],"kind":"creature","group":"fish","fact":"The giant grenadier is a deep-water rattail of the North Pacific that grows to over 2 metres long and lives for decades."},"giant-grouper":{"id":"giant-grouper","name":"Giant grouper","aliases":["Queensland grouper","Queensland groper","brindle bass","Epinephelus lanceolatus","giant groper","brindlebass"],"kind":"creature","group":"fish","fact":"The giant grouper, or Queensland grouper, is the largest bony fish on coral reefs, reaching about 2.7 metres and 400 kilograms."},"giant-isopod":{"id":"giant-isopod","name":"Giant isopod","aliases":["Bathynomus","Bathynomus giganteus","deep-sea isopod"],"kind":"creature","group":"crustaceans","fact":"The giant isopod is a deep-sea relative of the woodlouse that grows to about 40 centimetres and can go for years without a meal."},"giant-kelp":{"id":"giant-kelp","name":"Giant kelp","aliases":["Macrocystis pyrifera","Macrocystis"],"kind":"plant","group":"plants","fact":"Giant kelp is the largest seaweed, growing up to about 45 metres long and as much as half a metre in a single day."},"giant-kelpfish":{"id":"giant-kelpfish","name":"Giant kelpfish","aliases":["kelpfish","Heterostichus rostratus"],"kind":"creature","group":"fish","fact":"The giant kelpfish mimics a kelp blade, changing colour from green to brown or red to match the seaweed it hides among."},"giant-larvacean":{"id":"giant-larvacean","name":"Giant larvacean","aliases":["Bathochordaeus","Bathochordaeus charon"],"kind":"creature","group":"plankton","fact":"The giant larvacean builds a mucus house up to a metre across that filters the deep water and, when abandoned, sinks carbon and microplastics to the seafloor."},"giant-moray":{"id":"giant-moray","name":"Giant moray","aliases":["Gymnothorax javanicus","giant moray eel"],"kind":"creature","group":"fish","fact":"The giant moray can reach 3 metres and is the heaviest moray; it has been filmed hunting cooperatively with groupers on Red Sea reefs."},"giant-mottled-eel":{"id":"giant-mottled-eel","name":"Giant mottled eel","aliases":["marbled eel","Anguilla marmorata"],"kind":"creature","group":"fish","fact":"The giant mottled eel is the largest freshwater eel, reaching about 2 metres, and ranges from East Africa to Polynesia."},"giant-pacific-octopus":{"id":"giant-pacific-octopus","name":"Giant Pacific octopus","aliases":["North Pacific giant octopus","Enteroctopus dofleini","GPO"],"kind":"creature","group":"cephalopods","fact":"The giant Pacific octopus is the largest octopus, with an arm span that can exceed 4 metres, and a female guards her eggs without eating until she dies."},"giant-petrel":{"id":"giant-petrel","name":"Giant petrel","aliases":["southern giant petrel","northern giant petrel","stinker"],"kind":"creature","group":"seabirds","fact":"Giant petrels are the vultures of the Southern Ocean, tearing into seal and penguin carcasses, but they also catch fish, squid and krill at sea."},"giant-river-prawn":{"id":"giant-river-prawn","name":"Giant river prawn","aliases":["giant freshwater prawn","Macrobrachium rosenbergii","freshwater prawn","Malaysian prawn"],"kind":"creature","group":"crustaceans","fact":"The giant river prawn, with its long blue claws, is farmed in freshwater ponds across Asia and sold as scampi in India."},"giant-sea-bass":{"id":"giant-sea-bass","name":"Giant sea bass","aliases":["Stereolepis gigas","giant black sea bass","black sea bass of California"],"kind":"creature","group":"fish","fact":"The giant sea bass of California can reach over 2 metres and 250 kilograms, and nearly vanished before fishing for it was banned in 1982."},"giant-sea-spider":{"id":"giant-sea-spider","name":"Giant sea spider","aliases":["Colossendeis","Colossendeis megalonyx"],"kind":"creature","group":"sea spiders","fact":"Giant sea spiders of the deep and Antarctic seas can span about 70 centimetres, and pump blood with their guts rather than a strong heart."},"giant-siphonophore":{"id":"giant-siphonophore","name":"Giant siphonophore","aliases":["Praya dubia"],"kind":"creature","group":"jellies","fact":"The giant siphonophore Praya dubia can reach 40 to 50 metres long, among the longest animals on Earth, and its stinging tentacles glow when touched."},"giant-snakehead":{"id":"giant-snakehead","name":"Giant snakehead","aliases":["toman","redline snakehead","Channa micropeltes"],"kind":"creature","group":"fish","fact":"The giant snakehead breathes air and can grow to more than a metre long, and the parents aggressively guard their bright red young."},"giant-squid":{"id":"giant-squid","name":"Giant squid","aliases":["Architeuthis","Architeuthis dux"],"kind":"creature","group":"cephalopods","fact":"The giant squid has the largest eyes of any animal, about the size of a dinner plate, and was not filmed alive in the deep until 2012."},"giant-trevally":{"id":"giant-trevally","name":"Giant trevally","aliases":["GT","Caranx ignobilis"],"kind":"creature","group":"fish","fact":"The giant trevally of Indian Ocean reefs has been filmed leaping to snatch terns out of the air, and anglers prize its brutal strength."},"giant-tube-worm":{"id":"giant-tube-worm","name":"Giant tube worm","aliases":["tube worm","Riftia","Riftia pachyptila","tubeworm","giant tubeworm","vent tube worm"],"kind":"creature","group":"worms","fact":"The giant tube worm has no mouth or gut: bacteria inside it turn vent sulphide into food, letting it grow to 2 metres, nearly a metre of it in a single year."},"giant-warty-squid":{"id":"giant-warty-squid","name":"Giant warty squid","aliases":["Moroteuthopsis longimana","Kondakovia longimana"],"kind":"creature","group":"cephalopods","fact":"The giant warty squid of Antarctic waters can reach more than 2 metres in total length and is a food of sperm whales and other Southern Ocean predators."},"gila-trout":{"id":"gila-trout","name":"Gila trout","aliases":["Oncorhynchus gilae"],"kind":"creature","group":"fish","fact":"The Gila trout survives in a handful of mountain streams in New Mexico and Arizona and was among the first fish listed as endangered in the United States."},"gizzard-shad":{"id":"gizzard-shad","name":"Gizzard shad","aliases":["kohada","konoshiro","Konosirus punctatus","dotted gizzard shad"],"kind":"creature","group":"fish","fact":"The gizzard shad, kohada, is the fish by which Tokyo sushi chefs are judged; it is salted and pickled in vinegar before serving."},"glass-catfish":{"id":"glass-catfish","name":"Glass catfish","aliases":["ghost catfish","Kryptopterus vitreolus","Kryptopterus bicirrhis","phantom catfish"],"kind":"creature","group":"fish","fact":"The glass catfish of Southeast Asia is so transparent you can see its bones and organs, and it turns milky white when it dies."},"glass-eel":{"id":"glass-eel","name":"Glass eel","aliases":[],"kind":"creature","group":"fish","fact":"Young eels arriving at European and American coasts after drifting from the Sargasso Sea are called glass eels because their bodies are completely transparent."},"glass-octopus":{"id":"glass-octopus","name":"Glass octopus","aliases":["Vitreledonella richardi","Vitreledonella"],"kind":"creature","group":"cephalopods","fact":"The glass octopus is almost completely transparent; only its eyes, optic nerves and digestive tract show as it drifts through the open ocean."},"glass-sponge":{"id":"glass-sponge","name":"Glass sponge","aliases":["hexactinellid","Hexactinellida","Monorhaphis chuni","hexactinellid sponge","Venus' flower basket","Euplectella"],"kind":"creature","group":"sponges","fact":"Glass sponges build skeletons of silica glass fibres, and some deep-sea individuals are thought to be more than 10,000 years old."},"glass-squid":{"id":"glass-squid","name":"Glass squid","aliases":["cockatoo squid","cranchiid squid","Cranchiidae"],"kind":"creature","group":"cephalopods","fact":"Glass squid are almost completely transparent and keep their one opaque organ, the digestive gland, pointed vertically so it casts the smallest shadow."},"glassy-sweeper":{"id":"glassy-sweeper","name":"Glassy sweeper","aliases":["sweeper","Pempheris schomburgkii"],"kind":"creature","group":"fish","fact":"Glassy sweepers pack Caribbean caves in coppery schools by day and stream out at night to feed on plankton."},"globe-skimmer-dragonfly":{"id":"globe-skimmer-dragonfly","name":"Globe skimmer dragonfly","aliases":["globe skimmer","wandering glider","Pantala flavescens"],"kind":"creature","group":"insects","fact":"The globe skimmer dragonfly crosses the Indian Ocean between India and East Africa on the monsoon winds, a multi-generation round trip of about 14,000 to 18,000 kilometres."},"glomar-challenger":{"id":"glomar-challenger","name":"Glomar Challenger","aliases":[],"kind":"vessel","group":"vessels","fact":"The drilling ship Glomar Challenger took cores from the Atlantic floor in 1968 that confirmed sea-floor spreading and plate tectonics."},"gloomy-octopus":{"id":"gloomy-octopus","name":"Gloomy octopus","aliases":["Octopus tetricus","common Sydney octopus"],"kind":"creature","group":"cephalopods","fact":"Gloomy octopuses off eastern Australia gather at sites nicknamed Octopolis and Octlantis, where they have been filmed throwing shells and silt at each other."},"glovers-reef":{"id":"glovers-reef","name":"Glover's Reef","aliases":["Glover's Reef Atoll"],"kind":"place","group":"reefs","fact":"Glover's Reef is an atoll off Belize named after the pirate John Glover and is a marine reserve known for its sheer outer walls."},"glowing-sucker-octopus":{"id":"glowing-sucker-octopus","name":"Glowing sucker octopus","aliases":["Stauroteuthis syrtensis","Stauroteuthis"],"kind":"creature","group":"cephalopods","fact":"The glowing sucker octopus has suckers that no longer grip but glow blue-green, probably to lure the tiny copepods it eats."},"glowlight-tetra":{"id":"glowlight-tetra","name":"Glowlight tetra","aliases":["Hemigrammus erythrozonus"],"kind":"creature","group":"fish","fact":"The glowlight tetra is a 3-to-4-centimetre fish from Guyana with a glowing orange-red stripe down its side."},"goatfish":{"id":"goatfish","name":"Goatfish","aliases":["goat fish","Mullidae"],"kind":"creature","group":"fish","fact":"Goatfish dig through sand with a pair of chin barbels used like fingers, and some change from yellow to red in seconds when resting or being cleaned."},"goblin-shark":{"id":"goblin-shark","name":"Goblin shark","aliases":["Mitsukurina owstoni"],"kind":"creature","group":"sharks","fact":"The goblin shark shoots its jaws forward to snatch prey, and its pink skin comes from blood vessels showing through."},"goby":{"id":"goby","name":"Goby","aliases":["Gobiidae"],"kind":"creature","group":"fish","fact":"Gobies are tiny bottom-living fish whose pelvic fins are fused into a sucker that holds them onto rocks in surging water."},"golden-dorado":{"id":"golden-dorado","name":"Golden dorado","aliases":["dorado fish","Salminus brasiliensis"],"kind":"creature","group":"fish","fact":"The golden dorado of South American rivers is a brilliant gold predator that fly anglers travel to Argentina and Bolivia to catch."},"golden-gate":{"id":"golden-gate","name":"Golden Gate","aliases":["Golden Gate Strait"],"kind":"place","group":"straits","fact":"The Golden Gate is the strait connecting San Francisco Bay to the Pacific, and its famous bridge was for decades the longest suspension bridge in the world."},"golden-trout":{"id":"golden-trout","name":"Golden trout","aliases":["California golden trout","Oncorhynchus aguabonita"],"kind":"creature","group":"fish","fact":"The golden trout, with its brilliant gold and red colours, lives in the high Sierra Nevada and is the state freshwater fish of California."},"goldfish":{"id":"goldfish","name":"Goldfish","aliases":["Carassius auratus"],"kind":"creature","group":"fish","fact":"Goldfish were bred from dull carp in China about a thousand years ago, and released pets now grow huge and invasive in lakes around the world."},"goldsinny":{"id":"goldsinny","name":"Goldsinny","aliases":["goldsinny wrasse","Ctenolabrus rupestris"],"kind":"creature","group":"fish","fact":"The goldsinny is a small orange-brown wrasse of European rocky shores, now farmed as a cleaner fish to eat lice off farmed salmon."},"goliath-grouper":{"id":"goliath-grouper","name":"Goliath grouper","aliases":["Atlantic goliath grouper","jewfish","Epinephelus itajara"],"kind":"creature","group":"fish","fact":"The Atlantic goliath grouper can reach 2.5 metres and over 300 kilograms, and makes a booming sound to warn off divers."},"goliath-tigerfish":{"id":"goliath-tigerfish","name":"Goliath tigerfish","aliases":["Hydrocynus goliath","mbenga"],"kind":"creature","group":"fish","fact":"The goliath tigerfish of the Congo River has 32 dagger-like teeth and has been known to attack crocodiles."},"goonch":{"id":"goonch","name":"Goonch","aliases":["giant devil catfish","Bagarius yarrelli","Bagarius bagarius","goonch catfish"],"kind":"creature","group":"fish","fact":"The goonch, or giant devil catfish, is a huge, mottled catfish of South Asian rivers, blamed in reports from the Kali River for attacks on bathers."},"goose-barnacle":{"id":"goose-barnacle","name":"Goose barnacle","aliases":["gooseneck barnacle","percebes","Pollicipes pollicipes","goose neck barnacle","stalked barnacle","leaf barnacle","Pollicipes polymerus"],"kind":"creature","group":"crustaceans","fact":"Goose barnacles, percebes in Spain, are gathered from wave-battered rocks and are among the most expensive seafood in Europe; medieval writers thought geese hatched from them."},"gorgonian":{"id":"gorgonian","name":"Gorgonian","aliases":["gorgonian coral","horny coral"],"kind":"creature","group":"corals","fact":"Gorgonians are soft corals with a flexible, horn-like skeleton, growing as sea fans, whips and bushes."},"gourami":{"id":"gourami","name":"Gourami","aliases":["Osphronemidae","dwarf gourami","pearl gourami","three spot gourami"],"kind":"creature","group":"fish","fact":"Gouramis have a labyrinth organ that lets them breathe air from the surface, so they thrive in warm, stagnant water."},"grand-banks":{"id":"grand-banks","name":"Grand Banks","aliases":["Grand Banks of Newfoundland"],"kind":"place","group":"features","fact":"The Grand Banks off Newfoundland are shallow underwater plateaus whose cod fishery fed Europe for centuries before collapsing in 1992."},"grass-carp":{"id":"grass-carp","name":"Grass carp","aliases":["Ctenopharyngodon idella","white amur"],"kind":"creature","group":"fish","fact":"The grass carp is the most farmed fish on Earth by weight, raised in Chinese ponds on grass and water plants."},"gray-angelfish":{"id":"gray-angelfish","name":"Gray angelfish","aliases":["grey angelfish","Pomacanthus arcuatus"],"kind":"creature","group":"fish","fact":"The gray angelfish is a large, drab Caribbean angelfish that often follows divers; its juveniles are black with yellow bars."},"grayling":{"id":"grayling","name":"Grayling","aliases":["European grayling","Thymallus thymallus"],"kind":"creature","group":"fish","fact":"The grayling, 'lady of the stream', carries a tall sail-like dorsal fin and lives only in clean, cold rivers."},"grays-beaked-whale":{"id":"grays-beaked-whale","name":"Gray's beaked whale","aliases":["Haast's beaked whale","scamperdown whale","Mesoplodon grayi"],"kind":"creature","group":"whales","fact":"Gray's beaked whale, named after British zoologist John Edward Gray, is the beaked whale most often stranded in New Zealand and is seen in cold Southern Ocean waters."},"great-auk":{"id":"great-auk","name":"Great auk","aliases":["garefowl","Pinguinus impennis"],"kind":"creature","group":"seabirds","fact":"The great auk, a flightless North Atlantic seabird, was the original 'penguin', and the last known pair was killed on an Icelandic island in 1844."},"great-bahama-bank":{"id":"great-bahama-bank","name":"Great Bahama Bank","aliases":["Bahama Banks"],"kind":"place","group":"features","fact":"The Great Bahama Bank is a vast limestone platform so shallow that its turquoise waters are plainly visible from space, with the Tongue of the Ocean cut into it."},"great-barrier-reef":{"id":"great-barrier-reef","name":"Great Barrier Reef","aliases":[],"kind":"place","group":"reefs","fact":"The Great Barrier Reef stretches more than 2,300 kilometres along Australia's north-east coast and is the largest structure ever built by living things."},"great-barrier-reef-marine-park":{"id":"great-barrier-reef-marine-park","name":"Great Barrier Reef Marine Park","aliases":["Great Barrier Reef","GBR"],"kind":"place","group":"parks","fact":"The Great Barrier Reef Marine Park protects about 344,000 square kilometres of reef off Queensland, the largest coral reef system on Earth."},"great-blue-hole":{"id":"great-blue-hole","name":"Great Blue Hole","aliases":["Blue Hole","Belize Blue Hole","Blue Hole Belize"],"kind":"place","group":"divesites","fact":"The Great Blue Hole off Belize is a near-circular sinkhole about 300 metres across and 120 metres deep that was a dry cave before the sea rose."},"great-britain":{"id":"great-britain","name":"Great Britain","aliases":["Britain","British Isles","United Kingdom"],"kind":"place","group":"islands","fact":"Great Britain is the largest island in Europe and was joined to the continent by dry land until rising seas flooded Doggerland about 8,000 years ago."},"great-chagos-bank":{"id":"great-chagos-bank","name":"Great Chagos Bank","aliases":[],"kind":"place","group":"reefs","fact":"The Great Chagos Bank in the Indian Ocean is the largest atoll structure in the world and is almost entirely submerged."},"great-hammerhead":{"id":"great-hammerhead","name":"Great hammerhead","aliases":["great hammerhead shark","Sphyrna mokarran"],"kind":"creature","group":"sharks","fact":"The great hammerhead, the largest hammerhead at up to about 6 metres, uses its head to pin stingrays to the seabed."},"great-sea-reef":{"id":"great-sea-reef","name":"Great Sea Reef","aliases":["Cakaulevu","Cakaulevu Reef"],"kind":"place","group":"reefs","fact":"Fiji's Great Sea Reef, known locally as Cakaulevu, is the third-longest continuous barrier reef in the world."},"great-skua":{"id":"great-skua","name":"Great skua","aliases":["skua","bonxie","Stercorarius skua"],"kind":"creature","group":"seabirds","fact":"The great skua, nicknamed the bonxie in Shetland, catches fish itself but is better known for robbing gannets and puffins of theirs."},"great-white-shark":{"id":"great-white-shark","name":"Great white shark","aliases":["white shark","great white","white pointer","Carcharodon carcharias"],"kind":"creature","group":"sharks","fact":"Great white sharks can sense the faint electrical fields given off by the muscles and heartbeat of hidden prey."},"greater-amberjack":{"id":"greater-amberjack","name":"Greater amberjack","aliases":["amberjack","kanpachi","Seriola dumerili"],"kind":"creature","group":"fish","fact":"The greater amberjack, kanpachi in Japan, is a fast, powerful hunter of the open water, farmed in sea pens and served as firm, mild sashimi."},"greater-blue-ringed-octopus":{"id":"greater-blue-ringed-octopus","name":"Greater blue-ringed octopus","aliases":["Hapalochlaena lunulata"],"kind":"creature","group":"cephalopods","fact":"Despite its name the greater blue-ringed octopus is only about 10 centimetres across; it is the size of its rings that is greater than its relatives'."},"greater-forkbeard":{"id":"greater-forkbeard","name":"Greater forkbeard","aliases":["Phycis blennoides","forkbeard"],"kind":"creature","group":"fish","fact":"The greater forkbeard is a deep-water cod relative of the eastern Atlantic with long, forked pelvic fins used to feel for food."},"greater-pipefish":{"id":"greater-pipefish","name":"Greater pipefish","aliases":["Syngnathus acus"],"kind":"creature","group":"fish","fact":"The greater pipefish of European coasts grows to about 45 centimetres, and the male broods the eggs in a pouch under his tail."},"green-lipped-mussel":{"id":"green-lipped-mussel","name":"Green-lipped mussel","aliases":["New Zealand green-lipped mussel","greenshell mussel","Perna canaliculus","green mussel"],"kind":"creature","group":"molluscs","fact":"The green-lipped mussel is found only in New Zealand, where it is farmed on ropes and exported worldwide, including as a joint supplement."},"green-moray":{"id":"green-moray","name":"Green moray","aliases":["Gymnothorax funebris","green moray eel"],"kind":"creature","group":"fish","fact":"The green moray of the Caribbean is actually brown; a coat of yellow mucus over its skin makes it look green."},"green-neon-tetra":{"id":"green-neon-tetra","name":"Green neon tetra","aliases":["Paracheirodon simulans","false neon tetra","blue neon tetra"],"kind":"creature","group":"fish","fact":"The green neon tetra is a 2.5-centimetre relative of the neon tetra from the upper Orinoco and Rio Negro with a blue-green stripe."},"green-sawfish":{"id":"green-sawfish","name":"Green sawfish","aliases":["Pristis zijsron"],"kind":"creature","group":"rays","fact":"The green sawfish is one of the largest sawfish, reported at over 7 metres long, and is now critically endangered."},"green-sea-urchin":{"id":"green-sea-urchin","name":"Green sea urchin","aliases":["Strongylocentrotus droebachiensis"],"kind":"creature","group":"echinoderms","fact":"The green sea urchin lives in cold northern waters of both the Atlantic and the Pacific and is harvested for its roe."},"green-spotted-puffer":{"id":"green-spotted-puffer","name":"Green spotted puffer","aliases":["green puffer","Dichotomyctere nigroviridis"],"kind":"creature","group":"fish","fact":"The green spotted puffer lives in brackish South-East Asian estuaries and is a common, if demanding, aquarium fish."},"green-turtle":{"id":"green-turtle","name":"Green turtle","aliases":["green sea turtle","Chelonia mydas"],"kind":"creature","group":"turtles","fact":"Adult green sea turtles graze on seagrass and algae, which stains their fat green and gives them their name; they may live for 70 years or more."},"greenland":{"id":"greenland","name":"Greenland","aliases":["Kalaallit Nunaat"],"kind":"place","group":"islands","fact":"Greenland is the largest island in the world, lying between the Atlantic and Arctic oceans, and about 80 per cent of it is buried under an ice sheet."},"greenland-cod":{"id":"greenland-cod","name":"Greenland cod","aliases":["Gadus ogac","ogac"],"kind":"creature","group":"fish","fact":"The Greenland cod is a dark, slow-growing cod of Arctic coastal waters, caught by Inuit through holes in the ice."},"greenland-halibut":{"id":"greenland-halibut","name":"Greenland halibut","aliases":["Greenland turbot","black halibut","Reinhardtius hippoglossoides"],"kind":"creature","group":"fish","fact":"The Greenland halibut's migrating eye stops at the top edge of its head, so it can swim upright as well as lie flat."},"greenland-shark":{"id":"greenland-shark","name":"Greenland shark","aliases":["gurry shark","Somniosus microcephalus"],"kind":"creature","group":"sharks","fact":"Greenland sharks grow about a centimetre a year and may live for several centuries, longer than any other known vertebrate."},"grenadier":{"id":"grenadier","name":"Grenadier","aliases":["rattail","rat-tail","Macrouridae","grenadier fish"],"kind":"creature","group":"fish","fact":"Grenadiers, or rattails, are the commonest fish on the deep seabed, with big heads and whip-like tails, and have been seen about 7,000 metres down."},"grey-mullet":{"id":"grey-mullet","name":"Grey mullet","aliases":["gray mullet","thick-lipped grey mullet","flathead grey mullet","Mugil cephalus"],"kind":"creature","group":"fish","fact":"The grey mullet grazes algae and mud in estuaries and harbours around the world, and its roe is pressed into bottarga."},"grey-reef-shark":{"id":"grey-reef-shark","name":"Grey reef shark","aliases":["gray reef shark","Carcharhinus amblyrhynchos"],"kind":"creature","group":"sharks","fact":"Grey reef sharks warn off intruders with a hunched, exaggerated swimming display before they attack."},"grey-seal":{"id":"grey-seal","name":"Grey seal","aliases":["gray seal","Atlantic grey seal","Halichoerus grypus"],"kind":"creature","group":"seals","fact":"Grey seal pups are born with white fur and are weaned in under three weeks, after which the mother leaves them to fend for themselves."},"grey-snapper":{"id":"grey-snapper","name":"Grey snapper","aliases":["mangrove snapper","gray snapper","Lutjanus griseus"],"kind":"creature","group":"fish","fact":"The mangrove snapper, or gray snapper, grows up among mangrove roots and is one of the most commonly caught snappers in Florida."},"grey-triggerfish":{"id":"grey-triggerfish","name":"Grey triggerfish","aliases":["gray triggerfish","Balistes capriscus"],"kind":"creature","group":"fish","fact":"The grey triggerfish is found on both sides of the Atlantic, from the Gulf of Mexico to the Mediterranean, and is increasingly seen off Britain."},"grey-whale":{"id":"grey-whale","name":"Grey whale","aliases":["gray whale","Eschrichtius robustus","California gray whale","devil fish"],"kind":"creature","group":"whales","fact":"Grey whales feed unlike any other whale, rolling on their sides to suck up mouthfuls of mud and straining out tiny amphipods through their baleen."},"grouper":{"id":"grouper","name":"Grouper","aliases":["groper","Epinephelinae","Epinephelus","rock cod","Epinephelidae"],"kind":"creature","group":"fish","fact":"Groupers are big-mouthed reef predators that suck in prey whole, and some species have been seen hunting together with moray eels."},"grunion":{"id":"grunion","name":"Grunion","aliases":["California grunion","Leuresthes tenuis"],"kind":"creature","group":"fish","fact":"Grunion ride the highest tides onto Californian beaches at night to spawn in the sand, and crowds come to catch them by hand."},"grunt":{"id":"grunt","name":"Grunt","aliases":["grunt fish","French grunt","bluestriped grunt","white grunt","Haemulidae"],"kind":"creature","group":"fish","fact":"Grunts are named for the sound they make by grinding their throat teeth together, amplified by the swim bladder, especially when caught."},"grunt-sculpin":{"id":"grunt-sculpin","name":"Grunt sculpin","aliases":["Rhamphocottus richardsonii"],"kind":"creature","group":"fish","fact":"The grunt sculpin of the Pacific Northwest hops along the bottom on its fins and hides inside empty giant barnacle shells."},"guam":{"id":"guam","name":"Guam","aliases":[],"kind":"place","group":"islands","fact":"Guam is the largest of the Mariana Islands and lies close to the Mariana Trench, the deepest part of the ocean."},"guanabara-bay":{"id":"guanabara-bay","name":"Guanabara Bay","aliases":[],"kind":"place","group":"bays","fact":"Guanabara Bay is the great bay on which Rio de Janeiro stands, named River of January by Portuguese sailors who reached it in January 1502 and, by tradition, took it for a river mouth."},"guanay-cormorant":{"id":"guanay-cormorant","name":"Guanay cormorant","aliases":["guanay","Leucocarbo bougainvillii"],"kind":"creature","group":"seabirds","fact":"The guanay cormorant of Peru eats anchovies from the Humboldt Current, and its droppings built the guano deposits that made 19th-century fortunes."},"guiana-dolphin":{"id":"guiana-dolphin","name":"Guiana dolphin","aliases":["costero","estuarine dolphin","Sotalia guianensis"],"kind":"creature","group":"dolphins","fact":"The Guiana dolphin lives in estuaries and bays along the Atlantic coast of South and Central America and can sense electric fields with its snout."},"guinea-current":{"id":"guinea-current","name":"Guinea Current","aliases":[],"kind":"place","group":"currents","fact":"The Guinea Current flows eastward along the coast of West Africa into the Gulf of Guinea."},"guineafowl-puffer":{"id":"guineafowl-puffer","name":"Guineafowl puffer","aliases":["golden puffer","Arothron meleagris"],"kind":"creature","group":"fish","fact":"The guineafowl puffer is black with tiny white spots like the bird, and some individuals are entirely golden-yellow instead."},"guitarfish":{"id":"guitarfish","name":"Guitarfish","aliases":["shovelnose ray","shovelnose guitarfish","Rhinobatidae"],"kind":"creature","group":"rays","fact":"Guitarfish are rays shaped like a guitar, with a flattened shark-like body, and they give birth to live young."},"gulf-corvina":{"id":"gulf-corvina","name":"Gulf corvina","aliases":["Cynoscion othonopterus"],"kind":"creature","group":"fish","fact":"Gulf corvinas gather by the million in the Colorado River delta to spawn, and their chorus is loud enough to damage the hearing of nearby dolphins."},"gulf-menhaden":{"id":"gulf-menhaden","name":"Gulf menhaden","aliases":["Brevoortia patronus"],"kind":"creature","group":"fish","fact":"The Gulf menhaden is the biggest fishery by weight in the Gulf of Mexico and the main food of its pelicans, dolphins and redfish."},"gulf-of-alaska":{"id":"gulf-of-alaska","name":"Gulf of Alaska","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Alaska is a wide arm of the Pacific along Alaska's southern coast where glaciers meet the sea and ferocious winter storms are born."},"gulf-of-antalya":{"id":"gulf-of-antalya","name":"Gulf of Antalya","aliases":["Antalya Bay"],"kind":"place","group":"gulfs","fact":"The Gulf of Antalya on Turkey's southern coast is a wide bay of the Levantine Sea backed by the Taurus Mountains."},"gulf-of-bothnia":{"id":"gulf-of-bothnia","name":"Gulf of Bothnia","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Bothnia, the northern arm of the Baltic, is so fresh and cold that it is largely frozen for months each winter."},"gulf-of-cadiz":{"id":"gulf-of-cadiz","name":"Gulf of Cádiz","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Cádiz lies off south-west Spain and Portugal just outside the Strait of Gibraltar, where salty Mediterranean water pours out into the Atlantic."},"gulf-of-california":{"id":"gulf-of-california","name":"Gulf of California","aliases":["Sea of Cortez","Sea of Cortés","Vermilion Sea"],"kind":"place","group":"gulfs","fact":"The Gulf of California, also called the Sea of Cortez after the conquistador Hernán Cortés, separates Baja California from mainland Mexico and is home to the vaquita."},"gulf-of-carpentaria":{"id":"gulf-of-carpentaria","name":"Gulf of Carpentaria","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Carpentaria in northern Australia is named after Pieter de Carpentier, a governor-general of the Dutch East Indies, and hosts the Morning Glory cloud."},"gulf-of-corinth":{"id":"gulf-of-corinth","name":"Gulf of Corinth","aliases":["Corinthian Gulf"],"kind":"place","group":"gulfs","fact":"The Gulf of Corinth nearly cuts the Peloponnese off from mainland Greece, and the Corinth Canal, finished in 1893, links it to the Saronic Gulf."},"gulf-of-finland":{"id":"gulf-of-finland","name":"Gulf of Finland","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Finland is the easternmost arm of the Baltic Sea, with St Petersburg at its head and Helsinki and Tallinn on its shores."},"gulf-of-gabes":{"id":"gulf-of-gabes","name":"Gulf of Gabès","aliases":["Lesser Syrtis","Syrtis Minor"],"kind":"place","group":"gulfs","fact":"The Gulf of Gabès off Tunisia has the largest tides in the Mediterranean, up to about 2 metres, in a sea where tides are usually tiny."},"gulf-of-genoa":{"id":"gulf-of-genoa","name":"Gulf of Genoa","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Genoa is the northernmost part of the Ligurian Sea, with the port of Genoa, birthplace of Christopher Columbus, at its head."},"gulf-of-guinea":{"id":"gulf-of-guinea","name":"Gulf of Guinea","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Guinea is the great bend of the African coast where the equator and the prime meridian cross in open water."},"gulf-of-hammamet":{"id":"gulf-of-hammamet","name":"Gulf of Hammamet","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Hammamet is a bay on Tunisia's east coast lined with beach resorts."},"gulf-of-honduras":{"id":"gulf-of-honduras","name":"Gulf of Honduras","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Honduras is a Caribbean inlet bordered by Belize, Guatemala and Honduras at the southern end of the Mesoamerican Reef."},"gulf-of-iskenderun":{"id":"gulf-of-iskenderun","name":"Gulf of İskenderun","aliases":["Gulf of Alexandretta","Iskenderun Bay"],"kind":"place","group":"gulfs","fact":"The Gulf of İskenderun in the far north-east corner of the Mediterranean is where the Turkish coast turns south towards Syria, near the ancient battlefield of Issus."},"gulf-of-lion":{"id":"gulf-of-lion","name":"Gulf of Lion","aliases":["Gulf of Lions","Golfe du Lion"],"kind":"place","group":"gulfs","fact":"The Gulf of Lion on the south coast of France is swept by the mistral wind and receives the waters of the Rhône."},"gulf-of-maine":{"id":"gulf-of-maine","name":"Gulf of Maine","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Maine is one of the fastest-warming bodies of water in the world and borders the famous Georges Bank fishing grounds."},"gulf-of-mexico":{"id":"gulf-of-mexico","name":"Gulf of Mexico","aliases":["Gulf of America"],"kind":"place","group":"gulfs","fact":"The Gulf of Mexico is an ocean basin of the Atlantic almost encircled by Mexico, Cuba and the United States, and the Mississippi River drains into it."},"gulf-of-naples":{"id":"gulf-of-naples","name":"Gulf of Naples","aliases":["Bay of Naples"],"kind":"place","group":"gulfs","fact":"The Gulf of Naples is overlooked by Mount Vesuvius, whose eruption in AD 79 buried Pompeii, and holds the islands of Capri and Ischia."},"gulf-of-panama":{"id":"gulf-of-panama","name":"Gulf of Panama","aliases":["Bay of Panama","Panama Bay"],"kind":"place","group":"gulfs","fact":"The Gulf of Panama is the Pacific entrance to the Panama Canal and has some of the largest tides in the tropics, unlike the tiny tides on the Caribbean side."},"gulf-of-paria":{"id":"gulf-of-paria","name":"Gulf of Paria","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Paria is a shallow inlet between Trinidad and Venezuela, fed by the muddy waters of the Orinoco delta."},"gulf-of-riga":{"id":"gulf-of-riga","name":"Gulf of Riga","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Riga is a bay of the Baltic Sea enclosed by Latvia and Estonia and nearly cut off from the open sea by the island of Saaremaa."},"gulf-of-salerno":{"id":"gulf-of-salerno","name":"Gulf of Salerno","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Salerno, south of the Amalfi Coast, was where Allied troops landed in Italy in September 1943."},"gulf-of-san-jorge":{"id":"gulf-of-san-jorge","name":"Gulf of San Jorge","aliases":["Golfo San Jorge","San Jorge Gulf"],"kind":"place","group":"gulfs","fact":"The Gulf of San Jorge is a wide bay on the Patagonian coast of Argentina, open to the South Atlantic."},"gulf-of-sidra":{"id":"gulf-of-sidra","name":"Gulf of Sidra","aliases":["Gulf of Sirte","Gulf of Sirt"],"kind":"place","group":"gulfs","fact":"The Gulf of Sidra on the coast of Libya was claimed by Gaddafi as Libyan waters behind a Line of Death, leading to clashes with the US Navy in the 1980s."},"gulf-of-st-lawrence":{"id":"gulf-of-st-lawrence","name":"Gulf of St Lawrence","aliases":["Gulf of Saint Lawrence"],"kind":"place","group":"gulfs","fact":"The Gulf of St Lawrence, where the St Lawrence River meets the Atlantic, is one of the largest estuarine systems in the world, and ice covers the whole gulf in January and February."},"gulf-of-taranto":{"id":"gulf-of-taranto","name":"Gulf of Taranto","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Taranto is the large bay in the instep of Italy's boot, opening onto the Ionian Sea."},"gulf-of-tehuantepec":{"id":"gulf-of-tehuantepec","name":"Gulf of Tehuantepec","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Tehuantepec off southern Mexico is famous for violent gap winds that blast through the mountains and far out to sea."},"gulf-of-thailand":{"id":"gulf-of-thailand","name":"Gulf of Thailand","aliases":["Gulf of Siam"],"kind":"place","group":"gulfs","fact":"The Gulf of Thailand is a shallow inlet of the South China Sea, bordered by Thailand, Cambodia, Vietnam and Malaysia."},"gulf-of-tonkin":{"id":"gulf-of-tonkin","name":"Gulf of Tonkin","aliases":["Tonkin Gulf"],"kind":"place","group":"gulfs","fact":"The Gulf of Tonkin, between northern Vietnam and China, holds Halong Bay and gave its name to the 1964 incident that drew the United States deeper into the Vietnam War."},"gulf-of-trieste":{"id":"gulf-of-trieste","name":"Gulf of Trieste","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Trieste is the northernmost point of the Adriatic and of the whole Mediterranean, shared by Italy, Slovenia and Croatia."},"gulf-of-tunis":{"id":"gulf-of-tunis","name":"Gulf of Tunis","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Tunis is a bay of the Mediterranean on which the ruins of ancient Carthage stand, near the modern city of Tunis."},"gulf-of-venezuela":{"id":"gulf-of-venezuela","name":"Gulf of Venezuela","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Venezuela opens off the Caribbean and connects through a narrow channel to Lake Maracaibo, one of the world's oldest oil regions."},"gulf-of-venice":{"id":"gulf-of-venice","name":"Gulf of Venice","aliases":[],"kind":"place","group":"gulfs","fact":"The Gulf of Venice is the northern end of the Adriatic Sea, so shallow that Venice floods whenever strong winds push water into it."},"gulf-stream":{"id":"gulf-stream","name":"Gulf Stream","aliases":[],"kind":"place","group":"currents","fact":"The Gulf Stream carries warm water from the Gulf of Mexico up the US east coast and across the Atlantic, keeping north-west Europe far milder than its latitude suggests."},"gulf-sturgeon":{"id":"gulf-sturgeon","name":"Gulf sturgeon","aliases":["Acipenser oxyrinchus desotoi"],"kind":"creature","group":"fish","fact":"The Gulf sturgeon spends summers in rivers such as the Suwannee and winters in the Gulf of Mexico, and leaping fish have injured boaters."},"gull":{"id":"gull","name":"Gull","aliases":["seagull","sea gull","herring gull","great black-backed gull","black-headed gull"],"kind":"creature","group":"seabirds","fact":"Gulls are the ocean's opportunists, snatching fish from the surface, raiding fishing boats and stealing catches from other seabirds."},"gulper-eel":{"id":"gulper-eel","name":"Gulper eel","aliases":["pelican eel","Eurypharynx pelecanoides","umbrella-mouth gulper","pelican gulper"],"kind":"creature","group":"fish","fact":"The gulper eel's mouth is bigger than the rest of its body, and it can balloon out like a pelican's pouch to swallow prey larger than itself."},"gulper-shark":{"id":"gulper-shark","name":"Gulper shark","aliases":["Centrophorus granulosus"],"kind":"creature","group":"sharks","fact":"Gulper sharks live on deep slopes and have only one or two pups every couple of years, so their populations collapse quickly under fishing."},"gumboot-chiton":{"id":"gumboot-chiton","name":"Gumboot chiton","aliases":["giant Pacific chiton","wandering meatloaf","Cryptochiton stelleri"],"kind":"creature","group":"molluscs","fact":"The gumboot chiton is the largest chiton in the world, a reddish-brown lump up to about 36 centimetres long nicknamed the wandering meatloaf."},"guppy":{"id":"guppy","name":"Guppy","aliases":["millionfish","Poecilia reticulata"],"kind":"creature","group":"fish","fact":"The guppy, the classic beginner's aquarium fish, now lives wild on every continent except Antarctica after releases to control mosquitoes."},"gurnard":{"id":"gurnard","name":"Gurnard","aliases":["tub gurnard","red gurnard","grey gurnard","Trigla"],"kind":"creature","group":"fish","fact":"Gurnards grunt and growl by vibrating their swim bladder, which gave the fish its name from an old French word for grunting."},"gutweed":{"id":"gutweed","name":"Gutweed","aliases":["Ulva intestinalis","Enteromorpha","grass kelp"],"kind":"plant","group":"plants","fact":"Gutweed is a bright green, tube-shaped seaweed of upper shores and estuaries, named for its hollow, gut-like fronds."},"haddock":{"id":"haddock","name":"Haddock","aliases":["Melanogrammus aeglefinus"],"kind":"creature","group":"fish","fact":"Haddock, with a black 'thumbprint' behind the gill, is the favourite fish-and-chips fish in Scotland and northern England and is smoked as finnan haddie."},"hagfish":{"id":"hagfish","name":"Hagfish","aliases":["slime eel","Myxine","Pacific hagfish","Myxini"],"kind":"creature","group":"fish","fact":"A hagfish can turn a bucket of water into slime in seconds, ties itself in a knot to wipe it off, and feeds on carcasses thousands of metres down."},"hairy-vent-snail":{"id":"hairy-vent-snail","name":"Hairy vent snail","aliases":["Alviniconcha","Alviniconcha hessleri","hairy snail"],"kind":"creature","group":"molluscs","fact":"Alviniconcha vent snails have bristly shells and gills packed with bacteria that feed them, so they barely need to eat."},"hake":{"id":"hake","name":"Hake","aliases":["Merluccius"],"kind":"creature","group":"fish","fact":"Hake is a slim relative of cod and the favourite fish of Spain, which eats more of it than any other country."},"halfbeak":{"id":"halfbeak","name":"Halfbeak","aliases":["Hemiramphidae","ballyhoo"],"kind":"creature","group":"fish","fact":"Halfbeaks are slender surface fish with a long lower jaw; many species feed on seagrass and floating algae."},"halibut":{"id":"halibut","name":"Halibut","aliases":["Hippoglossus"],"kind":"creature","group":"fish","fact":"Halibut are the largest flatfish, and Atlantic halibut can grow to over 2 metres long and more than 300 kilograms."},"halifax":{"id":"halifax","name":"Halifax","aliases":["Halifax, Nova Scotia"],"kind":"place","group":"ports","fact":"Halifax, Nova Scotia, has one of the largest natural harbours in the world, and many of the Titanic's victims are buried in the city's cemeteries."},"halimeda":{"id":"halimeda","name":"Halimeda","aliases":["cactus algae","money plant algae"],"kind":"plant","group":"plants","fact":"Halimeda is a green seaweed built from chalky segments; its dead flakes make up much of the white sand on tropical beaches."},"hallucigenia":{"id":"hallucigenia","name":"Hallucigenia","aliases":[],"kind":"creature","group":"worms","fact":"Hallucigenia, a spiny Cambrian worm from the Burgess Shale, was so strange that scientists first reconstructed it upside down."},"halong-bay":{"id":"halong-bay","name":"Halong Bay","aliases":["Ha Long Bay"],"kind":"place","group":"bays","fact":"Halong Bay in northern Vietnam is studded with about 1,600 limestone islands and is a UNESCO World Heritage Site."},"halosaur":{"id":"halosaur","name":"Halosaur","aliases":["Halosauridae","Aldrovandia"],"kind":"creature","group":"fish","fact":"Halosaurs are long-tailed, eel-like fish of the deep seabed, swimming slowly over abyssal mud below 1,000 metres with a snout that overhangs the mouth."},"hammer-coral":{"id":"hammer-coral","name":"Hammer coral","aliases":["anchor coral","Euphyllia ancora","Fimbriaphyllia ancora"],"kind":"creature","group":"corals","fact":"Hammer coral's tentacles end in hammer or anchor-shaped tips, and it sends out long sweeper tentacles to sting neighbouring corals."},"hammerhead-shark":{"id":"hammerhead-shark","name":"Hammerhead shark","aliases":["hammerhead","scalloped hammerhead","great hammerhead","smooth hammerhead","Sphyrna"],"kind":"creature","group":"sharks","fact":"A hammerhead's wide head spreads its eyes and electrical sensors across a broad span, helping it sweep the seabed for buried rays."},"hanauma-bay":{"id":"hanauma-bay","name":"Hanauma Bay","aliases":["Hanauma Bay Nature Preserve"],"kind":"place","group":"parks","fact":"Hanauma Bay on Oahu is a flooded volcanic crater that became Hawaii's first marine life conservation district in 1967."},"hangzhou-bay":{"id":"hangzhou-bay","name":"Hangzhou Bay","aliases":[],"kind":"place","group":"bays","fact":"Hangzhou Bay in eastern China produces the world's largest tidal bore, a wall of water that surges up the Qiantang River."},"hans-hass":{"id":"hans-hass","name":"Hans Hass","aliases":[],"kind":"person","group":"people","fact":"Hans Hass was an Austrian diving pioneer who made some of the first underwater films of sharks and manta rays in the 1940s and 1950s."},"harbour-porpoise":{"id":"harbour-porpoise","name":"Harbour porpoise","aliases":["harbor porpoise","common porpoise","puffing pig","Phocoena phocoena"],"kind":"creature","group":"dolphins","fact":"The harbour porpoise is the smallest cetacean in European waters and must feed almost constantly to stay warm."},"harbour-seal":{"id":"harbour-seal","name":"Harbour seal","aliases":["harbor seal","common seal","Phoca vitulina"],"kind":"creature","group":"seals","fact":"Harbour seals are the most widespread pinniped, hauling out on coasts all around the Northern Hemisphere."},"hardhead-catfish":{"id":"hardhead-catfish","name":"Hardhead catfish","aliases":["hardhead sea catfish","Ariopsis felis","sea catfish"],"kind":"creature","group":"fish","fact":"The hardhead catfish is a sea catfish of the Gulf of Mexico whose males carry the marble-sized eggs in their mouths for about two months."},"harlequin-filefish":{"id":"harlequin-filefish","name":"Harlequin filefish","aliases":["orange-spotted filefish","orangespotted filefish","longnose filefish","Oxymonacanthus longirostris"],"kind":"creature","group":"fish","fact":"The harlequin filefish eats only Acropora coral polyps and ends up smelling like the coral it eats, which hides it from predators that hunt by scent."},"harlequin-rasbora":{"id":"harlequin-rasbora","name":"Harlequin rasbora","aliases":["rasbora","Trigonostigma heteromorpha"],"kind":"creature","group":"fish","fact":"The harlequin rasbora, with a black triangle on its side, lays its eggs on the underside of leaves in Malaysian and Thai streams."},"harlequin-shrimp":{"id":"harlequin-shrimp","name":"Harlequin shrimp","aliases":["Hymenocera picta","clown shrimp"],"kind":"creature","group":"crustaceans","fact":"Harlequin shrimp hunt in pairs and eat only starfish, flipping their prey over and feeding on it alive for days."},"harlequin-tuskfish":{"id":"harlequin-tuskfish","name":"Harlequin tuskfish","aliases":["harlequin tusk","Choerodon fasciatus"],"kind":"creature","group":"fish","fact":"The harlequin tuskfish has bright blue tusk-like teeth and orange bands, and uses the teeth to crush shellfish on Indo-Pacific reefs."},"harp-seal":{"id":"harp-seal","name":"Harp seal","aliases":["saddleback seal","Pagophilus groenlandicus"],"kind":"creature","group":"seals","fact":"Harp seal pups are born on the sea ice with fluffy white coats, and the species was the focus of the famous Canadian seal hunt protests."},"harp-sponge":{"id":"harp-sponge","name":"Harp sponge","aliases":["Chondrocladia lyra","lyre sponge"],"kind":"creature","group":"sponges","fact":"The harp sponge, found 3,300 metres down off California in 2012, is a carnivore: it snags tiny crustaceans on Velcro-like hooks along its harp-shaped branches."},"hatchetfish":{"id":"hatchetfish","name":"Hatchetfish","aliases":["marine hatchetfish","Argyropelecus","Sternoptychidae"],"kind":"creature","group":"fish","fact":"Hatchetfish are silver, blade-thin fish with photophores on their bellies that match the faint light from above, making them invisible from below."},"havana":{"id":"havana","name":"Havana","aliases":["La Habana"],"kind":"place","group":"ports","fact":"Havana's sheltered harbour on the Straits of Florida was the gathering point for Spain's treasure fleets before they crossed the Atlantic."},"hawaii":{"id":"hawaii","name":"Hawaii","aliases":["Hawaiian Islands","Big Island"],"kind":"place","group":"islands","fact":"The Hawaiian Islands are the tops of volcanoes built over a hotspot, and Mauna Kea is the tallest mountain on Earth measured from its base on the sea floor."},"hawaiian-emperor-seamount-chain":{"id":"hawaiian-emperor-seamount-chain","name":"Hawaiian-Emperor seamount chain","aliases":["Emperor seamounts","Hawaiian Emperor chain","Emperor seamount chain"],"kind":"place","group":"features","fact":"The Hawaiian-Emperor seamount chain is a line of drowned volcanoes stretching about 6,000 kilometres across the Pacific, built as the plate moved over a hotspot."},"hawaiian-monk-seal":{"id":"hawaiian-monk-seal","name":"Hawaiian monk seal","aliases":["Neomonachus schauinslandi"],"kind":"creature","group":"seals","fact":"The Hawaiian monk seal is one of the rarest seals, with only around 1,500 left, and its Hawaiian name means 'dog that runs in rough water'."},"hawkfish":{"id":"hawkfish","name":"Hawkfish","aliases":["hawk fish","Cirrhitidae"],"kind":"creature","group":"fish","fact":"Hawkfish perch on coral heads using their thick pectoral fins, watching for prey like a hawk before darting out to grab it."},"hawksbill-turtle":{"id":"hawksbill-turtle","name":"Hawksbill turtle","aliases":["hawksbill","hawksbill sea turtle","Eretmochelys imbricata"],"kind":"creature","group":"turtles","fact":"Hawksbill turtles eat sea sponges that are toxic to most animals, and their patterned shells were the source of 'tortoiseshell'."},"headless-chicken-monster":{"id":"headless-chicken-monster","name":"Headless chicken monster","aliases":["Enypniastes eximia","swimming sea cucumber","pink see-through fantasia","headless chicken fish","Spanish dancer sea cucumber"],"kind":"creature","group":"echinoderms","fact":"The headless chicken monster is a translucent pink sea cucumber that swims with a webbed collar and sheds a sticky glowing skin onto anything that touches it."},"heart-urchin":{"id":"heart-urchin","name":"Heart urchin","aliases":["sea potato","Echinocardium cordatum"],"kind":"creature","group":"echinoderms","fact":"The heart urchin, or sea potato, is a burrowing urchin with a heart-shaped shell that lives hidden in sand below the low-tide mark."},"heavisides-dolphin":{"id":"heavisides-dolphin","name":"Heaviside's dolphin","aliases":["Haviside's dolphin","Benguela dolphin","Cephalorhynchus heavisidii"],"kind":"creature","group":"dolphins","fact":"Heaviside's dolphin, found only off Namibia and South Africa, is named after the wrong man: its specimen came from a Captain Haviside, but was credited to a surgeon called Heaviside."},"hebrides":{"id":"hebrides","name":"Hebrides","aliases":["Outer Hebrides","Inner Hebrides","Western Isles","Isle of Skye","Skye","Lewis and Harris"],"kind":"place","group":"islands","fact":"The Hebrides off Scotland's west coast include Skye, Mull, Lewis and Harris, and the tiny island of Staffa with its basalt Fingal's Cave."},"hectors-beaked-whale":{"id":"hectors-beaked-whale","name":"Hector's beaked whale","aliases":["Mesoplodon hectori"],"kind":"creature","group":"whales","fact":"Hector's beaked whale is a small, rarely seen Southern Hemisphere beaked whale named after James Hector, a New Zealand scientist."},"hectors-dolphin":{"id":"hectors-dolphin","name":"Hector's dolphin","aliases":["New Zealand dolphin","Cephalorhynchus hectori"],"kind":"creature","group":"dolphins","fact":"Hector's dolphin of New Zealand is one of the smallest dolphins, about 1.4 metres long, with a rounded dorsal fin like a Mickey Mouse ear."},"hedgehog-seahorse":{"id":"hedgehog-seahorse","name":"Hedgehog seahorse","aliases":["Hippocampus spinosissimus"],"kind":"creature","group":"fish","fact":"The hedgehog seahorse is a spiny Indo-Pacific species that lives on sandy and muddy bottoms, often beside sponges, and is caught in trawls."},"helicoprion":{"id":"helicoprion","name":"Helicoprion","aliases":["buzzsaw shark"],"kind":"creature","group":"sharks","fact":"Helicoprion was a shark relative with a spiral 'buzzsaw' of teeth in its lower jaw that puzzled scientists for more than a century."},"hellenic-trench":{"id":"hellenic-trench","name":"Hellenic Trench","aliases":["Hellenic Trough","Calypso Deep"],"kind":"place","group":"trenches","fact":"The Hellenic Trench, curving south of Greece and Crete, contains the Calypso Deep, the deepest point in the Mediterranean at about 5,100 metres."},"helmet-jellyfish":{"id":"helmet-jellyfish","name":"Helmet jellyfish","aliases":["Periphylla periphylla"],"kind":"creature","group":"jellies","fact":"The helmet jellyfish lives in deep water and in dark Norwegian fjords, where it has multiplied so much that it has displaced the fish."},"herbert-nitsch":{"id":"herbert-nitsch","name":"Herbert Nitsch","aliases":[],"kind":"person","group":"people","fact":"Herbert Nitsch, the deepest man on Earth, free-dived to 214 metres on a single breath in 2007."},"hermit-crab":{"id":"hermit-crab","name":"Hermit crab","aliases":["Paguroidea"],"kind":"creature","group":"crustaceans","fact":"Hermit crabs have soft abdomens and move into empty snail shells, swapping for larger ones as they grow."},"heron":{"id":"heron","name":"Heron","aliases":["grey heron","great blue heron"],"kind":"creature","group":"birds","fact":"Herons stalk the shallows of estuaries and mangrove channels, striking fish with a lightning jab of their dagger-like bill."},"herring":{"id":"herring","name":"Herring","aliases":["Atlantic herring","Clupea harengus","Pacific herring"],"kind":"creature","group":"fish","fact":"Herring feed on copepods and krill in schools of millions, and communicate at night with bursts of bubbles from their vents."},"hijiki":{"id":"hijiki","name":"Hijiki","aliases":["Sargassum fusiforme","hiziki"],"kind":"plant","group":"plants","fact":"Hijiki is a brown seaweed eaten in Japan, usually dried and black; it is known for holding unusually high levels of arsenic."},"hikurangi-trench":{"id":"hikurangi-trench","name":"Hikurangi Trench","aliases":["Hikurangi Trough"],"kind":"place","group":"trenches","fact":"The Hikurangi Trench off the east coast of New Zealand's North Island is where the Pacific Plate dives beneath the Australian Plate."},"hilsa":{"id":"hilsa","name":"Hilsa","aliases":["ilish","hilsa shad","Tenualosa ilisha"],"kind":"creature","group":"fish","fact":"The hilsa is a shad that lives in the Bay of Bengal and swims up the Ganges and other rivers to spawn, and it is the national fish of Bangladesh."},"hirondellea-gigas":{"id":"hirondellea-gigas","name":"Hirondellea gigas","aliases":["Hirondellea"],"kind":"creature","group":"crustaceans","fact":"Hirondellea gigas amphipods swarm at the bottom of the Challenger Deep and make enzymes that digest sunken wood and plant debris."},"hjort-trench":{"id":"hjort-trench","name":"Hjort Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Hjort Trench south of New Zealand and Macquarie Island is one of the southernmost trenches in the world, reaching about 6,700 metres."},"hl-hunley":{"id":"hl-hunley","name":"H. L. Hunley","aliases":["Hunley","CSS Hunley"],"kind":"vessel","group":"wrecks","fact":"The Confederate submarine H. L. Hunley sank in 1864 shortly after becoming the first submarine to sink an enemy warship."},"hmas-sydney":{"id":"hmas-sydney","name":"HMAS Sydney","aliases":["Sydney"],"kind":"vessel","group":"wrecks","fact":"HMAS Sydney was lost with all 645 crew after a battle with the German raider Kormoran in 1941, and was found in 2008 about 2,500 metres down off Western Australia."},"hms-beagle":{"id":"hms-beagle","name":"HMS Beagle","aliases":["Beagle"],"kind":"vessel","group":"vessels","fact":"HMS Beagle carried the young Charles Darwin on a five-year surveying voyage around the world from 1831 to 1836 that led to his theory of evolution."},"hms-bounty":{"id":"hms-bounty","name":"Bounty","aliases":["HMS Bounty","HMAV Bounty"],"kind":"vessel","group":"wrecks","fact":"After the famous mutiny, the Bounty was burned and sunk by the mutineers at Pitcairn Island in 1790."},"hms-challenger":{"id":"hms-challenger","name":"HMS Challenger","aliases":["Challenger","Challenger expedition"],"kind":"vessel","group":"vessels","fact":"HMS Challenger sailed around the world from 1872 to 1876 on the first great oceanographic expedition, sounding the deep that now bears its name."},"hms-erebus":{"id":"hms-erebus","name":"HMS Erebus","aliases":["Erebus"],"kind":"vessel","group":"wrecks","fact":"HMS Erebus, one of the ships of Franklin's lost Arctic expedition, sank in the Canadian Arctic and was found in shallow water in 2014."},"hms-hood":{"id":"hms-hood","name":"HMS Hood","aliases":["Hood"],"kind":"vessel","group":"wrecks","fact":"HMS Hood blew up and sank in three minutes after a hit from the Bismarck in 1941, with only 3 of 1,418 men surviving; the wreck lies about 2,800 metres down."},"hms-terror":{"id":"hms-terror","name":"HMS Terror","aliases":["Terror"],"kind":"vessel","group":"wrecks","fact":"HMS Terror, Franklin's second ship, was found almost intact in 2016 in Terror Bay, off King William Island in the Canadian Arctic."},"hoff-crab":{"id":"hoff-crab","name":"Hoff crab","aliases":["Kiwa tyleri","Hasselhoff crab","Antarctic yeti crab"],"kind":"creature","group":"crustaceans","fact":"The Hoff crab, named for its hairy chest after actor David Hasselhoff, crowds by the thousand onto hot vent chimneys on the Antarctic East Scotia Ridge."},"hogchoker":{"id":"hogchoker","name":"Hogchoker","aliases":["Trinectes maculatus"],"kind":"creature","group":"fish","fact":"The hogchoker is a small American sole that swims up rivers and got its name because pigs fed on the rough-skinned fish supposedly choked on them."},"hogfish":{"id":"hogfish","name":"Hogfish","aliases":["hog snapper","Lachnolaimus maximus","hog fish"],"kind":"creature","group":"fish","fact":"The hogfish of the western Atlantic roots in sand with its long pig-like snout and is prized by spearfishers for its taste."},"hoki":{"id":"hoki","name":"Hoki","aliases":["blue grenadier","Macruronus novaezelandiae","blue hake"],"kind":"creature","group":"fish","fact":"Hoki is a deep-water cod relative of New Zealand's biggest fishery, and ends up in fish fingers and fast-food fish sandwiches."},"honeycomb-cowfish":{"id":"honeycomb-cowfish","name":"Honeycomb cowfish","aliases":["Acanthostracion polygonius"],"kind":"creature","group":"fish","fact":"The honeycomb cowfish of Caribbean reefs has two horns over its eyes and a boxy body patterned like a honeycomb."},"honeycomb-moray":{"id":"honeycomb-moray","name":"Honeycomb moray","aliases":["laced moray","tessellate moray","Gymnothorax favagineus"],"kind":"creature","group":"fish","fact":"The honeycomb moray, or laced moray, is a large white moray covered in black honeycomb spots, common on Indo-Pacific reefs."},"honeycomb-stingray":{"id":"honeycomb-stingray","name":"Honeycomb stingray","aliases":["reticulate whipray","honeycomb whipray","Himantura uarnak"],"kind":"creature","group":"rays","fact":"The honeycomb stingray has a tail up to three times its body length and a net-like pattern on its back."},"hooded-seal":{"id":"hooded-seal","name":"Hooded seal","aliases":["Cystophora cristata"],"kind":"creature","group":"seals","fact":"Male hooded seals inflate a bright red nasal balloon from one nostril to impress rivals, and pups are weaned in only four days."},"horn-shark":{"id":"horn-shark","name":"Horn shark","aliases":["Heterodontus francisci"],"kind":"creature","group":"sharks","fact":"The horn shark has a sharp spine in front of each dorsal fin and crushes sea urchins and molluscs with flat, molar-like back teeth."},"horned-sea-snake":{"id":"horned-sea-snake","name":"Horned sea snake","aliases":["Peron's sea snake","spiny-headed sea snake","Hydrophis peronii","Acalyptophis peronii"],"kind":"creature","group":"reptiles","fact":"The horned sea snake has small spines over its eyes and is the only sea snake with spiny scales on its head."},"horse-mackerel":{"id":"horse-mackerel","name":"Horse mackerel","aliases":["scad","jack mackerel","Trachurus"],"kind":"creature","group":"fish","fact":"Horse mackerel, or scad, are not true mackerel but jacks with a row of bony scales along the lateral line, and they school in vast numbers."},"horsehair-crab":{"id":"horsehair-crab","name":"Horsehair crab","aliases":["kegani","Erimacrus isenbeckii","hair crab"],"kind":"creature","group":"crustaceans","fact":"The horsehair crab of Hokkaido is covered in short bristles and is prized in Japan for its sweet meat and rich crab liver."},"horseshoe-crab":{"id":"horseshoe-crab","name":"Horseshoe crab","aliases":["Atlantic horseshoe crab","Limulus polyphemus","Limulus"],"kind":"creature","group":"arthropods","fact":"Horseshoe crabs have blue, copper-based blood that is harvested to test medicines and vaccines for bacterial contamination."},"houndfish":{"id":"houndfish","name":"Houndfish","aliases":["crocodile needlefish","Tylosurus crocodilus"],"kind":"creature","group":"fish","fact":"The houndfish is a 1.5-metre needlefish that leaps from the water at speed and has impaled fishermen with its beak."},"hourglass-dolphin":{"id":"hourglass-dolphin","name":"Hourglass dolphin","aliases":["Lagenorhynchus cruciger"],"kind":"creature","group":"dolphins","fact":"The hourglass dolphin is the only small dolphin found regularly in Antarctic waters, and its bold black-and-white pattern gives it its name."},"hubbs-beaked-whale":{"id":"hubbs-beaked-whale","name":"Hubbs' beaked whale","aliases":["Hubbs's beaked whale","arch-beaked whale","Mesoplodon carlhubbsi"],"kind":"creature","group":"whales","fact":"Hubbs' beaked whale is known mostly from strandings on the US west coast and Japan, and males carry a white cap on their heads."},"huchen":{"id":"huchen","name":"Huchen","aliases":["Danube salmon","Hucho hucho"],"kind":"creature","group":"fish","fact":"The huchen, or Danube salmon, is a giant trout relative of the Danube basin that can grow to more than a metre long and never goes to sea."},"hudson-bay":{"id":"hudson-bay","name":"Hudson Bay","aliases":["Hudson's Bay"],"kind":"place","group":"bays","fact":"Hudson Bay is a vast inland sea in Canada named after the English explorer Henry Hudson, who was set adrift there by mutineers in 1611 and never seen again."},"hudson-canyon":{"id":"hudson-canyon","name":"Hudson Canyon","aliases":["Hudson Submarine Canyon"],"kind":"place","group":"features","fact":"Hudson Canyon is the largest submarine canyon on the US Atlantic coast, continuing the course of the Hudson River across the seabed off New York."},"hudson-strait":{"id":"hudson-strait","name":"Hudson Strait","aliases":[],"kind":"place","group":"straits","fact":"Hudson Strait links Hudson Bay to the Labrador Sea and the Atlantic and is named after the English explorer Henry Hudson."},"humboldt-current":{"id":"humboldt-current","name":"Humboldt Current","aliases":["Peru Current","Peru-Chile Current"],"kind":"place","group":"currents","fact":"The Humboldt Current carries cold, nutrient-rich water north along the coast of Chile and Peru, feeding the world's largest anchovy fishery."},"humboldt-squid":{"id":"humboldt-squid","name":"Humboldt squid","aliases":["jumbo squid","jumbo flying squid","Dosidicus gigas","red devil","diablo rojo"],"kind":"creature","group":"cephalopods","fact":"Humboldt squid hunt in packs of hundreds and flash red and white across their skin, earning the nickname 'red devil' from fishermen."},"humbug-dascyllus":{"id":"humbug-dascyllus","name":"Humbug dascyllus","aliases":["humbug damselfish","whitetail dascyllus","Dascyllus aruanus","three-stripe damselfish","humbug"],"kind":"creature","group":"fish","fact":"The humbug dascyllus is a small black-and-white banded damselfish that lives in tight groups inside branching Acropora corals."},"humpback-anglerfish":{"id":"humpback-anglerfish","name":"Humpback anglerfish","aliases":["Melanocetus johnsonii","Johnson's anglerfish","common black devil"],"kind":"creature","group":"fish","fact":"The humpback anglerfish is the classic toothy black seadevil of the deep; females reach about 15 centimetres while the males are only around 2 centimetres long."},"humpback-dolphin":{"id":"humpback-dolphin","name":"Humpback dolphin","aliases":["Sousa"],"kind":"creature","group":"dolphins","fact":"Humpback dolphins live in shallow coastal waters and estuaries and have a distinctive hump beneath the dorsal fin."},"humpback-grouper":{"id":"humpback-grouper","name":"Humpback grouper","aliases":["panther grouper","polka-dot grouper","barramundi cod","Cromileptes altivelis","Chromileptes altivelis","highfin grouper"],"kind":"creature","group":"fish","fact":"The humpback grouper, or panther grouper, is a polka-dotted, small-headed grouper that swims head-down and is farmed as a luxury fish in Asia."},"humpback-whale":{"id":"humpback-whale","name":"Humpback whale","aliases":["humpback","Megaptera novaeangliae"],"kind":"creature","group":"whales","fact":"Male humpbacks sing long, complex songs, and the scientific name Megaptera novaeangliae means 'big-winged New Englander'."},"hydroid":{"id":"hydroid","name":"Hydroid","aliases":["stinging hydroid"],"kind":"creature","group":"jellies","fact":"Hydroids are plant-like colonies of stinging polyps, the attached stage of many jellyfish, and have been dredged from more than 8,200 metres in the Kermadec Trench."},"icarian-sea":{"id":"icarian-sea","name":"Icarian Sea","aliases":[],"kind":"place","group":"seas","fact":"The Icarian Sea is the part of the Aegean around the island of Icaria, where in legend Icarus fell into the sea after flying too close to the sun."},"iceland":{"id":"iceland","name":"Iceland","aliases":[],"kind":"place","group":"islands","fact":"Iceland sits astride the Mid-Atlantic Ridge, where the North American and Eurasian plates pull apart, which is why it is so volcanic."},"ichthyosaur":{"id":"ichthyosaur","name":"Ichthyosaur","aliases":["ichthyosaurus","fish lizard"],"kind":"creature","group":"reptiles","fact":"Ichthyosaurs were dolphin-shaped reptiles that gave birth to live young at sea, and Mary Anning found the first complete skeleton in 1811."},"ifremeria-snail":{"id":"ifremeria-snail","name":"Ifremeria snail","aliases":["Ifremeria nautilei","Ifremeria"],"kind":"creature","group":"molluscs","fact":"Ifremeria snails cluster in dense beds at western Pacific vents and brood their young inside a pouch in the foot."},"immortal-jellyfish":{"id":"immortal-jellyfish","name":"Immortal jellyfish","aliases":["Turritopsis dohrnii","Turritopsis","Benjamin Button jellyfish"],"kind":"creature","group":"jellies","fact":"The immortal jellyfish can turn its adult body back into a juvenile polyp when injured or starving, restarting its life cycle indefinitely."},"inanga":{"id":"inanga","name":"Inanga","aliases":["common galaxias","whitebait","jollytail","Galaxias maculatus"],"kind":"creature","group":"fish","fact":"The inanga of New Zealand and Australia lays its eggs on grasses flooded by spring tides, and the larvae are swept out to sea before returning as whitebait."},"inca-tern":{"id":"inca-tern","name":"Inca tern","aliases":["Larosterna inca"],"kind":"creature","group":"seabirds","fact":"The Inca tern of the Humboldt Current coast of Peru and Chile sports a dashing white moustache and snatches anchovies from the surface."},"indian-mackerel":{"id":"indian-mackerel","name":"Indian mackerel","aliases":["Rastrelliger kanagurta"],"kind":"creature","group":"fish","fact":"The Indian mackerel is the everyday fish of South and Southeast Asia, caught in huge numbers and fried, curried or dried."},"indian-ocean-humpback-dolphin":{"id":"indian-ocean-humpback-dolphin","name":"Indian Ocean humpback dolphin","aliases":["Sousa plumbea","humpback dolphin"],"kind":"creature","group":"dolphins","fact":"The Indian Ocean humpback dolphin has a pronounced hump under its dorsal fin and lives in estuaries and shallow coasts from South Africa to India."},"indian-oil-sardine":{"id":"indian-oil-sardine","name":"Indian oil sardine","aliases":["Sardinella longiceps","oil sardine"],"kind":"creature","group":"fish","fact":"The Indian oil sardine is the most important fish of India's west coast, caught by the hundreds of thousands of tonnes in the monsoon season."},"indo-pacific-bottlenose-dolphin":{"id":"indo-pacific-bottlenose-dolphin","name":"Indo-Pacific bottlenose dolphin","aliases":["Tursiops aduncus"],"kind":"creature","group":"dolphins","fact":"Indo-Pacific bottlenose dolphins in Shark Bay, Australia, carry sponges on their beaks as tools to protect them while foraging on the seabed."},"indo-pacific-finless-porpoise":{"id":"indo-pacific-finless-porpoise","name":"Indo-Pacific finless porpoise","aliases":["Neophocaena phocaenoides"],"kind":"creature","group":"dolphins","fact":"The Indo-Pacific finless porpoise lives in estuaries and shallow coasts from the Persian Gulf to the Taiwan Strait, including the Pearl River estuary."},"indo-pacific-humpback-dolphin":{"id":"indo-pacific-humpback-dolphin","name":"Indo-Pacific humpback dolphin","aliases":["Chinese white dolphin","Sousa chinensis"],"kind":"creature","group":"dolphins","fact":"Chinese white dolphins of the Pearl River estuary are actually pink as adults, and Hong Kong adopted them as its 1997 handover mascot."},"indus-river-dolphin":{"id":"indus-river-dolphin","name":"Indus river dolphin","aliases":["Indus dolphin","bhulan","Platanista minor"],"kind":"creature","group":"dolphins","fact":"The Indus river dolphin often swims on its side in the shallow, muddy Indus and was long trapped between irrigation barrages."},"ins-dakar":{"id":"ins-dakar","name":"INS Dakar","aliases":["Dakar","Dakar submarine"],"kind":"vessel","group":"wrecks","fact":"The Israeli submarine Dakar vanished in 1968 and was found in 1999 about 2,900 metres down between Crete and Cyprus."},"ionian-sea":{"id":"ionian-sea","name":"Ionian Sea","aliases":["Ionian"],"kind":"place","group":"seas","fact":"The Ionian Sea lies between southern Italy and western Greece and holds the deepest point in the Mediterranean, the Calypso Deep at about 5,100 metres."},"ireland":{"id":"ireland","name":"Ireland","aliases":["Eire","Emerald Isle"],"kind":"place","group":"islands","fact":"Ireland is the second-largest island of the British Isles, and the Gulf Stream keeps its climate mild enough for subtropical gardens to thrive on its west coast."},"irish-moss":{"id":"irish-moss","name":"Irish moss","aliases":["carrageen","carrageen moss","sea moss","Chondrus crispus"],"kind":"plant","group":"plants","fact":"Irish moss, or carrageen, is a small red seaweed whose extract carrageenan thickens ice cream, toothpaste and plant milks."},"irish-sea":{"id":"irish-sea","name":"Irish Sea","aliases":[],"kind":"place","group":"seas","fact":"The Irish Sea separates Ireland from Great Britain and opens to the Atlantic through the North Channel and St George's Channel."},"irminger-current":{"id":"irminger-current","name":"Irminger Current","aliases":[],"kind":"place","group":"currents","fact":"The Irminger Current is a warm branch of the North Atlantic Drift that flows west past Iceland towards Greenland."},"irrawaddy-dolphin":{"id":"irrawaddy-dolphin","name":"Irrawaddy dolphin","aliases":["Orcaella brevirostris"],"kind":"creature","group":"dolphins","fact":"Irrawaddy dolphins in Myanmar herd fish towards fishermen's nets and are rewarded with part of the catch."},"irukandji-jellyfish":{"id":"irukandji-jellyfish","name":"Irukandji jellyfish","aliases":["Irukandji","Carukia barnesi"],"kind":"creature","group":"jellies","fact":"The Irukandji jellyfish is barely the size of a fingernail and transparent, yet its sting causes hours of agony, vomiting and a feeling of impending doom."},"isles-of-scilly":{"id":"isles-of-scilly","name":"Isles of Scilly","aliases":["Scilly Isles","Scilly","Scillies"],"kind":"place","group":"islands","fact":"The Isles of Scilly lie about 45 kilometres off Cornwall and are warmed by the Gulf Stream so that subtropical plants grow in their gardens."},"isopod":{"id":"isopod","name":"Isopod","aliases":[],"kind":"creature","group":"crustaceans","fact":"Isopods, the group that includes woodlice, are found in every ocean habitat, including trench floors deeper than 6,000 metres."},"ivory-gull":{"id":"ivory-gull","name":"Ivory gull","aliases":["Pagophila eburnea"],"kind":"creature","group":"seabirds","fact":"The ivory gull is a pure-white gull that lives year-round among Arctic pack ice and scavenges polar bear kills."},"iwo-jima":{"id":"iwo-jima","name":"Iwo Jima","aliases":["Iwo To","Ioto"],"kind":"place","group":"islands","fact":"Iwo Jima is a small volcanic island south of Japan where US Marines raised the flag on Mount Suribachi in 1945."},"izu-ogasawara-trench":{"id":"izu-ogasawara-trench","name":"Izu-Ogasawara Trench","aliases":["Izu-Bonin Trench","Bonin Trench","Izu Trench","Ogasawara Trench"],"kind":"place","group":"trenches","fact":"The Izu-Ogasawara Trench runs south from Japan to join the Mariana Trench and reaches more than 9,700 metres deep."},"jack-dempsey":{"id":"jack-dempsey","name":"Jack Dempsey","aliases":["Jack Dempsey cichlid","Rocio octofasciata"],"kind":"creature","group":"fish","fact":"The Jack Dempsey cichlid from Central America was named after the boxer for its aggressive temper and strong-jawed face."},"jack-mackerel":{"id":"jack-mackerel","name":"Jack mackerel","aliases":["Pacific jack mackerel","Trachurus symmetricus"],"kind":"creature","group":"fish","fact":"The Pacific jack mackerel is a schooling jack, not a true mackerel, caught off California and Chile in enormous quantities."},"jacques-cousteau":{"id":"jacques-cousteau","name":"Jacques Cousteau","aliases":["Jacques-Yves Cousteau","Cousteau","Captain Cousteau"],"kind":"person","group":"people","fact":"Jacques Cousteau co-invented the Aqua-Lung in 1943, the first successful open-circuit scuba gear, and brought the undersea world to television aboard Calypso."},"jacques-mayol":{"id":"jacques-mayol","name":"Jacques Mayol","aliases":[],"kind":"person","group":"people","fact":"Jacques Mayol was the free diver who first dived below 100 metres on a single breath in 1976 and inspired the film The Big Blue."},"jacques-piccard":{"id":"jacques-piccard","name":"Jacques Piccard","aliases":[],"kind":"person","group":"people","fact":"Jacques Piccard and Don Walsh reached the bottom of the Challenger Deep in the bathyscaphe Trieste in 1960, the first humans ever to do so."},"james-bay":{"id":"james-bay","name":"James Bay","aliases":[],"kind":"place","group":"bays","fact":"James Bay, the southern arm of Hudson Bay, is named after Thomas James, the Welsh captain who wintered on its shore in 1631."},"james-cameron":{"id":"james-cameron","name":"James Cameron","aliases":[],"kind":"person","group":"people","fact":"The film director James Cameron made a solo dive to the bottom of the Challenger Deep in 2012 and has visited the Titanic wreck more than 30 times."},"james-clark-ross":{"id":"james-clark-ross","name":"James Clark Ross","aliases":[],"kind":"person","group":"people","fact":"James Clark Ross discovered the Ross Sea and Ross Ice Shelf in 1841 and made some of the first soundings of the deep ocean, reaching below 4,000 metres."},"james-cook":{"id":"james-cook","name":"James Cook","aliases":["Captain Cook","Captain James Cook","Cook"],"kind":"person","group":"people","fact":"Captain James Cook charted more of the Pacific than any navigator before him, crossed the Antarctic Circle, and kept his crews free of scurvy on three great voyages."},"japan":{"id":"japan","name":"Japan","aliases":["Japanese archipelago","Honshu","Hokkaido","Kyushu","Shikoku"],"kind":"place","group":"islands","fact":"Japan is an archipelago of thousands of islands in the western Pacific, dominated by the four large islands of Honshu, Hokkaido, Kyushu and Shikoku."},"japan-trench":{"id":"japan-trench","name":"Japan Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Japan Trench runs off north-east Honshu, and the 2011 Tōhoku earthquake that caused the Fukushima disaster ruptured along it."},"japanese-anchovy":{"id":"japanese-anchovy","name":"Japanese anchovy","aliases":["Engraulis japonicus","katakuchi iwashi"],"kind":"creature","group":"fish","fact":"The Japanese anchovy is one of the largest catches in the northwest Pacific, eaten dried as niboshi and as tiny boiled whitebait, shirasu."},"japanese-eel":{"id":"japanese-eel","name":"Japanese eel","aliases":["unagi","Anguilla japonica","Japanese freshwater eel"],"kind":"creature","group":"fish","fact":"The Japanese eel, the unagi of Japanese cooking, spawns near the Mariana Islands and its young drift thousands of kilometres back to East Asian rivers."},"japanese-flying-squid":{"id":"japanese-flying-squid","name":"Japanese flying squid","aliases":["Todarodes pacificus","Pacific flying squid","surume ika"],"kind":"creature","group":"cephalopods","fact":"The Japanese flying squid supports one of the biggest squid fisheries in the world and can glide briefly above the waves by jetting water."},"japanese-horse-mackerel":{"id":"japanese-horse-mackerel","name":"Japanese horse mackerel","aliases":["aji","horse mackerel","Japanese jack mackerel","Trachurus japonicus"],"kind":"creature","group":"fish","fact":"Horse mackerel, aji, is one of the most common fish in Tokyo sushi bars, served raw with grated ginger and spring onion."},"japanese-pygmy-seahorse":{"id":"japanese-pygmy-seahorse","name":"Japanese pygmy seahorse","aliases":["japapigu","Japan pig","Hippocampus japapigu"],"kind":"creature","group":"fish","fact":"The Japanese pygmy seahorse, nicknamed 'japapigu' or 'Japan pig', was known to local divers for years before being named as a new species in 2018."},"japanese-sardine":{"id":"japanese-sardine","name":"Japanese sardine","aliases":["Japanese pilchard","Sardinops melanostictus","maiwashi"],"kind":"creature","group":"fish","fact":"The Japanese sardine catch rose above 4 million tonnes in the 1980s before collapsing, one of the most dramatic booms and busts in fishing."},"japanese-sea-bass":{"id":"japanese-sea-bass","name":"Japanese sea bass","aliases":["suzuki","Lateolabrax japonicus"],"kind":"creature","group":"fish","fact":"Japanese sea bass, suzuki, is a summer sashimi fish that changes its name as it grows, a 'success fish' in Japanese tradition."},"japanese-sea-cucumber":{"id":"japanese-sea-cucumber","name":"Japanese sea cucumber","aliases":["Japanese spiky sea cucumber","namako","Apostichopus japonicus"],"kind":"creature","group":"echinoderms","fact":"The Japanese sea cucumber is farmed and dried as a luxury food across East Asia and is known in Japan as namako."},"japanese-sea-lion":{"id":"japanese-sea-lion","name":"Japanese sea lion","aliases":["Zalophus japonicus"],"kind":"creature","group":"seals","fact":"The Japanese sea lion bred on beaches of Japan and Korea until hunting wiped it out; the last reliable sightings were in the 1950s, with a final juvenile reported in 1974."},"japanese-spanish-mackerel":{"id":"japanese-spanish-mackerel","name":"Japanese Spanish mackerel","aliases":["sawara","Scomberomorus niphonius"],"kind":"creature","group":"fish","fact":"The Japanese Spanish mackerel, sawara, is a spring fish in Japan, grilled with miso or served as lightly seared sashimi."},"japanese-spider-crab":{"id":"japanese-spider-crab","name":"Japanese spider crab","aliases":["Macrocheira kaempferi","giant spider crab"],"kind":"creature","group":"crustaceans","fact":"The Japanese spider crab has the largest leg span of any arthropod, up to about 3.7 metres, and lives on the seabed off Japan down to about 600 metres."},"japanese-spiny-lobster":{"id":"japanese-spiny-lobster","name":"Japanese spiny lobster","aliases":["Ise ebi","Panulirus japonicus"],"kind":"creature","group":"crustaceans","fact":"The Japanese spiny lobster, Ise-ebi, is a celebration food in Japan, served grilled or raw at New Year and at weddings."},"java-trench":{"id":"java-trench","name":"Java Trench","aliases":["Sunda Trench","Sunda Double Trench"],"kind":"place","group":"trenches","fact":"The Java Trench, also called the Sunda Trench, is the deepest point in the Indian Ocean at more than 7,000 metres, and the 2004 tsunami began along it."},"jean-baptiste-charcot":{"id":"jean-baptiste-charcot","name":"Jean-Baptiste Charcot","aliases":["Charcot"],"kind":"person","group":"people","fact":"Jean-Baptiste Charcot led French Antarctic expeditions aboard the ships Français and Pourquoi-Pas? and charted long stretches of the Antarctic Peninsula."},"jean-michel-cousteau":{"id":"jean-michel-cousteau","name":"Jean-Michel Cousteau","aliases":[],"kind":"person","group":"people","fact":"Jean-Michel Cousteau, Jacques Cousteau's elder son, founded the Ocean Futures Society and has spent his life making ocean documentaries."},"jellyfish":{"id":"jellyfish","name":"Jellyfish","aliases":["jelly","sea jelly","medusa","moon jellyfish","moon jelly"],"kind":"creature","group":"jellies","fact":"Jellyfish have no brain, heart or blood and are more than 95 per cent water, yet they have drifted the oceans for more than 500 million years."},"jericho-worm":{"id":"jericho-worm","name":"Jericho worm","aliases":["Tevnia jerichonana","Tevnia"],"kind":"creature","group":"worms","fact":"The Jericho worm is a tube worm with a ringed tube like a crumbling wall, and it is usually the first tube worm to colonise a brand-new vent."},"jewel-damselfish":{"id":"jewel-damselfish","name":"Jewel damselfish","aliases":["Plectroglyphidodon lacrymatus","whitespotted devil","jewel damsel"],"kind":"creature","group":"fish","fact":"The jewel damselfish of Indo-Pacific reefs is spangled with tiny blue spots as a juvenile, and the adult farms a turf of red algae."},"jiaolong":{"id":"jiaolong","name":"Jiaolong","aliases":[],"kind":"vessel","group":"submersibles","fact":"China's submersible Jiaolong dived to more than 7,000 metres in the Mariana Trench in 2012."},"john-dory":{"id":"john-dory","name":"John Dory","aliases":["St Peter's fish","Zeus faber","Saint Pierre"],"kind":"creature","group":"fish","fact":"John Dory has a dark spot on each flank said to be St Peter's thumbprint, and its sweet white fillets are prized by chefs."},"joides-resolution":{"id":"joides-resolution","name":"JOIDES Resolution","aliases":[],"kind":"vessel","group":"vessels","fact":"The drilling ship JOIDES Resolution spent decades recovering sediment cores from the deep sea floor that record millions of years of Earth's climate."},"jonah-crab":{"id":"jonah-crab","name":"Jonah crab","aliases":["Cancer borealis"],"kind":"creature","group":"crustaceans","fact":"The Jonah crab of the north-west Atlantic was once lobster-pot bycatch but is now fished in its own right for its large claws."},"joseph-bonaparte-gulf":{"id":"joseph-bonaparte-gulf","name":"Joseph Bonaparte Gulf","aliases":["Bonaparte Gulf"],"kind":"place","group":"gulfs","fact":"The Joseph Bonaparte Gulf in northern Australia was named by the French explorer Nicolas Baudin after Napoleon's elder brother Joseph."},"juan-de-fuca-ridge":{"id":"juan-de-fuca-ridge","name":"Juan de Fuca Ridge","aliases":[],"kind":"place","group":"features","fact":"The Juan de Fuca Ridge off the Pacific Northwest is a spreading ridge whose vents are wired to shore by a cabled seafloor observatory."},"juan-fernandez-islands":{"id":"juan-fernandez-islands","name":"Juan Fernández Islands","aliases":["Juan Fernandez","Robinson Crusoe Island","Más a Tierra"],"kind":"place","group":"islands","fact":"The Juan Fernández Islands off Chile include Robinson Crusoe Island, where the marooned sailor Alexander Selkirk survived alone for four years and inspired Defoe's novel."},"junk":{"id":"junk","name":"Junk","aliases":["Chinese junk"],"kind":"vessel","group":"boats","fact":"The Chinese junk, with its battened sails, was sailing the seas centuries before similar rigs appeared in Europe, and Zheng He's treasure fleet used giant junks."},"k-129":{"id":"k-129","name":"K-129","aliases":["K129","Soviet submarine K-129"],"kind":"vessel","group":"wrecks","fact":"The Soviet missile submarine K-129 sank in 1968 about 4,900 metres down in the Pacific; the CIA's Glomar Explorer secretly lifted part of it in 1974 and the rest still lies there."},"kaga":{"id":"kaga","name":"Kaga","aliases":["IJN Kaga"],"kind":"vessel","group":"wrecks","fact":"The Japanese carrier Kaga, sunk at the Battle of Midway in 1942, was the first Midway carrier wreck found, in October 2019, more than 5,000 metres down."},"kaiko":{"id":"kaiko","name":"Kaiko","aliases":[],"kind":"vessel","group":"submersibles","fact":"Kaiko was a Japanese robotic vehicle that in 1995 became the second craft to reach the bottom of the Challenger Deep, and it was lost at sea in 2003."},"kawakawa":{"id":"kawakawa","name":"Kawakawa","aliases":["mackerel tuna","Euthynnus affinis","eastern little tuna"],"kind":"creature","group":"fish","fact":"The kawakawa, or mackerel tuna, is a small coastal tuna of the Indo-Pacific with wavy stripes on its back and dark spots under its pectoral fins."},"kayak":{"id":"kayak","name":"Kayak","aliases":["sea kayak","qajaq"],"kind":"vessel","group":"boats","fact":"The kayak was developed by Inuit and other Arctic peoples as a sealed one-person hunting boat for seals and other sea animals."},"kelp":{"id":"kelp","name":"Kelp","aliases":["Laminariales"],"kind":"plant","group":"plants","fact":"Kelps are large brown seaweeds that form underwater forests along cold, rocky coasts, anchored by a root-like holdfast rather than true roots."},"kelp-bass":{"id":"kelp-bass","name":"Kelp bass","aliases":["calico bass","Paralabrax clathratus"],"kind":"creature","group":"fish","fact":"The kelp bass, or calico bass, is a mottled sea bass of California's kelp forests and one of the state's most popular sport fish."},"kelp-crab":{"id":"kelp-crab","name":"Kelp crab","aliases":["northern kelp crab","Pugettia producta","shield-backed kelp crab"],"kind":"creature","group":"crustaceans","fact":"The kelp crab lives in kelp forests of the Pacific coast of North America, where it feeds mostly on the kelp itself."},"kelp-fly":{"id":"kelp-fly","name":"Kelp fly","aliases":["seaweed fly","Coelopa","Coelopidae"],"kind":"creature","group":"insects","fact":"Kelp flies lay their eggs in rotting seaweed on the strandline, and their larvae feed on it, becoming food for shore birds."},"kelp-greenling":{"id":"kelp-greenling","name":"Kelp greenling","aliases":["Hexagrammos decagrammus"],"kind":"creature","group":"fish","fact":"The kelp greenling of the North Pacific hides among kelp, and its males and females look so different that they were once described as separate species."},"kelp-perch":{"id":"kelp-perch","name":"Kelp perch","aliases":["Brachyistius frenatus"],"kind":"creature","group":"fish","fact":"The kelp perch is a small surfperch of California kelp beds that picks parasites off other fish and gives birth to fully formed young."},"kelp-rockfish":{"id":"kelp-rockfish","name":"Kelp rockfish","aliases":["Sebastes atrovirens"],"kind":"creature","group":"fish","fact":"The kelp rockfish rests motionless among kelp fronds, often head-down, and gives birth to live young like all rockfishes."},"kemps-ridley-sea-turtle":{"id":"kemps-ridley-sea-turtle","name":"Kemp's ridley sea turtle","aliases":["Kemp's ridley","Kemp's ridley turtle","Atlantic ridley","Lepidochelys kempii"],"kind":"creature","group":"turtles","fact":"Kemp's ridley is the rarest sea turtle and nests in mass daytime arrivals called arribadas, mostly on one Mexican beach, Rancho Nuevo."},"kerguelen-plateau":{"id":"kerguelen-plateau","name":"Kerguelen Plateau","aliases":[],"kind":"place","group":"features","fact":"The Kerguelen Plateau in the southern Indian Ocean is one of the largest submerged volcanic plateaus on Earth, with only a few island peaks breaking the surface."},"kermadec-snailfish":{"id":"kermadec-snailfish","name":"Kermadec snailfish","aliases":["Notoliparis kermadecensis"],"kind":"creature","group":"fish","fact":"The Kermadec snailfish lives only in the Kermadec Trench off New Zealand, where it has been filmed feeding in groups about 7,500 metres down."},"kermadec-trench":{"id":"kermadec-trench","name":"Kermadec Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Kermadec Trench north-east of New Zealand plunges to about 10,000 metres and is home to huge swarms of amphipods and snailfish."},"kilka":{"id":"kilka","name":"Kilka","aliases":["Caspian sprat","Clupeonella"],"kind":"creature","group":"fish","fact":"Kilka are tiny sprats of the Caspian and Black seas that once made up most of the Caspian catch before the comb jelly invasion."},"killer-shrimp":{"id":"killer-shrimp","name":"Killer shrimp","aliases":["Dikerogammarus villosus"],"kind":"creature","group":"crustaceans","fact":"The killer shrimp, a large amphipod from the Black Sea region, has spread through Europe's canals to Britain, killing far more prey than it eats."},"killifish":{"id":"killifish","name":"Killifish","aliases":["killie"],"kind":"creature","group":"fish","fact":"Some killifish live in puddles that dry up each year, surviving as eggs in the mud that hobbyists can buy and post in the mail."},"kina":{"id":"kina","name":"Kina","aliases":["Evechinus chloroticus","New Zealand sea urchin"],"kind":"creature","group":"echinoderms","fact":"Kina is New Zealand's native sea urchin, a kelp grazer whose roe is a traditional Māori delicacy."},"king-angelfish":{"id":"king-angelfish","name":"King angelfish","aliases":["Holacanthus passer"],"kind":"creature","group":"fish","fact":"The king angelfish, dark blue with a white bar and orange tail, runs cleaning stations for hammerheads around the Galápagos."},"king-crab":{"id":"king-crab","name":"King crab","aliases":["red king crab","Alaskan king crab","Alaska king crab","Paralithodes camtschaticus","taraba-gani","Kamchatka crab"],"kind":"creature","group":"crustaceans","fact":"Red king crabs of the Bering Sea can span 1.5 metres across the legs and are actually closer relatives of hermit crabs than of true crabs."},"king-mackerel":{"id":"king-mackerel","name":"King mackerel","aliases":["kingfish","Scomberomorus cavalla"],"kind":"creature","group":"fish","fact":"The king mackerel, or kingfish, is a big, fast Spanish mackerel of the western Atlantic, chased by anglers off Florida and known to leap clear of the water."},"king-penguin":{"id":"king-penguin","name":"King penguin","aliases":["Aptenodytes patagonicus"],"kind":"creature","group":"seabirds","fact":"King penguins dive to over 300 metres for lanternfish and take more than a year to raise a chick, the longest breeding cycle of any penguin."},"kingman-reef":{"id":"kingman-reef","name":"Kingman Reef","aliases":[],"kind":"place","group":"reefs","fact":"Kingman Reef is a nearly submerged coral atoll in the central Pacific with almost no dry land, yet its reef is one of the most pristine on Earth."},"kiribati":{"id":"kiribati","name":"Kiribati","aliases":["Gilbert Islands","Kiritimati","Tarawa","Line Islands","Phoenix Islands"],"kind":"place","group":"islands","fact":"Kiribati is spread across 33 islands straddling the equator and the International Date Line, and includes Kiritimati, the largest coral atoll by land area."},"kissing-gourami":{"id":"kissing-gourami","name":"Kissing gourami","aliases":["kissing fish","Helostoma temminckii"],"kind":"creature","group":"fish","fact":"Kissing gouramis press their lips together in a test of strength, and like other gouramis they breathe air with a labyrinth organ."},"kitefin-shark":{"id":"kitefin-shark","name":"Kitefin shark","aliases":["seal shark","Dalatias licha"],"kind":"creature","group":"sharks","fact":"The kitefin shark, found down to around 1,800 metres, is the largest known glowing vertebrate at up to about 1.8 metres long."},"kittiwake":{"id":"kittiwake","name":"Kittiwake","aliases":["black-legged kittiwake","Rissa tridactyla"],"kind":"creature","group":"seabirds","fact":"The kittiwake is a small, truly oceanic gull that spends the winter far out at sea and nests on sheer cliff ledges."},"knarr":{"id":"knarr","name":"Knarr","aliases":["knörr","Viking cargo ship"],"kind":"vessel","group":"boats","fact":"The knarr was the broad Viking cargo ship that carried settlers and livestock across the open North Atlantic to Iceland, Greenland and Vinland."},"knorr":{"id":"knorr","name":"Knorr","aliases":["RV Knorr","R/V Knorr"],"kind":"vessel","group":"vessels","fact":"The research vessel Knorr was the ship from which Robert Ballard's team found the wreck of the Titanic in 1985."},"knotted-wrack":{"id":"knotted-wrack","name":"Knotted wrack","aliases":["egg wrack","Ascophyllum nodosum","Ascophyllum","Norwegian kelp"],"kind":"plant","group":"plants","fact":"Knotted wrack, or egg wrack, is a long-lived brown seaweed with single egg-shaped air bladders along its fronds, harvested for alginate and fertiliser."},"knysna-seahorse":{"id":"knysna-seahorse","name":"Knysna seahorse","aliases":["Cape seahorse","Hippocampus capensis"],"kind":"creature","group":"fish","fact":"The Knysna seahorse lives only in a few estuaries on South Africa's southern coast and is listed as endangered."},"koi":{"id":"koi","name":"Koi","aliases":["nishikigoi","koi carp"],"kind":"creature","group":"fish","fact":"Koi are ornamental common carp bred in Japan, and prized fish have sold for more than a million dollars."},"kole-tang":{"id":"kole-tang","name":"Kole tang","aliases":["goldring bristletooth","yellow-eyed kole tang","Ctenochaetus strigosus","goldring surgeonfish","kole"],"kind":"creature","group":"fish","fact":"The kole tang, or goldring bristletooth, is a Hawaiian surgeonfish with a gold ring around each eye and comb-like teeth for brushing up algae and detritus."},"kombu":{"id":"kombu","name":"Kombu","aliases":["Saccharina japonica","konbu","dashima"],"kind":"plant","group":"plants","fact":"Kombu is dried kelp, the seaweed that gives Japanese dashi stock its savoury umami taste; monosodium glutamate was first isolated from it in 1908."},"komodo-national-park":{"id":"komodo-national-park","name":"Komodo National Park","aliases":["Komodo"],"kind":"place","group":"parks","fact":"Komodo National Park in Indonesia protects not only its dragons but strong-current reefs where manta rays gather to be cleaned."},"komsomolets":{"id":"komsomolets","name":"Komsomolets","aliases":["K-278","K-278 Komsomolets"],"kind":"vessel","group":"wrecks","fact":"The Soviet nuclear submarine Komsomolets sank in the Norwegian Sea in 1989 and lies about 1,700 metres down with its reactor and two nuclear torpedoes."},"koran-angelfish":{"id":"koran-angelfish","name":"Koran angelfish","aliases":["semicircle angelfish","Pomacanthus semicirculatus","koran angel"],"kind":"creature","group":"fish","fact":"The koran angelfish gets its name from the arabesque markings on the tail of some adults, said to resemble Arabic script; juveniles are blue with white arcs."},"korea-strait":{"id":"korea-strait","name":"Korea Strait","aliases":["Tsushima Strait"],"kind":"place","group":"straits","fact":"The Korea Strait between South Korea and Japan links the East China Sea to the Sea of Japan, and the Russian fleet was destroyed there at Tsushima in 1905."},"krill":{"id":"krill","name":"Krill","aliases":["Antarctic krill","Euphausia superba","euphausiid","okiami"],"kind":"creature","group":"crustaceans","fact":"Antarctic krill swarms can stretch for kilometres, and their total weight of several hundred million tonnes is among the largest of any animal species."},"kronosaurus":{"id":"kronosaurus","name":"Kronosaurus","aliases":[],"kind":"creature","group":"reptiles","fact":"Kronosaurus was a Cretaceous pliosaur from Queensland, Australia, whose skull alone is estimated at over 2 metres long."},"kuhli-loach":{"id":"kuhli-loach","name":"Kuhli loach","aliases":["loach","coolie loach","Pangio kuhlii"],"kind":"creature","group":"fish","fact":"The kuhli loach is a striped eel-like fish from South-east Asia that burrows into aquarium sand and comes out at night."},"kuril-islands":{"id":"kuril-islands","name":"Kuril Islands","aliases":["Kurils","Kuriles"],"kind":"place","group":"islands","fact":"The Kuril Islands are a volcanic chain between Kamchatka and Japan, still disputed between Russia and Japan since the end of the Second World War."},"kuril-kamchatka-trench":{"id":"kuril-kamchatka-trench","name":"Kuril-Kamchatka Trench","aliases":["Kuril Trench","Kamchatka Trench"],"kind":"place","group":"trenches","fact":"The Kuril-Kamchatka Trench runs south from Kamchatka past the Kuril Islands and reaches more than 9,000 metres deep."},"kuroshio":{"id":"kuroshio","name":"Kuroshio Current","aliases":["Kuroshio","Japan Current","Black Stream","Black Current"],"kind":"place","group":"currents","fact":"The Kuroshio, or Black Stream, is the Pacific's counterpart to the Gulf Stream, carrying warm water north past Japan."},"kursk":{"id":"kursk","name":"Kursk","aliases":["K-141 Kursk","submarine Kursk"],"kind":"vessel","group":"wrecks","fact":"The Russian submarine Kursk sank in the Barents Sea in August 2000 after torpedo explosions, with the loss of all 118 aboard."},"kuruma-prawn":{"id":"kuruma-prawn","name":"Kuruma prawn","aliases":["Japanese tiger prawn","Marsupenaeus japonicus","kuruma ebi","kuruma shrimp"],"kind":"creature","group":"crustaceans","fact":"The kuruma prawn, with its banded tail, is one of the most expensive prawns in Japan and the first prawn ever reared in a hatchery, in the 1930s."},"kvarner-gulf":{"id":"kvarner-gulf","name":"Kvarner Gulf","aliases":["Kvarner","Kvarner Bay","Gulf of Quarnero"],"kind":"place","group":"gulfs","fact":"The Kvarner Gulf is a bay of the northern Adriatic in Croatia, sheltered by the islands of Krk, Cres and Rab, with the port of Rijeka at its head."},"kwajalein-atoll":{"id":"kwajalein-atoll","name":"Kwajalein Atoll","aliases":["Kwajalein"],"kind":"place","group":"reefs","fact":"Kwajalein Atoll in the Marshall Islands encloses one of the largest lagoons in the world, about 2,000 square kilometres."},"labrador-current":{"id":"labrador-current","name":"Labrador Current","aliases":[],"kind":"place","group":"currents","fact":"The Labrador Current carries cold Arctic water and icebergs south past Newfoundland, and it was one of its icebergs that sank the Titanic."},"labrador-duck":{"id":"labrador-duck","name":"Labrador duck","aliases":["Camptorhynchus labradorius"],"kind":"creature","group":"seabirds","fact":"The Labrador duck, a sea duck of the North American Atlantic coast, was the first bird endemic to North America to go extinct, last seen in 1878."},"labrador-sea":{"id":"labrador-sea","name":"Labrador Sea","aliases":[],"kind":"place","group":"seas","fact":"The Labrador Sea between Canada and Greenland is one of the few places where surface water sinks to the deep ocean, helping drive global circulation."},"ladyfish":{"id":"ladyfish","name":"Ladyfish","aliases":["tenpounder","Elops saurus"],"kind":"creature","group":"fish","fact":"The ladyfish is a slim silver fish of warm estuaries that leaps and skips repeatedly across the surface when hooked."},"lagos":{"id":"lagos","name":"Lagos","aliases":[],"kind":"place","group":"ports","fact":"Lagos, Nigeria's largest city, grew around a lagoon opening onto the Atlantic, and its name is Portuguese for 'lakes'."},"lahontan-cutthroat-trout":{"id":"lahontan-cutthroat-trout","name":"Lahontan cutthroat trout","aliases":["Lahontan cutthroat","Oncorhynchus clarkii henshawi"],"kind":"creature","group":"fish","fact":"The Lahontan cutthroat is the largest subspecies of cutthroat trout, native to Nevada's Pyramid Lake, and is the state fish of Nevada."},"lake-sturgeon":{"id":"lake-sturgeon","name":"Lake sturgeon","aliases":["Acipenser fulvescens"],"kind":"creature","group":"fish","fact":"The lake sturgeon of the Great Lakes and Mississippi can live for more than 100 years and does not breed until it is about 20."},"lake-trout":{"id":"lake-trout","name":"Lake trout","aliases":["lake char","mackinaw","togue","Salvelinus namaycush","laker"],"kind":"creature","group":"fish","fact":"Lake trout are big, slow-growing char of cold northern lakes that can live for more than 25 years."},"lamp-shell":{"id":"lamp-shell","name":"Lamp shell","aliases":["lampshell","brachiopod"],"kind":"creature","group":"invertebrates","fact":"Lamp shells look like clams but belong to a separate ancient group, the brachiopods, and filter food with a coiled, tentacled organ called the lophophore."},"lancaster-sound":{"id":"lancaster-sound","name":"Lancaster Sound","aliases":[],"kind":"place","group":"straits","fact":"Lancaster Sound, the eastern entrance to the Northwest Passage, is named after Sir James Lancaster, a sponsor of William Baffin's 1616 voyage."},"lancastria":{"id":"lancastria","name":"Lancastria","aliases":["RMS Lancastria"],"kind":"vessel","group":"wrecks","fact":"The troopship Lancastria was bombed and sunk off Saint-Nazaire in June 1940, Britain's worst ever maritime disaster."},"lancelet":{"id":"lancelet","name":"Lancelet","aliases":["amphioxus","Branchiostoma"],"kind":"creature","group":"chordates","fact":"The lancelet, a finger-length fish-like animal that burrows in sand, has a body plan close to the ancestor of all vertebrates."},"lancetfish":{"id":"lancetfish","name":"Lancetfish","aliases":["Alepisaurus","Alepisaurus ferox","longnose lancetfish"],"kind":"creature","group":"fish","fact":"The lancetfish is a 2-metre deep-sea predator with a huge sail fin and fangs, and its watery flesh is so flabby that it is rarely eaten."},"lane-snapper":{"id":"lane-snapper","name":"Lane snapper","aliases":["Lutjanus synagris"],"kind":"creature","group":"fish","fact":"The lane snapper is a pink-and-yellow striped Caribbean snapper with a black spot on its side, common on grass flats and reefs."},"langoustine":{"id":"langoustine","name":"Langoustine","aliases":["Norway lobster","Dublin Bay prawn","scampi","Nephrops norvegicus","Nephrops"],"kind":"creature","group":"crustaceans","fact":"Langoustines live in burrows in muddy seabeds and are one of the most valuable catches landed in Britain, where they are sold as scampi."},"lanternfish":{"id":"lanternfish","name":"Lanternfish","aliases":["myctophid","Myctophidae","lantern fish"],"kind":"creature","group":"fish","fact":"Lanternfish may make up more than half of all deep-sea fish by weight, and their nightly rise towards the surface is the largest animal migration on Earth."},"lanternshark":{"id":"lanternshark","name":"Lanternshark","aliases":["lantern shark","velvet belly lanternshark","Etmopterus","velvet belly","Etmopterus spinax"],"kind":"creature","group":"sharks","fact":"Lanternsharks are small deep-sea sharks that glow along their bellies, hiding their silhouettes from predators looking up."},"laptev-sea":{"id":"laptev-sea","name":"Laptev Sea","aliases":[],"kind":"place","group":"seas","fact":"The Laptev Sea off Siberia is named after the Russian explorer cousins Dmitry and Khariton Laptev, who charted the Arctic coast in the 1730s and 1740s."},"largehead-hairtail":{"id":"largehead-hairtail","name":"Largehead hairtail","aliases":["hairtail","beltfish","Trichiurus lepturus","cutlassfish","ribbonfish"],"kind":"creature","group":"fish","fact":"The largehead hairtail is a ribbon-like, silver predator with fangs that is one of the largest fish catches in the world, mostly off China."},"largemouth-bass":{"id":"largemouth-bass","name":"Largemouth bass","aliases":["black bass","Micropterus salmoides","bass"],"kind":"creature","group":"fish","fact":"The male largemouth bass sweeps out a nest in the shallows and guards the eggs and fry for weeks, attacking anything that comes near."},"larger-pacific-striped-octopus":{"id":"larger-pacific-striped-octopus","name":"Larger Pacific striped octopus","aliases":["LPSO"],"kind":"creature","group":"cephalopods","fact":"The larger Pacific striped octopus is unusually social: pairs share dens and mate beak to beak, and the female lays several clutches instead of dying after one."},"largetooth-sawfish":{"id":"largetooth-sawfish","name":"Largetooth sawfish","aliases":["freshwater sawfish","Pristis pristis","Pristis microdon"],"kind":"creature","group":"rays","fact":"The largetooth sawfish can live in fresh water and has been caught hundreds of kilometres up rivers in Australia and Central America."},"larvacean":{"id":"larvacean","name":"Larvacean","aliases":["appendicularian","Oikopleura"],"kind":"creature","group":"plankton","fact":"Larvaceans are tadpole-shaped, transparent animals that build a disposable mucus 'house' around themselves to filter food, discarding it several times a day."},"las-palmas":{"id":"las-palmas","name":"Las Palmas","aliases":["Las Palmas de Gran Canaria"],"kind":"place","group":"ports","fact":"Las Palmas de Gran Canaria is a major Atlantic port where Columbus's ships stopped for repairs in 1492 before crossing to the Americas."},"lawnmower-blenny":{"id":"lawnmower-blenny","name":"Lawnmower blenny","aliases":["jewelled blenny","algae blenny","Salarias fasciatus"],"kind":"creature","group":"fish","fact":"The lawnmower blenny is named for its habit of cropping algae, which makes it a popular cleaner for reef aquariums."},"laysan-albatross":{"id":"laysan-albatross","name":"Laysan albatross","aliases":["Phoebastria immutabilis"],"kind":"creature","group":"seabirds","fact":"A Laysan albatross named Wisdom, ringed on Midway Atoll in 1956, was still hatching chicks in her seventies, the oldest known wild bird."},"leaf-scaled-sea-snake":{"id":"leaf-scaled-sea-snake","name":"Leaf-scaled sea snake","aliases":["Aipysurus foliosquama"],"kind":"creature","group":"reptiles","fact":"The leaf-scaled sea snake vanished from Ashmore Reef and was feared extinct until it turned up again off Western Australia in 2015."},"leafscale-gulper-shark":{"id":"leafscale-gulper-shark","name":"Leafscale gulper shark","aliases":["Centrophorus squamosus"],"kind":"creature","group":"sharks","fact":"The leafscale gulper shark, named for its leaf-shaped scales, lives on continental slopes down to about 2,400 metres."},"leafy-sea-dragon":{"id":"leafy-sea-dragon","name":"Leafy sea dragon","aliases":["leafy seadragon","leafy","Glauert's sea dragon","Phycodurus eques"],"kind":"creature","group":"fish","fact":"The leafy sea dragon's leaf-like flaps are camouflage only; it swims with tiny transparent fins, and the male carries the eggs under his tail."},"least-darter":{"id":"least-darter","name":"Least darter","aliases":["Etheostoma microperca"],"kind":"creature","group":"fish","fact":"The least darter is one of the smallest freshwater fish in North America, a 4-centimetre perch relative of weedy streams and lakes."},"least-killifish":{"id":"least-killifish","name":"Least killifish","aliases":["Heterandria formosa","dwarf livebearer","midget livebearer"],"kind":"creature","group":"fish","fact":"The least killifish is one of the smallest fish in North America, a 2-to-3-centimetre livebearer of the southeastern United States, and not a true killifish."},"leather-coral":{"id":"leather-coral","name":"Leather coral","aliases":["toadstool coral","Sarcophyton"],"kind":"creature","group":"corals","fact":"Leather corals are soft corals shaped like a toadstool with a leathery surface, and they shed a waxy film to clean themselves."},"leather-star":{"id":"leather-star","name":"Leather star","aliases":["Dermasterias imbricata"],"kind":"creature","group":"echinoderms","fact":"The leather star has a smooth, leathery skin and is said to smell of garlic when it is lifted from the water."},"leatherback-turtle":{"id":"leatherback-turtle","name":"Leatherback turtle","aliases":["leatherback","leathery turtle","Dermochelys coriacea","Leatherback sea turtle","lute turtle"],"kind":"creature","group":"turtles","fact":"Leatherback turtles have been tracked crossing the entire Pacific, more than 10,000 kilometres, from Indonesian nesting beaches to feeding grounds off California."},"leedsichthys":{"id":"leedsichthys","name":"Leedsichthys","aliases":[],"kind":"creature","group":"fish","fact":"Leedsichthys was a Jurassic filter-feeding fish perhaps 16 metres long, the largest bony fish known to have lived."},"leeuwin-current":{"id":"leeuwin-current","name":"Leeuwin Current","aliases":[],"kind":"place","group":"currents","fact":"The Leeuwin Current flows south along the coast of Western Australia, carrying warm tropical water that lets corals grow as far south as the Abrolhos Islands."},"lemon-shark":{"id":"lemon-shark","name":"Lemon shark","aliases":["Negaprion brevirostris"],"kind":"creature","group":"sharks","fact":"Lemon sharks return to the same mangrove nurseries where they were born to give birth to their own pups."},"lemon-sole":{"id":"lemon-sole","name":"Lemon sole","aliases":["Microstomus kitt"],"kind":"creature","group":"fish","fact":"Despite its name, the lemon sole is not a true sole but a right-eyed flounder found around the British Isles."},"lenok":{"id":"lenok","name":"Lenok","aliases":["Asiatic trout","Manchurian trout","Brachymystax lenok"],"kind":"creature","group":"fish","fact":"The lenok, sometimes called the Asiatic trout, lives in the cold rivers of Siberia, Mongolia, China and Korea."},"leopard-seal":{"id":"leopard-seal","name":"Leopard seal","aliases":["sea leopard","Hydrurga leptonyx"],"kind":"creature","group":"seals","fact":"Leopard seals are the Antarctic's top seal predator, hunting penguins and the pups of other seals."},"leopard-shark":{"id":"leopard-shark","name":"Leopard shark","aliases":["Triakis semifasciata"],"kind":"creature","group":"sharks","fact":"Leopard sharks gather in warm shallows off California each summer, with pregnant females basking in the waters off La Jolla."},"leopard-whipray":{"id":"leopard-whipray","name":"Leopard whipray","aliases":["Himantura leoparda"],"kind":"creature","group":"rays","fact":"The leopard whipray has a leopard-like pattern of dark rings and was only separated from the honeycomb stingray as a species in 2008."},"leptocephalus":{"id":"leptocephalus","name":"Leptocephalus","aliases":["eel larva","leptocephalus larva"],"kind":"creature","group":"fish","fact":"The leptocephalus is the leaf-shaped, see-through larva of eels, tarpon and bonefish, which drifts in the current for months before changing shape."},"lesser-electric-ray":{"id":"lesser-electric-ray","name":"Lesser electric ray","aliases":["Narcine bancroftii"],"kind":"creature","group":"rays","fact":"The lesser electric ray of the western Atlantic is small enough to hold in two hands yet can deliver a shock of around 14 to 37 volts."},"lettuce-coral":{"id":"lettuce-coral","name":"Lettuce coral","aliases":["Agaricia"],"kind":"creature","group":"corals","fact":"Lettuce coral grows in thin, ruffled plates like the leaves of a lettuce and is common on Caribbean reef slopes."},"lettuce-sea-slug":{"id":"lettuce-sea-slug","name":"Lettuce sea slug","aliases":["Elysia crispata","lettuce slug"],"kind":"creature","group":"molluscs","fact":"The lettuce sea slug eats green algae and keeps their chloroplasts alive inside its frilly body, where they go on making sugar from sunlight."},"levantine-sea":{"id":"levantine-sea","name":"Levantine Sea","aliases":["Levantine Basin"],"kind":"place","group":"seas","fact":"The Levantine Sea is the easternmost part of the Mediterranean, off Turkey, Syria, Lebanon, Israel and Egypt, and the saltiest part of the whole sea."},"leyte-gulf":{"id":"leyte-gulf","name":"Leyte Gulf","aliases":["Gulf of Leyte"],"kind":"place","group":"gulfs","fact":"Leyte Gulf in the Philippines saw the largest naval battle of the Second World War in October 1944."},"libyan-sea":{"id":"libyan-sea","name":"Libyan Sea","aliases":[],"kind":"place","group":"seas","fact":"The Libyan Sea is the stretch of the Mediterranean between Crete and the coast of Libya."},"lighthouse-reef":{"id":"lighthouse-reef","name":"Lighthouse Reef","aliases":["Lighthouse Reef Atoll"],"kind":"place","group":"reefs","fact":"Lighthouse Reef is an atoll off Belize whose lagoon contains the Great Blue Hole, a sinkhole about 125 metres deep made famous by Jacques Cousteau."},"ligurian-sea":{"id":"ligurian-sea","name":"Ligurian Sea","aliases":[],"kind":"place","group":"seas","fact":"The Ligurian Sea, between the Italian Riviera and Corsica, is part of the Pelagos Sanctuary, a protected area rich in fin whales and dolphins."},"limiting-factor":{"id":"limiting-factor","name":"Limiting Factor","aliases":["DSV Limiting Factor","Bakunawa"],"kind":"vessel","group":"submersibles","fact":"Limiting Factor is the submersible in which Victor Vescovo became the first person to dive to the deepest point of all five oceans, in 2018 and 2019."},"limpet":{"id":"limpet","name":"Limpet","aliases":["common limpet","Patella vulgata","Patella"],"kind":"creature","group":"molluscs","fact":"Limpets clamp their cone-shaped shells to rocks and return to the exact same 'home scar' after every grazing trip."},"lincoln-sea":{"id":"lincoln-sea","name":"Lincoln Sea","aliases":[],"kind":"place","group":"seas","fact":"The Lincoln Sea, north of Greenland and Ellesmere Island, is named after Robert Todd Lincoln, US Secretary of War and son of Abraham Lincoln."},"lined-butterflyfish":{"id":"lined-butterflyfish","name":"Lined butterflyfish","aliases":["Chaetodon lineolatus"],"kind":"creature","group":"fish","fact":"The lined butterflyfish is the largest butterflyfish, growing to about 30 centimetres, with thin vertical lines and a black band through the eye."},"lined-seahorse":{"id":"lined-seahorse","name":"Lined seahorse","aliases":["northern seahorse","Hippocampus erectus"],"kind":"creature","group":"fish","fact":"The lined seahorse is the seahorse of the western Atlantic, found from Nova Scotia to Venezuela, including the eelgrass beds of Chesapeake Bay."},"ling":{"id":"ling","name":"Ling","aliases":["common ling","Molva molva"],"kind":"creature","group":"fish","fact":"The ling is a long, slender cod relative of deep North Atlantic waters that can reach 2 metres; its salted, dried flesh is a traditional Norwegian export."},"lingcod":{"id":"lingcod","name":"Lingcod","aliases":["Ophiodon elongatus"],"kind":"creature","group":"fish","fact":"The male lingcod guards the egg mass on the kelp-forest floor through winter, and its flesh is sometimes blue-green, fading to white when cooked."},"lingula":{"id":"lingula","name":"Lingula","aliases":["Lingula brachiopod","lamp shell","brachiopod"],"kind":"creature","group":"brachiopods","fact":"Lingula, a burrowing brachiopod on a fleshy stalk, looks much like fossils more than 450 million years old and was one of Darwin's original examples of a living fossil."},"lionfish":{"id":"lionfish","name":"Lionfish","aliases":["red lionfish","Pterois","Pterois volitans","turkeyfish","firefish","common lionfish"],"kind":"creature","group":"fish","fact":"Lionfish have 18 venomous spines and, released from aquariums, have invaded the Caribbean and western Atlantic, where they have no natural predators."},"lions-mane-jellyfish":{"id":"lions-mane-jellyfish","name":"Lion's mane jellyfish","aliases":["lion's mane","giant jellyfish","hair jelly","Cyanea capillata","lions mane jelly"],"kind":"creature","group":"jellies","fact":"The lion's mane jellyfish of cold northern seas is the largest known jellyfish, with tentacles that can trail over 30 metres."},"liopleurodon":{"id":"liopleurodon","name":"Liopleurodon","aliases":[],"kind":"creature","group":"reptiles","fact":"Liopleurodon was a Jurassic pliosaur of European seas with a skull well over a metre long, far smaller than the 25-metre giant once shown on television."},"lisbon":{"id":"lisbon","name":"Lisbon","aliases":["Lisboa"],"kind":"place","group":"ports","fact":"Lisbon sits where the Tagus meets the Atlantic, and Vasco da Gama sailed from here in 1497 on the first voyage from Europe to India."},"little-auk":{"id":"little-auk","name":"Little auk","aliases":["dovekie","Alle alle"],"kind":"creature","group":"seabirds","fact":"The little auk is one of the most numerous seabirds in the Arctic, breeding in colonies of millions in Greenland and Svalbard."},"little-skate":{"id":"little-skate","name":"Little skate","aliases":["Leucoraja erinacea"],"kind":"creature","group":"rays","fact":"The little skate is a small, common skate of the north-west Atlantic that walks along the seabed on modified pelvic fins."},"little-tunny":{"id":"little-tunny","name":"Little tunny","aliases":["false albacore","bonita","Euthynnus alletteratus","little tuna"],"kind":"creature","group":"fish","fact":"The little tunny, or false albacore, is the most common tuna in the Atlantic, a small, fast, scribble-patterned fish loved by fly anglers but rarely eaten."},"livyatan":{"id":"livyatan","name":"Livyatan","aliases":["Livyatan melvillei"],"kind":"creature","group":"whales","fact":"Livyatan was a sperm whale of about 12 million years ago with teeth more than 30 centimetres long, named after Moby-Dick's author."},"lizardfish":{"id":"lizardfish","name":"Lizardfish","aliases":["Synodontidae","Synodus","lizard fish"],"kind":"creature","group":"fish","fact":"Lizardfish are toothy ambush hunters that sit on the sand, often with most of the body buried, and dart up to grab passing fish."},"lobster":{"id":"lobster","name":"Lobster","aliases":["American lobster","European lobster","Homarus","Maine lobster","Homarus americanus","Nephropidae"],"kind":"creature","group":"crustaceans","fact":"Lobsters keep growing throughout their lives by moulting their shells, and some may live for decades."},"loggerhead-turtle":{"id":"loggerhead-turtle","name":"Loggerhead turtle","aliases":["loggerhead","loggerhead sea turtle","Caretta caretta"],"kind":"creature","group":"turtles","fact":"The loggerhead sea turtle has a huge head and powerful jaws for crushing conchs and crabs, and can live for 70 years or more."},"loihi-seamount":{"id":"loihi-seamount","name":"Loihi Seamount","aliases":["Kamaʻehuakanaloa","Kamaehuakanaloa Seamount","Lōʻihi"],"kind":"place","group":"features","fact":"Loihi, now officially Kamaʻehuakanaloa, is an active undersea volcano south-east of Hawaii that may one day grow into the next Hawaiian island."},"lombok-strait":{"id":"lombok-strait","name":"Lombok Strait","aliases":[],"kind":"place","group":"straits","fact":"The Lombok Strait between Bali and Lombok marks part of the Wallace Line, the boundary between Asian and Australian wildlife."},"lomonosov-ridge":{"id":"lomonosov-ridge","name":"Lomonosov Ridge","aliases":[],"kind":"place","group":"features","fact":"The Lomonosov Ridge crosses the Arctic Ocean floor near the North Pole and is claimed by Russia, Canada and Denmark in competing seabed submissions."},"long-beaked-common-dolphin":{"id":"long-beaked-common-dolphin","name":"Long-beaked common dolphin","aliases":["Delphinus capensis","Delphinus bairdii"],"kind":"creature","group":"dolphins","fact":"The long-beaked common dolphin hugs the coasts of California, Peru and West Africa and has a noticeably longer snout than its short-beaked cousin."},"long-finned-pilot-whale":{"id":"long-finned-pilot-whale","name":"Long-finned pilot whale","aliases":["Globicephala melas"],"kind":"creature","group":"dolphins","fact":"Long-finned pilot whales are the target of the Faroe Islands' drive hunt, and their pods follow a leader so closely that they strand together."},"long-island":{"id":"long-island","name":"Long Island","aliases":[],"kind":"place","group":"islands","fact":"Long Island stretches about 190 kilometres east from New York City into the Atlantic and is the largest island in the contiguous United States."},"long-nosed-chimaera":{"id":"long-nosed-chimaera","name":"Long-nosed chimaera","aliases":["spookfish","narrownose chimaera","Harriotta raleighana"],"kind":"creature","group":"fish","fact":"Long-nosed chimaeras are deep-sea ghost sharks with a long pointed snout covered in electric-sensing pores."},"long-snouted-seahorse":{"id":"long-snouted-seahorse","name":"Long-snouted seahorse","aliases":["spiny seahorse","maned seahorse","Hippocampus guttulatus"],"kind":"creature","group":"fish","fact":"The long-snouted seahorse lives in seagrass meadows from the British Isles to the Mediterranean and Black Sea, and often grows a mane of skin filaments."},"long-spine-porcupinefish":{"id":"long-spine-porcupinefish","name":"Long-spine porcupinefish","aliases":["balloonfish","freckled porcupinefish","longspined porcupinefish","Diodon holocanthus"],"kind":"creature","group":"fish","fact":"The long-spine porcupinefish has spines that lie flat until it inflates, when they stand straight out, and it is found in warm seas worldwide."},"long-spined-sea-urchin":{"id":"long-spined-sea-urchin","name":"Long-spined sea urchin","aliases":["Diadema","long-spined urchin","black sea urchin","Diadema antillarum"],"kind":"creature","group":"echinoderms","fact":"The mass die-off of long-spined sea urchins in the Caribbean in 1983 let algae overgrow many reefs, showing how important their grazing was."},"longfin-bannerfish":{"id":"longfin-bannerfish","name":"Longfin bannerfish","aliases":["bannerfish","pennant coralfish","Heniochus acuminatus","poor man's Moorish idol"],"kind":"creature","group":"fish","fact":"The longfin bannerfish is a black-and-white butterflyfish with a long white dorsal banner, often mistaken for the Moorish idol."},"longfin-inshore-squid":{"id":"longfin-inshore-squid","name":"Longfin inshore squid","aliases":["Doryteuthis pealeii","Loligo pealeii","longfin squid"],"kind":"creature","group":"cephalopods","fact":"The longfin inshore squid of the US Atlantic coast is a workhorse of neuroscience: its giant nerve fibre helped reveal how nerves fire."},"longfin-mako":{"id":"longfin-mako","name":"Longfin mako","aliases":["longfin mako shark","Isurus paucus"],"kind":"creature","group":"sharks","fact":"The longfin mako has much longer pectoral fins than its shortfin cousin and is far more rarely seen."},"longhorn-cowfish":{"id":"longhorn-cowfish","name":"Longhorn cowfish","aliases":["cowfish","horned boxfish","Lactoria cornuta"],"kind":"creature","group":"fish","fact":"The longhorn cowfish is a boxfish with two horns over its eyes and can release a toxin into the water when it is stressed."},"longliner":{"id":"longliner","name":"Longliner","aliases":["longline boat","longline vessel","long-liner"],"kind":"vessel","group":"boats","fact":"A longliner fishes with a main line that can stretch for tens of kilometres, hung with thousands of baited hooks."},"longmans-beaked-whale":{"id":"longmans-beaked-whale","name":"Longman's beaked whale","aliases":["Indo-Pacific beaked whale","tropical bottlenose whale","Indopacetus pacificus"],"kind":"creature","group":"whales","fact":"Longman's beaked whale was known only from two skulls for most of the 20th century and lives in warm Indo-Pacific waters."},"longnose-batfish":{"id":"longnose-batfish","name":"Longnose batfish","aliases":["Ogcocephalus corniger"],"kind":"creature","group":"fish","fact":"The longnose batfish walks across the seabed on arm-like fins, has a pointed snout, and dangles a tiny lure from beneath it to attract prey."},"longnose-butterflyfish":{"id":"longnose-butterflyfish","name":"Longnose butterflyfish","aliases":["forcepsfish","yellow longnose butterflyfish","Forcipiger flavissimus","forceps fish","long-nosed butterflyfish","Forcipiger"],"kind":"creature","group":"fish","fact":"The longnose butterflyfish, or forcepsfish, uses its tweezer-like snout to pick tiny animals from coral crevices; it is Hawaii's lauwiliwilinukunukuoioi."},"longnose-gar":{"id":"longnose-gar","name":"Longnose gar","aliases":["Lepisosteus osseus"],"kind":"creature","group":"fish","fact":"The longnose gar gulps air at the surface and has a long, narrow snout filled with needle-like teeth."},"longnose-hawkfish":{"id":"longnose-hawkfish","name":"Longnose hawkfish","aliases":["Oxycirrhites typus"],"kind":"creature","group":"fish","fact":"The longnose hawkfish perches on deep gorgonian sea fans wearing a red check pattern, with a long snout for plucking tiny shrimps."},"longnose-skate":{"id":"longnose-skate","name":"Longnose skate","aliases":["Beringraja rhina","Raja rhina"],"kind":"creature","group":"rays","fact":"The longnose skate of the North American Pacific coast has a long pointed snout and lays eggs in leathery cases known as mermaid's purses."},"longship":{"id":"longship","name":"Longship","aliases":["Viking longship","Viking ship","dragon ship","drakkar"],"kind":"vessel","group":"boats","fact":"Viking longships were long, narrow and shallow-draughted, able to cross open sea and yet be rowed up shallow rivers to raid inland."},"longtail-tuna":{"id":"longtail-tuna","name":"Longtail tuna","aliases":["Thunnus tonggol"],"kind":"creature","group":"fish","fact":"The longtail tuna is a coastal tuna of the Indo-Pacific that stays in shallow seas rather than roaming the open ocean."},"loop-current":{"id":"loop-current","name":"Loop Current","aliases":[],"kind":"place","group":"currents","fact":"The Loop Current curls up into the Gulf of Mexico and back out past Florida, and its deep warm water can strengthen hurricanes passing over it."},"lophelia":{"id":"lophelia","name":"Lophelia","aliases":["Lophelia pertusa","Desmophyllum pertusum","cold-water coral"],"kind":"creature","group":"corals","fact":"Lophelia is a cold-water coral that builds reefs in the dark, hundreds of metres down, from Norway to the Gulf of Mexico."},"lord-howe-island-reef":{"id":"lord-howe-island-reef","name":"Lord Howe Island reef","aliases":["Lord Howe Island","Lord Howe reef"],"kind":"place","group":"reefs","fact":"The reef around Lord Howe Island, between Australia and New Zealand, is the southernmost coral reef in the world."},"lost-city-hydrothermal-field":{"id":"lost-city-hydrothermal-field","name":"Lost City hydrothermal field","aliases":["Lost City","Lost City vent field"],"kind":"place","group":"features","fact":"The Lost City is a field of pale carbonate chimneys up to 60 metres tall on the Atlantis Massif in the mid-Atlantic, venting warm alkaline fluid rather than black smoke."},"louvar":{"id":"louvar","name":"Louvar","aliases":["Luvarus imperialis"],"kind":"creature","group":"fish","fact":"The louvar is a rare open-ocean fish that looks like a tuna but is related to surgeonfish and feeds on jellyfish."},"luanda":{"id":"luanda","name":"Luanda","aliases":[],"kind":"place","group":"ports","fact":"Luanda, Angola's capital, is a major Atlantic port whose bay is sheltered by the long sand island of Ilha de Luanda."},"lumpsucker":{"id":"lumpsucker","name":"Lumpsucker","aliases":["lumpfish","Cyclopterus lumpus"],"kind":"creature","group":"fish","fact":"The male lumpsucker, or lumpfish, clings to a rock with a sucker on its belly and guards a pink mass of eggs through the spring tides."},"lungfish":{"id":"lungfish","name":"Lungfish","aliases":["Australian lungfish","African lungfish","South American lungfish","Protopterus","Dipnoi"],"kind":"creature","group":"fish","fact":"Lungfish have true lungs as well as gills and are the closest living fish relatives of land animals."},"lusitania":{"id":"lusitania","name":"Lusitania","aliases":["RMS Lusitania"],"kind":"vessel","group":"wrecks","fact":"The Lusitania was torpedoed by a German U-boat off Ireland in 1915 and lies on its side in about 93 metres of water, slowly collapsing."},"lusitanian-toadfish":{"id":"lusitanian-toadfish","name":"Lusitanian toadfish","aliases":["Halobatrachus didactylus"],"kind":"creature","group":"fish","fact":"The Lusitanian toadfish of Portuguese estuaries hums and 'boat-whistles' from its nest, and larger males even sing in choruses to attract females."},"macaroni-penguin":{"id":"macaroni-penguin","name":"Macaroni penguin","aliases":["Eudyptes chrysolophus"],"kind":"creature","group":"seabirds","fact":"Macaroni penguins are the most numerous penguin and together eat more krill than any other seabird species."},"mackerel":{"id":"mackerel","name":"Mackerel","aliases":["saba","Scomber"],"kind":"creature","group":"fish","fact":"Mackerels are fast, striped schooling fish with tiny finlets before the tail; they spoil quickly, so for sushi (saba) they are cured in salt and vinegar."},"mackerel-icefish":{"id":"mackerel-icefish","name":"Mackerel icefish","aliases":["Champsocephalus gunnari"],"kind":"creature","group":"fish","fact":"The mackerel icefish has no red blood cells, so its blood runs clear, and it feeds almost entirely on Antarctic krill."},"mackerel-scad":{"id":"mackerel-scad","name":"Mackerel scad","aliases":["scad","Decapterus macarellus"],"kind":"creature","group":"fish","fact":"The mackerel scad is a small schooling jack of tropical waters that is a staple bait and food fish from Hawaii to the Caribbean."},"madeira":{"id":"madeira","name":"Madeira","aliases":["Madeira Islands","Porto Santo"],"kind":"place","group":"islands","fact":"Madeira is a Portuguese volcanic island in the Atlantic north of the Canaries, famous for its fortified wine and the laurel forests that once covered it."},"madtom":{"id":"madtom","name":"Madtom","aliases":["tadpole madtom","Noturus","stonecat"],"kind":"creature","group":"fish","fact":"Madtoms are tiny North American catfish, mostly under 10 centimetres, with venom glands at the base of their pectoral spines that give a painful sting."},"maerl":{"id":"maerl","name":"Maerl","aliases":["rhodolith"],"kind":"plant","group":"plants","fact":"Maerl is a free-living coralline seaweed that grows into gravel-like nodules, forming seabed beds that take centuries to build up."},"mahi-mahi":{"id":"mahi-mahi","name":"Mahi-mahi","aliases":["dolphinfish","dorado","Coryphaena hippurus","common dolphinfish","dolphin fish","mahi","mahimahi"],"kind":"creature","group":"fish","fact":"Mahi-mahi, or dorado, is a fast-growing, brilliantly coloured open-ocean fish that is among the fastest swimmers in the sea and a popular restaurant catch."},"mahseer":{"id":"mahseer","name":"Mahseer","aliases":["golden mahseer","Tor putitora"],"kind":"creature","group":"fish","fact":"The golden mahseer of Himalayan rivers was the prized game fish of British India and is now endangered."},"mako-shark":{"id":"mako-shark","name":"Mako shark","aliases":["mako","shortfin mako","Isurus oxyrinchus","blue pointer","bonito shark","shortfin mako shark"],"kind":"creature","group":"sharks","fact":"Makos are widely regarded as the fastest sharks, built for speed with a crescent-shaped tail and a torpedo-shaped body."},"makran-trench":{"id":"makran-trench","name":"Makran Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Makran Trench in the Arabian Sea, off Pakistan and Iran, is a shallow trench where the Arabian Plate slides beneath Eurasia."},"malpelo-island":{"id":"malpelo-island","name":"Malpelo Island","aliases":["Malpelo","Malpelo Fauna and Flora Sanctuary"],"kind":"place","group":"parks","fact":"Malpelo, a bare rock in the Colombian Pacific, is a sanctuary where hundreds of hammerheads and silky sharks gather around its steep walls."},"man-of-war-fish":{"id":"man-of-war-fish","name":"Man-of-war fish","aliases":["bluebottle fish","Nomeus gronovii"],"kind":"creature","group":"fish","fact":"The man-of-war fish lives among the deadly tentacles of the Portuguese man o' war, nibbling on them while sheltering from predators."},"manatee":{"id":"manatee","name":"Manatee","aliases":["sea cow","Trichechus","West Indian manatee","Florida manatee","Caribbean manatee","Antillean manatee","Trichechus manatus"],"kind":"creature","group":"mammals","fact":"Manatees are gentle plant-eaters whose closest living relatives on land are elephants."},"mandarinfish":{"id":"mandarinfish","name":"Mandarinfish","aliases":["mandarin fish","mandarin dragonet","Synchiropus splendidus"],"kind":"creature","group":"fish","fact":"The mandarinfish is one of only two vertebrates known to make a true blue pigment, and it has no scales but a bitter, toxic coating."},"mangrove":{"id":"mangrove","name":"Mangrove","aliases":["mangrove tree"],"kind":"plant","group":"plants","fact":"Mangroves are trees that grow in salt water along tropical shores, with tangled stilt roots that trap mud and shelter young fish."},"mangrove-jack":{"id":"mangrove-jack","name":"Mangrove jack","aliases":["mangrove red snapper","Lutjanus argentimaculatus"],"kind":"creature","group":"fish","fact":"The mangrove jack is a snapper that lurks among mangrove roots in Australia and Asia when young and moves offshore to reefs as it matures."},"mangrove-killifish":{"id":"mangrove-killifish","name":"Mangrove killifish","aliases":["mangrove rivulus","Kryptolebias marmoratus"],"kind":"creature","group":"fish","fact":"The mangrove killifish can live for weeks out of water inside rotting logs, flipping itself across land with its tail, and most are self-fertilising hermaphrodites."},"mangrove-monitor":{"id":"mangrove-monitor","name":"Mangrove monitor","aliases":["Varanus indicus"],"kind":"creature","group":"reptiles","fact":"The mangrove monitor is a lizard of Australia and the western Pacific that swims through mangrove swamps and has a salt-excreting gland in its nose."},"mangrove-whipray":{"id":"mangrove-whipray","name":"Mangrove whipray","aliases":["Urogymnus granulatus","Himantura granulata"],"kind":"creature","group":"rays","fact":"The mangrove whipray spends its youth in mangroves and lagoons of the Indo-Pacific and has a white-spotted dark back."},"manila-clam":{"id":"manila-clam","name":"Manila clam","aliases":["Japanese littleneck","Ruditapes philippinarum","asari","Japanese carpet shell","Venerupis philippinarum"],"kind":"creature","group":"molluscs","fact":"The Manila clam is the most farmed clam in the world and reached North America by accident, mixed in with oyster seed shipped from Japan."},"manila-trench":{"id":"manila-trench","name":"Manila Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Manila Trench lies west of Luzon in the South China Sea and reaches about 5,400 metres deep."},"manta-ray":{"id":"manta-ray","name":"Manta ray","aliases":["manta","giant manta","reef manta","Mobula birostris","Mobula alfredi","giant manta ray","giant oceanic manta ray","reef manta ray","oceanic manta","oceanic manta ray","Manta birostris","giant oceanic manta"],"kind":"creature","group":"rays","fact":"Manta rays filter plankton through their gills and somersault repeatedly to stay in a dense patch of food."},"mantis-shrimp":{"id":"mantis-shrimp","name":"Mantis shrimp","aliases":["stomatopod","shako","Stomatopoda","peacock mantis shrimp","Odontodactylus scyllarus"],"kind":"creature","group":"crustaceans","fact":"A mantis shrimp strikes with the acceleration of a bullet and sees with up to 16 types of light-sensing cell, compared with our three."},"map-puffer":{"id":"map-puffer","name":"Map puffer","aliases":["Arothron mappa"],"kind":"creature","group":"fish","fact":"The map puffer is named for the maze of dark lines over its body, which look like the contour lines on a map."},"mar-del-plata":{"id":"mar-del-plata","name":"Mar del Plata","aliases":[],"kind":"place","group":"ports","fact":"Mar del Plata is Argentina's main seaside resort and its biggest fishing port."},"marble-trout":{"id":"marble-trout","name":"Marble trout","aliases":["marmorata","Salmo marmoratus"],"kind":"creature","group":"fish","fact":"The marble trout of Slovenia and northern Italy has a marbled pattern instead of spots and can grow to well over a metre long."},"marbled-electric-ray":{"id":"marbled-electric-ray","name":"Marbled electric ray","aliases":["marbled torpedo ray","Torpedo marmorata"],"kind":"creature","group":"rays","fact":"The marbled electric ray of the eastern Atlantic and Mediterranean stuns its prey with powerful electric shocks."},"marbled-lungfish":{"id":"marbled-lungfish","name":"Marbled lungfish","aliases":["Protopterus aethiopicus"],"kind":"creature","group":"fish","fact":"The marbled lungfish breathes air with paired lungs and has one of the largest genomes known, roughly 40 times the size of a human's."},"marbled-murrelet":{"id":"marbled-murrelet","name":"Marbled murrelet","aliases":["Brachyramphus marmoratus"],"kind":"creature","group":"seabirds","fact":"The marbled murrelet fishes at sea but nests on mossy branches high in old-growth conifers, sometimes far inland; its nest was not found until 1974."},"mariana-snailfish":{"id":"mariana-snailfish","name":"Mariana snailfish","aliases":["Pseudoliparis swirei"],"kind":"creature","group":"fish","fact":"The Mariana snailfish, named in 2017, has been collected from nearly 8,000 metres and has a see-through pink body with no scales."},"mariana-trench":{"id":"mariana-trench","name":"Mariana Trench","aliases":["Marianas Trench","Challenger Deep","Mariana","Marianas"],"kind":"place","group":"trenches","fact":"The Mariana Trench holds the Challenger Deep, the deepest known point in the ocean at about 10,935 metres."},"marianas-trench-marine-national-monument":{"id":"marianas-trench-marine-national-monument","name":"Marianas Trench Marine National Monument","aliases":["Mariana Trench Marine National Monument"],"kind":"place","group":"parks","fact":"The Marianas Trench Marine National Monument protects the waters and seabed around the deepest trench on Earth and its mud volcanoes."},"marie-tharp":{"id":"marie-tharp","name":"Marie Tharp","aliases":[],"kind":"person","group":"people","fact":"Marie Tharp drew the first map of the entire ocean floor and spotted the rift valley running down the Mid-Atlantic Ridge, key evidence for continental drift."},"marine-flatworm":{"id":"marine-flatworm","name":"Marine flatworm","aliases":["polyclad flatworm","polyclad","flatworm"],"kind":"creature","group":"worms","fact":"Marine flatworms cut into pieces can regrow into complete animals, and some are decorated as brightly as the nudibranchs they mimic."},"marine-iguana":{"id":"marine-iguana","name":"Marine iguana","aliases":["Galápagos marine iguana","sea iguana","Amblyrhynchus cristatus","iguana"],"kind":"creature","group":"reptiles","fact":"The marine iguana of the Galápagos is the only lizard that feeds in the sea, grazing algae underwater and sneezing out salt."},"marine-otter":{"id":"marine-otter","name":"Marine otter","aliases":["chungungo","sea cat","Lontra felina"],"kind":"creature","group":"mammals","fact":"The marine otter, or chungungo, of Chile and Peru is the smallest marine mammal, weighing about 4 kilograms, and lives along rocky shores."},"marine-virus":{"id":"marine-virus","name":"Marine virus","aliases":["virus","phage","bacteriophage"],"kind":"creature","group":"microbes","fact":"Marine viruses are the most numerous biological entities in the sea, around 10 million in every millilitre of seawater, and they kill about a fifth of the ocean's microbes every day."},"market-squid":{"id":"market-squid","name":"Market squid","aliases":["opalescent squid","California market squid","Doryteuthis opalescens","opalescent inshore squid","Loligo opalescens"],"kind":"creature","group":"cephalopods","fact":"Market squid gather in vast spawning schools off California, supporting one of the state's most valuable fisheries."},"marlin":{"id":"marlin","name":"Marlin","aliases":[],"kind":"creature","group":"fish","fact":"Marlins are big, spear-nosed billfish among the fastest fish in the ocean; Hemingway's The Old Man and the Sea is the story of a fight with a giant marlin."},"maroon-clownfish":{"id":"maroon-clownfish","name":"Maroon clownfish","aliases":["spine-cheeked anemonefish","Premnas biaculeatus","Amphiprion biaculeatus","spinecheek anemonefish"],"kind":"creature","group":"fish","fact":"The maroon clownfish is the largest clownfish, up to about 17 centimetres, with cheek spines and a female far bigger and more aggressive than her mate."},"marquesas-islands":{"id":"marquesas-islands","name":"Marquesas Islands","aliases":["Marquesas","Nuku Hiva","Hiva Oa"],"kind":"place","group":"islands","fact":"The Marquesas are rugged volcanic islands in French Polynesia without protecting reefs, where the painter Paul Gauguin spent his last years."},"marron":{"id":"marron","name":"Marron","aliases":["Cherax cainii","Cherax tenuimanus"],"kind":"creature","group":"crustaceans","fact":"The marron of Western Australia is one of the largest freshwater crayfish, reaching more than 2 kilograms, and is farmed for restaurants."},"marshall-islands":{"id":"marshall-islands","name":"Marshall Islands","aliases":["Marshalls","Majuro"],"kind":"place","group":"islands","fact":"The Marshall Islands are 29 low coral atolls in the central Pacific, including Bikini and Enewetak, where the United States tested nuclear weapons."},"mary-rose":{"id":"mary-rose","name":"Mary Rose","aliases":[],"kind":"vessel","group":"wrecks","fact":"Henry VIII's warship Mary Rose sank in the Solent in 1545 and was raised in 1982; its hull is now displayed in Portsmouth."},"masked-angelfish":{"id":"masked-angelfish","name":"Masked angelfish","aliases":["Genicanthus personatus"],"kind":"creature","group":"fish","fact":"The masked angelfish lives only on the deep reefs of the Northwestern Hawaiian Islands and is pure white with a black mask as a female."},"masked-butterflyfish":{"id":"masked-butterflyfish","name":"Masked butterflyfish","aliases":["bluecheek butterflyfish","golden butterflyfish","Chaetodon semilarvatus"],"kind":"creature","group":"fish","fact":"The masked butterflyfish lives only in the Red Sea and Gulf of Aden, where it is usually seen in pairs sheltering under table corals."},"masked-crab":{"id":"masked-crab","name":"Masked crab","aliases":["Corystes cassivelaunus"],"kind":"creature","group":"crustaceans","fact":"The masked crab buries itself in sand and breathes through a snorkel made of its two long antennae pressed together."},"masu-salmon":{"id":"masu-salmon","name":"Masu salmon","aliases":["masu","cherry salmon","Oncorhynchus masou"],"kind":"creature","group":"fish","fact":"The masu or cherry salmon is the Pacific salmon of Japan, Korea and the Russian Far East, and some populations never leave their rivers."},"matthew-flinders":{"id":"matthew-flinders","name":"Matthew Flinders","aliases":["Flinders"],"kind":"person","group":"people","fact":"Matthew Flinders was the first to sail right around Australia, from 1801 to 1803, and popularised the continent's name."},"matthew-fontaine-maury":{"id":"matthew-fontaine-maury","name":"Matthew Fontaine Maury","aliases":["Maury","Matthew Maury"],"kind":"person","group":"people","fact":"Matthew Fontaine Maury, known as the Pathfinder of the Seas, compiled ships' logs into the first charts of ocean winds and currents in the 1840s and 1850s."},"mauis-dolphin":{"id":"mauis-dolphin","name":"Māui dolphin","aliases":["Maui's dolphin","North Island Hector's dolphin","Cephalorhynchus hectori maui"],"kind":"creature","group":"dolphins","fact":"The Māui dolphin, a subspecies of Hector's dolphin off New Zealand's North Island, is among the rarest dolphins with only around 50 adults left."},"mauve-stinger":{"id":"mauve-stinger","name":"Mauve stinger","aliases":["Pelagia noctiluca","purple jellyfish","night-light jellyfish"],"kind":"creature","group":"jellies","fact":"The mauve stinger glows when disturbed at night and has caused mass stingings on Mediterranean beaches; one swarm wiped out a salmon farm in Northern Ireland."},"mbu-puffer":{"id":"mbu-puffer","name":"Mbu puffer","aliases":["giant freshwater puffer","Tetraodon mbu"],"kind":"creature","group":"fish","fact":"The mbu puffer of the Congo River is a freshwater giant that can reach about 67 centimetres long."},"mccullochs-anemonefish":{"id":"mccullochs-anemonefish","name":"McCulloch's anemonefish","aliases":["whitesnout anemonefish","Amphiprion mccullochi","McCulloch's clownfish"],"kind":"creature","group":"fish","fact":"McCulloch's anemonefish is a dark clownfish with a white face found only at Lord Howe and Norfolk Islands, one of the most restricted ranges of any clownfish."},"medaka":{"id":"medaka","name":"Medaka","aliases":["Japanese rice fish","Oryzias latipes","rice fish","Japanese medaka"],"kind":"creature","group":"fish","fact":"The medaka, or Japanese rice fish, is a 3-centimetre fish that became the first vertebrate to mate and lay eggs in space, aboard the space shuttle in 1994."},"mediterranean-damselfish":{"id":"mediterranean-damselfish","name":"Mediterranean damselfish","aliases":["Chromis chromis","Mediterranean chromis","castagnole"],"kind":"creature","group":"fish","fact":"The Mediterranean damselfish is the only native damselfish in the Mediterranean, a dark fish whose juveniles are brilliant blue, common in shoals above rocks."},"mediterranean-monk-seal":{"id":"mediterranean-monk-seal","name":"Mediterranean monk seal","aliases":["Monachus monachus","monk seal"],"kind":"creature","group":"seals","fact":"The Mediterranean monk seal gives birth in sea caves and numbers fewer than a thousand, most of them in Greece and off Mauritania."},"mediterranean-moray":{"id":"mediterranean-moray","name":"Mediterranean moray","aliases":["Muraena helena","Roman eel"],"kind":"creature","group":"fish","fact":"The Mediterranean moray was a Roman delicacy, kept in seaside fish ponds by wealthy Romans."},"mediterranean-parrotfish":{"id":"mediterranean-parrotfish","name":"Mediterranean parrotfish","aliases":["Sparisoma cretense","European parrotfish"],"kind":"creature","group":"fish","fact":"The Mediterranean parrotfish is the only native parrotfish in the Mediterranean, prized by the Romans, and is spreading north as the sea warms."},"mediterranean-sea":{"id":"mediterranean-sea","name":"Mediterranean Sea","aliases":["Mediterranean"],"kind":"place","group":"seas","fact":"The Mediterranean is almost landlocked, connected to the Atlantic only through the Strait of Gibraltar, and evaporates far more water than its rivers bring in."},"megalodon":{"id":"megalodon","name":"Megalodon","aliases":["Otodus megalodon","Carcharocles megalodon","meg"],"kind":"creature","group":"sharks","fact":"Megalodon, a shark perhaps 15 to 20 metres long, died out roughly 3.6 million years ago, and its teeth are the size of a human hand."},"megamouth-shark":{"id":"megamouth-shark","name":"Megamouth shark","aliases":["megamouth","Megachasma pelagios"],"kind":"creature","group":"sharks","fact":"The megamouth shark was unknown to science until 1976, when one was hauled up tangled in a US Navy sea anchor off Hawaii."},"megrim":{"id":"megrim","name":"Megrim","aliases":["whiff","Lepidorhombus whiffiagonis","Cornish sole"],"kind":"creature","group":"fish","fact":"The megrim is a slender, left-eyed flatfish of deep European slopes that was long overlooked by British diners and sold mostly to Spain."},"mekong-giant-catfish":{"id":"mekong-giant-catfish","name":"Mekong giant catfish","aliases":["Pangasianodon gigas","giant Mekong catfish"],"kind":"creature","group":"fish","fact":"The Mekong giant catfish is one of the largest freshwater fish on Earth, reaching about 3 metres and 300 kilograms, and is critically endangered."},"melon-headed-whale":{"id":"melon-headed-whale","name":"Melon-headed whale","aliases":["electra dolphin","many-toothed blackfish","Peponocephala electra"],"kind":"creature","group":"dolphins","fact":"Melon-headed whales travel in pods of hundreds and are actually dolphins, despite their name."},"menhaden":{"id":"menhaden","name":"Menhaden","aliases":["Atlantic menhaden","bunker","pogy","mossbunker","Brevoortia tyrannus","Gulf menhaden","Brevoortia"],"kind":"creature","group":"fish","fact":"Menhaden are oily filter-feeding fish of the American Atlantic coast, caught in huge numbers for fish oil and fish meal."},"mesoamerican-reef":{"id":"mesoamerican-reef","name":"Mesoamerican Reef","aliases":["Mesoamerican Barrier Reef","Mesoamerican Barrier Reef System","Great Mayan Reef","Mayan Reef"],"kind":"place","group":"reefs","fact":"The Mesoamerican Reef runs about 1,000 kilometres from Mexico's Yucatán to Honduras and is the largest barrier reef in the Western Hemisphere."},"meteor":{"id":"meteor","name":"Meteor","aliases":["German Meteor expedition"],"kind":"vessel","group":"vessels","fact":"The German ship Meteor criss-crossed the South Atlantic from 1925 to 1927 using echo sounding to produce the first detailed picture of a whole ocean basin's floor."},"mexican-golden-trout":{"id":"mexican-golden-trout","name":"Mexican golden trout","aliases":["Oncorhynchus chrysogaster"],"kind":"creature","group":"fish","fact":"The Mexican golden trout lives in mountain streams of the Sierra Madre Occidental and is one of the southernmost native trout in North America."},"miami":{"id":"miami","name":"Miami","aliases":["Port of Miami","PortMiami"],"kind":"place","group":"ports","fact":"The Port of Miami on Biscayne Bay calls itself the cruise capital of the world and handles more cruise passengers than any other port."},"mid-atlantic-ridge":{"id":"mid-atlantic-ridge","name":"Mid-Atlantic Ridge","aliases":[],"kind":"place","group":"features","fact":"The Mid-Atlantic Ridge is a chain of underwater volcanoes where new seafloor forms as Europe and Africa drift away from the Americas."},"middle-america-trench":{"id":"middle-america-trench","name":"Middle America Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Middle America Trench runs along the Pacific coast of Central America from Mexico to Costa Rica and reaches about 6,600 metres deep."},"midnight-parrotfish":{"id":"midnight-parrotfish","name":"Midnight parrotfish","aliases":["Scarus coelestinus"],"kind":"creature","group":"fish","fact":"The midnight parrotfish is a dark blue Caribbean parrotfish with bright blue markings on its head that often grazes in schools with other species."},"midshipman":{"id":"midshipman","name":"Midshipman","aliases":["plainfin midshipman","Porichthys notatus","midshipman fish"],"kind":"creature","group":"fish","fact":"The plainfin midshipman has rows of photophores like the buttons on a naval uniform, and the humming of the males keeps houseboat residents awake in Sausalito."},"midway-atoll":{"id":"midway-atoll","name":"Midway Atoll","aliases":["Midway","Midway Island","Midway Islands"],"kind":"place","group":"islands","fact":"Midway Atoll lies near the end of the Hawaiian chain and gave its name to the 1942 battle that turned the Pacific War."},"milkfish":{"id":"milkfish","name":"Milkfish","aliases":["bangus","Chanos chanos","bandeng"],"kind":"creature","group":"fish","fact":"Milkfish is the national fish of the Philippines, farmed in coastal ponds for centuries and eaten despite its many fine bones."},"mimic-filefish":{"id":"mimic-filefish","name":"Mimic filefish","aliases":["blacksaddle filefish","Paraluteres prionurus"],"kind":"creature","group":"fish","fact":"The mimic filefish copies the look of the poisonous saddled toby so closely that predators leave it alone, though it is not toxic itself."},"mimic-octopus":{"id":"mimic-octopus","name":"Mimic octopus","aliases":["Thaumoctopus mimicus"],"kind":"creature","group":"cephalopods","fact":"The mimic octopus of Indonesia impersonates lionfish, flatfish and sea snakes by changing its shape, colour and the way it moves."},"minerva-reefs":{"id":"minerva-reefs","name":"Minerva Reefs","aliases":["Minerva Reef","Teleki Tonga"],"kind":"place","group":"reefs","fact":"The Minerva Reefs are two remote atolls south of Fiji, claimed by Tonga, that briefly hosted a self-declared micronation in 1972."},"minke-whale":{"id":"minke-whale","name":"Minke whale","aliases":["minke","common minke whale","northern minke whale","lesser rorqual","Balaenoptera acutorostrata"],"kind":"creature","group":"whales","fact":"Minke whales are the smallest of the rorquals and the main target of whaling by Norway, Japan and Iceland today."},"mir":{"id":"mir","name":"Mir","aliases":["Mir-1","Mir-2","Mir submersible"],"kind":"vessel","group":"submersibles","fact":"The Russian submersibles Mir-1 and Mir-2 filmed the Titanic wreck for James Cameron's 1997 film and in 2007 planted a flag on the sea floor at the North Pole."},"molasses-reef":{"id":"molasses-reef","name":"Molasses Reef","aliases":[],"kind":"place","group":"reefs","fact":"Molasses Reef off Key Largo, Florida, lies inside the Florida Keys National Marine Sanctuary and is one of the most popular dive and snorkel sites in the Keys."},"mole-crab":{"id":"mole-crab","name":"Mole crab","aliases":["sand crab","Emerita"],"kind":"creature","group":"crustaceans","fact":"Mole crabs burrow backwards into the sand of surf beaches and filter food from the receding waves with their feathery antennae."},"molly":{"id":"molly","name":"Molly","aliases":["sailfin molly","Poecilia"],"kind":"creature","group":"fish","fact":"Mollies are hardy livebearers from Central America that thrive in anything from fresh to fully salty water."},"molokini":{"id":"molokini","name":"Molokini","aliases":["Molokini Crater"],"kind":"place","group":"divesites","fact":"Molokini is a crescent-shaped volcanic crater off Maui whose sheltered inner reef is one of Hawaii's most visited snorkelling spots."},"molucca-sea":{"id":"molucca-sea","name":"Molucca Sea","aliases":["Maluku Sea"],"kind":"place","group":"seas","fact":"The Molucca Sea lies between Sulawesi and the Maluku Islands, the Spice Islands that drew European traders to Indonesia."},"monk-seal":{"id":"monk-seal","name":"Monk seal","aliases":[],"kind":"creature","group":"seals","fact":"Monk seals are the only seals adapted to warm tropical and subtropical waters, and only two species survive today."},"monkfish":{"id":"monkfish","name":"Monkfish","aliases":["angler","goosefish","Lophius piscatorius","Lophius","ankimo","anko","anglerfish"],"kind":"creature","group":"fish","fact":"Monkfish lie flattened on the seabed and twitch a fleshy lure on their heads to draw fish into their enormous mouths."},"monterey-bay":{"id":"monterey-bay","name":"Monterey Bay","aliases":[],"kind":"place","group":"bays","fact":"Monterey Bay in California lies above a submarine canyon as deep as the Grand Canyon and is a sanctuary for sea otters and whales."},"monterey-bay-national-marine-sanctuary":{"id":"monterey-bay-national-marine-sanctuary","name":"Monterey Bay National Marine Sanctuary","aliases":["Monterey Bay"],"kind":"place","group":"parks","fact":"Monterey Bay National Marine Sanctuary stretches along central California and shelters kelp forests, sea otters and a submarine canyon deeper than the Grand Canyon."},"monterey-canyon":{"id":"monterey-canyon","name":"Monterey Canyon","aliases":["Monterey Submarine Canyon"],"kind":"place","group":"features","fact":"Monterey Canyon off California is a submarine canyon comparable in scale to the Grand Canyon, plunging to more than 3,000 metres."},"montevideo":{"id":"montevideo","name":"Montevideo","aliases":[],"kind":"place","group":"ports","fact":"Montevideo, Uruguay's capital and main port, lies on the Río de la Plata near where the Graf Spee was scuttled in 1939."},"montipora":{"id":"montipora","name":"Montipora","aliases":["Montipora coral"],"kind":"creature","group":"corals","fact":"Montipora corals grow as plates, crusts and branches and are popular in reef aquariums for their bright colours."},"moon-jellyfish":{"id":"moon-jellyfish","name":"Moon jellyfish","aliases":["moon jelly","common jellyfish","Aurelia aurita","Aurelia","saucer jelly"],"kind":"creature","group":"jellies","fact":"The moon jellyfish is see-through with four horseshoe-shaped gonads visible through its bell, and its sting is too weak to hurt most people."},"moon-snail":{"id":"moon-snail","name":"Moon snail","aliases":["necklace shell","Naticidae","Lewis's moon snail","Neverita lewisii"],"kind":"creature","group":"molluscs","fact":"Moon snails plough through sand on a huge foot, drilling neat round holes in clam shells, and lay their eggs in a collar of sand."},"moon-wrasse":{"id":"moon-wrasse","name":"Moon wrasse","aliases":["lunar wrasse","Thalassoma lunare","crescent wrasse"],"kind":"creature","group":"fish","fact":"The moon wrasse, or lunar wrasse, is a green-and-blue wrasse with a yellow crescent on the tail, common on reefs across the Indo-Pacific."},"moorish-idol":{"id":"moorish-idol","name":"Moorish idol","aliases":["Zanclus cornutus"],"kind":"creature","group":"fish","fact":"The Moorish idol, with its long trailing dorsal fin, is notoriously hard to keep in aquariums because it feeds mainly on sponges."},"moray-eel":{"id":"moray-eel","name":"Moray eel","aliases":["moray","Muraenidae","eel"],"kind":"creature","group":"fish","fact":"Moray eels have a second set of jaws in their throat that shoots forward to drag prey down the gullet."},"mosasaur":{"id":"mosasaur","name":"Mosasaur","aliases":["mosasaurus"],"kind":"creature","group":"reptiles","fact":"Mosasaurs were giant sea lizards related to monitor lizards and snakes that ruled the late Cretaceous seas until the asteroid struck."},"moses-sole":{"id":"moses-sole","name":"Moses sole","aliases":["Pardachirus marmoratus"],"kind":"creature","group":"fish","fact":"The Moses sole of the Red Sea oozes a milky, soap-like toxin from its fins that makes sharks spit it out, and the toxin was studied as a shark repellent."},"mosquitofish":{"id":"mosquitofish","name":"Mosquitofish","aliases":["western mosquitofish","Gambusia","Gambusia affinis"],"kind":"creature","group":"fish","fact":"The mosquitofish was released worldwide to eat mosquito larvae and has instead wiped out native fish and frogs from Australia to Spain."},"mozambique-channel":{"id":"mozambique-channel","name":"Mozambique Channel","aliases":[],"kind":"place","group":"straits","fact":"The Mozambique Channel separates Madagascar from the African mainland, and the coelacanth was found alive in the Comoros at its northern end."},"ms-estonia":{"id":"ms-estonia","name":"Estonia","aliases":["MS Estonia","Estonia ferry"],"kind":"vessel","group":"wrecks","fact":"The ferry Estonia sank in a Baltic storm in September 1994 with the loss of 852 lives, and lies on the seabed at about 80 metres."},"mud-crab":{"id":"mud-crab","name":"Mud crab","aliases":["giant mud crab","Scylla serrata","mangrove crab","Scylla"],"kind":"creature","group":"crustaceans","fact":"The giant mud crab of mangrove estuaries has claws strong enough to crack a mussel shell or a careless finger, and is the crab in Singapore chilli crab."},"mud-lobster":{"id":"mud-lobster","name":"Mud lobster","aliases":["Thalassina"],"kind":"creature","group":"crustaceans","fact":"The mud lobster of Indo-Pacific mangroves builds volcano-shaped mounds of mud over a metre high, which other mangrove animals use as homes."},"mudskipper":{"id":"mudskipper","name":"Mudskipper","aliases":["Periophthalmus","mud skipper"],"kind":"creature","group":"fish","fact":"Mudskippers are fish that walk and skip across mud flats, breathe through their skin, and retreat into burrows they dig in the mud."},"mullet":{"id":"mullet","name":"Mullet","aliases":["grey mullet","striped mullet","flathead mullet","Mugil cephalus"],"kind":"creature","group":"fish","fact":"Mullet feed on algae and detritus in estuaries and mangrove creeks and are famous for leaping clear of the water for no obvious reason."},"munks-devil-ray":{"id":"munks-devil-ray","name":"Munk's devil ray","aliases":["Munk's pygmy devil ray","mobula ray","Mobula munkiana"],"kind":"creature","group":"rays","fact":"Munk's devil rays gather in schools of thousands off Baja California and the Galápagos and leap metres into the air, landing with a slap."},"murex":{"id":"murex","name":"Murex","aliases":["Bolinus brandaris","Murex brandaris"],"kind":"creature","group":"molluscs","fact":"Murex are spiny sea snails whose glands gave the ancient Phoenicians the precious purple dye of Tyre, worn by emperors."},"murray-cod":{"id":"murray-cod","name":"Murray cod","aliases":["Maccullochella peelii"],"kind":"creature","group":"fish","fact":"The Murray cod is Australia's largest freshwater fish, growing well over a metre in the Murray-Darling rivers."},"musashi":{"id":"musashi","name":"Musashi","aliases":["battleship Musashi"],"kind":"vessel","group":"wrecks","fact":"The battleship Musashi, sister of the Yamato, was sunk in the Sibuyan Sea in 1944 and found by Paul Allen's team in 2015 more than 1,000 metres down."},"mushroom-coral":{"id":"mushroom-coral","name":"Mushroom coral","aliases":["Fungia"],"kind":"creature","group":"corals","fact":"Mushroom corals are single large polyps that live unattached on the sea floor and can creep slowly across the sand."},"muskellunge":{"id":"muskellunge","name":"Muskellunge","aliases":["muskie","musky","Esox masquinongy"],"kind":"creature","group":"fish","fact":"The muskellunge, 'fish of ten thousand casts', is the largest pike and can top 1.5 metres in the lakes of the Great Lakes region."},"musky-octopus":{"id":"musky-octopus","name":"Musky octopus","aliases":["Eledone moschata"],"kind":"creature","group":"cephalopods","fact":"The musky octopus of the Mediterranean gives off a distinct musky smell and has a single row of suckers on each arm."},"mussau-trench":{"id":"mussau-trench","name":"Mussau Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Mussau Trench north of Papua New Guinea is a young, short trench reaching about 7,000 metres deep."},"mussel":{"id":"mussel","name":"Mussel","aliases":["blue mussel","common mussel","Mytilus edulis","Mytilus"],"kind":"creature","group":"molluscs","fact":"Mussels anchor themselves to rocks with tough byssal threads, which have inspired new surgical glues."},"mutton-snapper":{"id":"mutton-snapper","name":"Mutton snapper","aliases":["Lutjanus analis"],"kind":"creature","group":"fish","fact":"The mutton snapper is a large Caribbean snapper with a black spot on its side and blue lines on its face, prized for the table."},"mv-derbyshire":{"id":"mv-derbyshire","name":"MV Derbyshire","aliases":["Derbyshire"],"kind":"vessel","group":"wrecks","fact":"The bulk carrier Derbyshire, the largest British ship ever lost at sea, went down in a typhoon in 1980 with 44 people and was found in 1994 about 4,200 metres down."},"myrtoan-sea":{"id":"myrtoan-sea","name":"Myrtoan Sea","aliases":["Mirtoan Sea"],"kind":"place","group":"seas","fact":"The Myrtoan Sea is the part of the Aegean between the Cyclades and the eastern coast of the Peloponnese."},"nankai-trough":{"id":"nankai-trough","name":"Nankai Trough","aliases":["Nankai Trench"],"kind":"place","group":"trenches","fact":"The Nankai Trough off southern Japan is a subduction trench feared for the huge earthquakes it produces roughly every 100 to 150 years."},"napoleon-wrasse":{"id":"napoleon-wrasse","name":"Napoleon wrasse","aliases":["humphead wrasse","Maori wrasse","Napoleon fish","Napoleonfish","Cheilinus undulatus","giant wrasse"],"kind":"creature","group":"fish","fact":"The Napoleon wrasse can grow to about 2 metres long and is one of the few fish that eats the toxic crown-of-thorns starfish."},"nares-strait":{"id":"nares-strait","name":"Nares Strait","aliases":[],"kind":"place","group":"straits","fact":"Nares Strait between Greenland and Ellesmere Island is named after George Nares, the British admiral who led an expedition towards the North Pole in 1875."},"narrow-barred-spanish-mackerel":{"id":"narrow-barred-spanish-mackerel","name":"Narrow-barred Spanish mackerel","aliases":["Scomberomorus commerson","Spaniard","narrow-barred mackerel"],"kind":"creature","group":"fish","fact":"The narrow-barred Spanish mackerel is a big, fast Indo-Pacific fish with wavy bars on its flanks, a prize of Australian and Gulf fishing."},"narrow-sawfish":{"id":"narrow-sawfish","name":"Narrow sawfish","aliases":["knifetooth sawfish","Anoxypristis cuspidata"],"kind":"creature","group":"rays","fact":"The narrow sawfish, or knifetooth sawfish, has a slimmer snout than other sawfish and is the only member of its genus, Anoxypristis."},"narwhal":{"id":"narwhal","name":"Narwhal","aliases":["narwhale","unicorn of the sea","Monodon monoceros"],"kind":"creature","group":"whales","fact":"The narwhal's spiral tusk is actually a tooth that can grow to about 3 metres and is packed with nerve endings."},"naso-tang":{"id":"naso-tang","name":"Naso tang","aliases":["orangespine unicornfish","lipstick tang","Naso lituratus","orange-spine unicornfish","lipstick surgeonfish"],"kind":"creature","group":"fish","fact":"The naso tang, or orangespine unicornfish, has bright orange tail spines like a lipstick, and the males trail a long filament from each tail lobe."},"nassau":{"id":"nassau","name":"Nassau","aliases":[],"kind":"place","group":"ports","fact":"Nassau, capital of the Bahamas, was a notorious pirate haven in the early 1700s, home to Blackbeard and Charles Vane."},"nassau-grouper":{"id":"nassau-grouper","name":"Nassau grouper","aliases":["Epinephelus striatus"],"kind":"creature","group":"fish","fact":"The Nassau grouper gathers in huge spawning groups at the same Caribbean sites each winter full moon, which made it easy to overfish; it is now endangered."},"natalia-molchanova":{"id":"natalia-molchanova","name":"Natalia Molchanova","aliases":[],"kind":"person","group":"people","fact":"Natalia Molchanova was the most decorated free diver in history, holding dozens of world records, before disappearing on a dive off Ibiza in 2015."},"nauru":{"id":"nauru","name":"Nauru","aliases":["Pleasant Island"],"kind":"place","group":"islands","fact":"Nauru is a single raised coral island in the Pacific, the smallest island nation in the world, once rich from mining phosphate formed from seabird droppings."},"nautile":{"id":"nautile","name":"Nautile","aliases":[],"kind":"vessel","group":"submersibles","fact":"Nautile is the French crewed submersible that explored the wreck of the Titanic and recovered thousands of artefacts from it."},"nautilus":{"id":"nautilus","name":"Nautilus","aliases":["chambered nautilus","pearly nautilus","Nautilus pompilius"],"kind":"creature","group":"cephalopods","fact":"The nautilus controls its buoyancy by adjusting gas in the chambers of its spiral shell, and its lineage has changed little in hundreds of millions of years."},"navaga":{"id":"navaga","name":"Navaga","aliases":["Eleginus nawaga","wachna cod"],"kind":"creature","group":"fish","fact":"The navaga is a small Arctic cod of the White and Barents Seas, fished through the ice in Russia in winter."},"needlefish":{"id":"needlefish","name":"Needlefish","aliases":["Belonidae","houndfish"],"kind":"creature","group":"fish","fact":"Needlefish have long beak-like jaws full of teeth and skim the surface at speed, occasionally spearing boaters when they leap."},"nematode":{"id":"nematode","name":"Nematode","aliases":["roundworm","marine nematode"],"kind":"creature","group":"worms","fact":"Nematodes are the most abundant animals in deep-sea mud, including the sediments of the Challenger Deep, nearly 11 kilometres down."},"neon-flying-squid":{"id":"neon-flying-squid","name":"Neon flying squid","aliases":["Ommastrephes bartramii","red flying squid"],"kind":"creature","group":"cephalopods","fact":"Neon flying squid have been photographed gliding about 30 metres through the air, spreading their fins and arms like wings."},"neon-goby":{"id":"neon-goby","name":"Neon goby","aliases":["Elacatinus oceanops","neon blue goby"],"kind":"creature","group":"fish","fact":"The neon goby is a 4-centimetre Caribbean cleaner fish with a blue stripe that picks parasites from much larger fish at cleaning stations."},"neon-tetra":{"id":"neon-tetra","name":"Neon tetra","aliases":["Paracheirodon innesi","tetra"],"kind":"creature","group":"fish","fact":"The neon tetra, with its electric blue stripe over red, grows to only about 3 centimetres and is one of the most popular aquarium fish, with millions bred each year."},"neopilina":{"id":"neopilina","name":"Neopilina","aliases":["monoplacophoran","Neopilina galatheae"],"kind":"creature","group":"molluscs","fact":"Neopilina, a limpet-like deep-sea mollusc dredged up in 1952, belongs to a group thought extinct for 350 million years."},"neptune-grass":{"id":"neptune-grass","name":"Neptune grass","aliases":["Posidonia oceanica","Posidonia","Mediterranean tapeweed"],"kind":"plant","group":"plants","fact":"Neptune grass, Posidonia oceanica, forms vast Mediterranean meadows; one clone off Ibiza is thought to be up to about 100,000 years old."},"neptunes-necklace":{"id":"neptunes-necklace","name":"Neptune's necklace","aliases":["Hormosira banksii","Hormosira","sea grapes weed"],"kind":"plant","group":"plants","fact":"Neptune's necklace is a seaweed of strings of water-filled beads, common on rocky shores of Australia and New Zealand."},"nereus":{"id":"nereus","name":"Nereus","aliases":[],"kind":"vessel","group":"submersibles","fact":"Nereus was a hybrid robot submarine that reached the Challenger Deep in 2009 and was lost in the Kermadec Trench in 2014 when it imploded at nearly 10,000 metres."},"new-bedford":{"id":"new-bedford","name":"New Bedford","aliases":[],"kind":"place","group":"ports","fact":"New Bedford, Massachusetts, was the whaling capital of the world in the 1800s and is today the highest-value fishing port in the United States."},"new-britain-trench":{"id":"new-britain-trench","name":"New Britain Trench","aliases":[],"kind":"place","group":"trenches","fact":"The New Britain Trench off Papua New Guinea drops to about 9,000 metres and has been explored by robotic landers dropped from the surface."},"new-caledonia":{"id":"new-caledonia","name":"New Caledonia","aliases":["Grande Terre","Nouvelle-Calédonie"],"kind":"place","group":"islands","fact":"New Caledonia is a French territory in the south-west Pacific whose main island is ringed by one of the longest barrier reefs in the world."},"new-caledonia-barrier-reef":{"id":"new-caledonia-barrier-reef","name":"New Caledonia Barrier Reef","aliases":["New Caledonian Barrier Reef","New Caledonia reef","New Caledonia lagoon"],"kind":"place","group":"reefs","fact":"The New Caledonia Barrier Reef is the second-longest double barrier reef in the world and encloses one of the largest lagoons on Earth."},"new-england-seamounts":{"id":"new-england-seamounts","name":"New England Seamounts","aliases":["New England Seamount chain","Bear Seamount"],"kind":"place","group":"features","fact":"The New England Seamounts are a chain of extinct volcanoes running south-east from Georges Bank into the deep Atlantic, home to cold-water coral gardens."},"new-guinea":{"id":"new-guinea","name":"New Guinea","aliases":["Papua New Guinea","Papua","Niugini"],"kind":"place","group":"islands","fact":"New Guinea is the second-largest island in the world and is home to the birds of paradise and more than 800 languages."},"new-hebrides-trench":{"id":"new-hebrides-trench","name":"New Hebrides Trench","aliases":["Vanuatu Trench"],"kind":"place","group":"trenches","fact":"The New Hebrides Trench near Vanuatu reaches about 7,600 metres, and a 2013 expedition found it full of cusk eels and prawns rather than the snailfish seen in other trenches."},"new-york":{"id":"new-york","name":"New York","aliases":["New York City","NYC"],"kind":"place","group":"ports","fact":"New York Harbour is one of the great natural harbours of the world and was the main gateway for immigrants arriving in the United States."},"new-zealand":{"id":"new-zealand","name":"New Zealand","aliases":["Aotearoa"],"kind":"place","group":"islands","fact":"New Zealand's two main islands sit alone in the South Pacific, and their isolation produced flightless birds like the kiwi and the extinct giant moa."},"new-zealand-longfin-eel":{"id":"new-zealand-longfin-eel","name":"New Zealand longfin eel","aliases":["longfin eel","Anguilla dieffenbachii"],"kind":"creature","group":"fish","fact":"The New Zealand longfin eel is one of the largest and longest-lived freshwater eels; females can live for more than 60 years before heading to sea to spawn once."},"new-zealand-mud-snail":{"id":"new-zealand-mud-snail","name":"New Zealand mud snail","aliases":["Potamopyrgus antipodarum"],"kind":"creature","group":"molluscs","fact":"The tiny New Zealand mud snail spreads on anglers' boots and can reach hundreds of thousands per square metre in rivers of the western USA and Europe."},"new-zealand-sea-lion":{"id":"new-zealand-sea-lion","name":"New Zealand sea lion","aliases":["Hooker's sea lion","Phocarctos hookeri"],"kind":"creature","group":"seals","fact":"The New Zealand sea lion, or Hooker's sea lion, is one of the rarest sea lions and breeds mainly on the remote Auckland Islands."},"newfoundland":{"id":"newfoundland","name":"Newfoundland","aliases":[],"kind":"place","group":"islands","fact":"Newfoundland is a large island off eastern Canada where Vikings landed around the year 1000 and whose Grand Banks were once the richest cod fishery on Earth."},"night-shark":{"id":"night-shark","name":"Night shark","aliases":["Carcharhinus signatus"],"kind":"creature","group":"sharks","fact":"The night shark has large green eyes and lives along the edge of the continental shelf in the Atlantic, rising to feed at night."},"nile-perch":{"id":"nile-perch","name":"Nile perch","aliases":["Lates niloticus"],"kind":"creature","group":"fish","fact":"The Nile perch, introduced to Lake Victoria in the 1950s, grows to about 2 metres and drove hundreds of native cichlid species to extinction."},"ninety-east-ridge":{"id":"ninety-east-ridge","name":"Ninety East Ridge","aliases":["Ninetyeast Ridge","90 East Ridge"],"kind":"place","group":"features","fact":"The Ninety East Ridge is a remarkably straight underwater mountain chain in the Indian Ocean, named because it follows the 90th meridian east."},"ningaloo-marine-park":{"id":"ningaloo-marine-park","name":"Ningaloo Marine Park","aliases":["Ningaloo Reef","Ningaloo"],"kind":"place","group":"parks","fact":"Ningaloo Reef in Western Australia is a fringing reef you can swim to from the beach, famous for whale sharks that gather every autumn."},"ningaloo-reef":{"id":"ningaloo-reef","name":"Ningaloo Reef","aliases":["Ningaloo"],"kind":"place","group":"reefs","fact":"Ningaloo Reef in Western Australia is a fringing reef that hugs the shore so closely you can swim to it from the beach, and whale sharks gather there each year."},"ninja-lanternshark":{"id":"ninja-lanternshark","name":"Ninja lanternshark","aliases":["ninja lantern shark","Etmopterus benchleyi"],"kind":"creature","group":"sharks","fact":"The ninja lanternshark, a black glowing shark described in 2015, was named by the describer's young cousins, and its species name honours Jaws author Peter Benchley."},"noble-pen-shell":{"id":"noble-pen-shell","name":"Noble pen shell","aliases":["pen shell","fan mussel","Pinna nobilis"],"kind":"creature","group":"molluscs","fact":"The noble pen shell is a metre-long fan mussel of Mediterranean seagrass meadows whose silky threads were once woven into 'sea silk', and a parasite has nearly wiped it out since 2016."},"noctiluca":{"id":"noctiluca","name":"Noctiluca","aliases":["sea sparkle","Noctiluca scintillans"],"kind":"plant","group":"plankton","fact":"Noctiluca, the 'sea sparkle', is a bubble-like dinoflagellate that lights up breaking waves at night with blue bioluminescence."},"nomuras-jellyfish":{"id":"nomuras-jellyfish","name":"Nomura's jellyfish","aliases":["Nemopilema nomurai","Nomura jellyfish","echizen kurage"],"kind":"creature","group":"jellies","fact":"Nomura's jellyfish can weigh 200 kilograms and measure 2 metres across, and swarms drifting from China into Japanese waters have capsized a fishing boat."},"norfolk":{"id":"norfolk","name":"Norfolk","aliases":["Norfolk, Virginia"],"kind":"place","group":"ports","fact":"Norfolk, Virginia, at the mouth of Chesapeake Bay, is home to the largest naval base in the world."},"nori":{"id":"nori","name":"Nori","aliases":["laver","Porphyra","Pyropia","gim","zicai"],"kind":"plant","group":"plants","fact":"Nori is dried, pressed sheets of the red seaweed laver, grown on nets in shallow Japanese bays and used to wrap sushi rolls."},"norris-top-snail":{"id":"norris-top-snail","name":"Norris's top snail","aliases":["Norris's top shell","kelp snail","smooth turban","Norrisia norrisii"],"kind":"creature","group":"molluscs","fact":"Norris's top snail crawls up giant kelp to graze, then lets go and sinks when it senses a sea star hunting it."},"north-atlantic-drift":{"id":"north-atlantic-drift","name":"North Atlantic Drift","aliases":["North Atlantic Current"],"kind":"place","group":"currents","fact":"The North Atlantic Drift is the continuation of the Gulf Stream that carries warm water towards Britain, Norway and the Arctic."},"north-atlantic-gyre":{"id":"north-atlantic-gyre","name":"North Atlantic Gyre","aliases":["North Atlantic Subtropical Gyre"],"kind":"place","group":"currents","fact":"The North Atlantic Gyre is the clockwise loop formed by the Gulf Stream, North Atlantic Drift, Canary Current and North Equatorial Current, enclosing the Sargasso Sea."},"north-atlantic-right-whale":{"id":"north-atlantic-right-whale","name":"North Atlantic right whale","aliases":["northern right whale","Eubalaena glacialis","right whale"],"kind":"creature","group":"whales","fact":"The North Atlantic right whale is one of the most endangered great whales, with only around 370 left off eastern North America."},"north-equatorial-current":{"id":"north-equatorial-current","name":"North Equatorial Current","aliases":[],"kind":"place","group":"currents","fact":"The North Equatorial Current flows westward just north of the equator in both the Atlantic and the Pacific, driven by the trade winds."},"north-pacific-gyre":{"id":"north-pacific-gyre","name":"North Pacific Gyre","aliases":["North Pacific Subtropical Gyre"],"kind":"place","group":"currents","fact":"The North Pacific Gyre is the huge clockwise circulation of the North Pacific whose calm centre collects floating plastic in the Great Pacific Garbage Patch."},"north-pacific-right-whale":{"id":"north-pacific-right-whale","name":"North Pacific right whale","aliases":["Eubalaena japonica"],"kind":"creature","group":"whales","fact":"The North Pacific right whale is one of the rarest whales, with perhaps only about 30 animals left in the eastern North Pacific."},"north-sea":{"id":"north-sea","name":"North Sea","aliases":[],"kind":"place","group":"seas","fact":"The North Sea is a shallow arm of the Atlantic between Britain and mainland Europe, averaging only about 90 metres deep."},"northern-anchovy":{"id":"northern-anchovy","name":"Northern anchovy","aliases":["Engraulis mordax"],"kind":"creature","group":"fish","fact":"The northern anchovy schools along the North American Pacific coast and feeds everything from humpback whales to brown pelicans."},"northern-bottlenose-whale":{"id":"northern-bottlenose-whale","name":"Northern bottlenose whale","aliases":["bottlenose whale","Hyperoodon ampullatus"],"kind":"creature","group":"whales","fact":"Northern bottlenose whales were heavily hunted in the North Atlantic for their oil and are famously curious about boats."},"northern-elephant-seal":{"id":"northern-elephant-seal","name":"Northern elephant seal","aliases":["Mirounga angustirostris","elephant seal"],"kind":"creature","group":"seals","fact":"Northern elephant seals were hunted to the brink of extinction in the 19th century, with perhaps fewer than 100 left, and now number well over 100,000."},"northern-fur-seal":{"id":"northern-fur-seal","name":"Northern fur seal","aliases":["Callorhinus ursinus"],"kind":"creature","group":"seals","fact":"Most of the world's northern fur seals breed on the Pribilof Islands in the Bering Sea, where they were once hunted by the hundreds of thousands."},"northern-gannet":{"id":"northern-gannet","name":"Northern gannet","aliases":["gannet","Morus bassanus"],"kind":"creature","group":"seabirds","fact":"Northern gannets plunge-dive from up to 30 metres, hitting the water at around 100 kilometres per hour, with air sacs under the skin to cushion the impact."},"northern-pike":{"id":"northern-pike","name":"Northern pike","aliases":["pike","Esox lucius"],"kind":"creature","group":"fish","fact":"Northern pike lunge at prey from cover and leap clear of the water when hooked, and they can reach well over a metre long."},"northern-pipefish":{"id":"northern-pipefish","name":"Northern pipefish","aliases":["Syngnathus fuscus"],"kind":"creature","group":"fish","fact":"The northern pipefish lives in eelgrass beds along the western Atlantic coast, often alongside the lined seahorse."},"northern-prawn":{"id":"northern-prawn","name":"Northern prawn","aliases":["pink shrimp","northern shrimp","Pandalus borealis","coldwater prawn","cold-water prawn","deepwater prawn","amaebi","sweet shrimp"],"kind":"creature","group":"crustaceans","fact":"The northern prawn starts life as a male and changes into a female after a few years, and is the cold-water prawn in most prawn cocktails."},"northern-puffer":{"id":"northern-puffer","name":"Northern puffer","aliases":["sea squab","Sphoeroides maculatus"],"kind":"creature","group":"fish","fact":"The northern puffer of the US east coast is sold as 'sea squab', its flesh being far less toxic than that of tropical puffers."},"northern-right-whale-dolphin":{"id":"northern-right-whale-dolphin","name":"Northern right whale dolphin","aliases":["Lissodelphis borealis"],"kind":"creature","group":"dolphins","fact":"The northern right whale dolphin of the North Pacific has no dorsal fin and skims along the surface in low, long leaps."},"norway-pout":{"id":"norway-pout","name":"Norway pout","aliases":["Trisopterus esmarkii"],"kind":"creature","group":"fish","fact":"The Norway pout is a small cod relative of the North Sea caught almost entirely for fishmeal and oil."},"norwegian-current":{"id":"norwegian-current","name":"Norwegian Current","aliases":["Norwegian Atlantic Current"],"kind":"place","group":"currents","fact":"The Norwegian Current carries warm Atlantic water north along the coast of Norway, keeping its harbours ice-free even beyond the Arctic Circle."},"nudibranch":{"id":"nudibranch","name":"Nudibranch","aliases":["sea slug"],"kind":"creature","group":"molluscs","fact":"Nudibranchs are sea slugs, and some steal the stinging cells from the anemones they eat and reuse them for their own defence."},"nuestra-senora-de-atocha":{"id":"nuestra-senora-de-atocha","name":"Nuestra Señora de Atocha","aliases":["Atocha"],"kind":"vessel","group":"wrecks","fact":"The Spanish treasure galleon Nuestra Señora de Atocha sank in a hurricane off the Florida Keys in 1622; its gold and silver were found in 1985."},"numbfish":{"id":"numbfish","name":"Numbfish","aliases":["coffin ray","Hypnos monopterygius","Australian numbfish"],"kind":"creature","group":"rays","fact":"The Australian numbfish is a flabby electric ray that lies buried in sand and can deliver a strong shock, and it is sometimes stranded alive on beaches."},"nurse-shark":{"id":"nurse-shark","name":"Nurse shark","aliases":["Ginglymostoma cirratum"],"kind":"creature","group":"sharks","fact":"Nurse sharks rest in groups on the seabed by day and suck prey out of crevices with a powerful vacuum-like gulp."},"nursehound":{"id":"nursehound","name":"Nursehound","aliases":["bull huss","large-spotted dogfish","greater spotted dogfish","Scyliorhinus stellaris"],"kind":"creature","group":"sharks","fact":"The nursehound is a large spotted catshark of the eastern Atlantic that lays its eggs in tough cases attached to seaweed."},"nurseryfish":{"id":"nurseryfish","name":"Nurseryfish","aliases":["humphead glassfish","Kurtus gulliveri"],"kind":"creature","group":"fish","fact":"The male nurseryfish of northern Australia and New Guinea carries the egg cluster hooked onto a bony hook on his forehead until the eggs hatch."},"nuuk":{"id":"nuuk","name":"Nuuk","aliases":["Godthåb","Godthaab"],"kind":"place","group":"ports","fact":"Nuuk, Greenland's capital, lies on the Labrador Sea and is one of the smallest capital cities in the world."},"oarfish":{"id":"oarfish","name":"Oarfish","aliases":["giant oarfish","Regalecus glesne","king of herrings"],"kind":"creature","group":"fish","fact":"The giant oarfish is the longest bony fish, reaching about 8 metres, and its rare strandings probably inspired sea-serpent legends."},"oarweed":{"id":"oarweed","name":"Oarweed","aliases":["Laminaria digitata","tangle"],"kind":"plant","group":"plants","fact":"Oarweed is a common European kelp with a thick stem and a blade split into fingers, exposed only at the lowest tides."},"oasisia-tube-worm":{"id":"oasisia-tube-worm","name":"Oasisia tube worm","aliases":["Oasisia alvinae","Oasisia"],"kind":"creature","group":"worms","fact":"Oasisia is a slender tube worm that grows in tangles among giant tube worms at East Pacific vents and, like them, feeds through bacteria instead of a mouth."},"ocean-quahog":{"id":"ocean-quahog","name":"Ocean quahog","aliases":["Icelandic cyprine","mahogany clam","black clam","Arctica islandica","quahog","Ming the clam"],"kind":"creature","group":"molluscs","fact":"An ocean quahog dredged up off Iceland in 2006 was 507 years old, the oldest known individual animal ever found."},"ocean-sunfish":{"id":"ocean-sunfish","name":"Ocean sunfish","aliases":["mola mola","mola","sunfish","common mola"],"kind":"creature","group":"fish","fact":"The ocean sunfish, or mola, is the heaviest bony fish, weighing over 2 tonnes, and drifts the open ocean eating jellyfish."},"oceanic-whitetip-shark":{"id":"oceanic-whitetip-shark","name":"Oceanic whitetip shark","aliases":["oceanic whitetip","Carcharhinus longimanus"],"kind":"creature","group":"sharks","fact":"Oceanic whitetips were blamed for many of the deaths of USS Indianapolis sailors adrift in the Pacific in 1945."},"ocellaris-clownfish":{"id":"ocellaris-clownfish","name":"Ocellaris clownfish","aliases":["ocellaris","common clownfish","false percula clownfish","false clownfish","Amphiprion ocellaris","false percula"],"kind":"creature","group":"fish","fact":"The ocellaris clownfish is the orange, three-barred fish made famous as Nemo; the film's success made it one of the most traded reef fish in the world."},"ocellate-river-stingray":{"id":"ocellate-river-stingray","name":"Ocellate river stingray","aliases":["freshwater stingray","motoro","peacock-eye stingray","Potamotrygon motoro"],"kind":"creature","group":"rays","fact":"The ocellate river stingray lives in the Amazon and Paraná river systems and is one of the few rays found only in fresh water."},"ochre-sea-star":{"id":"ochre-sea-star","name":"Ochre sea star","aliases":["ochre star","purple sea star","Pisaster ochraceus"],"kind":"creature","group":"echinoderms","fact":"The ochre sea star comes in purple or orange and is a keystone predator that stops mussels from taking over the rocky shore."},"octopus":{"id":"octopus","name":"Octopus","aliases":["tako","Octopoda"],"kind":"creature","group":"cephalopods","fact":"An octopus has three hearts and blue, copper-based blood, and about two-thirds of its neurons sit in its eight arms rather than its brain."},"odd-bobtail-squid":{"id":"odd-bobtail-squid","name":"Odd bobtail squid","aliases":["Heteroteuthis dispar"],"kind":"creature","group":"cephalopods","fact":"The odd bobtail squid defends itself by squirting a glowing cloud of luminous mucus instead of dark ink."},"ohrid-trout":{"id":"ohrid-trout","name":"Ohrid trout","aliases":["koran","Salmo letnica"],"kind":"creature","group":"fish","fact":"The Ohrid trout lives only in Lake Ohrid, one of the oldest lakes in Europe, on the border of North Macedonia and Albania."},"oil-tanker":{"id":"oil-tanker","name":"Oil tanker","aliases":["tanker","supertanker","crude carrier"],"kind":"vessel","group":"boats","fact":"The largest oil tankers ever built, the ultra-large crude carriers, could carry more than 500,000 tonnes of oil in a single voyage."},"okeanos-explorer":{"id":"okeanos-explorer","name":"Okeanos Explorer","aliases":["NOAA Ship Okeanos Explorer"],"kind":"vessel","group":"vessels","fact":"Okeanos Explorer is a US government ship dedicated entirely to exploring unknown parts of the ocean, broadcasting its dives live online."},"okinawa":{"id":"okinawa","name":"Okinawa","aliases":["Ryukyu Islands","Ryukyus"],"kind":"place","group":"islands","fact":"Okinawa is the largest of Japan's Ryukyu Islands, in the East China Sea, and was the site of the last great battle of the Second World War in 1945."},"olive-flounder":{"id":"olive-flounder","name":"Olive flounder","aliases":["Japanese flounder","hirame","bastard halibut","Paralichthys olivaceus"],"kind":"creature","group":"fish","fact":"The olive flounder, or hirame, is the most widely farmed flatfish in Japan and South Korea and is served raw as sashimi."},"olive-ridley-sea-turtle":{"id":"olive-ridley-sea-turtle","name":"Olive ridley sea turtle","aliases":["olive ridley","olive ridley turtle","Pacific ridley","Lepidochelys olivacea"],"kind":"creature","group":"turtles","fact":"Olive ridleys nest in arribadas of tens of thousands of females on single beaches in Costa Rica, Mexico and India."},"olive-sea-snake":{"id":"olive-sea-snake","name":"Olive sea snake","aliases":["golden sea snake","Aipysurus laevis"],"kind":"creature","group":"reptiles","fact":"The olive sea snake of Australian reefs has light-sensing cells in its tail, so it can keep its tail hidden in a crevice."},"oman-anemonefish":{"id":"oman-anemonefish","name":"Oman anemonefish","aliases":["Oman clownfish","Amphiprion omanensis"],"kind":"creature","group":"fish","fact":"The Oman anemonefish is found only along the coast of Oman, where it lives in anemones on rocky reefs."},"omuras-whale":{"id":"omuras-whale","name":"Omura's whale","aliases":["dwarf fin whale","Balaenoptera omurai","Omura whale"],"kind":"creature","group":"whales","fact":"Omura's whale was only recognised as a species in 2003 and was first filmed alive off Madagascar in 2015."},"opabinia":{"id":"opabinia","name":"Opabinia","aliases":[],"kind":"creature","group":"arthropods","fact":"Opabinia, a Cambrian sea creature with five eyes and a clawed trunk, reportedly drew laughter when first shown to scientists in 1972."},"opah":{"id":"opah","name":"Opah","aliases":["moonfish","Lampris"],"kind":"creature","group":"fish","fact":"The opah, or moonfish, is the only fish known to keep its whole body warm, circulating heated blood through its gills."},"opalescent-nudibranch":{"id":"opalescent-nudibranch","name":"Opalescent nudibranch","aliases":["Hermissenda crassicornis","Hermissenda"],"kind":"creature","group":"molluscs","fact":"The opalescent nudibranch of Pacific Northwest tide pools stores stinging cells from the hydroids it eats in the orange tips of its back."},"opaleye":{"id":"opaleye","name":"Opaleye","aliases":["Girella nigricans"],"kind":"creature","group":"fish","fact":"The opaleye is a Californian kelp-forest fish with bright blue-green eyes that feeds mainly on seaweed."},"opossum-shrimp":{"id":"opossum-shrimp","name":"Opossum shrimp","aliases":["mysid","mysid shrimp","Mysida"],"kind":"creature","group":"crustaceans","fact":"Opossum shrimp carry their young in a pouch like a possum and swarm in glassy clouds in caves, estuaries and the deep sea."},"orange-clownfish":{"id":"orange-clownfish","name":"Orange clownfish","aliases":["percula clownfish","clown anemonefish","Amphiprion percula","percula","true percula"],"kind":"creature","group":"fish","fact":"The orange clownfish, or percula, looks almost identical to the ocellaris but has thicker black edges to its white bars, and lives around New Guinea and the Great Barrier Reef."},"orange-lined-triggerfish":{"id":"orange-lined-triggerfish","name":"Orange-lined triggerfish","aliases":["orangelined triggerfish","undulate triggerfish","Balistapus undulatus"],"kind":"creature","group":"fish","fact":"The orange-lined triggerfish is dark green with curving orange lines and is notoriously aggressive, both on the reef and in aquariums."},"orange-roughy":{"id":"orange-roughy","name":"Orange roughy","aliases":["Hoplostethus atlanticus","deep-sea perch","slimehead"],"kind":"creature","group":"fish","fact":"The orange roughy lives at 500 to 1,500 metres, does not breed until its twenties and can live for about 150 years, which is why it was so easily overfished."},"orange-spotted-grouper":{"id":"orange-spotted-grouper","name":"Orange-spotted grouper","aliases":["estuary cod","Epinephelus coioides","estuary grouper","goldspotted rockcod"],"kind":"creature","group":"fish","fact":"The orange-spotted grouper, or estuary cod, is a brown grouper with orange spots that is farmed widely in Southeast Asia for live-fish restaurants."},"orca":{"id":"orca","name":"Orca","aliases":["killer whale","Orcinus orca"],"kind":"creature","group":"dolphins","fact":"Orcas are actually the largest dolphins, and different populations have their own dialects and hunting traditions."},"oresund":{"id":"oresund","name":"Oresund","aliases":["the Sound"],"kind":"place","group":"straits","fact":"The Oresund between Denmark and Sweden is one of the three Danish straits linking the Baltic to the North Sea, now spanned by the Oresund Bridge."},"organ-pipe-coral":{"id":"organ-pipe-coral","name":"Organ pipe coral","aliases":["pipe organ coral","Tubipora musica"],"kind":"creature","group":"corals","fact":"Organ pipe coral has a bright red skeleton of parallel tubes like organ pipes, hidden under greyish-green polyps."},"oriental-sweetlips":{"id":"oriental-sweetlips","name":"Oriental sweetlips","aliases":["sweetlips","Plectorhinchus vittatus"],"kind":"creature","group":"fish","fact":"The oriental sweetlips of Indian Ocean reefs hangs under ledges in striped schools by day, and its juveniles wriggle like poisonous flatworms."},"orkney":{"id":"orkney","name":"Orkney","aliases":["Orkney Islands","Orkneys"],"kind":"place","group":"islands","fact":"Orkney, just north of mainland Scotland, is home to Skara Brae, a stone village older than the pyramids, and the natural harbour of Scapa Flow."},"ormer":{"id":"ormer","name":"Ormer","aliases":["Haliotis tuberculata","green ormer"],"kind":"creature","group":"molluscs","fact":"The ormer is the European abalone, gathered by hand on Channel Island beaches at low tide on a handful of strictly controlled days each year."},"ornate-ghost-pipefish":{"id":"ornate-ghost-pipefish","name":"Ornate ghost pipefish","aliases":["ghost pipefish","harlequin ghost pipefish","Solenostomus paradoxus"],"kind":"creature","group":"fish","fact":"In ornate ghost pipefish it is the female, not the male, that broods the eggs, in a pouch formed by her enlarged pelvic fins."},"ornate-sea-snake":{"id":"ornate-sea-snake","name":"Ornate sea snake","aliases":["ornate reef sea snake","Hydrophis ocellatus"],"kind":"creature","group":"reptiles","fact":"The ornate sea snake lives on reefs and sandy flats around northern Australia and feeds on fish and fish eggs."},"ornate-wobbegong":{"id":"ornate-wobbegong","name":"Ornate wobbegong","aliases":["Orectolobus ornatus"],"kind":"creature","group":"sharks","fact":"The ornate wobbegong is a carpet shark of eastern Australian reefs that lies camouflaged on the bottom by day and hunts at night."},"oscar":{"id":"oscar","name":"Oscar","aliases":["oscar fish","Astronotus ocellatus"],"kind":"creature","group":"fish","fact":"The oscar is a big Amazon cichlid that recognises its owner, begs at the glass and rearranges the gravel in its tank."},"osprey":{"id":"osprey","name":"Osprey","aliases":["sea hawk","fish hawk","Pandion haliaetus"],"kind":"creature","group":"seabirds","fact":"The osprey hits the water feet-first and has a reversible outer toe and spiny foot pads to grip slippery fish."},"osprey-reef":{"id":"osprey-reef","name":"Osprey Reef","aliases":[],"kind":"place","group":"reefs","fact":"Osprey Reef is a submerged atoll in the Coral Sea off Queensland whose walls plunge about 1,000 metres and attract shark-diving expeditions."},"ostracod":{"id":"ostracod","name":"Ostracod","aliases":["seed shrimp","Ostracoda"],"kind":"creature","group":"crustaceans","fact":"Ostracods, or seed shrimps, are tiny crustaceans sealed in a hinged shell, and some species flash blue light to attract mates."},"otis-barton":{"id":"otis-barton","name":"Otis Barton","aliases":[],"kind":"person","group":"people","fact":"Otis Barton designed and paid for the bathysphere in which he and William Beebe dived in the 1930s, and in 1949 reached about 1,370 metres alone in his benthoscope."},"otocinclus":{"id":"otocinclus","name":"Otocinclus","aliases":["oto","oto catfish","dwarf suckermouth catfish","Otocinclus vittatus"],"kind":"creature","group":"fish","fact":"Otocinclus, or 'otos', are tiny suckermouth catfish from South America, kept in aquariums to graze algae and barely 4 centimetres long."},"otodus":{"id":"otodus","name":"Otodus","aliases":["Otodus obliquus"],"kind":"creature","group":"sharks","fact":"Otodus obliquus was a giant mackerel shark of about 50 million years ago whose lineage led to megalodon."},"outer-banks":{"id":"outer-banks","name":"Outer Banks","aliases":["Ocracoke","Hatteras Island"],"kind":"place","group":"islands","fact":"The Outer Banks are a long chain of barrier islands off North Carolina, where the Wright brothers first flew and the pirate Blackbeard was killed."},"outrigger-canoe":{"id":"outrigger-canoe","name":"Outrigger canoe","aliases":["outrigger","va'a","waka ama"],"kind":"vessel","group":"boats","fact":"An outrigger canoe has a float lashed alongside the hull for stability, and such canoes carried Austronesian peoples across the Pacific and Indian Oceans."},"oyashio":{"id":"oyashio","name":"Oyashio Current","aliases":["Oyashio","Kuril Current","Okhotsk Current"],"kind":"place","group":"currents","fact":"The Oyashio is a cold current flowing south from the Bering Sea past Kamchatka, and where it meets the warm Kuroshio it creates rich fishing grounds off Japan."},"oyster":{"id":"oyster","name":"Oyster","aliases":["Pacific oyster","Crassostrea gigas","Ostreidae","eastern oyster","rock oyster"],"kind":"creature","group":"molluscs","fact":"A single oyster can filter up to around 190 litres of water a day, and oyster reefs once lined estuaries such as New York Harbour."},"oyster-toadfish":{"id":"oyster-toadfish","name":"Oyster toadfish","aliases":["toadfish","Opsanus tau","Gulf toadfish","Opsanus"],"kind":"creature","group":"fish","fact":"The male oyster toadfish guards the eggs in a den and calls females with a foghorn-like 'boat whistle' that can be heard from boats above."},"pacific-angelshark":{"id":"pacific-angelshark","name":"Pacific angelshark","aliases":["Pacific angel shark","Squatina californica"],"kind":"creature","group":"sharks","fact":"The Pacific angelshark lies buried in sand off California and Mexico and snaps upward at passing fish faster than the eye can follow."},"pacific-bluefin-tuna":{"id":"pacific-bluefin-tuna","name":"Pacific bluefin tuna","aliases":["Thunnus orientalis","kuromaguro"],"kind":"creature","group":"fish","fact":"The Pacific bluefin tuna is the species behind Tokyo's record new-year auctions; one sold for about 333 million yen in 2019."},"pacific-cod":{"id":"pacific-cod","name":"Pacific cod","aliases":["Gadus macrocephalus","grey cod","gray cod"],"kind":"creature","group":"fish","fact":"The Pacific cod is a major fishery of the Bering Sea and Gulf of Alaska, with catches of several hundred thousand tonnes a year."},"pacific-electric-ray":{"id":"pacific-electric-ray","name":"Pacific electric ray","aliases":["Tetronarce californica","Torpedo californica"],"kind":"creature","group":"rays","fact":"The Pacific electric ray hunts at night off California, enveloping fish in its disc and shocking them with up to about 45 volts."},"pacific-halibut":{"id":"pacific-halibut","name":"Pacific halibut","aliases":["Hippoglossus stenolepis","halibut"],"kind":"creature","group":"fish","fact":"Pacific halibut are a mainstay of Alaskan fisheries, and anglers call the biggest ones, over 45 kilograms, barn doors."},"pacific-herring":{"id":"pacific-herring","name":"Pacific herring","aliases":["Clupea pallasii"],"kind":"creature","group":"fish","fact":"The Pacific herring is fished mainly for its roe, sold to Japan as kazunoko, and its eggs laid on kelp are a traditional food of the Pacific Northwest."},"pacific-lamprey":{"id":"pacific-lamprey","name":"Pacific lamprey","aliases":["Entosphenus tridentatus"],"kind":"creature","group":"fish","fact":"The Pacific lamprey climbs waterfalls with its sucker mouth on its way up Columbia River tributaries and is a traditional food of Native peoples."},"pacific-leaping-blenny":{"id":"pacific-leaping-blenny","name":"Pacific leaping blenny","aliases":["leaping blenny","Alticus arnoldorum"],"kind":"creature","group":"fish","fact":"The Pacific leaping blenny of Guam lives entirely out of water on wave-splashed rocks, leaping between them by curling and flicking its tail."},"pacific-oyster":{"id":"pacific-oyster","name":"Pacific oyster","aliases":["Japanese oyster","Crassostrea gigas","Magallana gigas","rock oyster"],"kind":"creature","group":"molluscs","fact":"The Pacific oyster, native to Japan, is now the most farmed oyster in the world and grows on coasts from France to Australia."},"pacific-sand-lance":{"id":"pacific-sand-lance","name":"Pacific sand lance","aliases":["Ammodytes hexapterus","Ammodytes personatus"],"kind":"creature","group":"fish","fact":"Pacific sand lance spend the night and much of the winter buried in coarse sand, which is why mapping their sand beds matters for salmon and seabirds."},"pacific-sandfish":{"id":"pacific-sandfish","name":"Pacific sandfish","aliases":["Trichodon trichodon","sandfish"],"kind":"creature","group":"fish","fact":"The Pacific sandfish buries itself in sand with just its upturned mouth exposed, and is a key prey of seabirds and salmon in Alaska."},"pacific-sardine":{"id":"pacific-sardine","name":"Pacific sardine","aliases":["California sardine","Sardinops sagax"],"kind":"creature","group":"fish","fact":"The Pacific sardine fuelled Monterey's Cannery Row until the stock collapsed in the 1950s, and it still booms and busts with ocean cycles."},"pacific-saury":{"id":"pacific-saury","name":"Pacific saury","aliases":["saury","sanma","Cololabis saira","mackerel pike"],"kind":"creature","group":"fish","fact":"Pacific saury, sanma, is caught by the hundreds of thousands of tonnes in the northwest Pacific and is an autumn favourite grilled whole in Japan."},"pacific-seahorse":{"id":"pacific-seahorse","name":"Pacific seahorse","aliases":["giant seahorse","Hippocampus ingens"],"kind":"creature","group":"fish","fact":"The Pacific seahorse is the only seahorse in the eastern Pacific, ranging from California to Peru and the Galápagos Islands."},"pacific-sleeper-shark":{"id":"pacific-sleeper-shark","name":"Pacific sleeper shark","aliases":["Somniosus pacificus"],"kind":"creature","group":"sharks","fact":"The Pacific sleeper shark is a sluggish giant of cold northern waters that has been recorded at depths of around 2,000 metres."},"pacific-spiny-lumpsucker":{"id":"pacific-spiny-lumpsucker","name":"Pacific spiny lumpsucker","aliases":["spiny lumpsucker","Eumicrotremus orbis"],"kind":"creature","group":"fish","fact":"The Pacific spiny lumpsucker is a golf-ball-sized fish of the Pacific Northwest that sticks to eelgrass and rocks with a suction disc."},"pacific-white-sided-dolphin":{"id":"pacific-white-sided-dolphin","name":"Pacific white-sided dolphin","aliases":["Lagenorhynchus obliquidens"],"kind":"creature","group":"dolphins","fact":"Pacific white-sided dolphins travel in boisterous groups of hundreds in the cool North Pacific and often ride the bow waves of ships."},"paddlefish":{"id":"paddlefish","name":"Paddlefish","aliases":["American paddlefish","spoonbill","spoonbill catfish","Polyodon spathula"],"kind":"creature","group":"fish","fact":"The American paddlefish's long paddle-shaped snout is packed with tens of thousands of electroreceptors used to detect swarms of plankton."},"paedocypris":{"id":"paedocypris","name":"Paedocypris","aliases":["Paedocypris progenetica"],"kind":"creature","group":"fish","fact":"Paedocypris progenetica, from the peat swamps of Sumatra, matures at under 8 millimetres and is among the smallest fish known."},"pagasetic-gulf":{"id":"pagasetic-gulf","name":"Pagasetic Gulf","aliases":["Gulf of Volos","Pagasitic Gulf","Gulf of Pagasae"],"kind":"place","group":"gulfs","fact":"The Pagasetic Gulf is an almost enclosed bay of the Aegean in Thessaly from whose shore, in legend, Jason and the Argonauts set sail for the Golden Fleece."},"palancar-reef":{"id":"palancar-reef","name":"Palancar Reef","aliases":[],"kind":"place","group":"reefs","fact":"Palancar Reef off Cozumel, Mexico, is part of the Mesoamerican Reef and became a famous dive site after Jacques Cousteau filmed it in the 1960s."},"palau":{"id":"palau","name":"Palau","aliases":["Belau","Rock Islands"],"kind":"place","group":"islands","fact":"Palau in the western Pacific is famous for its Rock Islands and for Jellyfish Lake, where millions of harmless jellyfish drift in a marine lake."},"palau-national-marine-sanctuary":{"id":"palau-national-marine-sanctuary","name":"Palau National Marine Sanctuary","aliases":["Palau"],"kind":"place","group":"parks","fact":"Palau closed about 80 percent of its waters to fishing in 2020, creating one of the largest fully protected marine sanctuaries in the world."},"palau-trench":{"id":"palau-trench","name":"Palau Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Palau Trench lies east of the islands of Palau in the western Pacific and reaches about 8,000 metres deep."},"palk-strait":{"id":"palk-strait","name":"Palk Strait","aliases":[],"kind":"place","group":"straits","fact":"Palk Strait between India and Sri Lanka is so shallow that large ships cannot pass, and a chain of shoals called Adam's Bridge lies at its southern end."},"palm-worm":{"id":"palm-worm","name":"Palm worm","aliases":["Paralvinella palmiformis"],"kind":"creature","group":"worms","fact":"The palm worm builds mucus tubes on Pacific vent chimneys and spreads a crown of tentacles like a palm tree to feed in the hot water."},"palmyra-atoll":{"id":"palmyra-atoll","name":"Palmyra Atoll","aliases":["Palmyra"],"kind":"place","group":"reefs","fact":"Palmyra Atoll, an uninhabited US territory south of Hawaii, has reefs so untouched that predators like sharks make up most of the fish biomass."},"pancake-batfish":{"id":"pancake-batfish","name":"Pancake batfish","aliases":["Halieutichthys aculeatus"],"kind":"creature","group":"fish","fact":"The pancake batfish is a round, flattened fish of the Gulf of Mexico seabed that hops along on arm-like fins."},"pangasius":{"id":"pangasius","name":"Pangasius","aliases":["basa","swai","iridescent shark","river cobbler","tra","Pangasianodon hypophthalmus","sutchi catfish","Vietnamese catfish","panga"],"kind":"creature","group":"fish","fact":"Pangasius, sold as basa or river cobbler, is a Vietnamese Mekong catfish farmed in vast numbers and exported as cheap white fillets."},"pantropical-spotted-dolphin":{"id":"pantropical-spotted-dolphin","name":"Pantropical spotted dolphin","aliases":["spotted dolphin","Stenella attenuata"],"kind":"creature","group":"dolphins","fact":"Pantropical spotted dolphins swim above yellowfin tuna in the eastern Pacific, where millions died in tuna nets before dolphin-safe fishing."},"papahanaumokuakea":{"id":"papahanaumokuakea","name":"Papahānaumokuākea Marine National Monument","aliases":["Papahanaumokuakea","Northwestern Hawaiian Islands"],"kind":"place","group":"parks","fact":"Papahānaumokuākea protects the uninhabited north-western Hawaiian Islands and is one of the largest marine protected areas in the world."},"paradise-fish":{"id":"paradise-fish","name":"Paradise fish","aliases":["paradise gourami","Macropodus opercularis"],"kind":"creature","group":"fish","fact":"The paradise fish breathes air with a labyrinth organ and was one of the first tropical fish kept in home aquariums."},"parrotfish":{"id":"parrotfish","name":"Parrotfish","aliases":["parrot fish","Scaridae","Scarinae"],"kind":"creature","group":"fish","fact":"Parrotfish grind coral with beak-like teeth and excrete the remains as fine white sand, producing much of the sand on tropical beaches."},"patagonian-red-octopus":{"id":"patagonian-red-octopus","name":"Patagonian red octopus","aliases":["Enteroctopus megalocyathus","southern red octopus"],"kind":"creature","group":"cephalopods","fact":"The Patagonian red octopus is fished along the coasts of Chile and Argentina and is a close relative of the giant Pacific octopus."},"patagonian-toothfish":{"id":"patagonian-toothfish","name":"Patagonian toothfish","aliases":["Chilean sea bass","Dissostichus eleginoides","toothfish","Chilean seabass"],"kind":"creature","group":"fish","fact":"The Patagonian toothfish was renamed 'Chilean sea bass' by a fish wholesaler in 1977 to sell it, and lives down to about 3,800 metres."},"payara":{"id":"payara","name":"Payara","aliases":["vampire fish","sabre-tooth tetra","Hydrolycus scomberoides"],"kind":"creature","group":"fish","fact":"The payara of the Orinoco and Amazon has two lower fangs so long that they fit into holes in its upper jaw."},"pea-crab":{"id":"pea-crab","name":"Pea crab","aliases":["Pinnotheres","oyster crab"],"kind":"creature","group":"crustaceans","fact":"The pea crab is a tiny crab that lives inside the shells of living mussels and oysters, stealing food from its host's gills."},"pea-puffer":{"id":"pea-puffer","name":"Pea puffer","aliases":["dwarf puffer","Malabar puffer","Carinotetraodon travancoricus","pygmy puffer"],"kind":"creature","group":"fish","fact":"The pea puffer from the rivers of south-west India is one of the smallest pufferfish, about 3 centimetres long."},"peacock-bass":{"id":"peacock-bass","name":"Peacock bass","aliases":["tucunaré","Cichla"],"kind":"creature","group":"fish","fact":"The peacock bass is an Amazon cichlid, not a bass, and was released in Florida canals, where anglers now chase it."},"peacock-flounder":{"id":"peacock-flounder","name":"Peacock flounder","aliases":["flowery flounder","Bothus mancus","Bothus lunatus"],"kind":"creature","group":"fish","fact":"The peacock flounder is covered in bright blue rings and can change its pattern to match the reef in seconds."},"peacock-mantis-shrimp":{"id":"peacock-mantis-shrimp","name":"Peacock mantis shrimp","aliases":["Odontodactylus scyllarus","clown mantis shrimp","harlequin mantis shrimp"],"kind":"creature","group":"crustaceans","fact":"The peacock mantis shrimp's club-like arms hit so hard they can crack aquarium glass and shatter crab shells in a single blow."},"peacocks-tail":{"id":"peacocks-tail","name":"Peacock's tail","aliases":["Padina pavonica","Padina","peacock's tail seaweed"],"kind":"plant","group":"plants","fact":"Peacock's tail is a small fan-shaped brown seaweed of warm rock pools, banded with white lime and shimmering blue-green."},"peales-dolphin":{"id":"peales-dolphin","name":"Peale's dolphin","aliases":["black-chinned dolphin","Lagenorhynchus australis"],"kind":"creature","group":"dolphins","fact":"Peale's dolphin lives among the kelp beds and channels of Patagonia and the Falkland Islands and is named after artist Titian Peale."},"pearlfish":{"id":"pearlfish","name":"Pearlfish","aliases":["Carapidae"],"kind":"creature","group":"fish","fact":"The pearlfish spends the day hiding inside the body of a sea cucumber, slipping in tail-first through its anus."},"pearly-razorfish":{"id":"pearly-razorfish","name":"Pearly razorfish","aliases":["razorfish","cleaver wrasse","Xyrichtys novacula","razor wrasse"],"kind":"creature","group":"fish","fact":"The pearly razorfish is a wrasse with a blade-thin head that dives headfirst into sand in an instant to escape, and sleeps buried there."},"pedersons-cleaner-shrimp":{"id":"pedersons-cleaner-shrimp","name":"Pederson's cleaner shrimp","aliases":["Ancylomenes pedersoni","Periclimenes pedersoni","Pederson cleaner shrimp"],"kind":"creature","group":"crustaceans","fact":"Pederson's cleaner shrimp is see-through with violet spots and lives on Caribbean anemones, where it cleans parasites from visiting fish."},"pelagibacter":{"id":"pelagibacter","name":"Pelagibacter","aliases":["SAR11","Pelagibacter ubique"],"kind":"creature","group":"microbes","fact":"Pelagibacter ubique, from the SAR11 group, is probably the most abundant organism on Earth, a bacterium with hundreds of thousands in every millilitre of surface seawater."},"pelagic-stingray":{"id":"pelagic-stingray","name":"Pelagic stingray","aliases":["Pteroplatytrygon violacea"],"kind":"creature","group":"rays","fact":"The pelagic stingray is the only stingray that lives in the open ocean rather than on the seabed."},"pelagic-thresher":{"id":"pelagic-thresher","name":"Pelagic thresher","aliases":["pelagic thresher shark","Alopias pelagicus"],"kind":"creature","group":"sharks","fact":"Pelagic threshers rise to a reef cleaning station at Malapascua in the Philippines each dawn to have parasites picked off by cleaner wrasses."},"pelagos-sanctuary":{"id":"pelagos-sanctuary","name":"Pelagos Sanctuary","aliases":["Pelagos Sanctuary for Mediterranean Marine Mammals"],"kind":"place","group":"parks","fact":"The Pelagos Sanctuary is a marine mammal reserve between France, Monaco and Italy where fin whales and striped dolphins feed in the Ligurian Sea."},"pelican":{"id":"pelican","name":"Pelican","aliases":[],"kind":"creature","group":"seabirds","fact":"A pelican scoops fish in a throat pouch that can hold around 10 litres of water, which it drains before swallowing the catch."},"penguin":{"id":"penguin","name":"Penguin","aliases":[],"kind":"creature","group":"seabirds","fact":"Penguins have backward-pointing spines on the tongue and roof of the mouth that stop slippery krill and fish escaping as they swallow."},"pentland-firth":{"id":"pentland-firth","name":"Pentland Firth","aliases":[],"kind":"place","group":"straits","fact":"The Pentland Firth between mainland Scotland and Orkney has some of the fastest tidal currents in the world, used today to generate electricity."},"peppermint-angelfish":{"id":"peppermint-angelfish","name":"Peppermint angelfish","aliases":["Paracentropyge boylei","Centropyge boylei","Boyle's angelfish"],"kind":"creature","group":"fish","fact":"The peppermint angelfish, striped red and white, lives on deep reefs in the Cook Islands below 100 metres; one at Hawaii's Waikiki Aquarium drew offers of 30,000 dollars."},"peppermint-shrimp":{"id":"peppermint-shrimp","name":"Peppermint shrimp","aliases":["Lysmata wurdemanni"],"kind":"creature","group":"crustaceans","fact":"The peppermint shrimp is stocked in reef aquariums because it eats the pest anemone Aiptasia."},"periwinkle":{"id":"periwinkle","name":"Periwinkle","aliases":["common periwinkle","winkle","Littorina littorea","Littorina"],"kind":"creature","group":"molluscs","fact":"Periwinkles are small shore snails that seal themselves inside their shells with a trapdoor to survive hours out of water at low tide."},"permit":{"id":"permit","name":"Permit","aliases":["Trachinotus falcatus"],"kind":"creature","group":"fish","fact":"The permit is a wary, deep-bodied flats fish of the Caribbean that fly anglers consider among the hardest to catch."},"peru-chile-trench":{"id":"peru-chile-trench","name":"Peru-Chile Trench","aliases":["Atacama Trench","Chile Trench","Peru Trench","Richards Deep"],"kind":"place","group":"trenches","fact":"The Peru-Chile Trench, or Atacama Trench, runs about 5,900 kilometres along South America's Pacific coast and reaches about 8,000 metres deep."},"peruvian-anchoveta":{"id":"peruvian-anchoveta","name":"Peruvian anchoveta","aliases":["anchoveta","Engraulis ringens"],"kind":"creature","group":"fish","fact":"The Peruvian anchoveta is the most heavily fished species on Earth, with catches that have topped 10 million tonnes a year, nearly all ground into fishmeal."},"petrale-sole":{"id":"petrale-sole","name":"Petrale sole","aliases":["Eopsetta jordani"],"kind":"creature","group":"fish","fact":"The petrale sole, a right-eyed flounder of the US and Canadian Pacific coast, is one of the most prized flatfish caught there."},"petrel":{"id":"petrel","name":"Petrel","aliases":["storm petrel"],"kind":"creature","group":"seabirds","fact":"Petrels are tube-nosed seabirds with a keen sense of smell that pick fish, squid and krill from the water, and the giant petrels also scavenge."},"phaeocystis":{"id":"phaeocystis","name":"Phaeocystis","aliases":[],"kind":"plant","group":"plankton","fact":"Phaeocystis is a colony-forming alga whose spring blooms whip up thick brown foam on North Sea beaches."},"pharaoh-cuttlefish":{"id":"pharaoh-cuttlefish","name":"Pharaoh cuttlefish","aliases":["Sepia pharaonis"],"kind":"creature","group":"cephalopods","fact":"The pharaoh cuttlefish of the Indo-Pacific is one of the most heavily fished cuttlefish and is also bred in labs for research."},"philippe-cousteau":{"id":"philippe-cousteau","name":"Philippe Cousteau","aliases":[],"kind":"person","group":"people","fact":"Philippe Cousteau, Jacques Cousteau's younger son, filmed and co-produced many of his father's undersea documentaries before dying in a seaplane crash in 1979."},"philippine-sea":{"id":"philippine-sea","name":"Philippine Sea","aliases":[],"kind":"place","group":"seas","fact":"The Philippine Sea, east of the Philippines, is the largest sea in the world by area and contains the Mariana Trench."},"philippine-trench":{"id":"philippine-trench","name":"Philippine Trench","aliases":["Mindanao Trench","Mindanao Deep","Galathea Deep","Emden Deep"],"kind":"place","group":"trenches","fact":"The Philippine Trench off Mindanao reaches about 10,500 metres at the Emden Deep, named after the German cruiser that sounded it in 1927."},"philippines":{"id":"philippines","name":"Philippines","aliases":["Philippine Islands","Luzon","Mindanao"],"kind":"place","group":"islands","fact":"The Philippines is an archipelago of more than 7,000 islands between the South China Sea and the Pacific."},"phoenix-islands-protected-area":{"id":"phoenix-islands-protected-area","name":"Phoenix Islands Protected Area","aliases":["Phoenix Islands","PIPA"],"kind":"place","group":"parks","fact":"The Phoenix Islands Protected Area in Kiribati covers more than 400,000 square kilometres of the central Pacific around eight coral atolls."},"phronima":{"id":"phronima","name":"Phronima","aliases":["pram bug","Phronima sedentaria","barrel amphipod"],"kind":"creature","group":"crustaceans","fact":"Phronima is a transparent amphipod that hollows out a salp and lives inside the barrel, rearing its young there as it drifts."},"phytoplankton":{"id":"phytoplankton","name":"Phytoplankton","aliases":["algae","microalgae"],"kind":"plant","group":"plankton","fact":"Phytoplankton are the drifting microscopic algae and bacteria that produce roughly half of the oxygen in Earth's atmosphere."},"picasso-triggerfish":{"id":"picasso-triggerfish","name":"Picasso triggerfish","aliases":["lagoon triggerfish","blackbar triggerfish","Rhinecanthus aculeatus"],"kind":"creature","group":"fish","fact":"The Picasso triggerfish wears a pattern of blue, black and yellow stripes that looks painted on, and it drums by beating its pectoral fins against its swim bladder."},"pictus-catfish":{"id":"pictus-catfish","name":"Pictus catfish","aliases":["pictus cat","Pimelodus pictus"],"kind":"creature","group":"fish","fact":"The pictus catfish is a spotted, long-whiskered aquarium catfish from the Amazon and Orinoco whose barbels can be as long as its body."},"piglet-squid":{"id":"piglet-squid","name":"Piglet squid","aliases":["Helicocranchia pfefferi","Helicocranchia"],"kind":"creature","group":"cephalopods","fact":"The piglet squid is a see-through, balloon-shaped deep-sea squid whose tuft of arms above a snout-like funnel gives it a comical piggy face."},"pike-conger":{"id":"pike-conger","name":"Pike conger","aliases":["daggertooth pike conger","hamo","Muraenesox cinereus","pike eel"],"kind":"creature","group":"fish","fact":"The daggertooth pike conger is a fanged eel of Indo-Pacific coasts eaten in Japan as hamo, famously in Kyoto in summer."},"pillar-coral":{"id":"pillar-coral","name":"Pillar coral","aliases":["Dendrogyra cylindrus"],"kind":"creature","group":"corals","fact":"Pillar coral grows in tall columns up to about 3 metres high and, unlike most corals, extends its feeding polyps by day."},"pilot-fish":{"id":"pilot-fish","name":"Pilot fish","aliases":["pilotfish","Naucrates ductor"],"kind":"creature","group":"fish","fact":"Pilot fish swim alongside sharks, rays and turtles, feeding on scraps and parasites, and are rarely attacked by their hosts."},"pilot-whale":{"id":"pilot-whale","name":"Pilot whale","aliases":["Globicephala"],"kind":"creature","group":"dolphins","fact":"Pilot whales are large dolphins that travel in tight-knit pods and are prone to mass strandings on beaches."},"pincushion-starfish":{"id":"pincushion-starfish","name":"Pincushion starfish","aliases":["cushion star","pincushion star","Culcita"],"kind":"creature","group":"echinoderms","fact":"The pincushion starfish of Indo-Pacific reefs is so plump and rounded that its five arms are barely visible, making it look like a puffed-up pillow."},"pinecone-fish":{"id":"pinecone-fish","name":"Pinecone fish","aliases":["pineapplefish","Monocentris japonica","Monocentris","pineconefish"],"kind":"creature","group":"fish","fact":"The pinecone fish is armoured in big plated scales and carries glowing bacteria in two light organs on its lower jaw to lure prey at night."},"pinfish":{"id":"pinfish","name":"Pinfish","aliases":["Lagodon rhomboides"],"kind":"creature","group":"fish","fact":"The pinfish of the western Atlantic eats more and more seagrass as it grows, and is a common bait fish in Florida."},"pink-salmon":{"id":"pink-salmon","name":"Pink salmon","aliases":["humpback salmon","humpy","Oncorhynchus gorbuscha"],"kind":"creature","group":"fish","fact":"Pink salmon are the smallest and most abundant Pacific salmon and live on a strict two-year cycle, so odd-year and even-year runs never mix."},"pink-skunk-clownfish":{"id":"pink-skunk-clownfish","name":"Pink skunk clownfish","aliases":["skunk clownfish","skunk anemonefish","pink anemonefish","Amphiprion perideraion","pink skunk anemonefish"],"kind":"creature","group":"fish","fact":"The pink skunk clownfish is a pale pink anemonefish with a white stripe along its back, like a skunk, living in magnificent anemones."},"pink-vent-fish":{"id":"pink-vent-fish","name":"Pink vent fish","aliases":["Thermarces cerberus","vent eelpout","Thermarces","vent fish"],"kind":"creature","group":"fish","fact":"The pink vent fish is an eelpout found only at East Pacific vents, where it lies among the tube worms and eats limpets and amphipods."},"pink-whipray":{"id":"pink-whipray","name":"Pink whipray","aliases":["Pateobatis fai","Himantura fai"],"kind":"creature","group":"rays","fact":"The pink whipray is a large Indo-Pacific stingray that often rests in piles of several individuals on sandy lagoon floors."},"pipefish":{"id":"pipefish","name":"Pipefish","aliases":["pipe fish","Syngnathus"],"kind":"creature","group":"fish","fact":"Pipefish are straightened-out relatives of seahorses, and the males carry the eggs on their belly or in a brood pouch until they hatch."},"pipi":{"id":"pipi","name":"Pipi","aliases":["Paphies australis","Plebidonax deltoides"],"kind":"creature","group":"molluscs","fact":"Pipi are wedge-shaped surf clams dug from sandy beaches in Australia and New Zealand, traditionally found by twisting your feet into the wet sand."},"piraiba":{"id":"piraiba","name":"Piraíba","aliases":["lau-lau","goliath catfish","Brachyplatystoma filamentosum","kumakuma"],"kind":"creature","group":"fish","fact":"The piraíba is the giant catfish of the Amazon, reaching about 3 metres and more than 150 kilograms, the largest catfish in the Americas."},"piranha":{"id":"piranha","name":"Piranha","aliases":["red-bellied piranha","Pygocentrus","Pygocentrus nattereri"],"kind":"creature","group":"fish","fact":"Piranhas bark, drum and croak by vibrating their swim bladder, with different sounds for warning, confronting and snapping at rivals."},"pistol-shrimp":{"id":"pistol-shrimp","name":"Pistol shrimp","aliases":["snapping shrimp","Alpheus","alpheid shrimp"],"kind":"creature","group":"crustaceans","fact":"A pistol shrimp snaps its claw shut so fast it creates a collapsing bubble that briefly approaches the temperature of the Sun's surface and stuns prey."},"pitcairn-islands":{"id":"pitcairn-islands","name":"Pitcairn Islands","aliases":["Pitcairn","Pitcairn Island"],"kind":"place","group":"islands","fact":"Pitcairn Island was settled in 1790 by the mutineers of HMS Bounty and remains one of the least populated territories on Earth."},"placoderm":{"id":"placoderm","name":"Placoderm","aliases":[],"kind":"creature","group":"fish","fact":"Placoderms, the first jawed fish, wore bony armour on their heads and vanished entirely about 360 million years ago."},"plaice":{"id":"plaice","name":"Plaice","aliases":["European plaice","Pleuronectes platessa"],"kind":"creature","group":"fish","fact":"Plaice are easy to recognise by the bright orange spots scattered across their brown upper side."},"plain-bonito":{"id":"plain-bonito","name":"Plain bonito","aliases":["Orcynopsis unicolor"],"kind":"creature","group":"fish","fact":"The plain bonito is an unstriped, deep-bodied bonito of the eastern Atlantic and Mediterranean."},"plankton":{"id":"plankton","name":"Plankton","aliases":["plankter"],"kind":"creature","group":"plankton","fact":"Plankton means 'wanderer' in Greek: it is every organism, from bacteria to jellyfish, that cannot swim against the current."},"platy":{"id":"platy","name":"Platy","aliases":["southern platyfish","Xiphophorus maculatus"],"kind":"creature","group":"fish","fact":"The platy is a small Mexican livebearer bred into dozens of colour forms and recommended for every beginner's tank."},"platypus":{"id":"platypus","name":"Platypus","aliases":["duck-billed platypus","Ornithorhynchus anatinus"],"kind":"creature","group":"mammals","fact":"The platypus hunts with its eyes, ears and nostrils closed, finding prey entirely with about 40,000 electric sensors in its rubbery bill."},"pleco":{"id":"pleco","name":"Pleco","aliases":["plecostomus","common pleco","suckermouth catfish","Hypostomus plecostomus","plec"],"kind":"creature","group":"fish","fact":"Plecos gulp air at the surface and absorb the oxygen through their stomach lining when the water runs low in oxygen."},"plesiosaur":{"id":"plesiosaur","name":"Plesiosaur","aliases":["plesiosaurus"],"kind":"creature","group":"reptiles","fact":"Plesiosaurs were long-necked marine reptiles that flew through the water on four flippers and vanished with the dinosaurs 66 million years ago."},"pliosaur":{"id":"pliosaur","name":"Pliosaur","aliases":["pliosaurus"],"kind":"creature","group":"reptiles","fact":"Pliosaurs were short-necked, huge-headed marine reptiles whose bite was among the most powerful of any animal that ever lived."},"plumose-anemone":{"id":"plumose-anemone","name":"Plumose anemone","aliases":["Metridium senile","frilled anemone"],"kind":"creature","group":"cnidarians","fact":"The plumose anemone is a tall white or orange anemone with a feathery crown of hundreds of fine tentacles, common on wrecks and pier legs."},"pocket-shark":{"id":"pocket-shark","name":"Pocket shark","aliases":["American pocket shark","Mollisquama mississippiensis","Mollisquama"],"kind":"creature","group":"sharks","fact":"Only two pocket sharks have ever been found, and the tiny shark's pocket glands near its front fins are thought to squirt glowing fluid."},"polar-bear":{"id":"polar-bear","name":"Polar bear","aliases":["ice bear","white bear","nanook","Ursus maritimus"],"kind":"creature","group":"mammals","fact":"Polar bears are classed as marine mammals because they spend most of their lives on sea ice hunting seals, and they can swim for days."},"polarstern":{"id":"polarstern","name":"Polarstern","aliases":["RV Polarstern"],"kind":"vessel","group":"vessels","fact":"The German icebreaker Polarstern spent a year frozen into Arctic sea ice for the MOSAiC expedition of 2019 to 2020, the largest polar research expedition ever mounted."},"pollack":{"id":"pollack","name":"Pollack","aliases":["European pollock","Pollachius pollachius","lythe"],"kind":"creature","group":"fish","fact":"The pollack is a golden-brown European cousin of cod with a jutting lower jaw, popular with sea anglers around rocky coasts and wrecks."},"pollock":{"id":"pollock","name":"Pollock","aliases":["pollack","saithe","coley","Pollachius"],"kind":"creature","group":"fish","fact":"Pollock, a cod relative, produce thumping sounds with their swim bladder when handled or cornered, a trait shared with cod and haddock, which grunt during spawning."},"pom-pom-crab":{"id":"pom-pom-crab","name":"Pom-pom crab","aliases":["boxer crab","Lybia","Lybia tessellata","cheerleader crab"],"kind":"creature","group":"crustaceans","fact":"The pom-pom crab holds a live sea anemone in each claw and waves them like boxing gloves; if it loses one it tears the other in half to grow a new pair."},"pompeii-worm":{"id":"pompeii-worm","name":"Pompeii worm","aliases":["Alvinella pompejana","Alvinella"],"kind":"creature","group":"worms","fact":"The Pompeii worm lives in tubes on vent chimneys with its tail in water of around 80 degrees Celsius, making it one of the most heat-tolerant animals known."},"ponta-delgada":{"id":"ponta-delgada","name":"Ponta Delgada","aliases":[],"kind":"place","group":"ports","fact":"Ponta Delgada, the largest city of the Azores, sits on the island of São Miguel in the middle of the North Atlantic."},"pontohs-pygmy-seahorse":{"id":"pontohs-pygmy-seahorse","name":"Pontoh's pygmy seahorse","aliases":["Hippocampus pontohi","Pontoh's seahorse","weedy pygmy seahorse"],"kind":"creature","group":"fish","fact":"Pontoh's pygmy seahorse is a free-living pygmy seahorse of about 1.7 centimetres that clings to algae and hydroids rather than sea fans."},"ponyfish":{"id":"ponyfish","name":"Ponyfish","aliases":["Leiognathidae","slipmouth","pony fish"],"kind":"creature","group":"fish","fact":"Ponyfish keep glowing bacteria in a ring-shaped organ around the throat and shine the light out through transparent windows in their bellies."},"poor-cod":{"id":"poor-cod","name":"Poor cod","aliases":["Trisopterus minutus"],"kind":"creature","group":"fish","fact":"The poor cod is a small, coppery cod relative of European coasts, too small to be worth eating but important food for larger fish."},"poor-knights-islands":{"id":"poor-knights-islands","name":"Poor Knights Islands","aliases":["Poor Knights","Poor Knights Islands Marine Reserve"],"kind":"place","group":"parks","fact":"The Poor Knights Islands off New Zealand's North Island are a marine reserve that Jacques Cousteau rated among the best dive sites in the world."},"porbeagle":{"id":"porbeagle","name":"Porbeagle","aliases":["porbeagle shark","Lamna nasus"],"kind":"creature","group":"sharks","fact":"The porbeagle, a cold-water cousin of the great white, keeps its muscles warm and ranges as far north as Iceland and Norway."},"porcelain-crab":{"id":"porcelain-crab","name":"Porcelain crab","aliases":["Porcellanidae"],"kind":"creature","group":"crustaceans","fact":"Porcelain crabs are flat, fragile crab-like animals that filter plankton with feathery mouthparts and readily drop a leg to escape."},"porcupine-bank":{"id":"porcupine-bank","name":"Porcupine Bank","aliases":[],"kind":"place","group":"features","fact":"Porcupine Bank, west of Ireland, is a raised area of seabed named after HMS Porcupine, the survey ship that charted it in the 1860s."},"porcupine-ray":{"id":"porcupine-ray","name":"Porcupine ray","aliases":["Urogymnus asperrimus"],"kind":"creature","group":"rays","fact":"The porcupine ray has no stinging spine at all; instead its back is covered in sharp thorns."},"porcupinefish":{"id":"porcupinefish","name":"Porcupinefish","aliases":["porcupine fish","Diodon","balloonfish","spiny puffer","porcupine puffer","Diodon holocanthus"],"kind":"creature","group":"fish","fact":"The porcupinefish inflates into a spiky ball when threatened, and its skin and organs carry tetrodotoxin, so it is poisonous to eat."},"porites":{"id":"porites","name":"Porites","aliases":["Porites coral"],"kind":"creature","group":"corals","fact":"Porites corals grow in massive domes so slowly and steadily that scientists drill cores from them to read centuries of ocean climate."},"porkfish":{"id":"porkfish","name":"Porkfish","aliases":["Anisotremus virginicus"],"kind":"creature","group":"fish","fact":"The porkfish, a yellow-striped grunt with two black bars on its head, schools under Caribbean ledges by day and feeds at night."},"porpoise":{"id":"porpoise","name":"Porpoise","aliases":[],"kind":"creature","group":"dolphins","fact":"Porpoises are small toothed whales with spade-shaped teeth and blunt snouts, unlike the cone-shaped teeth and beaks of dolphins."},"port-jackson-shark":{"id":"port-jackson-shark","name":"Port Jackson shark","aliases":["Heterodontus portusjacksoni"],"kind":"creature","group":"sharks","fact":"Port Jackson sharks lay spiral-shaped eggs that the mother wedges into rock crevices."},"porto":{"id":"porto","name":"Porto","aliases":["Oporto"],"kind":"place","group":"ports","fact":"Porto, at the mouth of the Douro river, gave its name both to Portugal and to port wine."},"portuguese-dogfish":{"id":"portuguese-dogfish","name":"Portuguese dogfish","aliases":["Portuguese shark","Centroscymnus coelolepis"],"kind":"creature","group":"sharks","fact":"The Portuguese dogfish has been caught at nearly 3,700 metres, deeper than any other shark known."},"portuguese-man-o-war":{"id":"portuguese-man-o-war","name":"Portuguese man o' war","aliases":["man o' war","man-of-war","bluebottle","Physalia physalis","Portuguese man of war","Physalia","floating terror"],"kind":"creature","group":"jellies","fact":"The Portuguese man o' war is not a jellyfish but a colony of specialised animals under a gas-filled sail, trailing tentacles that can reach 30 metres."},"potato-cod":{"id":"potato-cod","name":"Potato cod","aliases":["potato grouper","potato bass","Epinephelus tukula","potato rockcod"],"kind":"creature","group":"fish","fact":"The potato cod is a grouper of the Indo-Pacific covered in large dark blotches like potatoes; the tame giants of the Cod Hole on the Great Barrier Reef are famous among divers."},"potters-angelfish":{"id":"potters-angelfish","name":"Potter's angelfish","aliases":["Potter's angel","Centropyge potteri","russet angelfish"],"kind":"creature","group":"fish","fact":"Potter's angelfish is a dwarf angelfish found only in Hawaii, orange with blue-black scribbles."},"pouting":{"id":"pouting","name":"Pouting","aliases":["bib","pout","Trisopterus luscus"],"kind":"creature","group":"fish","fact":"The pouting, or bib, is a small, deep-bodied cod relative with coppery bands, common around piers and wrecks in European waters."},"powder-blue-tang":{"id":"powder-blue-tang","name":"Powder blue tang","aliases":["powder blue surgeonfish","Acanthurus leucosternon"],"kind":"creature","group":"fish","fact":"The powder blue tang is a pale blue surgeonfish with a black face and yellow dorsal fin, found on Indian Ocean reefs, often in large grazing schools."},"prawn":{"id":"prawn","name":"Prawn","aliases":["king prawn"],"kind":"creature","group":"crustaceans","fact":"Prawn and shrimp are not scientific terms: Britain and Australia mostly say prawn and North America mostly says shrimp for the same animals."},"predatory-tunicate":{"id":"predatory-tunicate","name":"Predatory tunicate","aliases":["Megalodicopia hians","carnivorous sea squirt"],"kind":"creature","group":"tunicates","fact":"The predatory tunicate is a sea squirt anchored in deep-sea canyons that holds its hood open like a Venus flytrap and snaps it shut on passing animals."},"priapulid-worm":{"id":"priapulid-worm","name":"Priapulid worm","aliases":["penis worm","priapulid","Priapulida"],"kind":"creature","group":"worms","fact":"Priapulid worms burrow in cold seafloor mud and look much as their relatives did in the Cambrian, more than 500 million years ago."},"prickly-shark":{"id":"prickly-shark","name":"Prickly shark","aliases":["Echinorhinus cookei"],"kind":"creature","group":"sharks","fact":"The prickly shark is a bulky Pacific relative of the bramble shark, covered in thorn-like scales, and lives on deep slopes."},"prince-albert-i-of-monaco":{"id":"prince-albert-i-of-monaco","name":"Prince Albert I of Monaco","aliases":["Albert I of Monaco","Prince Albert I"],"kind":"person","group":"people","fact":"Prince Albert I of Monaco spent his fortune on oceanographic cruises in the 1880s and 1890s and founded the Oceanographic Museum of Monaco."},"princess-parrotfish":{"id":"princess-parrotfish","name":"Princess parrotfish","aliases":["Scarus taeniopterus"],"kind":"creature","group":"fish","fact":"The princess parrotfish is a Caribbean parrotfish whose males are blue-green with pink stripes, and it grazes in mixed schools over the reef."},"proboscis-monkey":{"id":"proboscis-monkey","name":"Proboscis monkey","aliases":["Nasalis larvatus"],"kind":"creature","group":"mammals","fact":"The proboscis monkey lives only in Borneo's mangrove and riverside forests, swims well with partly webbed feet, and the male's huge nose amplifies its calls."},"prochlorococcus":{"id":"prochlorococcus","name":"Prochlorococcus","aliases":["Prochlorococcus marinus"],"kind":"creature","group":"microbes","fact":"Prochlorococcus is the most abundant photosynthetic organism on Earth, yet this tiny ocean bacterium was not discovered until 1986."},"puerto-rico":{"id":"puerto-rico","name":"Puerto Rico","aliases":[],"kind":"place","group":"islands","fact":"Puerto Rico lies at the eastern end of the Greater Antilles, and just north of it the Puerto Rico Trench drops to the deepest point in the Atlantic."},"puerto-rico-trench":{"id":"puerto-rico-trench","name":"Puerto Rico Trench","aliases":["Milwaukee Deep","Puerto Rico"],"kind":"place","group":"trenches","fact":"The Puerto Rico Trench is the deepest point in the Atlantic Ocean, reaching about 8,400 metres at the Milwaukee Deep."},"puffadder-shyshark":{"id":"puffadder-shyshark","name":"Puffadder shyshark","aliases":["happy Eddie","Haploblepharus edwardsii"],"kind":"creature","group":"sharks","fact":"The puffadder shyshark of South African kelp forests curls into a ring and covers its eyes with its tail when threatened, hence the name shyshark."},"pufferfish":{"id":"pufferfish","name":"Pufferfish","aliases":["puffer","fugu","blowfish","Tetraodontidae","globefish","swellfish"],"kind":"creature","group":"fish","fact":"Pufferfish carry tetrodotoxin, a poison with no antidote that is about 1,200 times deadlier than cyanide, yet fugu is a Japanese delicacy."},"puget-sound":{"id":"puget-sound","name":"Puget Sound","aliases":[],"kind":"place","group":"bays","fact":"Puget Sound is a deep, glacier-carved inlet of the Pacific in Washington state, named by George Vancouver after his lieutenant Peter Puget, with Seattle on its shore."},"pumpkinseed":{"id":"pumpkinseed","name":"Pumpkinseed","aliases":["pumpkinseed sunfish","Lepomis gibbosus"],"kind":"creature","group":"fish","fact":"The pumpkinseed sunfish is a brightly coloured pond fish of North America that has become invasive across Europe."},"purple-sea-urchin":{"id":"purple-sea-urchin","name":"Purple sea urchin","aliases":["Strongylocentrotus purpuratus"],"kind":"creature","group":"echinoderms","fact":"Purple sea urchins can bore shallow pits into solid rock and, left unchecked, can mow down whole kelp forests."},"purse-seiner":{"id":"purse-seiner","name":"Purse seiner","aliases":["seiner","purse seine boat","seine boat","tuna seiner"],"kind":"vessel","group":"boats","fact":"A purse seiner surrounds a school of fish with a long wall of net, then draws the bottom closed like a purse; most tuna and sardines are caught this way."},"puysegur-trench":{"id":"puysegur-trench","name":"Puysegur Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Puysegur Trench off the south-west tip of New Zealand is where the Australian Plate begins to slide beneath the Pacific Plate."},"pygmy-corydoras":{"id":"pygmy-corydoras","name":"Pygmy corydoras","aliases":["pygmy cory","Corydoras pygmaeus"],"kind":"creature","group":"fish","fact":"The pygmy corydoras is a 2.5-centimetre armoured catfish from Brazil that, unlike its relatives, swims in mid-water in shoals."},"pygmy-killer-whale":{"id":"pygmy-killer-whale","name":"Pygmy killer whale","aliases":["Feresa attenuata"],"kind":"creature","group":"dolphins","fact":"The pygmy killer whale is a small, little-known dark dolphin of tropical seas that was known only from two skulls until the 1950s."},"pygmy-right-whale":{"id":"pygmy-right-whale","name":"Pygmy right whale","aliases":["Caperea marginata"],"kind":"creature","group":"whales","fact":"The pygmy right whale is the smallest and least-known baleen whale, rarely seen alive in the cool waters of the Southern Hemisphere."},"pygmy-seahorse":{"id":"pygmy-seahorse","name":"Pygmy seahorse","aliases":["pygmy sea horse"],"kind":"creature","group":"fish","fact":"Pygmy seahorses are mostly under 2.5 centimetres long and so well camouflaged on sea fans and corals that the first was found only when its host fan was collected."},"pygmy-sperm-whale":{"id":"pygmy-sperm-whale","name":"Pygmy sperm whale","aliases":["Kogia breviceps"],"kind":"creature","group":"whales","fact":"The pygmy sperm whale squirts a cloud of reddish-brown fluid to confuse predators, much as a squid uses ink."},"pygmy-squid":{"id":"pygmy-squid","name":"Pygmy squid","aliases":["Idiosepius","Idiosepius pygmaeus","two-toned pygmy squid"],"kind":"creature","group":"cephalopods","fact":"Pygmy squid are among the smallest cephalopods, about the size of a fingernail, and glue themselves to seagrass blades with a sticky patch on their back."},"pygmy-sunfish":{"id":"pygmy-sunfish","name":"Pygmy sunfish","aliases":["Elassoma","Elassomatidae","banded pygmy sunfish","Everglades pygmy sunfish"],"kind":"creature","group":"fish","fact":"Pygmy sunfishes of the southeastern United States are 2-to-3-centimetre swamp fish, not true sunfish, that flash iridescent blue when breeding."},"pyjama-shark":{"id":"pyjama-shark","name":"Pyjama shark","aliases":["pyjama catshark","striped catshark","pajama shark","Poroderma africanum"],"kind":"creature","group":"sharks","fact":"The pyjama shark, a striped catshark of South African kelp forests, starred in the film My Octopus Teacher and hunts at night."},"pyrosome":{"id":"pyrosome","name":"Pyrosome","aliases":["fire body","Pyrosoma","sea pickle","unicorn of the sea","giant pyrosome","Pyrosoma spinosum"],"kind":"creature","group":"plankton","fact":"A pyrosome is a hollow tube of thousands of cloned tunicates that glows blue-green, and some grow longer than a bus."},"quagga-mussel":{"id":"quagga-mussel","name":"Quagga mussel","aliases":["Dreissena bugensis"],"kind":"creature","group":"molluscs","fact":"The quagga mussel followed the zebra mussel into the Great Lakes and has largely replaced it, carpeting the lake beds in their trillions."},"quahog":{"id":"quahog","name":"Quahog","aliases":["hard clam","hard-shell clam","Mercenaria mercenaria","littleneck","cherrystone","northern quahog","chowder clam"],"kind":"creature","group":"molluscs","fact":"The quahog is the hard clam of New England chowder, and its cousin the ocean quahog, dredged off Iceland, lived to 507 years, the oldest animal ever aged."},"queen-angelfish":{"id":"queen-angelfish","name":"Queen angelfish","aliases":["Holacanthus ciliaris"],"kind":"creature","group":"fish","fact":"The queen angelfish of the Caribbean wears a blue 'crown' ringed with spots on its forehead and feeds mostly on sponges."},"queen-annes-revenge":{"id":"queen-annes-revenge","name":"Queen Anne's Revenge","aliases":[],"kind":"vessel","group":"wrecks","fact":"Blackbeard's flagship Queen Anne's Revenge ran aground and was lost off Beaufort, North Carolina, in 1718; its wreck was found in 1996."},"queen-parrotfish":{"id":"queen-parrotfish","name":"Queen parrotfish","aliases":["Scarus vetula"],"kind":"creature","group":"fish","fact":"The queen parrotfish of the Caribbean sleeps at night inside a cocoon of mucus that it secretes, which may hide its scent from predators."},"queen-triggerfish":{"id":"queen-triggerfish","name":"Queen triggerfish","aliases":["Balistes vetula","old wife"],"kind":"creature","group":"fish","fact":"The queen triggerfish of the Caribbean and tropical Atlantic blows jets of water to flip sea urchins over and eat their soft undersides."},"rabbitfish":{"id":"rabbitfish","name":"Rabbitfish","aliases":["spinefoot","Siganidae","Siganus","dusky spinefoot","marbled spinefoot","rabbit fish"],"kind":"creature","group":"fish","fact":"Rabbitfish are harmless-looking reef grazers with venomous spines in their fins that cause an agonising sting if handled."},"raccoon-butterflyfish":{"id":"raccoon-butterflyfish","name":"Raccoon butterflyfish","aliases":["raccoon butterfly","Chaetodon lunula","crescent-masked butterflyfish"],"kind":"creature","group":"fish","fact":"The raccoon butterflyfish has a black mask across its eyes like a raccoon and feeds at night on coral polyps and small animals."},"rachel-carson":{"id":"rachel-carson","name":"Rachel Carson","aliases":[],"kind":"person","group":"people","fact":"Rachel Carson was a marine biologist whose book The Sea Around Us, published in 1951, introduced millions of readers to the science of the oceans."},"radiolarian":{"id":"radiolarian","name":"Radiolarian","aliases":["Radiolaria"],"kind":"creature","group":"plankton","fact":"Radiolarians are single-celled plankton with intricate glassy skeletons of silica, so beautiful that Ernst Haeckel drew hundreds of them in the 1800s."},"rainbow-parrotfish":{"id":"rainbow-parrotfish","name":"Rainbow parrotfish","aliases":["Scarus guacamaia"],"kind":"creature","group":"fish","fact":"The rainbow parrotfish is the largest parrotfish in the Atlantic, up to about 1.2 metres, with a coppery body and green fins, and its young grow up in mangroves."},"rainbow-smelt":{"id":"rainbow-smelt","name":"Rainbow smelt","aliases":["smelt","Osmerus mordax"],"kind":"creature","group":"fish","fact":"Rainbow smelt live in coastal seas and run up rivers to spawn in early spring, and freshly caught smelt smell faintly of cucumber."},"rainbow-trout":{"id":"rainbow-trout","name":"Rainbow trout","aliases":["steelhead","steelhead trout","Oncorhynchus mykiss","trout"],"kind":"creature","group":"fish","fact":"Rainbow trout that migrate to sea are called steelhead; they return silver and powerful to spawn in their home rivers and can spawn more than once."},"rainbow-warrior":{"id":"rainbow-warrior","name":"Rainbow Warrior","aliases":[],"kind":"vessel","group":"wrecks","fact":"The Greenpeace ship Rainbow Warrior was sunk by bombs planted by French agents in Auckland harbour in 1985."},"rainbowfish":{"id":"rainbowfish","name":"Rainbowfish","aliases":["Melanotaeniidae","Boeseman's rainbowfish"],"kind":"creature","group":"fish","fact":"Rainbowfish from New Guinea and Australia shimmer with shifting colours and are among the most peaceful community aquarium fish."},"raja-ampat":{"id":"raja-ampat","name":"Raja Ampat","aliases":["Raja Ampat Islands","Four Kings"],"kind":"place","group":"reefs","fact":"The reefs of Raja Ampat in Indonesia hold more coral and reef-fish species than almost anywhere else on Earth, at the heart of the Coral Triangle."},"ram-cichlid":{"id":"ram-cichlid","name":"Ram cichlid","aliases":["German blue ram","blue ram","Mikrogeophagus ramirezi"],"kind":"creature","group":"fish","fact":"The ram cichlid is a small, brilliantly coloured dwarf cichlid from Venezuelan and Colombian streams that pairs up to guard its eggs."},"ramaris-beaked-whale":{"id":"ramaris-beaked-whale","name":"Ramari's beaked whale","aliases":["Mesoplodon eueu"],"kind":"creature","group":"whales","fact":"Ramari's beaked whale, described in 2021, is named after Māori whale expert Ramari Stewart, the first cetacean named after an indigenous woman."},"rams-horn-squid":{"id":"rams-horn-squid","name":"Ram's horn squid","aliases":["spirula","little post horn squid","Spirula spirula"],"kind":"creature","group":"cephalopods","fact":"The ram's horn squid carries a coiled, chambered shell inside its body, and the little white shells wash up on beaches worldwide."},"rangiroa":{"id":"rangiroa","name":"Rangiroa","aliases":["Rangiroa Atoll"],"kind":"place","group":"reefs","fact":"Rangiroa in French Polynesia is one of the largest atolls in the world, with a lagoon so big that the whole island of Tahiti would fit inside it."},"ras-mohammed-national-park":{"id":"ras-mohammed-national-park","name":"Ras Mohammed National Park","aliases":["Ras Mohammed","Ras Muhammad"],"kind":"place","group":"parks","fact":"Ras Mohammed, Egypt's first national park, sits at the tip of the Sinai where the Red Sea's Shark Reef and Yolanda Reef draw divers from around the world."},"razor-clam":{"id":"razor-clam","name":"Razor clam","aliases":["razor shell","razorfish","Ensis","Pacific razor clam"],"kind":"creature","group":"molluscs","fact":"Razor clams can dig down through wet sand faster than a person can dig, which is why collectors sprinkle salt to make them pop up."},"razor-surgeonfish":{"id":"razor-surgeonfish","name":"Razor surgeonfish","aliases":["yellowtail surgeonfish","Prionurus laticlavius"],"kind":"creature","group":"fish","fact":"The razor surgeonfish grazes the rocky shores of the Galápagos in huge grey schools with bright yellow tails."},"razorbill":{"id":"razorbill","name":"Razorbill","aliases":["Alca torda"],"kind":"creature","group":"seabirds","fact":"The razorbill is the closest living relative of the extinct great auk and chases fish underwater using its wings."},"red-bass":{"id":"red-bass","name":"Red bass","aliases":["two-spot red snapper","twinspot snapper","Lutjanus bohar","bohar snapper","bohar"],"kind":"creature","group":"fish","fact":"The red bass is a big reef snapper that so often carries ciguatera poison that it is a no-take species in Queensland, banned from being kept or sold."},"red-cod":{"id":"red-cod","name":"Red cod","aliases":["Pseudophycis bachus","hoka"],"kind":"creature","group":"fish","fact":"The red cod of New Zealand is a morid cod, a distant relative of the Atlantic cod, with a single chin barbel and pinkish skin."},"red-coral":{"id":"red-coral","name":"Red coral","aliases":["precious coral","precious red coral","Mediterranean red coral","Corallium rubrum"],"kind":"creature","group":"corals","fact":"Red coral from the Mediterranean has been harvested for jewellery for thousands of years and grows only a few millimetres a year."},"red-drum":{"id":"red-drum","name":"Red drum","aliases":["redfish","channel bass","Sciaenops ocellatus","red fish"],"kind":"creature","group":"fish","fact":"The red drum, or redfish, is farmed in ponds and cages in Texas and China after blackened redfish made the wild fish a craze in the 1980s."},"red-eared-slider":{"id":"red-eared-slider","name":"Red-eared slider","aliases":["red-eared terrapin","Trachemys scripta elegans"],"kind":"creature","group":"reptiles","fact":"The red-eared slider, the pet-shop turtle, has been dumped into ponds worldwide and is now one of the most widespread invasive reptiles."},"red-grouper":{"id":"red-grouper","name":"Red grouper","aliases":["Epinephelus morio"],"kind":"creature","group":"fish","fact":"The red grouper of the Gulf of Mexico digs and maintains pits in the seabed that become homes for many other reef animals."},"red-gurnard":{"id":"red-gurnard","name":"Red gurnard","aliases":["Chelidonichthys cuculus"],"kind":"creature","group":"fish","fact":"The red gurnard walks over the North Sea floor on finger-like fin rays and grunts audibly when caught."},"red-hind":{"id":"red-hind","name":"Red hind","aliases":["Epinephelus guttatus"],"kind":"creature","group":"fish","fact":"The red hind is a small Caribbean grouper with red spots that gathers to spawn at traditional sites and is a staple catch in the Virgin Islands."},"red-lipped-batfish":{"id":"red-lipped-batfish","name":"Red-lipped batfish","aliases":["Galápagos batfish","Ogcocephalus darwini"],"kind":"creature","group":"fish","fact":"The red-lipped batfish of the Galápagos is a poor swimmer and instead walks across the seabed on its stiff, limb-like fins."},"red-mangrove":{"id":"red-mangrove","name":"Red mangrove","aliases":["Rhizophora mangle","Rhizophora"],"kind":"plant","group":"plants","fact":"The red mangrove stands on arching prop roots and drops long, pencil-shaped seedlings that float away to take root on other shores."},"red-mullet":{"id":"red-mullet","name":"Red mullet","aliases":["surmullet","rouget","Mullus","Mullus surmuletus"],"kind":"creature","group":"fish","fact":"Red mullet feel for prey with two chin barbels, and the ancient Romans paid fortunes for large ones and watched them change colour as they died."},"red-rock-crab":{"id":"red-rock-crab","name":"Red rock crab","aliases":["Cancer productus"],"kind":"creature","group":"crustaceans","fact":"The red rock crab of the Pacific Northwest has big black-tipped claws strong enough to crush barnacles and snails."},"red-scorpionfish":{"id":"red-scorpionfish","name":"Red scorpionfish","aliases":["rascasse","large-scaled scorpionfish","Scorpaena scrofa"],"kind":"creature","group":"fish","fact":"The red scorpionfish, the rascasse, has venomous spines and is the essential fish of a true Marseille bouillabaisse."},"red-sea-bannerfish":{"id":"red-sea-bannerfish","name":"Red Sea bannerfish","aliases":["Heniochus intermedius"],"kind":"creature","group":"fish","fact":"The Red Sea bannerfish trails a long white dorsal filament like a pennant and lives only in the Red Sea and Gulf of Aden."},"red-sea-bream":{"id":"red-sea-bream","name":"Red sea bream","aliases":["tai","madai","Pagrus major","Japanese sea bream"],"kind":"creature","group":"fish","fact":"Red sea bream, tai, is Japan's celebration fish, served as sashimi at weddings and New Year because its name sounds like 'medetai', meaning happy."},"red-sea-urchin":{"id":"red-sea-urchin","name":"Red sea urchin","aliases":["Mesocentrotus franciscanus","Strongylocentrotus franciscanus","giant red sea urchin"],"kind":"creature","group":"echinoderms","fact":"The red sea urchin of the Pacific coast can live for more than 100 years, and its roe is sold as uni in sushi restaurants."},"red-snapper":{"id":"red-snapper","name":"Red snapper","aliases":["northern red snapper","Lutjanus campechanus","American red snapper"],"kind":"creature","group":"fish","fact":"The northern red snapper of the Gulf of Mexico can live for over 50 years and is so popular that many cheaper fish are passed off as it in restaurants."},"red-swamp-crayfish":{"id":"red-swamp-crayfish","name":"Red swamp crayfish","aliases":["Louisiana crawfish","Procambarus clarkii","Louisiana crayfish","red swamp crawfish"],"kind":"creature","group":"crustaceans","fact":"The red swamp crayfish is the star of Louisiana crawfish boils and has spread as an invader to rivers and rice paddies across Europe, Africa and Asia."},"redtail-catfish":{"id":"redtail-catfish","name":"Redtail catfish","aliases":["red-tailed catfish","Phractocephalus hemioliopterus","pirarara"],"kind":"creature","group":"fish","fact":"The redtail catfish of the Amazon has a bright orange-red tail and grows well over a metre, a giant that aquarists often regret buying."},"redtoothed-triggerfish":{"id":"redtoothed-triggerfish","name":"Redtoothed triggerfish","aliases":["red-toothed triggerfish","Niger triggerfish","Odonus niger"],"kind":"creature","group":"fish","fact":"The redtoothed triggerfish is blue-black with red teeth and feeds on plankton in the water column above Indo-Pacific reefs."},"reef-manta-ray":{"id":"reef-manta-ray","name":"Reef manta ray","aliases":["reef manta","Mobula alfredi","Manta alfredi"],"kind":"creature","group":"rays","fact":"Reef mantas visit cleaning stations on coral reefs and can be told apart by the unique spot patterns on their bellies."},"reef-shark":{"id":"reef-shark","name":"Reef shark","aliases":[],"kind":"creature","group":"sharks","fact":"Reef sharks are the sleek, mostly harmless sharks that patrol coral reefs, and their numbers are a good sign of a healthy reef."},"reef-triggerfish":{"id":"reef-triggerfish","name":"Reef triggerfish","aliases":["humuhumunukunukuapuaa","humuhumu","wedge-tail triggerfish","rectangular triggerfish","Hawaiian triggerfish","Rhinecanthus rectangulus"],"kind":"creature","group":"fish","fact":"The reef triggerfish is Hawaii's state fish, with the famous Hawaiian name humuhumunukunukuāpuaʻa, meaning roughly 'triggerfish with a snout like a pig'."},"regal-angelfish":{"id":"regal-angelfish","name":"Regal angelfish","aliases":["royal angelfish","Pygoplites diacanthus"],"kind":"creature","group":"fish","fact":"The regal angelfish, striped in orange, white and blue, is a shy sponge-eater of Indo-Pacific reefs that is notoriously difficult to keep in aquariums."},"remora":{"id":"remora","name":"Remora","aliases":["suckerfish","sharksucker","shark sucker","Echeneidae"],"kind":"creature","group":"fish","fact":"Remoras hitch rides on sharks, whales, turtles and even ships using a suction disc on top of the head, eating scraps and parasites."},"revillagigedo-archipelago":{"id":"revillagigedo-archipelago","name":"Revillagigedo Archipelago","aliases":["Socorro","Socorro Island","Revillagigedo Islands","Revillagigedo National Park"],"kind":"place","group":"parks","fact":"The Revillagigedo Islands, often just called Socorro, are a Mexican national park where giant oceanic manta rays approach divers to be cleaned."},"rex-sole":{"id":"rex-sole","name":"Rex sole","aliases":["Glyptocephalus zachirus"],"kind":"creature","group":"fish","fact":"The rex sole is a slender, thin-bodied flatfish of the North Pacific with a very small mouth, usually fried whole on the bone."},"reykjanes-ridge":{"id":"reykjanes-ridge","name":"Reykjanes Ridge","aliases":[],"kind":"place","group":"features","fact":"The Reykjanes Ridge is the stretch of the Mid-Atlantic Ridge that runs south-west from Iceland, where the ridge actually rises above sea level."},"reykjavik":{"id":"reykjavik","name":"Reykjavik","aliases":[],"kind":"place","group":"ports","fact":"Reykjavik, the world's northernmost national capital, grew up around its harbour and Iceland's fishing fleet."},"ribbon-eel":{"id":"ribbon-eel","name":"Ribbon eel","aliases":["Rhinomuraena quaesita","leaf-nosed moray","bernis eel","ribbon moray","leaf-nosed moray eel","blue ribbon eel"],"kind":"creature","group":"fish","fact":"The ribbon eel lives in a burrow in sand or rubble and changes from black to blue to yellow as it turns from juvenile to male to female."},"ribbon-reefs":{"id":"ribbon-reefs","name":"Ribbon Reefs","aliases":["Ribbon Reef","Ribbon Reef Number 10"],"kind":"place","group":"reefs","fact":"The Ribbon Reefs are a chain of ten long, narrow reefs on the outer Great Barrier Reef, home to the famous Cod Hole dive site."},"ribbon-seal":{"id":"ribbon-seal","name":"Ribbon seal","aliases":["Histriophoca fasciata"],"kind":"creature","group":"seals","fact":"Ribbon seals have striking white bands around the neck and flippers and spend most of the year in the open Bering Sea and Sea of Okhotsk."},"ribbon-worm":{"id":"ribbon-worm","name":"Ribbon worm","aliases":["nemertean","bootlace worm"],"kind":"creature","group":"worms","fact":"Ribbon worms fire a sticky proboscis to catch prey, and some species regrow a complete worm from a small fragment."},"rices-whale":{"id":"rices-whale","name":"Rice's whale","aliases":["Gulf of Mexico whale","Balaenoptera ricei","Rice whale"],"kind":"creature","group":"whales","fact":"Rice's whale, named in 2021 after biologist Dale Rice, lives only in the Gulf of Mexico and numbers only around 50 animals."},"richelieu-rock":{"id":"richelieu-rock","name":"Richelieu Rock","aliases":[],"kind":"place","group":"divesites","fact":"Richelieu Rock, a horseshoe-shaped pinnacle in the Andaman Sea off Thailand, is prized for whale shark sightings and purple soft corals."},"ridgeia-tube-worm":{"id":"ridgeia-tube-worm","name":"Ridgeia tube worm","aliases":["Ridgeia piscesae","Ridgeia"],"kind":"creature","group":"worms","fact":"Ridgeia tube worms blanket the vents of the Juan de Fuca Ridge off Canada, growing tall and thin or short and fat depending on how hot their spot is."},"right-whale":{"id":"right-whale","name":"Right whale","aliases":["North Atlantic right whale","southern right whale","Eubalaena"],"kind":"creature","group":"whales","fact":"Right whales got their name from whalers because they were the 'right' whale to hunt: slow, rich in oil, and floating when dead."},"ringed-seal":{"id":"ringed-seal","name":"Ringed seal","aliases":["Pusa hispida","Baltic ringed seal"],"kind":"creature","group":"seals","fact":"Ringed seals are the smallest and most common Arctic seal, keeping breathing holes open in the ice with their claws, and are the polar bear's main prey."},"rio-de-janeiro":{"id":"rio-de-janeiro","name":"Rio de Janeiro","aliases":["Rio"],"kind":"place","group":"ports","fact":"Rio de Janeiro means 'River of January', the name given by Portuguese sailors who reached Guanabara Bay in January 1502."},"rissos-dolphin":{"id":"rissos-dolphin","name":"Risso's dolphin","aliases":["grampus","Grampus griseus"],"kind":"creature","group":"dolphins","fact":"Risso's dolphins are born dark grey and turn almost white with age as they accumulate scars from fights and squid."},"river-dolphin":{"id":"river-dolphin","name":"River dolphin","aliases":[],"kind":"creature","group":"dolphins","fact":"River dolphins have long slender beaks, tiny eyes and flexible necks suited to hunting in murky, cluttered water."},"roach":{"id":"roach","name":"Roach","aliases":["Rutilus rutilus"],"kind":"creature","group":"fish","fact":"The roach, with its red fins and silver body, is the fish most often caught by beginners in European rivers and canals."},"robben-island":{"id":"robben-island","name":"Robben Island","aliases":[],"kind":"place","group":"islands","fact":"Robben Island in Table Bay off Cape Town is where Nelson Mandela was imprisoned for 18 of his 27 years in jail."},"robert-ballard":{"id":"robert-ballard","name":"Robert Ballard","aliases":["Bob Ballard","Ballard"],"kind":"person","group":"people","fact":"Robert Ballard led the team that found the wreck of the Titanic in 1985 and also located the Bismarck and took part in the discovery of hydrothermal vents."},"rock-beauty":{"id":"rock-beauty","name":"Rock beauty","aliases":["Holacanthus tricolor","rock beauty angelfish"],"kind":"creature","group":"fish","fact":"The rock beauty is a Caribbean angelfish, yellow at the front and black behind, that feeds mainly on sponges."},"rock-cook":{"id":"rock-cook","name":"Rock cook","aliases":["Centrolabrus exoletus","rock cook wrasse","small-mouthed wrasse"],"kind":"creature","group":"fish","fact":"The rock cook is a small wrasse of European waters that cleans parasites from other fish, and is used to de-louse farmed salmon."},"rockall":{"id":"rockall","name":"Rockall","aliases":[],"kind":"place","group":"islands","fact":"Rockall is a lone granite rock about 20 metres high in the North Atlantic, west of Scotland, claimed by Britain and argued over for its fishing waters."},"rockall-bank":{"id":"rockall-bank","name":"Rockall Bank","aliases":["Rockall Plateau","Rockall"],"kind":"place","group":"features","fact":"Rockall Bank is a submerged plateau west of Scotland from which only the tiny granite islet of Rockall breaks the surface."},"rockfish":{"id":"rockfish","name":"Rockfish","aliases":["Sebastes","rock fish","Pacific rockfish","rock cod"],"kind":"creature","group":"fish","fact":"Rockfishes of the North Pacific are among the longest-lived fish; several species live well past 100 years, and the rougheye may reach 200."},"rockhopper-penguin":{"id":"rockhopper-penguin","name":"Rockhopper penguin","aliases":["southern rockhopper penguin","Eudyptes chrysocome","northern rockhopper penguin"],"kind":"creature","group":"seabirds","fact":"Rockhopper penguins hop up cliffs with both feet together and feed on krill, squid and small fish."},"rohu":{"id":"rohu","name":"Rohu","aliases":["Labeo rohita","rui"],"kind":"creature","group":"fish","fact":"Rohu is a carp of South Asian rivers, the most popular eating fish in Bangladesh and eastern India."},"roosterfish":{"id":"roosterfish","name":"Roosterfish","aliases":["pez gallo","Nematistius pectoralis"],"kind":"creature","group":"fish","fact":"The roosterfish of the eastern Pacific raises a comb of seven long dorsal spines and is caught from the beaches of Baja and Costa Rica."},"ropefish":{"id":"ropefish","name":"Ropefish","aliases":["reedfish","rope fish","snakefish","Erpetoichthys calabaricus"],"kind":"creature","group":"fish","fact":"The ropefish has lungs as well as gills and can survive for a while out of water, slithering along like a snake."},"roseate-spoonbill":{"id":"roseate-spoonbill","name":"Roseate spoonbill","aliases":["Platalea ajaja"],"kind":"creature","group":"birds","fact":"The roseate spoonbill sweeps its flat bill from side to side through estuary shallows, snapping it shut on shrimps and small fish."},"ross-sea":{"id":"ross-sea","name":"Ross Sea","aliases":[],"kind":"place","group":"seas","fact":"The Ross Sea is a deep bay of Antarctica named after James Clark Ross, who discovered it in 1841, and it is fringed by the Ross Ice Shelf, the largest in the world."},"ross-sea-marine-protected-area":{"id":"ross-sea-marine-protected-area","name":"Ross Sea Marine Protected Area","aliases":["Ross Sea","Ross Sea MPA"],"kind":"place","group":"parks","fact":"The Ross Sea Marine Protected Area in Antarctica, agreed in 2016, is among the largest protected areas on the planet and shelters Adélie penguins and toothfish."},"ross-seal":{"id":"ross-seal","name":"Ross seal","aliases":["Ommatophoca rossii"],"kind":"creature","group":"seals","fact":"The Ross seal is the least-known Antarctic seal, living deep in the pack ice and making eerie siren-like calls."},"rough-toothed-dolphin":{"id":"rough-toothed-dolphin","name":"Rough-toothed dolphin","aliases":["Steno bredanensis"],"kind":"creature","group":"dolphins","fact":"The rough-toothed dolphin has a sloping, reptile-like head with no crease between beak and forehead, and finely ridged teeth."},"rougheye-rockfish":{"id":"rougheye-rockfish","name":"Rougheye rockfish","aliases":["Sebastes aleutianus","blacktip rockfish"],"kind":"creature","group":"fish","fact":"The rougheye rockfish is one of the longest-lived fish known, with individuals aged at more than 200 years from the growth rings in their ear bones."},"roughtail-stingray":{"id":"roughtail-stingray","name":"Roughtail stingray","aliases":["Bathytoshia centroura","Dasyatis centroura"],"kind":"creature","group":"rays","fact":"The roughtail stingray is one of the largest whiptail stingrays in the Atlantic, over 2 metres across, with rows of thorns on its tail."},"round-goby":{"id":"round-goby","name":"Round goby","aliases":["Neogobius melanostomus"],"kind":"creature","group":"fish","fact":"The round goby from the Black and Caspian seas arrived in the Great Lakes in ballast water in 1990 and now numbers in the billions there and in the Baltic."},"round-herring":{"id":"round-herring","name":"Round herring","aliases":["Etrumeus","Etrumeus teres"],"kind":"creature","group":"fish","fact":"Round herrings are slim schooling fish of warm seas including the Gulf of Mexico, caught as bait and for fishmeal."},"round-sardinella":{"id":"round-sardinella","name":"Round sardinella","aliases":["Sardinella aurita","gilt sardine"],"kind":"creature","group":"fish","fact":"The round sardinella is a small schooling fish caught in huge numbers off West Africa, where it is a staple protein."},"round-stingray":{"id":"round-stingray","name":"Round stingray","aliases":["round ray","Haller's round ray","Urobatis halleri"],"kind":"creature","group":"rays","fact":"Round stingrays cause most of the stingray injuries on southern California beaches, which is why bathers do the 'stingray shuffle'."},"roundnose-grenadier":{"id":"roundnose-grenadier","name":"Roundnose grenadier","aliases":["Coryphaenoides rupestris","rock grenadier"],"kind":"creature","group":"fish","fact":"The roundnose grenadier is a deep-sea cod relative trawled at over 1,000 metres in the North Atlantic that can live for more than 50 years."},"rowley-shoals":{"id":"rowley-shoals","name":"Rowley Shoals","aliases":[],"kind":"place","group":"reefs","fact":"The Rowley Shoals are three atolls off north-west Australia that rise steeply from deep water and are famous for strong tidal currents and clear water."},"royal-gramma":{"id":"royal-gramma","name":"Royal gramma","aliases":["fairy basslet","Gramma loreto"],"kind":"creature","group":"fish","fact":"The royal gramma, or fairy basslet, is a purple-and-yellow Caribbean reef fish that often swims upside down beneath ledges."},"rrs-discovery":{"id":"rrs-discovery","name":"RRS Discovery","aliases":["Discovery"],"kind":"vessel","group":"vessels","fact":"The Discovery was built for Scott's first Antarctic expedition in 1901, and three later British research ships of the same name have continued its work."},"rrs-sir-david-attenborough":{"id":"rrs-sir-david-attenborough","name":"RRS Sir David Attenborough","aliases":["Sir David Attenborough"],"kind":"vessel","group":"vessels","fact":"The polar research ship RRS Sir David Attenborough got its name after a 2016 public vote overwhelmingly chose Boaty McBoatface, a name given to one of its robot submarines instead."},"ruby-sea-dragon":{"id":"ruby-sea-dragon","name":"Ruby sea dragon","aliases":["ruby seadragon","Phyllopteryx dewysea"],"kind":"creature","group":"fish","fact":"The ruby sea dragon, deep red and living below the reach of most divers off Western Australia, was named as a new species only in 2015 and first filmed alive in 2016."},"rudist":{"id":"rudist","name":"Rudist","aliases":[],"kind":"creature","group":"molluscs","fact":"Rudists were strange cone-shaped clams that built reefs in Cretaceous seas and died out along with the dinosaurs."},"ryukyu-trench":{"id":"ryukyu-trench","name":"Ryukyu Trench","aliases":["Nansei-Shoto Trench"],"kind":"place","group":"trenches","fact":"The Ryukyu Trench runs along the Ryukyu Islands between Japan and Taiwan and reaches about 7,500 metres deep."},"sabertooth-fish":{"id":"sabertooth-fish","name":"Sabertooth fish","aliases":["Evermannella","Coccorella","sabretooth fish","sabre-tooth fish"],"kind":"creature","group":"fish","fact":"Sabertooth fish are small deep-sea hunters with upward-looking eyes and fangs that stick out past the jaw."},"sable-island":{"id":"sable-island","name":"Sable Island","aliases":[],"kind":"place","group":"islands","fact":"Sable Island is a crescent of sand off Nova Scotia known as the Graveyard of the Atlantic for its hundreds of shipwrecks, and home to wild horses."},"sablefish":{"id":"sablefish","name":"Sablefish","aliases":["black cod","Anoplopoma fimbria","gindara","butterfish"],"kind":"creature","group":"fish","fact":"Sablefish, sold as black cod, is a buttery deep-water fish of the North Pacific, famous miso-marinated, and it can live for more than 90 years."},"saddleback-clownfish":{"id":"saddleback-clownfish","name":"Saddleback clownfish","aliases":["saddleback anemonefish","Amphiprion polymnus"],"kind":"creature","group":"fish","fact":"The saddleback clownfish has a white saddle on its back rather than a full bar, and lives in anemones on open sand rather than on the reef."},"saddled-toby":{"id":"saddled-toby","name":"Saddled toby","aliases":["Valentini puffer","black-saddled toby","Canthigaster valentini"],"kind":"creature","group":"fish","fact":"The saddled toby is so poisonous that the harmless mimic filefish has evolved to copy its black saddles and colours almost exactly."},"sailboat":{"id":"sailboat","name":"Sailboat","aliases":["sailing boat","sail boat"],"kind":"vessel","group":"boats","fact":"Sailboats are driven by the wind alone, and the oldest known picture of a sail, on an Egyptian pot, is more than 5,000 years old."},"sailfin-tang":{"id":"sailfin-tang","name":"Sailfin tang","aliases":["Pacific sailfin tang","Zebrasoma veliferum","sailfin surgeonfish"],"kind":"creature","group":"fish","fact":"The sailfin tang raises enormous dorsal and anal fins to look twice its size, and is banded brown and yellow."},"sailfish":{"id":"sailfish","name":"Sailfish","aliases":["Istiophorus","Atlantic sailfish","Indo-Pacific sailfish"],"kind":"creature","group":"fish","fact":"The sailfish is widely held to be the fastest fish in the sea, raising its huge dorsal sail when it herds sardines into tight balls."},"saithe":{"id":"saithe","name":"Saithe","aliases":["coley","coalfish","Pollachius virens","Boston bluefish","black pollock","pollock"],"kind":"creature","group":"fish","fact":"Saithe, or coley, is a dark-fleshed cousin of cod caught in huge numbers in the North Atlantic; cheaper than cod, it is often used in fish pies."},"sakhalin-taimen":{"id":"sakhalin-taimen","name":"Sakhalin taimen","aliases":["Japanese huchen","Parahucho perryi"],"kind":"creature","group":"fish","fact":"The Sakhalin taimen of Japan and the Russian Far East is a critically endangered giant that migrates between rivers and the sea."},"salema":{"id":"salema","name":"Salema","aliases":["salema porgy","dreamfish","saupe","Sarpa salpa"],"kind":"creature","group":"fish","fact":"The salema, a striped Mediterranean bream, can cause vivid hallucinations lasting days when eaten, earning it the nickname 'the dreamfish'."},"salish-sea":{"id":"salish-sea","name":"Salish Sea","aliases":[],"kind":"place","group":"seas","fact":"The Salish Sea, which includes Puget Sound and the Strait of Georgia, was only officially named in 2009, after the Coast Salish peoples."},"sally-lightfoot-crab":{"id":"sally-lightfoot-crab","name":"Sally Lightfoot crab","aliases":["Grapsus grapsus","red rock crab"],"kind":"creature","group":"crustaceans","fact":"Sally Lightfoot crabs skitter over Galápagos lava rocks in bright red and blue, and pick ticks off basking marine iguanas."},"salmon":{"id":"salmon","name":"Salmon","aliases":["Pacific salmon","Atlantic salmon","Salmo salar","sockeye salmon","chinook salmon","coho salmon","king salmon","Oncorhynchus"],"kind":"creature","group":"fish","fact":"Pacific salmon at sea feed heavily on krill, and the pigment from those crustaceans is what turns their flesh pink."},"salmon-shark":{"id":"salmon-shark","name":"Salmon shark","aliases":["Lamna ditropis"],"kind":"creature","group":"sharks","fact":"The salmon shark can hold its body temperature well above that of the cold North Pacific, letting it chase salmon in near-freezing seas."},"salp":{"id":"salp","name":"Salp","aliases":["Salpa","Salpa thompsoni"],"kind":"creature","group":"plankton","fact":"Salps are barrel-shaped, transparent relatives of vertebrates that pump water through their bodies, and can link into chains many metres long."},"saltwater-crocodile":{"id":"saltwater-crocodile","name":"Saltwater crocodile","aliases":["estuarine crocodile","saltie","Indo-Pacific crocodile","sea crocodile","Crocodylus porosus","crocodile"],"kind":"creature","group":"reptiles","fact":"The saltwater crocodile is the largest living reptile, over 6 metres long, and swims between islands across hundreds of kilometres of open sea."},"salvador":{"id":"salvador","name":"Salvador","aliases":["Salvador da Bahia","Bahia"],"kind":"place","group":"ports","fact":"Salvador, Brazil's first capital, sits on the Bay of All Saints, one of the largest bays on the Atlantic coast of South America."},"samoa":{"id":"samoa","name":"Samoa","aliases":["Samoan Islands","American Samoa","Western Samoa","Upolu"],"kind":"place","group":"islands","fact":"The Samoan Islands in the central Pacific are divided between the independent nation of Samoa and the US territory of American Samoa."},"sampan":{"id":"sampan","name":"Sampan","aliases":[],"kind":"vessel","group":"boats","fact":"The sampan is a flat-bottomed wooden boat of China and Southeast Asia, used for fishing and as a floating home in harbours and rivers."},"san-cristobal-trench":{"id":"san-cristobal-trench","name":"San Cristobal Trench","aliases":[],"kind":"place","group":"trenches","fact":"The San Cristobal Trench runs south of the Solomon Islands and is part of the chain of trenches along the Pacific's Ring of Fire."},"san-francisco-bay":{"id":"san-francisco-bay","name":"San Francisco Bay","aliases":["SF Bay"],"kind":"place","group":"bays","fact":"San Francisco Bay is the largest estuary on the Pacific coast of the Americas, entered through the Golden Gate strait."},"san-jose-galleon":{"id":"san-jose-galleon","name":"San José","aliases":["San Jose galleon","galleon San Jose"],"kind":"vessel","group":"wrecks","fact":"The Spanish galleon San José, sunk by the British off Cartagena in 1708 with a cargo of gold, silver and emeralds, was located in 2015 about 600 metres down."},"san-juan":{"id":"san-juan","name":"San Juan","aliases":["San Juan, Puerto Rico"],"kind":"place","group":"ports","fact":"San Juan, Puerto Rico, is guarded by El Morro, a Spanish fortress begun in 1539 to protect the harbour entrance."},"sand-bubbler-crab":{"id":"sand-bubbler-crab","name":"Sand bubbler crab","aliases":["Scopimera","Dotilla"],"kind":"creature","group":"crustaceans","fact":"Sand bubbler crabs sift sand for food and leave thousands of tiny sand balls radiating from their burrows on tropical beaches at low tide."},"sand-dollar":{"id":"sand-dollar","name":"Sand dollar","aliases":[],"kind":"creature","group":"echinoderms","fact":"Sand dollars are flattened sea urchins, and the bleached white 'shell' found on beaches is the animal's skeleton, or test."},"sand-eel":{"id":"sand-eel","name":"Sand eel","aliases":["sandeel","sand lance","lesser sand eel","Ammodytes","sandlance","launce"],"kind":"creature","group":"fish","fact":"Sand eels are slim silvery fish that dive headfirst into sand to hide, and puffins and kittiwakes depend on them to feed their chicks."},"sand-hopper":{"id":"sand-hopper","name":"Sand hopper","aliases":["sandhopper","beach flea","beach hopper","Talitrus saltator"],"kind":"creature","group":"crustaceans","fact":"Sand hoppers are tiny shrimp-like crustaceans that live in and feed on rotting seaweed washed up along the strandline."},"sand-tiger-shark":{"id":"sand-tiger-shark","name":"Sand tiger shark","aliases":["sand tiger","grey nurse shark","ragged-tooth shark","raggie","spotted ragged-tooth shark","Carcharias taurus"],"kind":"creature","group":"sharks","fact":"Sand tiger embryos eat their siblings in the womb, so only one pup from each uterus survives to birth."},"sandbar-shark":{"id":"sandbar-shark","name":"Sandbar shark","aliases":["brown shark","thickskin shark","Carcharhinus plumbeus"],"kind":"creature","group":"sharks","fact":"Sandbar sharks have an unusually tall dorsal fin and were once the mainstay of the shark fishery on the US east coast."},"sanddab":{"id":"sanddab","name":"Sanddab","aliases":["Pacific sanddab","Citharichthys sordidus","Citharichthys"],"kind":"creature","group":"fish","fact":"Pacific sanddabs are small left-eyed flounders of the US west coast, pan-fried whole and a speciality of Monterey and San Francisco restaurants."},"sanganeb-atoll":{"id":"sanganeb-atoll","name":"Sanganeb Atoll","aliases":["Sanganeb","Sanganeb Reef"],"kind":"place","group":"reefs","fact":"Sanganeb is the only atoll in the Red Sea, rising off the coast of Sudan and protected as a UNESCO World Heritage Site."},"santos":{"id":"santos","name":"Santos","aliases":[],"kind":"place","group":"ports","fact":"Santos, near São Paulo, is the busiest port in Latin America and the main gateway for Brazil's coffee exports."},"sao-tome-and-principe":{"id":"sao-tome-and-principe","name":"São Tomé and Príncipe","aliases":["São Tomé","Príncipe"],"kind":"place","group":"islands","fact":"São Tomé and Príncipe are two volcanic islands in the Gulf of Guinea that make up Africa's second-smallest country."},"sarcastic-fringehead":{"id":"sarcastic-fringehead","name":"Sarcastic fringehead","aliases":["Neoclinus blanchardi"],"kind":"creature","group":"fish","fact":"The sarcastic fringehead of the Californian coast defends its burrow by gaping an enormous fluorescent mouth at rivals."},"sardine":{"id":"sardine","name":"Sardine","aliases":["pilchard","European pilchard","Sardina pilchardus","Pacific sardine","iwashi"],"kind":"creature","group":"fish","fact":"Sardines filter copepods and krill from the water, and their immense schools off South Africa form the annual sardine run."},"sardinella":{"id":"sardinella","name":"Sardinella","aliases":["round sardinella","Sardinella aurita"],"kind":"creature","group":"fish","fact":"Sardinellas are small sardine-like fish that support huge fisheries off West Africa, where they are smoked and dried for food."},"sargasso-sea":{"id":"sargasso-sea","name":"Sargasso Sea","aliases":[],"kind":"place","group":"seas","fact":"The Sargasso Sea is the only sea with no coastline, bounded instead by Atlantic currents, and both European and American eels spawn there."},"sargassum":{"id":"sargassum","name":"Sargassum","aliases":["sargasso weed","gulfweed"],"kind":"plant","group":"plants","fact":"Sargassum is a floating brown seaweed held up by gas-filled bladders; huge rafts of it give the Sargasso Sea its name and shelter young sea turtles."},"saronic-gulf":{"id":"saronic-gulf","name":"Saronic Gulf","aliases":["Gulf of Aegina","Saronic Sea"],"kind":"place","group":"gulfs","fact":"The Saronic Gulf is the bay of the Aegean on which Athens and its port Piraeus stand, where the Greeks crushed the Persian fleet at Salamis in 480 BC."},"satomis-pygmy-seahorse":{"id":"satomis-pygmy-seahorse","name":"Satomi's pygmy seahorse","aliases":["Hippocampus satomiae","Satomi's seahorse"],"kind":"creature","group":"fish","fact":"Satomi's pygmy seahorse, from Indonesia, is about 1.4 centimetres long and is the smallest known seahorse."},"sawfish":{"id":"sawfish","name":"Sawfish","aliases":["carpenter shark","Pristis"],"kind":"creature","group":"rays","fact":"A sawfish's toothed snout is lined with sensors that detect prey, and it slashes sideways to stun fish."},"sawshark":{"id":"sawshark","name":"Sawshark","aliases":["saw shark","Pristiophoridae"],"kind":"creature","group":"sharks","fact":"Sawsharks carry a long flat saw-like snout with a pair of trailing barbels, and unlike sawfish they have gills on the sides of the head."},"sawtooth-eel":{"id":"sawtooth-eel","name":"Sawtooth eel","aliases":["Serrivomer","Serrivomeridae"],"kind":"creature","group":"fish","fact":"Sawtooth eels are small deep-sea eels with saw-like rows of teeth, drifting in the midwater of all the oceans."},"scaldfish":{"id":"scaldfish","name":"Scaldfish","aliases":["Arnoglossus laterna"],"kind":"creature","group":"fish","fact":"The scaldfish is a small, translucent flatfish of European seas whose loose scales come off so easily that it looks scalded when caught."},"scallop":{"id":"scallop","name":"Scallop","aliases":["king scallop","Pecten","sea scallop","bay scallop","great scallop","Pecten maximus","hotate","Pectinidae"],"kind":"creature","group":"molluscs","fact":"Scallops have dozens of tiny blue eyes along the edge of their shells and can swim by clapping their shells together."},"scalloped-hammerhead":{"id":"scalloped-hammerhead","name":"Scalloped hammerhead","aliases":["scalloped hammerhead shark","Sphyrna lewini"],"kind":"creature","group":"sharks","fact":"Scalloped hammerheads gather in schools of hundreds around seamounts such as Cocos Island and the Galápagos."},"scaly-foot-snail":{"id":"scaly-foot-snail","name":"Scaly-foot snail","aliases":["scaly-foot gastropod","Chrysomallon squamiferum","sea pangolin","volcano snail"],"kind":"creature","group":"molluscs","fact":"The scaly-foot snail armours its foot with plates of iron sulphide and is the first species declared endangered because of deep-sea mining."},"scapa-flow":{"id":"scapa-flow","name":"Scapa Flow","aliases":[],"kind":"place","group":"divesites","fact":"Scapa Flow in Orkney is where the interned German High Seas Fleet was scuttled in 1919, leaving battleships and cruisers that divers still explore."},"scarlet-badis":{"id":"scarlet-badis","name":"Scarlet badis","aliases":["Dario dario"],"kind":"creature","group":"fish","fact":"The scarlet badis is a 2-centimetre fish from India with scarlet and blue bars, one of the smallest perch-like fish."},"scarlet-ibis":{"id":"scarlet-ibis","name":"Scarlet ibis","aliases":["Eudocimus ruber"],"kind":"creature","group":"birds","fact":"The scarlet ibis gets its brilliant red colour from pigments in the crabs and shrimps it probes out of mangrove mud."},"schoolmaster-snapper":{"id":"schoolmaster-snapper","name":"Schoolmaster snapper","aliases":["schoolmaster","Lutjanus apodus"],"kind":"creature","group":"fish","fact":"The schoolmaster is a yellow-finned Caribbean snapper that gathers in daytime schools beneath elkhorn coral and mangroves."},"schooner":{"id":"schooner","name":"Schooner","aliases":["fishing schooner"],"kind":"vessel","group":"boats","fact":"A schooner is a sailing ship with two or more masts whose main sails run fore-and-aft, a rig that made it a favourite of fishermen and smugglers."},"scorpionfish":{"id":"scorpionfish","name":"Scorpionfish","aliases":["Scorpaenidae","Scorpaena","scorpion fish"],"kind":"creature","group":"fish","fact":"Scorpionfish are camouflaged ambush hunters with venomous fin spines, and the family includes the lionfish and the stonefish."},"scott-reef":{"id":"scott-reef","name":"Scott Reef","aliases":[],"kind":"place","group":"reefs","fact":"Scott Reef is a remote atoll system off north-west Australia that recovered remarkably after being devastated by coral bleaching in 1998."},"scrawled-filefish":{"id":"scrawled-filefish","name":"Scrawled filefish","aliases":["Aluterus scriptus"],"kind":"creature","group":"fish","fact":"The scrawled filefish has blue scribbles over an olive body that it can lighten, darken or mottle to match its surroundings."},"sculpin":{"id":"sculpin","name":"Sculpin","aliases":["Cottidae"],"kind":"creature","group":"fish","fact":"Sculpins are spiny bottom fish of cold waters, and several species grunt and hum during territorial disputes and courtship."},"sea-anemone":{"id":"sea-anemone","name":"Sea anemone","aliases":["anemone"],"kind":"creature","group":"cnidarians","fact":"Sea anemones look like flowers but are predators armed with stinging tentacles, found from rock pools to the floors of ocean trenches."},"sea-angel":{"id":"sea-angel","name":"Sea angel","aliases":["naked sea butterfly","clione","Clione limacina"],"kind":"creature","group":"molluscs","fact":"The sea angel is a tiny swimming sea slug of Arctic waters that flaps two wing-like lobes and preys only on sea butterflies."},"sea-apple":{"id":"sea-apple","name":"Sea apple","aliases":["Pseudocolochirus","Pseudocolochirus violaceus"],"kind":"creature","group":"echinoderms","fact":"The sea apple is a brightly coloured sea cucumber that feeds with a crown of tentacles and can release a toxin that kills everything in an aquarium."},"sea-bass":{"id":"sea-bass","name":"Sea bass","aliases":["European sea bass","branzino","Dicentrarchus labrax","loup de mer","bar","lubina"],"kind":"creature","group":"fish","fact":"The European sea bass, sold as branzino, is a prized angling fish of the North Sea and Atlantic coasts and is widely farmed in the Mediterranean."},"sea-biscuit":{"id":"sea-biscuit","name":"Sea biscuit","aliases":["Clypeaster"],"kind":"creature","group":"echinoderms","fact":"A sea biscuit is a thick, domed relative of the sand dollar that burrows through sand on tropical sea floors."},"sea-bream":{"id":"sea-bream","name":"Sea bream","aliases":["gilthead bream","gilthead sea bream","gilt-head bream","Sparus aurata","dorade","gilthead seabream","orata"],"kind":"creature","group":"fish","fact":"The gilthead sea bream, named for the gold bar between its eyes, is one of the most farmed fish in the Mediterranean."},"sea-butterfly":{"id":"sea-butterfly","name":"Sea butterfly","aliases":["pteropod","shelled pteropod","Limacina helicina","Limacina","thecosome","Thecosomata"],"kind":"creature","group":"molluscs","fact":"Sea butterflies are tiny swimming snails that flap wing-like flaps, and their thin shells are threatened by ocean acidification."},"sea-chub":{"id":"sea-chub","name":"Sea chub","aliases":["rudderfish","Bermuda chub","Kyphosus","drummer"],"kind":"creature","group":"fish","fact":"Sea chubs, or rudderfish, are unusual among reef fish in eating mostly brown seaweeds such as sargassum, and they often follow boats."},"sea-cow":{"id":"sea-cow","name":"Sea cow","aliases":["sirenian","Sirenia"],"kind":"creature","group":"mammals","fact":"Sea cows, the manatees and dugong, are the only plant-eating marine mammals and are related to elephants rather than seals."},"sea-cucumber":{"id":"sea-cucumber","name":"Sea cucumber","aliases":["holothurian","Holothuroidea","namako","Japanese sea cucumber","Apostichopus japonicus"],"kind":"creature","group":"echinoderms","fact":"Sea cucumbers breathe through their bottoms and can eject their sticky internal organs at attackers, growing them back within weeks."},"sea-daisy":{"id":"sea-daisy","name":"Sea daisy","aliases":["Xyloplax"],"kind":"creature","group":"echinoderms","fact":"Sea daisies are tiny disc-shaped echinoderms found on sunken wood in the deep sea and were only discovered in 1986."},"sea-dragon":{"id":"sea-dragon","name":"Sea dragon","aliases":["seadragon","leafy sea dragon","leafy seadragon","weedy sea dragon","weedy seadragon","Phycodurus eques"],"kind":"creature","group":"fish","fact":"Sea dragons are seahorse relatives found only in the coastal waters of southern Australia, where they drift among kelp and seagrass."},"sea-fan":{"id":"sea-fan","name":"Sea fan","aliases":["fan coral","gorgonian","common sea fan","Gorgonia ventalina"],"kind":"creature","group":"corals","fact":"A sea fan is a soft coral whose colony grows into a flat, lacy fan held side-on to the current to catch drifting plankton."},"sea-firefly":{"id":"sea-firefly","name":"Sea firefly","aliases":["Vargula hilgendorfii","umi-hotaru"],"kind":"creature","group":"crustaceans","fact":"The sea firefly is a 3-millimetre ostracod that squirts glowing blue mucus; dried ones were used by Japanese soldiers as a dim reading light."},"sea-gooseberry":{"id":"sea-gooseberry","name":"Sea gooseberry","aliases":["Pleurobrachia","Pleurobrachia pileus","Pleurobrachia bachei"],"kind":"creature","group":"jellies","fact":"The sea gooseberry is a glassy, marble-sized comb jelly that trails two long sticky tentacles to snare copepods."},"sea-grapes":{"id":"sea-grapes","name":"Sea grapes","aliases":["green caviar","Caulerpa lentillifera","umibudo","lato"],"kind":"plant","group":"plants","fact":"Sea grapes are a green seaweed with tiny bubble-like beads that pop in the mouth, eaten fresh in Okinawa and the Philippines."},"sea-hare":{"id":"sea-hare","name":"Sea hare","aliases":["Aplysia","California sea hare"],"kind":"creature","group":"molluscs","fact":"The sea hare is a large sea slug that squirts a cloud of purple ink when it is disturbed."},"sea-krait":{"id":"sea-krait","name":"Sea krait","aliases":["Laticauda","banded sea krait","Laticauda colubrina"],"kind":"creature","group":"reptiles","fact":"Sea kraits are the only sea snakes that come ashore to lay eggs, and they have highly potent venom but rarely bite people."},"sea-lamprey":{"id":"sea-lamprey","name":"Sea lamprey","aliases":["lamprey","Petromyzon marinus"],"kind":"creature","group":"fish","fact":"The sea lamprey grows up at sea clamped onto fish, rasping through their skin to feed on blood, then swims up rivers to spawn and die."},"sea-lemon":{"id":"sea-lemon","name":"Sea lemon","aliases":["Doris pseudoargus","Peltodoris nobilis"],"kind":"creature","group":"molluscs","fact":"The sea lemon is a yellow, warty nudibranch of Atlantic and Pacific shores that eats sponges, and the Pacific species gives off a fruity, citrus-like smell."},"sea-lettuce":{"id":"sea-lettuce","name":"Sea lettuce","aliases":["Ulva lactuca","Ulva"],"kind":"plant","group":"plants","fact":"Sea lettuce is a bright green seaweed with fronds only two cells thick, which can bloom into 'green tides' where sewage or farm runoff enriches the water."},"sea-lily":{"id":"sea-lily","name":"Sea lily","aliases":["stalked crinoid","crinoid","feather star"],"kind":"creature","group":"echinoderms","fact":"Sea lilies are animals, not plants: feathery filter feeders on a stalk that were common 300 million years ago and today live densely on rocks more than 9,000 metres down in the Izu-Ogasawara Trench."},"sea-lion":{"id":"sea-lion","name":"Sea lion","aliases":["sealion","California sea lion","Zalophus californianus"],"kind":"creature","group":"seals","fact":"Sea lions differ from true seals in having small external ear flaps and in walking on all four flippers on land."},"sea-louse":{"id":"sea-louse","name":"Sea louse","aliases":["salmon louse","fish louse","Lepeophtheirus salmonis","sea lice"],"kind":"creature","group":"crustaceans","fact":"Sea lice are tiny copepods that attach to salmon and feed on their skin and blood, and they are a major problem on salmon farms."},"sea-mink":{"id":"sea-mink","name":"Sea mink","aliases":["Neogale macrodon","Neovison macrodon"],"kind":"creature","group":"mammals","fact":"The sea mink, a large coastal mink of New England and Atlantic Canada, was trapped to extinction for its fur by about 1900."},"sea-moth":{"id":"sea-moth","name":"Sea moth","aliases":["Pegasus","Pegasidae","dragon sea moth"],"kind":"creature","group":"fish","fact":"Sea moths are small armoured fish of Indo-Pacific sand flats that walk on their pelvic fins and spread wing-like pectoral fins."},"sea-mouse":{"id":"sea-mouse","name":"Sea mouse","aliases":["Aphrodita aculeata","Aphrodita"],"kind":"creature","group":"worms","fact":"The sea mouse is a furry-looking marine worm whose iridescent bristles were among the first natural structures found to work like optical fibres."},"sea-nettle":{"id":"sea-nettle","name":"Sea nettle","aliases":["Pacific sea nettle","Chrysaora fuscescens","Atlantic sea nettle","Chrysaora quinquecirrha","Chrysaora","West Coast sea nettle"],"kind":"creature","group":"jellies","fact":"Sea nettles are golden-brown jellyfish with long frilly oral arms whose sting feels like brushing a stinging nettle, hence the name."},"sea-of-azov":{"id":"sea-of-azov","name":"Sea of Azov","aliases":["Azov Sea"],"kind":"place","group":"seas","fact":"The Sea of Azov, linked to the Black Sea by the Kerch Strait, is the shallowest sea in the world, averaging only about 7 metres deep."},"sea-of-crete":{"id":"sea-of-crete","name":"Sea of Crete","aliases":["Cretan Sea"],"kind":"place","group":"seas","fact":"The Sea of Crete is the southern part of the Aegean between Crete and the Cyclades, and is deeper than most of the Aegean."},"sea-of-japan":{"id":"sea-of-japan","name":"Sea of Japan","aliases":["East Sea"],"kind":"place","group":"seas","fact":"The Sea of Japan, called the East Sea in Korea, is a marginal sea of the Pacific nearly enclosed by Japan, Korea and Russia."},"sea-of-marmara":{"id":"sea-of-marmara","name":"Sea of Marmara","aliases":["Marmara Sea","Propontis"],"kind":"place","group":"seas","fact":"The Sea of Marmara is a small inland sea entirely within Turkey, linking the Black Sea to the Aegean through the Bosporus and Dardanelles."},"sea-of-okhotsk":{"id":"sea-of-okhotsk","name":"Sea of Okhotsk","aliases":["Okhotsk Sea"],"kind":"place","group":"seas","fact":"The Sea of Okhotsk, off Russia's far east, is the coldest sea in East Asia and is covered by drifting ice for much of the winter."},"sea-of-sardinia":{"id":"sea-of-sardinia","name":"Sea of Sardinia","aliases":["Sardinian Sea"],"kind":"place","group":"seas","fact":"The Sea of Sardinia is the stretch of the western Mediterranean between Sardinia and the Balearic Islands."},"sea-otter":{"id":"sea-otter","name":"Sea otter","aliases":["Enhydra lutris"],"kind":"creature","group":"mammals","fact":"Sea otters have the densest fur of any animal and use rocks as tools to crack open shellfish."},"sea-palm":{"id":"sea-palm","name":"Sea palm","aliases":["Postelsia palmaeformis","Postelsia"],"kind":"plant","group":"plants","fact":"The sea palm looks like a tiny palm tree and lives only on the most wave-battered rocks of the Pacific coast of North America."},"sea-pansy":{"id":"sea-pansy","name":"Sea pansy","aliases":["Renilla","Renilla reniformis"],"kind":"creature","group":"corals","fact":"The sea pansy is a flat, purple soft coral colony on sand that glows green when touched, thanks to a protein now used in laboratories."},"sea-pen":{"id":"sea-pen","name":"Sea pen","aliases":["Pennatula","Pennatulacea","pennatulacean"],"kind":"creature","group":"corals","fact":"A sea pen is a colony of polyps shaped like an old quill pen, rooted in soft mud, and many species glow green when touched."},"sea-pig":{"id":"sea-pig","name":"Sea pig","aliases":["Scotoplanes","Scotoplanes globosa"],"kind":"creature","group":"echinoderms","fact":"Sea pigs are pink, pudgy sea cucumbers that walk on tube feet across abyssal plains, often in herds all facing the current, 1,000 to 6,000 metres down."},"sea-raven":{"id":"sea-raven","name":"Sea raven","aliases":["Hemitripterus americanus"],"kind":"creature","group":"fish","fact":"The sea raven is a lumpy, ragged-finned sculpin of the North American Atlantic coast that puffs itself up with water when caught."},"sea-robin":{"id":"sea-robin","name":"Sea robin","aliases":["searobin","Prionotus","northern sea robin","Triglidae"],"kind":"creature","group":"fish","fact":"Sea robins 'walk' on finger-like fin rays and grunt or croak by vibrating their swim bladder, a sound anglers hear when they lift them from the water."},"sea-sapphire":{"id":"sea-sapphire","name":"Sea sapphire","aliases":["Sapphirina","sapphirinid copepod"],"kind":"creature","group":"crustaceans","fact":"The sea sapphire is a copepod whose males flash brilliant blue, then turn transparent and vanish as they tilt, thanks to crystal plates in their skin."},"sea-scorpion":{"id":"sea-scorpion","name":"Sea scorpion","aliases":["eurypterid","Eurypterus","Pterygotus","Jaekelopterus"],"kind":"creature","group":"arthropods","fact":"Sea scorpions, or eurypterids, were armoured arthropods that died out about 250 million years ago, and the largest reached about 2.5 metres."},"sea-slater":{"id":"sea-slater","name":"Sea slater","aliases":["sea roach","rock louse","Ligia"],"kind":"creature","group":"crustaceans","fact":"The sea slater is a large woodlouse of the splash zone that hides in crevices by day and scavenges over the rocks at night."},"sea-snail":{"id":"sea-snail","name":"Sea snail","aliases":["snail","marine snail","gastropod","marine gastropod"],"kind":"creature","group":"molluscs","fact":"Sea snails build their spiral shells from calcium carbonate drawn from seawater, adding to the opening as they grow."},"sea-snake":{"id":"sea-snake","name":"Sea snake","aliases":["sea krait","banded sea krait","Laticauda","Hydrophis","olive sea snake","Hydrophiinae","yellow-bellied sea snake"],"kind":"creature","group":"reptiles","fact":"Sea snakes are venomous relatives of cobras with paddle-shaped tails, and most give birth to live young at sea."},"sea-spider":{"id":"sea-spider","name":"Sea spider","aliases":["pycnogonid","Pycnogonida"],"kind":"creature","group":"arthropods","fact":"Sea spiders are not true spiders but leggy marine arthropods, and in Antarctic waters they grow as wide as a dinner plate."},"sea-squirt":{"id":"sea-squirt","name":"Sea squirt","aliases":["tunicate","ascidian"],"kind":"creature","group":"tunicates","fact":"A sea squirt starts life as a swimming tadpole-like larva, then glues itself to a rock and spends the rest of its life pumping water through its body to filter food."},"sea-star":{"id":"sea-star","name":"Sea star","aliases":["starfish","star fish"],"kind":"creature","group":"echinoderms","fact":"Sea stars have no brain or blood, pumping seawater through their bodies to move hundreds of tiny tube feet."},"sea-toad":{"id":"sea-toad","name":"Sea toad","aliases":["coffinfish","Chaunacidae","Chaunax"],"kind":"creature","group":"fish","fact":"Sea toads, or coffinfish, are deep-sea anglerfish that can inflate their bodies with water and hold their breath for minutes to save energy."},"sea-trout":{"id":"sea-trout","name":"Sea trout","aliases":["sea-run brown trout","Salmo trutta trutta"],"kind":"creature","group":"fish","fact":"The sea trout is a brown trout that goes to sea to feed, and anglers fish for it at night in rivers draining into the North and Baltic seas."},"sea-turtle":{"id":"sea-turtle","name":"Sea turtle","aliases":["turtle","marine turtle"],"kind":"creature","group":"turtles","fact":"Sea turtles cannot pull their heads into their shells, and females return to the beach where they hatched to lay their own eggs."},"sea-urchin":{"id":"sea-urchin","name":"Sea urchin","aliases":["urchin","Echinoidea","uni"],"kind":"creature","group":"echinoderms","fact":"A sea urchin's spines sit on a rigid shell called a test, which is made of plates of calcium carbonate."},"sea-walnut":{"id":"sea-walnut","name":"Sea walnut","aliases":["Mnemiopsis leidyi","Mnemiopsis","warty comb jelly","American comb jelly"],"kind":"creature","group":"jellies","fact":"The sea walnut, a comb jelly from the American Atlantic, invaded the Black Sea in ballast water and helped collapse its anchovy fishery in the 1980s."},"sea-wasp":{"id":"sea-wasp","name":"Sea wasp","aliases":["Australian box jellyfish","Chironex fleckeri"],"kind":"creature","group":"jellies","fact":"The sea wasp, a box jellyfish of northern Australia, carries enough venom in its tentacles to kill a person within minutes."},"sea-whip":{"id":"sea-whip","name":"Sea whip","aliases":["whip coral","Leptogorgia","Leptogorgia virgulata"],"kind":"creature","group":"corals","fact":"A sea whip is a soft coral that grows as a single long, flexible rod, often brightly coloured, swaying in the current."},"seagrass":{"id":"seagrass","name":"Seagrass","aliases":["sea grass"],"kind":"plant","group":"plants","fact":"Seagrasses are true flowering plants, not seaweeds, with roots and underwater flowers, and their meadows store carbon far faster than forests on land."},"seahorse":{"id":"seahorse","name":"Seahorse","aliases":["sea horse","Hippocampus"],"kind":"creature","group":"fish","fact":"Seahorses are reef fish that swim upright, grip coral with their tails, and leave the males to carry the eggs in a pouch."},"seal":{"id":"seal","name":"Seal","aliases":["true seal","earless seal","Phocidae"],"kind":"creature","group":"seals","fact":"Seals are marine mammals with streamlined bodies and flippers, and true seals have no external ear flaps."},"seamoth":{"id":"seamoth","name":"Seamoth","aliases":["sea moth","Pegasus","Pegasidae"],"kind":"creature","group":"fish","fact":"Seamoths are small armoured fish with wing-like fins and a long flat snout, and they walk across the sand on their pelvic fins."},"sebae-clownfish":{"id":"sebae-clownfish","name":"Sebae clownfish","aliases":["sebae anemonefish","Amphiprion sebae"],"kind":"creature","group":"fish","fact":"The sebae clownfish is a dark anemonefish with a yellow tail and two white bars from the northern Indian Ocean; many fish sold under its name are actually Clark's."},"sei-whale":{"id":"sei-whale","name":"Sei whale","aliases":["Balaenoptera borealis"],"kind":"creature","group":"whales","fact":"The sei whale is one of the fastest great whales and was hunted hard in the 1960s once fin whale numbers had collapsed."},"senegal-bichir":{"id":"senegal-bichir","name":"Senegal bichir","aliases":["grey bichir","dinosaur eel","Polypterus senegalus"],"kind":"creature","group":"fish","fact":"The Senegal bichir has paired lungs and is sometimes sold in aquariums as the dinosaur eel for its ancient look."},"senorita":{"id":"senorita","name":"Señorita","aliases":["senorita wrasse","Oxyjulis californica"],"kind":"creature","group":"fish","fact":"The señorita is a slim, cigar-shaped wrasse of California's kelp forests that cleans parasites off other fish and sleeps buried in sand."},"sergeant-major":{"id":"sergeant-major","name":"Sergeant major","aliases":["Abudefduf saxatilis","sergeant major damselfish","sergeant major fish"],"kind":"creature","group":"fish","fact":"The sergeant major is a striped damselfish found on reefs around the world, named for the stripes on a sergeant's sleeve; it swarms around divers for crumbs."},"serrated-wrack":{"id":"serrated-wrack","name":"Serrated wrack","aliases":["toothed wrack","saw wrack","Fucus serratus"],"kind":"plant","group":"plants","fact":"Serrated wrack is the toothed-edged brown seaweed of the lower shore, with no air bladders, sheltering many small animals beneath it."},"seto-inland-sea":{"id":"seto-inland-sea","name":"Seto Inland Sea","aliases":["Seto Naikai","Inland Sea of Japan","Inland Sea"],"kind":"place","group":"seas","fact":"The Seto Inland Sea separates three of Japan's main islands, Honshu, Shikoku and Kyushu, and is dotted with about 3,000 islands."},"sevan-trout":{"id":"sevan-trout","name":"Sevan trout","aliases":["ishkhan","Salmo ischchan"],"kind":"creature","group":"fish","fact":"The Sevan trout is found naturally only in Lake Sevan in Armenia and is endangered after the lake was lowered for irrigation and power."},"seven-arm-octopus":{"id":"seven-arm-octopus","name":"Seven-arm octopus","aliases":["Haliphron atlanticus","Haliphron","seven-armed octopus"],"kind":"creature","group":"cephalopods","fact":"The seven-arm octopus is one of the largest octopuses, with a 4-metre specimen known, and has been photographed holding and eating jellyfish."},"seven-figure-pygmy-goby":{"id":"seven-figure-pygmy-goby","name":"Seven-figure pygmy goby","aliases":["Eviota sigillata","sevenfigure pygmy goby"],"kind":"creature","group":"fish","fact":"The seven-figure pygmy goby, a 2-centimetre reef fish, has the shortest lifespan of any vertebrate, living for about two months."},"sewol":{"id":"sewol","name":"Sewol","aliases":["MV Sewol"],"kind":"vessel","group":"wrecks","fact":"The South Korean ferry Sewol capsized and sank in April 2014 with the loss of more than 300 people, most of them schoolchildren."},"sexy-shrimp":{"id":"sexy-shrimp","name":"Sexy shrimp","aliases":["sexy anemone shrimp","Thor amboinensis","squat shrimp"],"kind":"creature","group":"crustaceans","fact":"The sexy shrimp got its name from the way it constantly sways its tail up and down while sitting on a sea anemone."},"shark":{"id":"shark","name":"Shark","aliases":["Selachii"],"kind":"creature","group":"sharks","fact":"Every shark has ampullae of Lorenzini, jelly-filled pores on its snout that detect the faint electric fields of a hidden animal's muscles and heartbeat."},"sharpnose-puffer":{"id":"sharpnose-puffer","name":"Sharpnose puffer","aliases":["Caribbean sharpnose puffer","Canthigaster rostrata"],"kind":"creature","group":"fish","fact":"The sharpnose puffer is a thumb-sized Caribbean puffer with a pointed snout and bright blue lines around its eyes."},"sharpnose-sevengill-shark":{"id":"sharpnose-sevengill-shark","name":"Sharpnose sevengill shark","aliases":["sharpnose sevengill","Heptranchias perlo"],"kind":"creature","group":"sharks","fact":"The sharpnose sevengill is a slender deep-water shark with seven gill slits and large green eyes."},"shearwater":{"id":"shearwater","name":"Shearwater","aliases":["Manx shearwater","great shearwater","Cory's shearwater"],"kind":"creature","group":"seabirds","fact":"Shearwaters skim the waves on stiff wings and dive after fish and squid, some chasing them tens of metres down."},"sheepshead":{"id":"sheepshead","name":"Sheepshead","aliases":["Archosargus probatocephalus"],"kind":"creature","group":"fish","fact":"The sheepshead of the Gulf of Mexico has eerily human-looking teeth for crunching barnacles and crabs off pilings."},"shepherds-beaked-whale":{"id":"shepherds-beaked-whale","name":"Shepherd's beaked whale","aliases":["Tasman beaked whale","Tasmacetus shepherdi"],"kind":"creature","group":"whales","fact":"Shepherd's beaked whale is the only beaked whale with a full set of functional teeth in both jaws."},"shetland":{"id":"shetland","name":"Shetland","aliases":["Shetland Islands","Shetlands"],"kind":"place","group":"islands","fact":"Shetland is the northernmost part of the British Isles, closer to Norway than to Edinburgh, with a long Norse history."},"shinkai-6500":{"id":"shinkai-6500","name":"Shinkai 6500","aliases":["Shinkai"],"kind":"vessel","group":"submersibles","fact":"Japan's Shinkai 6500 can dive to 6,500 metres and was for many years the deepest-diving crewed research submersible in service."},"shonisaurus":{"id":"shonisaurus","name":"Shonisaurus","aliases":[],"kind":"creature","group":"reptiles","fact":"Shonisaurus was a Triassic ichthyosaur the size of a bus, and dozens of its skeletons lie together at Berlin-Ichthyosaur State Park in Nevada."},"shore-crab":{"id":"shore-crab","name":"Shore crab","aliases":["European green crab","green crab","Carcinus maenas","common shore crab","green shore crab"],"kind":"creature","group":"crustaceans","fact":"The shore crab, the common rock-pool crab of Europe, has spread around the world in ships' ballast water and is one of the most invasive marine species."},"shore-rockling":{"id":"shore-rockling","name":"Shore rockling","aliases":["rockling","Gaidropsarus mediterraneus"],"kind":"creature","group":"fish","fact":"The shore rockling is a small, eel-like cod relative with three barbels, found under stones in rock pools around Britain."},"short-finned-eel":{"id":"short-finned-eel","name":"Short-finned eel","aliases":["shortfin eel","Anguilla australis","Australian short-finned eel"],"kind":"creature","group":"fish","fact":"The short-finned eel of Australia and New Zealand migrates thousands of kilometres to spawn in the Coral Sea."},"short-finned-pilot-whale":{"id":"short-finned-pilot-whale","name":"Short-finned pilot whale","aliases":["Globicephala macrorhynchus"],"kind":"creature","group":"dolphins","fact":"Short-finned pilot whales sprint after squid in the deep, earning the nickname 'cheetahs of the deep', and females live decades past menopause."},"short-nosed-sea-snake":{"id":"short-nosed-sea-snake","name":"Short-nosed sea snake","aliases":["Sahul reef snake","Aipysurus apraefrontalis"],"kind":"creature","group":"reptiles","fact":"The short-nosed sea snake was feared extinct for 15 years until a pair was photographed courting on Ningaloo Reef in 2015."},"short-snouted-seahorse":{"id":"short-snouted-seahorse","name":"Short-snouted seahorse","aliases":["Hippocampus hippocampus"],"kind":"creature","group":"fish","fact":"The short-snouted seahorse is one of two seahorse species native to British waters and has even been found in the Thames estuary."},"short-tail-stingray":{"id":"short-tail-stingray","name":"Short-tail stingray","aliases":["smooth stingray","short-tailed stingray","Bathytoshia brevicaudata","Dasyatis brevicaudata"],"kind":"creature","group":"rays","fact":"The short-tail stingray is among the largest stingrays, reaching over 2 metres across and about 350 kilograms."},"short-tailed-shearwater":{"id":"short-tailed-shearwater","name":"Short-tailed shearwater","aliases":["muttonbird","Ardenna tenuirostris"],"kind":"creature","group":"seabirds","fact":"Short-tailed shearwaters, Australia's muttonbirds, loop around the Pacific to Alaska and back each year, a journey of roughly 30,000 kilometres."},"shortbill-spearfish":{"id":"shortbill-spearfish","name":"Shortbill spearfish","aliases":["Tetrapturus angustirostris","spearfish"],"kind":"creature","group":"fish","fact":"The shortbill spearfish is a slim, fast billfish of the Pacific with a bill barely longer than its lower jaw."},"shovelnose-guitarfish":{"id":"shovelnose-guitarfish","name":"Shovelnose guitarfish","aliases":["guitarfish","Pseudobatos productus"],"kind":"creature","group":"rays","fact":"The shovelnose guitarfish is a ray with a pointed shovel-shaped snout and a shark-like tail, lying on sandy bottoms off California and Mexico."},"shrimp":{"id":"shrimp","name":"Shrimp","aliases":["prawn","ebi"],"kind":"creature","group":"crustaceans","fact":"Shrimps and prawns wear a thin, flexible shell that they shed many times as they grow."},"shrimp-goby":{"id":"shrimp-goby","name":"Shrimp goby","aliases":["watchman goby","prawn goby","yellow watchman goby","Amblyeleotris","Cryptocentrus"],"kind":"creature","group":"fish","fact":"Shrimp gobies stand guard at the mouth of a burrow dug by a pistol shrimp, warning the shrimp with a flick of the tail when danger approaches."},"shrimpfish":{"id":"shrimpfish","name":"Shrimpfish","aliases":["razorfish","Centriscidae"],"kind":"creature","group":"fish","fact":"Shrimpfish, or razorfish, are thin armoured relatives of seahorses that swim head-down in synchronised groups, often hiding among sea urchin spines."},"siamese-algae-eater":{"id":"siamese-algae-eater","name":"Siamese algae eater","aliases":["Crossocheilus oblongus"],"kind":"creature","group":"fish","fact":"The Siamese algae eater is valued by aquarists because it is one of the few fish that eats stringy black beard algae."},"sicklefin-lemon-shark":{"id":"sicklefin-lemon-shark","name":"Sicklefin lemon shark","aliases":["sharptooth lemon shark","Negaprion acutidens"],"kind":"creature","group":"sharks","fact":"The sicklefin lemon shark is the Indo-Pacific cousin of the lemon shark and is a favourite of shark-feeding dives in French Polynesia."},"signal-crayfish":{"id":"signal-crayfish","name":"Signal crayfish","aliases":["Pacifastacus leniusculus","American signal crayfish"],"kind":"creature","group":"crustaceans","fact":"The signal crayfish, named for the white patch at its claw joints, was introduced from North America and now dominates rivers across Europe."},"silfra":{"id":"silfra","name":"Silfra","aliases":["Silfra fissure"],"kind":"place","group":"divesites","fact":"Silfra in Iceland is a flooded crack between the North American and Eurasian plates, with glacial water so clear that visibility exceeds 100 metres."},"silky-shark":{"id":"silky-shark","name":"Silky shark","aliases":["Carcharhinus falciformis"],"kind":"creature","group":"sharks","fact":"Silky sharks get their name from the smooth feel of their skin and are among the most heavily fished sharks in the world."},"silver-carp":{"id":"silver-carp","name":"Silver carp","aliases":["Hypophthalmichthys molitrix","flying carp","Asian carp"],"kind":"creature","group":"fish","fact":"The silver carp is among the most farmed fish in the world in China, yet in American rivers it is an invader notorious for leaping out of the water at boats."},"silver-cheeked-toadfish":{"id":"silver-cheeked-toadfish","name":"Silver-cheeked toadfish","aliases":["silverstripe blaasop","Lagocephalus sceleratus"],"kind":"creature","group":"fish","fact":"The silver-cheeked toadfish, a highly toxic puffer, spread from the Red Sea through the Suez Canal and now plagues fisheries across the Mediterranean."},"silver-dollar":{"id":"silver-dollar","name":"Silver dollar","aliases":["Metynnis"],"kind":"creature","group":"fish","fact":"The silver dollar is a flat, coin-shaped Amazon fish kept in aquariums, a plant-eating cousin of the piranha."},"silver-hake":{"id":"silver-hake","name":"Silver hake","aliases":["Merluccius bilinearis","New England hake"],"kind":"creature","group":"fish","fact":"The silver hake is the main hake of the US east coast, a fast-swimming predator of small fish that is sold there under the name whiting."},"silver-perch":{"id":"silver-perch","name":"Silver perch","aliases":["Bairdiella chrysoura"],"kind":"creature","group":"fish","fact":"The silver perch is a small drum of US Atlantic estuaries that joins loud evening drumming choruses in summer, picked up by hydrophones in Chesapeake Bay."},"silvertip-shark":{"id":"silvertip-shark","name":"Silvertip shark","aliases":["Carcharhinus albimarginatus"],"kind":"creature","group":"sharks","fact":"Silvertip sharks, with white edges on every fin, patrol the drop-offs of Indo-Pacific reefs and are bold around divers."},"sipadan":{"id":"sipadan","name":"Sipadan","aliases":["Sipadan Island","Pulau Sipadan"],"kind":"place","group":"divesites","fact":"Sipadan, off Malaysian Borneo, is an oceanic island rising 600 metres from the seabed, famed for green turtles and swirling barracuda tornadoes."},"siphonophore":{"id":"siphonophore","name":"Siphonophore","aliases":[],"kind":"creature","group":"jellies","fact":"A siphonophore is a chain of specialised clones acting as one animal; one filmed off Western Australia in 2020 was estimated at about 45 metres long."},"six-line-wrasse":{"id":"six-line-wrasse","name":"Six-line wrasse","aliases":["sixline wrasse","Pseudocheilinus hexataenia","six-stripe wrasse","sixstripe wrasse"],"kind":"creature","group":"fish","fact":"The six-line wrasse is a tiny purple-and-orange striped wrasse from Indo-Pacific reefs that hunts pests such as flatworms in aquariums."},"sixgill-shark":{"id":"sixgill-shark","name":"Sixgill shark","aliases":["bluntnose sixgill shark","Hexanchus griseus","cow shark","bluntnose sixgill","sixgill","six-gill shark"],"kind":"creature","group":"sharks","fact":"The bluntnose sixgill shark has six gill slits instead of five, grows to about 5 metres and spends the day down to about 2,500 metres."},"sixgill-stingray":{"id":"sixgill-stingray","name":"Sixgill stingray","aliases":["Hexatrygon bickelli"],"kind":"creature","group":"rays","fact":"The sixgill stingray lives in deep water and is the only stingray with six pairs of gill slits instead of five."},"skagerrak":{"id":"skagerrak","name":"Skagerrak","aliases":[],"kind":"place","group":"straits","fact":"The Skagerrak is the strait between Norway, Denmark and Sweden that links the North Sea to the Baltic, and it was the scene of the Battle of Jutland in 1916."},"skate":{"id":"skate","name":"Skate","aliases":["common skate","Raja"],"kind":"creature","group":"rays","fact":"Skates lay their eggs in leathery cases called mermaid's purses that often wash up on beaches."},"skellig-michael":{"id":"skellig-michael","name":"Skellig Michael","aliases":["Skellig","Great Skellig","Skellig Islands","Skelligs"],"kind":"place","group":"islands","fact":"Skellig Michael is a jagged rock off Ireland with a sixth-century monastery on its summit, later used as Luke Skywalker's hideout in Star Wars."},"skipjack-tuna":{"id":"skipjack-tuna","name":"Skipjack tuna","aliases":["skipjack","katsuo","aku","Katsuwonus pelamis","striped tuna"],"kind":"creature","group":"fish","fact":"Skipjack is the most-caught tuna in the world and the one in most tins; in Japan it is katsuo, dried into bonito flakes and seared as tataki."},"slate-pencil-urchin":{"id":"slate-pencil-urchin","name":"Slate pencil urchin","aliases":["pencil urchin","red pencil urchin","Heterocentrotus mamillatus"],"kind":"creature","group":"echinoderms","fact":"The slate pencil urchin's thick, blunt reddish spines look like old-fashioned slate pencils and have been used to make wind chimes and jewellery."},"sleeper-shark":{"id":"sleeper-shark","name":"Sleeper shark","aliases":[],"kind":"creature","group":"sharks","fact":"Sleeper sharks are sluggish cold-water sharks of the deep, and the flesh of some species is toxic until it is fermented or dried."},"slender-giant-moray":{"id":"slender-giant-moray","name":"Slender giant moray","aliases":["Strophidon sathete","giant slender moray","Gangetic moray"],"kind":"creature","group":"fish","fact":"The slender giant moray is the longest eel in the world, reaching about 4 metres, and lives in muddy estuaries of the Indo-Pacific."},"slender-seahorse":{"id":"slender-seahorse","name":"Slender seahorse","aliases":["longsnout seahorse","Brazilian seahorse","Hippocampus reidi"],"kind":"creature","group":"fish","fact":"The slender seahorse of the Caribbean and Brazil is a popular aquarium species that comes in yellow, orange, red and black."},"slender-tuna":{"id":"slender-tuna","name":"Slender tuna","aliases":["Allothunnus fallai"],"kind":"creature","group":"fish","fact":"The slender tuna is a Southern Ocean member of the tuna family that feeds on krill and is rarely seen by anyone but longline crews."},"slingjaw-wrasse":{"id":"slingjaw-wrasse","name":"Slingjaw wrasse","aliases":["sling-jaw wrasse","Epibulus insidiator"],"kind":"creature","group":"fish","fact":"The slingjaw wrasse can shoot its jaws forward to half its body length to snatch prey, the most extreme jaw protrusion of any fish."},"slipper-limpet":{"id":"slipper-limpet","name":"Slipper limpet","aliases":["slipper shell","Crepidula fornicata"],"kind":"creature","group":"molluscs","fact":"Slipper limpets live in stacks, with the males on top turning female as they age, and they have become invasive on European coasts."},"slipper-lobster":{"id":"slipper-lobster","name":"Slipper lobster","aliases":["shovel-nosed lobster","Moreton Bay bug","Balmain bug","flathead lobster","bug"],"kind":"creature","group":"crustaceans","fact":"Slipper lobsters have flat, plate-like antennae instead of long feelers and are sold in Australia as Moreton Bay bugs and Balmain bugs."},"slippery-dick":{"id":"slippery-dick","name":"Slippery dick","aliases":["Halichoeres bivittatus"],"kind":"creature","group":"fish","fact":"The slippery dick is a common Caribbean wrasse named for its slimy, hard-to-hold body; it changes from a striped female to a greener male."},"slit-shell-snail":{"id":"slit-shell-snail","name":"Slit shell snail","aliases":["slit shell","pleurotomariid","Pleurotomariidae"],"kind":"creature","group":"molluscs","fact":"Slit shell snails of deep tropical slopes belong to a family with a fossil record back to the Cambrian, around 500 million years ago, and their shells are prized by collectors."},"sloop":{"id":"sloop","name":"Sloop","aliases":[],"kind":"vessel","group":"boats","fact":"A sloop is a sailing boat with a single mast and one headsail, the most common rig on modern yachts."},"small-spotted-catshark":{"id":"small-spotted-catshark","name":"Small-spotted catshark","aliases":["lesser spotted dogfish","sandy dogfish","rough hound","morgay","Scyliorhinus canicula","catshark"],"kind":"creature","group":"sharks","fact":"The small-spotted catshark lays its eggs in curly-tendrilled cases known as mermaid's purses and is one of the commonest sharks around Britain."},"smallmouth-bass":{"id":"smallmouth-bass","name":"Smallmouth bass","aliases":["smallie","bronzeback","Micropterus dolomieu"],"kind":"creature","group":"fish","fact":"The smallmouth bass prefers cooler, rockier rivers and lakes than its largemouth cousin and fights hard for its size."},"smalltooth-sand-tiger":{"id":"smalltooth-sand-tiger","name":"Smalltooth sand tiger","aliases":["smalltooth sand tiger shark","bumpytail ragged-tooth","Odontaspis ferox"],"kind":"creature","group":"sharks","fact":"The smalltooth sand tiger is a bulky deep-water shark that lives down to around 900 metres and is rarely seen alive."},"smalltooth-sawfish":{"id":"smalltooth-sawfish","name":"Smalltooth sawfish","aliases":["Pristis pectinata"],"kind":"creature","group":"rays","fact":"The smalltooth sawfish was once found from New York to Brazil but now survives mainly in south-west Florida, where it is protected."},"smooth-hammerhead":{"id":"smooth-hammerhead","name":"Smooth hammerhead","aliases":["smooth hammerhead shark","Sphyrna zygaena"],"kind":"creature","group":"sharks","fact":"The smooth hammerhead has no notch in the middle of its head and ranges further into cool water than other hammerheads."},"smooth-handfish":{"id":"smooth-handfish","name":"Smooth handfish","aliases":["Sympterichthys unipennis"],"kind":"creature","group":"fish","fact":"The smooth handfish of Tasmania, known from one specimen collected in 1802, was declared extinct in 2020, the first modern marine fish so listed, though the IUCN later reset it to data deficient."},"smooth-hound":{"id":"smooth-hound","name":"Smooth-hound","aliases":["smoothhound","smooth hound shark","starry smooth-hound","common smooth-hound","Mustelus"],"kind":"creature","group":"sharks","fact":"Smooth-hounds are small, harmless sharks with flat crushing teeth for eating crabs, and anglers catch them along European shores."},"smooth-trunkfish":{"id":"smooth-trunkfish","name":"Smooth trunkfish","aliases":["Lactophrys triqueter","trunkfish"],"kind":"creature","group":"fish","fact":"The smooth trunkfish of the Caribbean blows jets of water into the sand to uncover the worms and crustaceans it eats."},"snailfish":{"id":"snailfish","name":"Snailfish","aliases":["hadal snailfish","Liparidae"],"kind":"creature","group":"fish","fact":"Snailfish are the deepest-living fish known: one was filmed at 8,336 metres in the Izu-Ogasawara Trench in 2022."},"snake-eel":{"id":"snake-eel","name":"Snake eel","aliases":["Ophichthidae","Ophichthus"],"kind":"creature","group":"fish","fact":"Snake eels have a hard, pointed tail that they use to burrow backwards into sand, leaving only the head poking out."},"snake-pipefish":{"id":"snake-pipefish","name":"Snake pipefish","aliases":["Entelurus aequoreus"],"kind":"creature","group":"fish","fact":"The snake pipefish of the north-east Atlantic has almost no tail fin, and its numbers exploded across the North Sea in the mid-2000s."},"snakehead":{"id":"snakehead","name":"Snakehead","aliases":["Channa","northern snakehead","Channa argus"],"kind":"creature","group":"fish","fact":"Snakeheads breathe air with a chamber above their gills and can wriggle short distances over land between ponds."},"snakelocks-anemone":{"id":"snakelocks-anemone","name":"Snakelocks anemone","aliases":["Anemonia viridis","Anemonia sulcata","snakelocks"],"kind":"creature","group":"cnidarians","fact":"The snakelocks anemone cannot fully pull in its long green tentacles, which get their colour from algae living inside them and their purple tips from a pigment."},"snapper":{"id":"snapper","name":"Snapper","aliases":["Lutjanidae","Lutjanus"],"kind":"creature","group":"fish","fact":"Snappers are schooling reef predators prized as food fish, and the red snapper can live for more than 50 years."},"snipe-eel":{"id":"snipe-eel","name":"Snipe eel","aliases":["Nemichthys","Nemichthys scolopaceus","slender snipe eel","Nemichthyidae"],"kind":"creature","group":"fish","fact":"The snipe eel has a body like a ribbon and thin, outward-curving jaws like a bird's beak that cannot close, which it uses to snag shrimp by their antennae."},"snipefish":{"id":"snipefish","name":"Snipefish","aliases":["bellowsfish","Macroramphosus"],"kind":"creature","group":"fish","fact":"The snipefish is a small deep-water relative of seahorses with a long tube snout, named after the wading bird with a long bill."},"snook":{"id":"snook","name":"Snook","aliases":["common snook","Centropomus undecimalis","robalo"],"kind":"creature","group":"fish","fact":"The common snook lives in the mangrove estuaries of Florida and the Gulf of Mexico and changes from male to female as it grows."},"snow-crab":{"id":"snow-crab","name":"Snow crab","aliases":["queen crab","opilio crab","Chionoecetes opilio","zuwai-gani"],"kind":"creature","group":"crustaceans","fact":"Snow crabs live on cold northern seabeds, and billions vanished from the Bering Sea after a marine heatwave, closing the fishery in 2022."},"snow-petrel":{"id":"snow-petrel","name":"Snow petrel","aliases":["Pagodroma nivea"],"kind":"creature","group":"seabirds","fact":"The snow petrel is pure white, breeds farther south than almost any other bird, and has been seen at the South Pole itself."},"snowflake-moray":{"id":"snowflake-moray","name":"Snowflake moray","aliases":["snowflake eel","clouded moray","starry moray","Echidna nebulosa"],"kind":"creature","group":"fish","fact":"The snowflake moray has blunt, pebble-like teeth for crushing crabs and shrimp, and is a popular aquarium moray."},"snowy-grouper":{"id":"snowy-grouper","name":"Snowy grouper","aliases":["Hyporthodus niveatus"],"kind":"creature","group":"fish","fact":"The snowy grouper lives on deep rocky bottoms of the western Atlantic; its juveniles are dotted with white spots like snow."},"sockeye-salmon":{"id":"sockeye-salmon","name":"Sockeye salmon","aliases":["sockeye","red salmon","kokanee","Oncorhynchus nerka"],"kind":"creature","group":"fish","fact":"Sockeye salmon turn brilliant red with green heads when they return from the sea to spawn, and landlocked populations are known as kokanee."},"soft-coral":{"id":"soft-coral","name":"Soft coral","aliases":[],"kind":"creature","group":"corals","fact":"Soft corals have no hard skeleton and sway in the current, supported by tiny limestone needles in their flesh."},"soft-shell-clam":{"id":"soft-shell-clam","name":"Soft-shell clam","aliases":["steamer clam","steamer","Mya arenaria","softshell clam","longneck clam","Ipswich clam"],"kind":"creature","group":"molluscs","fact":"Soft-shell clams, the 'steamers' of New England clam shacks, have a long neck that squirts water when you walk over the mud flat."},"sohal-surgeonfish":{"id":"sohal-surgeonfish","name":"Sohal surgeonfish","aliases":["sohal tang","Acanthurus sohal","Arabian surgeonfish","Arabian tang"],"kind":"creature","group":"fish","fact":"The sohal tang of the Red Sea is a striped surgeonfish with bright orange tail blades that it uses fiercely to defend its territory against divers and other fish."},"soldierfish":{"id":"soldierfish","name":"Soldierfish","aliases":["soldier fish","Myripristis","blackbar soldierfish","Myripristis jacobus"],"kind":"creature","group":"fish","fact":"Soldierfish are red night-active reef fish that grunt, growl and click with swim-bladder muscles to defend their caves."},"sole":{"id":"sole","name":"Sole","aliases":[],"kind":"creature","group":"fish","fact":"Soles are oval, right-eyed flatfish named after the Latin word for a sandal, which the Romans thought they resembled."},"solenette":{"id":"solenette","name":"Solenette","aliases":["Buglossidium luteum","yellow sole"],"kind":"creature","group":"fish","fact":"The solenette is a tiny sole, rarely more than 12 centimetres long, that lies on sandy seabeds around Britain and is thrown back by trawlers."},"solomon-islands":{"id":"solomon-islands","name":"Solomon Islands","aliases":["Solomons","Guadalcanal"],"kind":"place","group":"islands","fact":"The Solomon Islands in the south-west Pacific include Guadalcanal, where a brutal six-month battle was fought in 1942 and 1943."},"solomon-sea":{"id":"solomon-sea","name":"Solomon Sea","aliases":[],"kind":"place","group":"seas","fact":"The Solomon Sea lies between the Solomon Islands and Papua New Guinea and was the scene of fierce naval battles in the Second World War."},"somali-current":{"id":"somali-current","name":"Somali Current","aliases":[],"kind":"place","group":"currents","fact":"The Somali Current off the Horn of Africa is one of the few currents that reverses direction, flowing north in the summer monsoon and south in winter."},"sooty-shearwater":{"id":"sooty-shearwater","name":"Sooty shearwater","aliases":["Ardenna grisea"],"kind":"creature","group":"seabirds","fact":"Sooty shearwaters fly a figure-of-eight loop around the entire Pacific each year, a round trip of about 64,000 kilometres."},"south-american-lungfish":{"id":"south-american-lungfish","name":"South American lungfish","aliases":["Lepidosiren paradoxa"],"kind":"creature","group":"fish","fact":"The South American lungfish breathes mostly with its two lungs and digs a burrow in the mud when its swamp dries out."},"south-american-sea-lion":{"id":"south-american-sea-lion","name":"South American sea lion","aliases":["southern sea lion","Patagonian sea lion","Otaria flavescens"],"kind":"creature","group":"seals","fact":"South American sea lion males have a huge mane-like neck that earned the species its 'lion' name, and some hunt penguins and fur seal pups."},"south-china-sea":{"id":"south-china-sea","name":"South China Sea","aliases":[],"kind":"place","group":"seas","fact":"The South China Sea is a marginal sea of the western Pacific crossed by roughly a third of the world's shipping."},"south-equatorial-current":{"id":"south-equatorial-current","name":"South Equatorial Current","aliases":[],"kind":"place","group":"currents","fact":"The South Equatorial Current flows westward along the equator, and in the Atlantic it splits on the coast of Brazil to feed both the Brazil Current and the Guiana Current."},"south-georgia":{"id":"south-georgia","name":"South Georgia","aliases":["South Georgia Island"],"kind":"place","group":"islands","fact":"South Georgia is a mountainous, glacier-covered island in the South Atlantic where Ernest Shackleton is buried and millions of king penguins and fur seals breed."},"south-polar-skua":{"id":"south-polar-skua","name":"South polar skua","aliases":["Stercorarius maccormicki"],"kind":"creature","group":"seabirds","fact":"The south polar skua breeds on the Antarctic coast, steals penguin eggs and chicks, and has been recorded at the South Pole."},"south-sandwich-trench":{"id":"south-sandwich-trench","name":"South Sandwich Trench","aliases":["Meteor Deep"],"kind":"place","group":"trenches","fact":"The South Sandwich Trench east of the South Sandwich Islands is the deepest trench in the South Atlantic, reaching about 8,300 metres at the Meteor Deep."},"south-shetland-trench":{"id":"south-shetland-trench","name":"South Shetland Trench","aliases":[],"kind":"place","group":"trenches","fact":"The South Shetland Trench north of the Antarctic Peninsula is one of the few ocean trenches in Antarctic waters."},"southern-blue-ringed-octopus":{"id":"southern-blue-ringed-octopus","name":"Southern blue-ringed octopus","aliases":["Hapalochlaena maculosa"],"kind":"creature","group":"cephalopods","fact":"The southern blue-ringed octopus lives in tide pools and shallow reefs of southern Australia and delivers its venom through a bite that is often painless."},"southern-blue-whiting":{"id":"southern-blue-whiting","name":"Southern blue whiting","aliases":["Micromesistius australis"],"kind":"creature","group":"fish","fact":"The southern blue whiting is a cod relative of sub-Antarctic waters fished off New Zealand, Argentina and the Falklands."},"southern-bluefin-tuna":{"id":"southern-bluefin-tuna","name":"Southern bluefin tuna","aliases":["Thunnus maccoyii"],"kind":"creature","group":"fish","fact":"The southern bluefin tuna was fished down to a small fraction of its original numbers and is now ranched in sea pens off South Australia."},"southern-bottlenose-whale":{"id":"southern-bottlenose-whale","name":"Southern bottlenose whale","aliases":["Hyperoodon planifrons"],"kind":"creature","group":"whales","fact":"The southern bottlenose whale feeds near the Antarctic ice edge and is one of the most often sighted beaked whales in the Southern Ocean."},"southern-bull-kelp":{"id":"southern-bull-kelp","name":"Southern bull kelp","aliases":["Durvillaea antarctica","Durvillaea","rimurapa"],"kind":"plant","group":"plants","fact":"Southern bull kelp has a honeycomb-like inner flesh that keeps it afloat, and Māori once used its blades as bags to store food."},"southern-elephant-seal":{"id":"southern-elephant-seal","name":"Southern elephant seal","aliases":["Mirounga leonina","elephant seal"],"kind":"creature","group":"seals","fact":"The southern elephant seal is the largest seal and the largest carnivoran, with bulls weighing up to about 4 tonnes."},"southern-flounder":{"id":"southern-flounder","name":"Southern flounder","aliases":["flounder","Paralichthys lethostigma"],"kind":"creature","group":"fish","fact":"The southern flounder of the Gulf of Mexico is speared at night by 'floundering' anglers wading the shallows with lights."},"southern-right-whale":{"id":"southern-right-whale","name":"Southern right whale","aliases":["Eubalaena australis"],"kind":"creature","group":"whales","fact":"Southern right whales 'sail' by holding their tail flukes up in the wind, and they gather to calve off Argentina, South Africa and Australia."},"southern-right-whale-dolphin":{"id":"southern-right-whale-dolphin","name":"Southern right whale dolphin","aliases":["Lissodelphis peronii"],"kind":"creature","group":"dolphins","fact":"The southern right whale dolphin has no dorsal fin at all and is strikingly black and white."},"southern-stingray":{"id":"southern-stingray","name":"Southern stingray","aliases":["Hypanus americanus","Dasyatis americana"],"kind":"creature","group":"rays","fact":"Southern stingrays gather in the shallows of Stingray City in the Cayman Islands, where they have been hand-fed by visitors for decades."},"sowerbys-beaked-whale":{"id":"sowerbys-beaked-whale","name":"Sowerby's beaked whale","aliases":["North Sea beaked whale","Mesoplodon bidens"],"kind":"creature","group":"whales","fact":"Sowerby's beaked whale was the first beaked whale described, from an animal stranded in the Moray Firth in Scotland in 1800."},"spade-toothed-whale":{"id":"spade-toothed-whale","name":"Spade-toothed whale","aliases":["spade-toothed beaked whale","Bahamonde's beaked whale","Mesoplodon traversii"],"kind":"creature","group":"whales","fact":"The spade-toothed whale is the rarest whale known; only a handful of specimens have ever been found, and none has been seen alive at sea."},"spaghetti-eel":{"id":"spaghetti-eel","name":"Spaghetti eel","aliases":["Moringua","Moringuidae"],"kind":"creature","group":"fish","fact":"Spaghetti eels are extremely thin, worm-like eels of the Indo-Pacific that burrow in sand and are found in rivers as well as the sea."},"spanish-dancer":{"id":"spanish-dancer","name":"Spanish dancer","aliases":["Hexabranchus sanguineus"],"kind":"creature","group":"molluscs","fact":"The Spanish dancer is a large red nudibranch that swims by flapping its body like a flamenco skirt and lays a red rose-shaped ribbon of eggs."},"spanish-hogfish":{"id":"spanish-hogfish","name":"Spanish hogfish","aliases":["Bodianus rufus"],"kind":"creature","group":"fish","fact":"The Spanish hogfish is a purple-and-yellow Caribbean wrasse whose juveniles work as cleaners on larger fish."},"spanish-mackerel":{"id":"spanish-mackerel","name":"Spanish mackerel","aliases":["Atlantic Spanish mackerel","Scomberomorus maculatus"],"kind":"creature","group":"fish","fact":"The Atlantic Spanish mackerel is a spotted, fast-swimming schooling fish of the US east coast and Gulf of Mexico, popular with anglers and on the plate."},"spanish-shawl":{"id":"spanish-shawl","name":"Spanish shawl","aliases":["Flabellinopsis iodinea","Flabellina iodinea"],"kind":"creature","group":"molluscs","fact":"The Spanish shawl is a purple nudibranch of the California coast with orange frills, which it waves while swimming to escape predators."},"spanner-crab":{"id":"spanner-crab","name":"Spanner crab","aliases":["Ranina ranina","red frog crab","kona crab"],"kind":"creature","group":"crustaceans","fact":"The spanner crab walks forwards instead of sideways and has flattened claws shaped like spanners, used to dig into sand."},"sparkling-gourami":{"id":"sparkling-gourami","name":"Sparkling gourami","aliases":["pygmy gourami","Trichopsis pumila","dwarf croaking gourami"],"kind":"creature","group":"fish","fact":"The sparkling gourami is a 4-centimetre fish from Southeast Asia that makes audible croaking sounds when courting or fighting."},"speckled-hind":{"id":"speckled-hind","name":"Speckled hind","aliases":["Epinephelus drummondhayi","Kitty Mitchell","strawberry grouper"],"kind":"creature","group":"fish","fact":"The speckled hind is a deep-water grouper of the southeastern US, dusted with tiny white spots, so overfished that it is now protected."},"spectacled-porpoise":{"id":"spectacled-porpoise","name":"Spectacled porpoise","aliases":["Phocoena dioptrica"],"kind":"creature","group":"dolphins","fact":"The spectacled porpoise has dark rings around its eyes like glasses and lives in cold sub-Antarctic waters, where it is rarely seen alive."},"sperm-whale":{"id":"sperm-whale","name":"Sperm whale","aliases":["cachalot","Physeter macrocephalus"],"kind":"creature","group":"whales","fact":"Sperm whales dive over 2 kilometres deep hunting squid and have the largest brain of any animal."},"spider-crab":{"id":"spider-crab","name":"Spider crab","aliases":["European spider crab","spiny spider crab","Maja squinado","Maja brachydactyla"],"kind":"creature","group":"crustaceans","fact":"European spider crabs pile up in mounds of hundreds during their summer moult and decorate their spiny shells with seaweed."},"spine-bellied-sea-snake":{"id":"spine-bellied-sea-snake","name":"Spine-bellied sea snake","aliases":["Shaw's sea snake","short sea snake","Hydrophis curtus","Lapemis curtus"],"kind":"creature","group":"reptiles","fact":"The spine-bellied sea snake is a stout, aggressive sea snake often caught in trawl nets off Australia and Southeast Asia."},"spined-pygmy-shark":{"id":"spined-pygmy-shark","name":"Spined pygmy shark","aliases":["Squaliolus laticaudus"],"kind":"creature","group":"sharks","fact":"The spined pygmy shark is one of the smallest sharks, about 25 centimetres long, and glows from its belly far below the surface."},"spinner-dolphin":{"id":"spinner-dolphin","name":"Spinner dolphin","aliases":["long-snouted spinner dolphin","Hawaiian spinner dolphin","Stenella longirostris"],"kind":"creature","group":"dolphins","fact":"Spinner dolphins leap and spin several times in the air, and rest in shallow bays by day after hunting offshore at night."},"spinner-shark":{"id":"spinner-shark","name":"Spinner shark","aliases":["Carcharhinus brevipinna"],"kind":"creature","group":"sharks","fact":"Spinner sharks charge up through schools of fish and burst from the water spinning, sometimes turning three times in the air."},"spiny-chromis":{"id":"spiny-chromis","name":"Spiny chromis","aliases":["Acanthochromis polyacanthus","spiny damselfish"],"kind":"creature","group":"fish","fact":"The spiny chromis of the Great Barrier Reef is unusual among reef fish in that both parents guard their young for weeks after hatching."},"spiny-dogfish":{"id":"spiny-dogfish","name":"Spiny dogfish","aliases":["dogfish","spurdog","piked dogfish","Squalus acanthias","rock salmon"],"kind":"creature","group":"sharks","fact":"Spiny dogfish carry their pups for up to two years, one of the longest pregnancies of any vertebrate."},"spiny-lobster":{"id":"spiny-lobster","name":"Spiny lobster","aliases":["rock lobster","langouste","Caribbean spiny lobster","Panulirus","sea crayfish"],"kind":"creature","group":"crustaceans","fact":"Spiny lobsters have no big claws and march across the seabed in single-file lines of dozens during autumn migrations."},"spiny-starfish":{"id":"spiny-starfish","name":"Spiny starfish","aliases":["Marthasterias glacialis"],"kind":"creature","group":"echinoderms","fact":"The spiny starfish of European coasts can reach about 70 centimetres across and is armed with rows of blunt spines ringed by tiny pincers."},"splendid-toadfish":{"id":"splendid-toadfish","name":"Splendid toadfish","aliases":["Cozumel splendid toadfish","Sanopus splendidus"],"kind":"creature","group":"fish","fact":"The splendid toadfish is found only around Cozumel, Mexico, where it hides under coral ledges and whistles to attract mates."},"sponge":{"id":"sponge","name":"Sponge","aliases":["sea sponge"],"kind":"creature","group":"sponges","fact":"Sponges are the simplest animals, with no organs or nerves, yet a carnivorous sponge was dredged from 9,990 metres in the Philippine Trench."},"sponge-crab":{"id":"sponge-crab","name":"Sponge crab","aliases":["Dromia","Dromiidae","dromiid crab"],"kind":"creature","group":"crustaceans","fact":"Sponge crabs cut a living sponge to size and hold it over their backs with their hind legs as a hat that grows with them."},"spot-prawn":{"id":"spot-prawn","name":"Spot prawn","aliases":["spot shrimp","Pandalus platyceros","Alaskan spot prawn"],"kind":"creature","group":"crustaceans","fact":"The spot prawn is the largest shrimp on the North American Pacific coast and is eaten raw as amaebi in sushi bars."},"spotted-boxfish":{"id":"spotted-boxfish","name":"Spotted boxfish","aliases":["Ostracion meleagris"],"kind":"creature","group":"fish","fact":"Male spotted boxfish are blue with gold spots while females are black with white spots, so different that they were once thought to be separate species."},"spotted-drum":{"id":"spotted-drum","name":"Spotted drum","aliases":["Equetus punctatus"],"kind":"creature","group":"fish","fact":"The spotted drum of the Caribbean has a tall ribbon-like dorsal fin as a juvenile and hides under ledges by day to feed at night."},"spotted-eagle-ray":{"id":"spotted-eagle-ray","name":"Spotted eagle ray","aliases":["white-spotted eagle ray","Aetobatus narinari","eagle ray"],"kind":"creature","group":"rays","fact":"Spotted eagle rays can leap clear of the water and have a white-spotted back and a whip-like tail armed with venomous spines."},"spotted-garden-eel":{"id":"spotted-garden-eel","name":"Spotted garden eel","aliases":["Heteroconger hassi"],"kind":"creature","group":"fish","fact":"The spotted garden eel lives in colonies of hundreds on Indo-Pacific sand slopes, each eel anchored tail-first in its own burrow."},"spotted-handfish":{"id":"spotted-handfish","name":"Spotted handfish","aliases":["Brachionichthys hirsutus"],"kind":"creature","group":"fish","fact":"The spotted handfish of Tasmania walks along the seabed on hand-like fins and is critically endangered, with only a few thousand left."},"spotted-jelly":{"id":"spotted-jelly","name":"Spotted jelly","aliases":["golden jellyfish","Mastigias papua","lagoon jelly","Palau jellyfish"],"kind":"creature","group":"jellies","fact":"Millions of golden jellyfish follow the sun across Palau's Jellyfish Lake each day to feed the algae in their tissues, and their sting is too mild to notice."},"spotted-ratfish":{"id":"spotted-ratfish","name":"Spotted ratfish","aliases":["Hydrolagus colliei","ratfish","chimaera"],"kind":"creature","group":"fish","fact":"The spotted ratfish, a chimaera with rabbit-like teeth and a rat-like tail, carries a venomous spine on its back."},"spotted-seahorse":{"id":"spotted-seahorse","name":"Spotted seahorse","aliases":["common seahorse","yellow seahorse","estuary seahorse","Hippocampus kuda"],"kind":"creature","group":"fish","fact":"The spotted seahorse of the Indo-Pacific is one of the species most heavily traded dried for use in traditional medicine."},"spotted-seal":{"id":"spotted-seal","name":"Spotted seal","aliases":["largha seal","Phoca largha"],"kind":"creature","group":"seals","fact":"Spotted seals breed on the sea ice of the Bering and Okhotsk Seas and are closely related to harbour seals."},"spotted-seatrout":{"id":"spotted-seatrout","name":"Spotted seatrout","aliases":["speckled trout","spotted sea trout","speck","Cynoscion nebulosus"],"kind":"creature","group":"fish","fact":"The spotted seatrout, a drum rather than a trout, makes staccato drumming calls at dusk in spawning season across Gulf of Mexico estuaries."},"spotted-wobbegong":{"id":"spotted-wobbegong","name":"Spotted wobbegong","aliases":["Orectolobus maculatus"],"kind":"creature","group":"sharks","fact":"The spotted wobbegong lies camouflaged on Australian reefs, usually under 2 metres long though reported up to about 3, and has bitten people who stepped on or disturbed it."},"sprat":{"id":"sprat","name":"Sprat","aliases":["European sprat","Sprattus sprattus","brisling"],"kind":"creature","group":"fish","fact":"Sprats are tiny herring relatives caught by the hundreds of thousands of tonnes, smoked whole in Baltic countries and tinned as 'brisling sardines'."},"squat-lobster":{"id":"squat-lobster","name":"Squat lobster","aliases":["Galatheidae","Munida"],"kind":"creature","group":"crustaceans","fact":"Squat lobsters are flattened crab-like relatives of hermit crabs that tuck their tails under their bodies and swarm on deep-sea coral and vent fields."},"squid":{"id":"squid","name":"Squid","aliases":["calamari","ika","Teuthida","Loligo"],"kind":"creature","group":"cephalopods","fact":"Squid swim by jet propulsion, squirting water from a flexible funnel, and some species can launch themselves clear of the surface."},"squirrelfish":{"id":"squirrelfish","name":"Squirrelfish","aliases":["soldierfish","squirrel fish","Holocentrinae","Holocentrus adscensionis","Holocentrus"],"kind":"creature","group":"fish","fact":"Squirrelfish are red, big-eyed reef fish that hide in caves by day and come out to hunt at night."},"ss-central-america":{"id":"ss-central-america","name":"SS Central America","aliases":["Central America","Ship of Gold"],"kind":"vessel","group":"wrecks","fact":"The SS Central America, the 'Ship of Gold', sank in an 1857 hurricane with tonnes of California gold, and was found in 1988 about 2,200 metres down off the Carolinas."},"ss-gairsoppa":{"id":"ss-gairsoppa","name":"SS Gairsoppa","aliases":["Gairsoppa"],"kind":"vessel","group":"wrecks","fact":"The SS Gairsoppa, torpedoed in 1941, was found in 2011 about 4,700 metres down, and more than 100 tonnes of silver were recovered from it, the deepest such salvage."},"ss-rio-grande":{"id":"ss-rio-grande","name":"SS Rio Grande","aliases":["Rio Grande"],"kind":"vessel","group":"wrecks","fact":"The German blockade runner Rio Grande, sunk in 1944, was found in 1996 at 5,762 metres in the South Atlantic and held the record for the deepest shipwreck for decades."},"ss-thistlegorm":{"id":"ss-thistlegorm","name":"SS Thistlegorm","aliases":["Thistlegorm"],"kind":"vessel","group":"wrecks","fact":"The SS Thistlegorm, a British freighter sunk in the Red Sea in 1941, still holds motorbikes, trucks and locomotives and is among the most dived wrecks anywhere."},"ss-yongala":{"id":"ss-yongala","name":"SS Yongala","aliases":["Yongala","Yongala wreck"],"kind":"vessel","group":"wrecks","fact":"The SS Yongala sank in a cyclone off Queensland in 1911 with everyone aboard, and the wreck is now smothered in corals and giant groupers."},"st-helena":{"id":"st-helena","name":"St Helena","aliases":["Saint Helena"],"kind":"place","group":"islands","fact":"St Helena is a remote volcanic island in the South Atlantic where Napoleon was exiled from 1815 until his death in 1821."},"st-johns":{"id":"st-johns","name":"St. John's","aliases":["Saint John's","St John's, Newfoundland"],"kind":"place","group":"ports","fact":"St. John's, Newfoundland, is the easternmost city in North America and one of the oldest English settlements on the continent."},"staghorn-coral":{"id":"staghorn-coral","name":"Staghorn coral","aliases":["Acropora cervicornis"],"kind":"creature","group":"corals","fact":"Staghorn coral grows fast in antler-like branches, but Caribbean staghorn has declined by more than 90 per cent since the 1980s."},"stalked-jellyfish":{"id":"stalked-jellyfish","name":"Stalked jellyfish","aliases":["stauromedusa","Haliclystus","kaleidoscope jellyfish"],"kind":"creature","group":"jellies","fact":"Stalked jellyfish are tiny trumpet-shaped jellyfish that live upside down, glued by a stalk to seaweed and seagrass instead of swimming."},"star-coral":{"id":"star-coral","name":"Star coral","aliases":["great star coral","boulder star coral","Montastraea","Orbicella"],"kind":"creature","group":"corals","fact":"Star corals build the massive boulders of Caribbean reefs, and their polyps leave star-shaped cups in the skeleton."},"star-sucker-pygmy-octopus":{"id":"star-sucker-pygmy-octopus","name":"Star-sucker pygmy octopus","aliases":["Octopus wolfi","Wolfi octopus"],"kind":"creature","group":"cephalopods","fact":"The star-sucker pygmy octopus is the smallest known octopus, about 2.5 centimetres long and weighing less than a gram."},"stargazer":{"id":"stargazer","name":"Stargazer","aliases":["Uranoscopidae","Uranoscopus","northern stargazer","Astroscopus"],"kind":"creature","group":"fish","fact":"Stargazers bury themselves in sand with only their upward-facing eyes showing, and some species can give an electric shock."},"starry-flounder":{"id":"starry-flounder","name":"Starry flounder","aliases":["Platichthys stellatus"],"kind":"creature","group":"fish","fact":"The starry flounder can be left- or right-eyed and is named for the star-shaped spiny scales scattered across its skin."},"stejnegers-beaked-whale":{"id":"stejnegers-beaked-whale","name":"Stejneger's beaked whale","aliases":["Bering Sea beaked whale","saber-toothed whale","Mesoplodon stejnegeri"],"kind":"creature","group":"whales","fact":"Stejneger's beaked whale, also called the Bering Sea beaked whale, lives in cold North Pacific waters and often strands in the Aleutian Islands."},"steller-sea-lion":{"id":"steller-sea-lion","name":"Steller sea lion","aliases":["Steller's sea lion","northern sea lion","Eumetopias jubatus"],"kind":"creature","group":"seals","fact":"Steller sea lions are the largest sea lions, with bulls reaching about a tonne, and are named after naturalist Georg Steller."},"stellers-sea-cow":{"id":"stellers-sea-cow","name":"Steller's sea cow","aliases":["Hydrodamalis gigas","Steller sea cow"],"kind":"creature","group":"mammals","fact":"Steller's sea cow, an 8-metre relative of the dugong, was hunted to extinction within about 27 years of its discovery in 1741."},"stellers-sea-eagle":{"id":"stellers-sea-eagle","name":"Steller's sea eagle","aliases":["Haliaeetus pelagicus"],"kind":"creature","group":"birds","fact":"Steller's sea eagle, one of the heaviest eagles in the world, catches salmon and cod along the coasts of Kamchatka and winters in Hokkaido."},"stellwagen-bank":{"id":"stellwagen-bank","name":"Stellwagen Bank","aliases":["Stellwagen Bank National Marine Sanctuary"],"kind":"place","group":"features","fact":"Stellwagen Bank, a sandy plateau at the mouth of Massachusetts Bay, is a national marine sanctuary famous for its humpback whale watching."},"stethacanthus":{"id":"stethacanthus","name":"Stethacanthus","aliases":["anvil shark"],"kind":"creature","group":"sharks","fact":"Stethacanthus was a small shark of about 360 million years ago whose males carried a flat, anvil-shaped dorsal fin topped with tooth-like scales."},"stingray":{"id":"stingray","name":"Stingray","aliases":["sting ray","ray"],"kind":"creature","group":"rays","fact":"A stingray's venomous barb is a modified scale on its tail, used only in self-defence when the ray is stepped on or threatened."},"stokes-sea-snake":{"id":"stokes-sea-snake","name":"Stokes's sea snake","aliases":["Stokes' sea snake","Hydrophis stokesii","Astrotia stokesii"],"kind":"creature","group":"reptiles","fact":"Stokes's sea snake is one of the heaviest sea snakes, with a thick body and the longest fangs of any sea snake."},"stone-crab":{"id":"stone-crab","name":"Stone crab","aliases":["Florida stone crab","Menippe mercenaria"],"kind":"creature","group":"crustaceans","fact":"Florida stone crabs are fished for their claws alone: a claw is removed and the live crab is returned to the sea to grow a new one."},"stonefish":{"id":"stonefish","name":"Stonefish","aliases":["reef stonefish","Synanceia","Synanceia verrucosa"],"kind":"creature","group":"fish","fact":"The stonefish is the most venomous fish known, with 13 dorsal spines, and lies half-buried in sand looking exactly like an encrusted rock."},"stony-coral":{"id":"stony-coral","name":"Stony coral","aliases":["hard coral","scleractinian","Scleractinia"],"kind":"creature","group":"corals","fact":"Stony corals are the reef builders, each polyp laying down a cup of limestone so that colonies slowly pile up into reefs."},"stoplight-loosejaw":{"id":"stoplight-loosejaw","name":"Stoplight loosejaw","aliases":["Malacosteus","Malacosteus niger","loosejaw"],"kind":"creature","group":"fish","fact":"The stoplight loosejaw shines a red searchlight that most deep-sea animals cannot see, and has a jaw with no floor so it can snap shut faster."},"stoplight-parrotfish":{"id":"stoplight-parrotfish","name":"Stoplight parrotfish","aliases":["Sparisoma viride"],"kind":"creature","group":"fish","fact":"The stoplight parrotfish of the Caribbean changes from a mottled red-and-brown female phase to a green male with a yellow spot, like a traffic light."},"stout-infantfish":{"id":"stout-infantfish","name":"Stout infantfish","aliases":["Schindleria brevipinguis"],"kind":"creature","group":"fish","fact":"The stout infantfish of the Great Barrier Reef matures at about 7 to 8 millimetres and weighs about a milligram, one of the smallest and lightest vertebrates."},"strait-of-bonifacio":{"id":"strait-of-bonifacio","name":"Strait of Bonifacio","aliases":["Bonifacio Strait"],"kind":"place","group":"straits","fact":"The Strait of Bonifacio separates Corsica from Sardinia and is notorious for strong winds and shipwrecks."},"strait-of-dover":{"id":"strait-of-dover","name":"Strait of Dover","aliases":["Dover Strait","Pas de Calais"],"kind":"place","group":"straits","fact":"The Strait of Dover is the narrowest part of the English Channel, about 33 kilometres wide, and one of the busiest shipping lanes in the world."},"strait-of-gibraltar":{"id":"strait-of-gibraltar","name":"Strait of Gibraltar","aliases":["Gibraltar Strait","Straits of Gibraltar"],"kind":"place","group":"straits","fact":"The Strait of Gibraltar joins the Atlantic to the Mediterranean and is only about 14 kilometres wide at its narrowest, between Spain and Morocco."},"strait-of-hormuz":{"id":"strait-of-hormuz","name":"Strait of Hormuz","aliases":["Hormuz Strait","Hormuz"],"kind":"place","group":"straits","fact":"The Strait of Hormuz connects the Persian Gulf to the Gulf of Oman, and about a fifth of the world's oil passes through it."},"strait-of-juan-de-fuca":{"id":"strait-of-juan-de-fuca","name":"Strait of Juan de Fuca","aliases":["Juan de Fuca Strait"],"kind":"place","group":"straits","fact":"The Strait of Juan de Fuca between Washington state and Vancouver Island is named after a Greek sailor, known by his Spanish name Juan de Fuca, who claimed to have found it in 1592."},"strait-of-magellan":{"id":"strait-of-magellan","name":"Strait of Magellan","aliases":["Magellan Strait","Straits of Magellan"],"kind":"place","group":"straits","fact":"The Strait of Magellan, named after Ferdinand Magellan who sailed through it in 1520, lets ships pass between the Atlantic and Pacific south of mainland South America."},"strait-of-malacca":{"id":"strait-of-malacca","name":"Strait of Malacca","aliases":["Malacca Strait","Straits of Malacca"],"kind":"place","group":"straits","fact":"The Strait of Malacca between Malaysia and Sumatra is one of the busiest shipping lanes in the world, linking the Indian Ocean to the South China Sea."},"strait-of-messina":{"id":"strait-of-messina","name":"Strait of Messina","aliases":["Messina Strait"],"kind":"place","group":"straits","fact":"The Strait of Messina between Sicily and mainland Italy is home to the whirlpools behind the legend of Scylla and Charybdis."},"strait-of-otranto":{"id":"strait-of-otranto","name":"Strait of Otranto","aliases":["Otranto Strait"],"kind":"place","group":"straits","fact":"The Strait of Otranto between Italy and Albania is the gateway from the Ionian Sea into the Adriatic."},"strap-toothed-whale":{"id":"strap-toothed-whale","name":"Strap-toothed whale","aliases":["strap-toothed beaked whale","Layard's beaked whale","Mesoplodon layardii"],"kind":"creature","group":"whales","fact":"Male strap-toothed whales, also called Layard's beaked whales, grow two tusks that curl over the upper jaw and stop the mouth opening more than a few centimetres."},"strawberry-squid":{"id":"strawberry-squid","name":"Strawberry squid","aliases":["Histioteuthis heteropsis","cock-eyed squid","jewel squid"],"kind":"creature","group":"cephalopods","fact":"The strawberry squid has one big eye that looks up for shadows and one small eye that looks down for flashes of light, and skin dotted with photophores."},"striped-bass":{"id":"striped-bass","name":"Striped bass","aliases":["striper","rockfish","Atlantic striped bass","Morone saxatilis","striped sea bass"],"kind":"creature","group":"fish","fact":"Striped bass spawn in rivers such as the Hudson and the tributaries of Chesapeake Bay and spend their adult lives roaming the Atlantic coast."},"striped-bonito":{"id":"striped-bonito","name":"Striped bonito","aliases":["Sarda orientalis","oriental bonito","hagatsuo"],"kind":"creature","group":"fish","fact":"The striped bonito of the Indo-Pacific is eaten as sashimi in Japan, where it is called hagatsuo."},"striped-dolphin":{"id":"striped-dolphin","name":"Striped dolphin","aliases":["streaker","Stenella coeruleoalba"],"kind":"creature","group":"dolphins","fact":"Striped dolphins are fast, acrobatic dolphins with blue-black stripes and are the most common dolphin in the Mediterranean."},"striped-eel-catfish":{"id":"striped-eel-catfish","name":"Striped eel catfish","aliases":["Plotosus lineatus","coral catfish","eeltail catfish"],"kind":"creature","group":"fish","fact":"Juvenile striped eel catfish swarm in tight balls on reefs, and each one carries venomous spines that have caused rare human deaths."},"striped-marlin":{"id":"striped-marlin","name":"Striped marlin","aliases":["Kajikia audax","Tetrapturus audax"],"kind":"creature","group":"fish","fact":"The striped marlin hunts in packs off Baja California, where it herds sardine bait balls at high speed and lights up its stripes as it attacks."},"striped-mullet":{"id":"striped-mullet","name":"Striped mullet","aliases":["mullet","grey mullet","flathead grey mullet","flathead mullet","Mugil cephalus"],"kind":"creature","group":"fish","fact":"Striped mullet wander freely between the sea, estuaries and completely fresh water, but spawn offshore in the open sea."},"striped-raphael-catfish":{"id":"striped-raphael-catfish","name":"Striped Raphael catfish","aliases":["talking catfish","striped Raphael","Platydoras armatulus","Platydoras costatus","humbug catfish"],"kind":"creature","group":"fish","fact":"The striped Raphael catfish, a 'talking catfish', squeaks by grinding its pectoral spines and is armoured with a row of sharp plates along each side."},"sturgeon":{"id":"sturgeon","name":"Sturgeon","aliases":["Acipenser","Acipenseridae","white sturgeon","beluga sturgeon"],"kind":"creature","group":"fish","fact":"Most sturgeons spend their adult lives in the sea or in large lakes and swim up rivers to spawn, and some live for more than 100 years."},"submarine":{"id":"submarine","name":"Submarine","aliases":["sub","U-boat"],"kind":"vessel","group":"boats","fact":"Nuclear submarines can stay underwater for months at a time, limited only by the food they carry for the crew."},"sugar-kelp":{"id":"sugar-kelp","name":"Sugar kelp","aliases":["Saccharina latissima","sugar wrack","sea belt"],"kind":"plant","group":"plants","fact":"Sugar kelp has a long, crinkled single blade and gets its name from the sweet white powder, mannitol, that forms on it when dried."},"sulphide-worm":{"id":"sulphide-worm","name":"Sulphide worm","aliases":["Paralvinella sulfincola","sulfide worm"],"kind":"creature","group":"worms","fact":"The sulphide worm chooses to sit in water of about 50 degrees Celsius on vent chimneys, hotter than any other animal has been shown to prefer."},"sulu-sea":{"id":"sulu-sea","name":"Sulu Sea","aliases":[],"kind":"place","group":"seas","fact":"The Sulu Sea in the south-west Philippines holds the Tubbataha Reefs and is enclosed by Palawan, Borneo and the Sulu Archipelago."},"summer-flounder":{"id":"summer-flounder","name":"Summer flounder","aliases":["fluke","Paralichthys dentatus"],"kind":"creature","group":"fish","fact":"The summer flounder, or fluke, is a left-eyed flatfish prized by anglers on the US east coast and can change colour to match the bottom."},"sun-coral":{"id":"sun-coral","name":"Sun coral","aliases":["orange cup coral","orange sun coral","tube coral","Tubastraea"],"kind":"creature","group":"corals","fact":"Sun coral has no symbiotic algae, so it can grow in dark caves and under piers, opening its bright orange polyps at night to catch plankton."},"sunda-shelf":{"id":"sunda-shelf","name":"Sunda Shelf","aliases":["Sundaland"],"kind":"place","group":"features","fact":"The Sunda Shelf is the drowned extension of mainland South-east Asia, shallow seafloor that linked Borneo, Sumatra and Java to the continent during ice ages."},"sunda-strait":{"id":"sunda-strait","name":"Sunda Strait","aliases":[],"kind":"place","group":"straits","fact":"The Sunda Strait between Java and Sumatra links the Java Sea to the Indian Ocean and holds the volcano Krakatoa."},"sunflower-sea-star":{"id":"sunflower-sea-star","name":"Sunflower sea star","aliases":["sunflower star","sunflower starfish","Pycnopodia helianthoides"],"kind":"creature","group":"echinoderms","fact":"The sunflower sea star has up to 24 arms, speeds along on thousands of tube feet and eats sea urchins, but a wasting disease wiped out most of them after 2013."},"supergiant-amphipod":{"id":"supergiant-amphipod","name":"Supergiant amphipod","aliases":["Alicella gigantea","Alicella","super giant amphipod"],"kind":"creature","group":"crustaceans","fact":"The supergiant amphipod grows to about 34 centimetres, around ten times the size of most amphipods, and was caught 7,000 metres down in the Kermadec Trench."},"surf-clam":{"id":"surf-clam","name":"Surf clam","aliases":["hokkigai","Sakhalin surf clam","Pseudocardium sachalinense","hokki clam"],"kind":"creature","group":"molluscs","fact":"The surf clam, hokkigai, is served in sushi with its tip blanched, which turns the foot a bright red."},"surfperch":{"id":"surfperch","name":"Surfperch","aliases":["seaperch","Embiotocidae","barred surfperch"],"kind":"creature","group":"fish","fact":"Surfperches of the North American Pacific coast give birth to fully formed live young, which is unusual for a marine fish."},"surgeonfish":{"id":"surgeonfish","name":"Surgeonfish","aliases":["tang","Acanthuridae"],"kind":"creature","group":"fish","fact":"Surgeonfish are named for the scalpel-like spines at the base of the tail, and they graze algae that would otherwise smother coral."},"surtsey":{"id":"surtsey","name":"Surtsey","aliases":[],"kind":"place","group":"islands","fact":"Surtsey is a volcanic island off Iceland that rose from the sea in 1963 and has been off limits to all but scientists ever since."},"swamp-eel":{"id":"swamp-eel","name":"Swamp eel","aliases":["Asian swamp eel","Monopterus albus","rice eel"],"kind":"creature","group":"fish","fact":"The Asian swamp eel breathes air, burrows into mud when ponds dry out, and has become an invader of Florida and Georgia wetlands."},"sweetlips":{"id":"sweetlips","name":"Sweetlips","aliases":[],"kind":"creature","group":"fish","fact":"Sweetlips are reef fish named for their thick, fleshy lips, and their juveniles often look nothing like the adults."},"swell-shark":{"id":"swell-shark","name":"Swell shark","aliases":["swellshark","Cephaloscyllium ventriosum"],"kind":"creature","group":"sharks","fact":"The swell shark glows green under blue light and can gulp water to double its size and wedge itself into a crevice when threatened."},"swordfish":{"id":"swordfish","name":"Swordfish","aliases":["broadbill","Xiphias gladius","mekajiki"],"kind":"creature","group":"fish","fact":"Swordfish slash at squid with a flat bill and are among the fastest fish in the sea; their meaty steaks are eaten worldwide and served raw as mekajiki in Japan."},"swordtail":{"id":"swordtail","name":"Swordtail","aliases":["green swordtail","Xiphophorus hellerii"],"kind":"creature","group":"fish","fact":"The male swordtail grows a long blade from the bottom of its tail that females prefer longer, a classic example of sexual selection."},"sydney-rock-oyster":{"id":"sydney-rock-oyster","name":"Sydney rock oyster","aliases":["Saccostrea glomerata"],"kind":"creature","group":"molluscs","fact":"The Sydney rock oyster has been farmed in New South Wales estuaries since the 1870s, making it Australia's oldest aquaculture industry."},"sylvia-earle":{"id":"sylvia-earle","name":"Sylvia Earle","aliases":["Her Deepness"],"kind":"person","group":"people","fact":"Sylvia Earle, nicknamed Her Deepness, set a record in 1979 by walking the sea floor at 381 metres in a pressurised suit and has spent thousands of hours underwater."},"synodontis":{"id":"synodontis","name":"Synodontis catfish","aliases":["Synodontis","squeaker","squeaker catfish","featherfin squeaker","featherfin catfish"],"kind":"creature","group":"fish","fact":"Synodontis catfish of Africa are called squeakers because they chirp by rubbing their pectoral spines; the featherfin squeaker is an aquarium favourite."},"table-coral":{"id":"table-coral","name":"Table coral","aliases":["tabletop coral","plate coral"],"kind":"creature","group":"corals","fact":"Table coral grows outward in broad, flat plates that shade the reef below and give small fish a roof to hide under."},"tahiti":{"id":"tahiti","name":"Tahiti","aliases":["Society Islands"],"kind":"place","group":"islands","fact":"Tahiti is the largest island of French Polynesia, a volcanic peak ringed by reef, where Captain Cook observed the transit of Venus in 1769."},"taimen":{"id":"taimen","name":"Taimen","aliases":["Siberian taimen","Siberian salmon","Hucho taimen"],"kind":"creature","group":"fish","fact":"The taimen of Siberia and Mongolia is the largest salmonid in the world, reaching about 2 metres and living for more than 50 years."},"taiwan-strait":{"id":"taiwan-strait","name":"Taiwan Strait","aliases":["Formosa Strait"],"kind":"place","group":"straits","fact":"The Taiwan Strait separates Taiwan from mainland China and is about 130 kilometres wide at its narrowest."},"tanaid":{"id":"tanaid","name":"Tanaid","aliases":["tanaidacean","Tanaidacea"],"kind":"creature","group":"crustaceans","fact":"Tanaids are tiny, shrimp-like crustaceans that build tubes in the mud and are among the commonest animals in deep trench sediments."},"tarpon":{"id":"tarpon","name":"Tarpon","aliases":["Atlantic tarpon","silver king","Megalops atlanticus"],"kind":"creature","group":"fish","fact":"Tarpon gulp air into a swim bladder that works like a lung, and young tarpon grow up in brackish and freshwater backwaters before moving out to sea."},"tasman-sea":{"id":"tasman-sea","name":"Tasman Sea","aliases":["the Ditch"],"kind":"place","group":"seas","fact":"The Tasman Sea between Australia and New Zealand is named after the Dutch explorer Abel Tasman, who sailed it in 1642, and is nicknamed the Ditch."},"tasmanian-giant-crab":{"id":"tasmanian-giant-crab","name":"Tasmanian giant crab","aliases":["Pseudocarcinus gigas","giant deepwater crab"],"kind":"creature","group":"crustaceans","fact":"The Tasmanian giant crab can weigh more than 13 kilograms and has one huge claw; it lives on the edge of the continental shelf off southern Australia."},"tasmanian-giant-freshwater-crayfish":{"id":"tasmanian-giant-freshwater-crayfish","name":"Tasmanian giant freshwater crayfish","aliases":["Astacopsis gouldi","giant freshwater crayfish","Tasmanian giant crayfish","giant freshwater lobster"],"kind":"creature","group":"crustaceans","fact":"The Tasmanian giant freshwater crayfish is the largest freshwater invertebrate on Earth, once reaching about 6 kilograms, and can live for about 40 years."},"tasselled-wobbegong":{"id":"tasselled-wobbegong","name":"Tasselled wobbegong","aliases":["tasseled wobbegong","Eucrossorhinus dasypogon"],"kind":"creature","group":"sharks","fact":"The tasselled wobbegong has a fringe of branching skin lobes around its head, and one was photographed on the Great Barrier Reef with a whole bamboo shark head-first in its jaws."},"tautog":{"id":"tautog","name":"Tautog","aliases":["blackfish","Tautoga onitis","tog"],"kind":"creature","group":"fish","fact":"The tautog, or blackfish, is a chunky wrasse of the US east coast that sleeps so soundly on the bottom at night that divers can pick it up."},"tawny-nurse-shark":{"id":"tawny-nurse-shark","name":"Tawny nurse shark","aliases":["Nebrius ferrugineus"],"kind":"creature","group":"sharks","fact":"The tawny nurse shark is a docile Indo-Pacific reef shark that sucks prey from crevices and rests in groups in reef caves."},"telescope-octopus":{"id":"telescope-octopus","name":"Telescope octopus","aliases":["Amphitretus pelagicus","Amphitretus"],"kind":"creature","group":"cephalopods","fact":"The telescope octopus is a see-through deep-sea octopus with tubular eyes on stalks that point upward to spot prey against the faint light."},"telescopefish":{"id":"telescopefish","name":"Telescopefish","aliases":["Gigantura","Gigantura indica","telescope fish"],"kind":"creature","group":"fish","fact":"The telescopefish has forward-pointing tubular eyes like a pair of binoculars and can swallow prey longer than itself."},"tench":{"id":"tench","name":"Tench","aliases":["doctor fish","Tinca tinca"],"kind":"creature","group":"fish","fact":"The tench, a slimy olive fish of still European waters, was once believed to heal other fish that rubbed against it."},"tern":{"id":"tern","name":"Tern","aliases":["common tern"],"kind":"creature","group":"seabirds","fact":"Terns hover over the water and then plunge head-first to seize small fish just below the surface."},"thermaic-gulf":{"id":"thermaic-gulf","name":"Thermaic Gulf","aliases":["Gulf of Thessaloniki","Gulf of Salonika","Thermaikos Gulf"],"kind":"place","group":"gulfs","fact":"The Thermaic Gulf is the arm of the Aegean at whose head stands Thessaloniki, Greece's second city."},"thick-billed-murre":{"id":"thick-billed-murre","name":"Thick-billed murre","aliases":["Brünnich's guillemot","thick-billed guillemot","Uria lomvia"],"kind":"creature","group":"seabirds","fact":"Thick-billed murres of Arctic and sub-Arctic seas are among the deepest-diving flying birds, with dives recorded to 150 metres and beyond."},"thimble-jellyfish":{"id":"thimble-jellyfish","name":"Thimble jellyfish","aliases":["Linuche unguiculata"],"kind":"creature","group":"jellies","fact":"The thumb-sized thimble jellyfish's larvae cause 'sea bather's eruption', an itchy rash under swimsuits along Florida and Caribbean beaches."},"thongweed":{"id":"thongweed","name":"Thongweed","aliases":["sea spaghetti","sea thong","Himanthalia elongata","Himanthalia"],"kind":"plant","group":"plants","fact":"Thongweed, or sea spaghetti, grows from a small button into straps up to about 2 metres long and is sold fresh as a sea vegetable."},"thor-heyerdahl":{"id":"thor-heyerdahl","name":"Thor Heyerdahl","aliases":["Heyerdahl"],"kind":"person","group":"people","fact":"Thor Heyerdahl sailed the balsa raft Kon-Tiki about 8,000 kilometres across the Pacific in 1947 to show that ancient people could have made such voyages."},"thornback-ray":{"id":"thornback-ray","name":"Thornback ray","aliases":["thornback skate","roker","Raja clavata"],"kind":"creature","group":"rays","fact":"The thornback ray, the most common skate around Britain, is covered in thorny spines and lays egg cases known as mermaid's purses."},"thorntail-stingray":{"id":"thorntail-stingray","name":"Thorntail stingray","aliases":["black stingray","Dasyatis thetidis"],"kind":"creature","group":"rays","fact":"The thorntail stingray of Australia, New Zealand and South Africa carries rows of thorns along its tail and can reach 1.8 metres across."},"thorny-seahorse":{"id":"thorny-seahorse","name":"Thorny seahorse","aliases":["Hippocampus histrix"],"kind":"creature","group":"fish","fact":"The thorny seahorse is covered in sharp spines and is found across the Indo-Pacific from the Red Sea to Hawaii."},"thracian-sea":{"id":"thracian-sea","name":"Thracian Sea","aliases":[],"kind":"place","group":"seas","fact":"The Thracian Sea is the northernmost part of the Aegean, off the coasts of Greek Thrace and Macedonia and the island of Thasos."},"threadfin-butterflyfish":{"id":"threadfin-butterflyfish","name":"Threadfin butterflyfish","aliases":["Chaetodon auriga","auriga butterflyfish"],"kind":"creature","group":"fish","fact":"The threadfin butterflyfish has a trailing thread on its dorsal fin and a chevron pattern on its sides; it is one of the most widespread Indo-Pacific butterflyfish."},"three-band-anemonefish":{"id":"three-band-anemonefish","name":"Three-band anemonefish","aliases":["three-band clownfish","Amphiprion tricinctus","Marshall Islands anemonefish"],"kind":"creature","group":"fish","fact":"The three-band anemonefish lives only in the Marshall Islands, where some individuals turn almost completely black."},"three-spined-stickleback":{"id":"three-spined-stickleback","name":"Three-spined stickleback","aliases":["stickleback","threespine stickleback","Gasterosteus aculeatus"],"kind":"creature","group":"fish","fact":"Many three-spined sticklebacks live at sea and move into fresh water to breed, where the red-bellied male builds a nest and guards the eggs."},"thresher-shark":{"id":"thresher-shark","name":"Thresher shark","aliases":["thresher","fox shark","common thresher","Alopias vulpinus"],"kind":"creature","group":"sharks","fact":"Thresher sharks whip their enormous tails, which can be as long as their bodies, to stun fish before eating them."},"tidepool-sculpin":{"id":"tidepool-sculpin","name":"Tidepool sculpin","aliases":["sculpin","Oligocottus maculosus"],"kind":"creature","group":"fish","fact":"The tidepool sculpin is a small camouflaged fish that can find its way back to its home pool after being carried to another one."},"tiger-barb":{"id":"tiger-barb","name":"Tiger barb","aliases":["barb","Puntigrus tetrazona"],"kind":"creature","group":"fish","fact":"The tiger barb from Sumatra and Borneo is a striped aquarium favourite that nips fins unless kept in a school of six or more."},"tiger-grouper":{"id":"tiger-grouper","name":"Tiger grouper","aliases":["Mycteroperca tigris"],"kind":"creature","group":"fish","fact":"The tiger grouper is a Caribbean grouper with diagonal tiger stripes that visits cleaning stations to have its gills picked clean by gobies."},"tiger-prawn":{"id":"tiger-prawn","name":"Tiger prawn","aliases":["giant tiger prawn","black tiger prawn","Penaeus monodon","tiger shrimp","Asian tiger shrimp","black tiger shrimp"],"kind":"creature","group":"crustaceans","fact":"The giant tiger prawn grows to about 33 centimetres, one of the largest prawns, and has escaped from farms to invade the Gulf of Mexico."},"tiger-puffer":{"id":"tiger-puffer","name":"Tiger puffer","aliases":["fugu","torafugu","Takifugu rubripes","Japanese pufferfish"],"kind":"creature","group":"fish","fact":"The tiger puffer, torafugu, is the most prized fugu; its liver and ovaries hold a deadly poison, so only licensed chefs in Japan may prepare it as sashimi."},"tiger-shark":{"id":"tiger-shark","name":"Tiger shark","aliases":["Galeocerdo cuvier"],"kind":"creature","group":"sharks","fact":"Young tiger sharks carry the dark stripes that give them their name, and the stripes fade as the shark matures."},"tiger-shovelnose-catfish":{"id":"tiger-shovelnose-catfish","name":"Tiger shovelnose catfish","aliases":["tiger shovelnose","Pseudoplatystoma fasciatum","Pseudoplatystoma","tiger catfish","surubim"],"kind":"creature","group":"fish","fact":"The tiger shovelnose catfish of South America has a long flat snout and bold black stripes, and can grow to over a metre long."},"tiger-tail-seahorse":{"id":"tiger-tail-seahorse","name":"Tiger tail seahorse","aliases":["tigertail seahorse","Hippocampus comes"],"kind":"creature","group":"fish","fact":"The tiger tail seahorse of South-East Asia is named for the dark bands on its tail and, with the common seahorse, makes up most of the Philippine seahorse catch."},"tilapia":{"id":"tilapia","name":"Tilapia","aliases":["Nile tilapia","Oreochromis niloticus","Oreochromis","Mozambique tilapia"],"kind":"creature","group":"fish","fact":"Tilapia is a freshwater fish farmed in warm ponds worldwide and is now one of the most eaten fish on earth; it was raised in ancient Egypt."},"tinkers-butterflyfish":{"id":"tinkers-butterflyfish","name":"Tinker's butterflyfish","aliases":["Chaetodon tinkeri","Hawaiian butterflyfish"],"kind":"creature","group":"fish","fact":"Tinker's butterflyfish is a deep-reef butterflyfish from Hawaii, white with a bold black triangle, so rare that it fetches high prices from aquarists."},"titan-triggerfish":{"id":"titan-triggerfish","name":"Titan triggerfish","aliases":["giant triggerfish","moustache triggerfish","Balistoides viridescens"],"kind":"creature","group":"fish","fact":"The titan triggerfish guards its nest fiercely and will charge and bite divers who swim into the cone-shaped territory above its eggs."},"titanic":{"id":"titanic","name":"Titanic","aliases":["RMS Titanic"],"kind":"vessel","group":"wrecks","fact":"The Titanic lies in two main pieces about 3,800 metres down in the North Atlantic, where Robert Ballard's team found it in 1985."},"tokyo-bay":{"id":"tokyo-bay","name":"Tokyo Bay","aliases":["Edo Bay"],"kind":"place","group":"bays","fact":"Tokyo Bay, the harbour of Tokyo and Yokohama, is where Commodore Perry's black ships arrived in 1853 to open Japan to trade."},"tomato-clownfish":{"id":"tomato-clownfish","name":"Tomato clownfish","aliases":["Amphiprion frenatus","tomato anemonefish","bridled anemonefish"],"kind":"creature","group":"fish","fact":"The tomato clownfish is a red-orange anemonefish with a single white head bar that lives in bubble-tip anemones in the western Pacific."},"tomopteris":{"id":"tomopteris","name":"Tomopteris","aliases":["gossamer worm","Tomopteris worm"],"kind":"creature","group":"worms","fact":"Tomopteris is a transparent swimming worm of the open ocean and one of the very few animals able to make yellow light."},"tonga":{"id":"tonga","name":"Tonga","aliases":["Tongatapu","Friendly Islands"],"kind":"place","group":"islands","fact":"Tonga is a kingdom of about 170 islands in the South Pacific, and the Tonga Trench off its coast is the second-deepest in the world."},"tonga-trench":{"id":"tonga-trench","name":"Tonga Trench","aliases":["Horizon Deep"],"kind":"place","group":"trenches","fact":"The Tonga Trench is the second-deepest trench on Earth, reaching about 10,800 metres at the Horizon Deep."},"tongue-eating-louse":{"id":"tongue-eating-louse","name":"Tongue-eating louse","aliases":["tongue-eating isopod","tongue biter","tongue louse","Cymothoa exigua"],"kind":"creature","group":"crustaceans","fact":"The tongue-eating louse is an isopod that enters a fish through its gills, drains the blood from its tongue, and then takes the tongue's place."},"tonguefish":{"id":"tonguefish","name":"Tonguefish","aliases":["tongue sole","tongue fish","Cynoglossidae"],"kind":"creature","group":"fish","fact":"Tonguefish are tongue-shaped flatfish with both eyes on the left side, and one species lives beside hydrothermal vents in the Pacific."},"top-shell":{"id":"top-shell","name":"Top shell","aliases":["topshell","top snail","painted top shell"],"kind":"creature","group":"molluscs","fact":"Top shells are cone-shaped grazing snails of rocky shores that scrape seaweed and algal film from the rocks."},"tope":{"id":"tope","name":"Tope","aliases":["tope shark","school shark","soupfin shark","snapper shark","Galeorhinus galeus"],"kind":"creature","group":"sharks","fact":"The tope, or school shark, was heavily fished for its vitamin-rich liver oil in the 1940s and can live for over 50 years."},"topknot":{"id":"topknot","name":"Topknot","aliases":["Zeugopterus punctatus","common topknot"],"kind":"creature","group":"fish","fact":"The topknot is a small, rough-scaled flatfish of rocky shores that clings upside-down beneath ledges rather than lying on sand."},"torch-coral":{"id":"torch-coral","name":"Torch coral","aliases":["Euphyllia glabrescens"],"kind":"creature","group":"corals","fact":"Torch coral has long, flowing tentacles tipped with glowing knobs and is a favourite of reef aquarists."},"torres-strait":{"id":"torres-strait","name":"Torres Strait","aliases":[],"kind":"place","group":"straits","fact":"Torres Strait between Australia and New Guinea is named after the Spanish navigator Luis Váez de Torres, who sailed through it in 1606."},"totoaba":{"id":"totoaba","name":"Totoaba","aliases":["Totoaba macdonaldi"],"kind":"creature","group":"fish","fact":"The totoaba, a drum of the Gulf of California, makes booming calls with its swim bladder, the organ now smuggled as a delicacy, which has driven it close to extinction."},"transparent-goby":{"id":"transparent-goby","name":"Transparent goby","aliases":["Aphia minuta"],"kind":"creature","group":"fish","fact":"The transparent goby is a see-through, finger-length fish of European coasts that lives only a year and is eaten by the plateful as whitebait in Italy and Spain."},"transpolar-drift":{"id":"transpolar-drift","name":"Transpolar Drift","aliases":["Transpolar Drift Stream"],"kind":"place","group":"currents","fact":"The Transpolar Drift carries sea ice from Siberia across the North Pole towards Greenland, and it carried Nansen's ship Fram across the Arctic."},"trawler":{"id":"trawler","name":"Trawler","aliases":["fishing trawler","stern trawler","beam trawler"],"kind":"vessel","group":"boats","fact":"A trawler catches fish by dragging a large net, the trawl, through the water or along the seabed behind it."},"trichodesmium":{"id":"trichodesmium","name":"Trichodesmium","aliases":["sea sawdust"],"kind":"creature","group":"microbes","fact":"Trichodesmium, or sea sawdust, is a cyanobacterium that forms floating brown rafts and pulls nitrogen from the air to fertilise the tropical ocean."},"trieste":{"id":"trieste","name":"Trieste","aliases":["Bathyscaphe Trieste"],"kind":"vessel","group":"submersibles","fact":"The bathyscaphe Trieste carried Jacques Piccard and Don Walsh to the bottom of the Challenger Deep in 1960, the first crewed dive to the ocean's deepest point."},"triggerfish":{"id":"triggerfish","name":"Triggerfish","aliases":["trigger","Balistidae"],"kind":"creature","group":"fish","fact":"A triggerfish locks itself into a crevice at night by raising a dorsal spine that can only be released by a second, smaller trigger spine."},"trilobite":{"id":"trilobite","name":"Trilobite","aliases":[],"kind":"creature","group":"arthropods","fact":"Trilobites crawled the seafloor for about 270 million years and were among the first animals with complex eyes before dying out 252 million years ago."},"trimmatom-nanus":{"id":"trimmatom-nanus","name":"Trimmatom nanus","aliases":[],"kind":"creature","group":"fish","fact":"Trimmatom nanus, a goby of the Chagos Islands and Maldives, matures at under 1 centimetre and held the record as the smallest vertebrate from 1981 to 2004."},"triops":{"id":"triops","name":"Triops","aliases":["tadpole shrimp","Triops cancriformis"],"kind":"creature","group":"crustaceans","fact":"Triops tadpole shrimp hatch in temporary pools from eggs that can wait years in dry dust, and tadpole shrimp that look much like them were already around more than 200 million years ago."},"tripletail":{"id":"tripletail","name":"Tripletail","aliases":["Atlantic tripletail","Lobotes surinamensis"],"kind":"creature","group":"fish","fact":"The tripletail floats on its side under buoys and weed in the Gulf of Mexico, pretending to be a drifting leaf."},"tripod-fish":{"id":"tripod-fish","name":"Tripod fish","aliases":["tripodfish","Bathypterois grallator","Bathypterois"],"kind":"creature","group":"fish","fact":"The tripod fish stands motionless on the abyssal floor on three stiff fin rays up to a metre long, facing the current with its mouth open."},"trireme":{"id":"trireme","name":"Trireme","aliases":[],"kind":"vessel","group":"boats","fact":"The trireme was the ancient Greek warship rowed by three banks of oarsmen, which won the Battle of Salamis in 480 BC."},"tristan-da-cunha":{"id":"tristan-da-cunha","name":"Tristan da Cunha","aliases":["Tristan"],"kind":"place","group":"islands","fact":"Tristan da Cunha is the most remote inhabited island in the world, with about 250 people living more than 2,000 kilometres from the nearest inhabited land."},"tritons-trumpet":{"id":"tritons-trumpet","name":"Triton's trumpet","aliases":["giant triton","triton","Charonia tritonis"],"kind":"creature","group":"molluscs","fact":"The Triton's trumpet is a huge sea snail that preys on crown-of-thorns starfish, and its shell has been blown as a horn for centuries."},"trout":{"id":"trout","name":"Trout","aliases":["rainbow trout","Oncorhynchus mykiss","brown trout","steelhead"],"kind":"creature","group":"fish","fact":"Several trout, including brown and rainbow trout, have sea-run forms that feed in the ocean and return to rivers to spawn."},"trues-beaked-whale":{"id":"trues-beaked-whale","name":"True's beaked whale","aliases":["Mesoplodon mirus"],"kind":"creature","group":"whales","fact":"True's beaked whale is named after Frederick True, an American museum curator, and was first filmed underwater in the Azores in 2017."},"trumpetfish":{"id":"trumpetfish","name":"Trumpetfish","aliases":["Aulostomus","Aulostomus maculatus"],"kind":"creature","group":"fish","fact":"The trumpetfish hangs vertically among sea fans and shadows larger fish to sneak up on its prey."},"tsugaru-strait":{"id":"tsugaru-strait","name":"Tsugaru Strait","aliases":[],"kind":"place","group":"straits","fact":"The Tsugaru Strait separates Honshu from Hokkaido and is crossed by the Seikan Tunnel, one of the longest rail tunnels in the world."},"tuamotu-islands":{"id":"tuamotu-islands","name":"Tuamotu Islands","aliases":["Tuamotus","Tuamotu Archipelago"],"kind":"place","group":"islands","fact":"The Tuamotus are the largest chain of coral atolls in the world, about 80 low islands strung across French Polynesia."},"tubbataha-reef":{"id":"tubbataha-reef","name":"Tubbataha Reef","aliases":["Tubbataha","Tubbataha Reefs Natural Park"],"kind":"place","group":"reefs","fact":"The Tubbataha Reefs in the Philippines' Sulu Sea are two coral atolls so rich in life that they were made a UNESCO World Heritage Site."},"tube-anemone":{"id":"tube-anemone","name":"Tube anemone","aliases":["cerianthid","tube-dwelling anemone","Cerianthus"],"kind":"creature","group":"cnidarians","fact":"Tube anemones live inside a slimy tube buried in sand and can withdraw their two rings of long tentacles in a flash when disturbed."},"tucuxi":{"id":"tucuxi","name":"Tucuxi","aliases":["Sotalia fluviatilis"],"kind":"creature","group":"dolphins","fact":"The tucuxi is a small grey dolphin that lives in the Amazon river system yet looks like a miniature bottlenose rather than a river dolphin."},"tugboat":{"id":"tugboat","name":"Tugboat","aliases":["tug","towboat","tug boat"],"kind":"vessel","group":"boats","fact":"Tugboats are small but extremely powerful, built to push and pull ships many times their own size in and out of harbours."},"tuna":{"id":"tuna","name":"Tuna","aliases":["maguro","Thunnus","tunny","Thunnini"],"kind":"creature","group":"fish","fact":"Tunas are warm-blooded, torpedo-shaped sprinters among the fastest fish in the sea; in Japan tuna is maguro, the most popular sushi fish of all."},"turbot":{"id":"turbot","name":"Turbot","aliases":["Scophthalmus maximus","Psetta maxima"],"kind":"creature","group":"fish","fact":"Turbot are prized food fish with a nearly circular body and can change their colour to match the gravel they lie on."},"turneffe-atoll":{"id":"turneffe-atoll","name":"Turneffe Atoll","aliases":["Turneffe Islands","Turneffe"],"kind":"place","group":"reefs","fact":"Turneffe Atoll off Belize is a large coral atoll whose mangrove islands and seagrass lagoons shelter manatees, crocodiles and bonefish."},"turtle-barnacle":{"id":"turtle-barnacle","name":"Turtle barnacle","aliases":["Chelonibia"],"kind":"creature","group":"crustaceans","fact":"Turtle barnacles settle on the shells of sea turtles and ride with them, filtering food from the water as the turtle swims."},"turtle-grass":{"id":"turtle-grass","name":"Turtle grass","aliases":["Thalassia testudinum","Thalassia"],"kind":"plant","group":"plants","fact":"Turtle grass is the dominant seagrass of the Caribbean, grazed by green turtles and manatees."},"turtle-headed-sea-snake":{"id":"turtle-headed-sea-snake","name":"Turtle-headed sea snake","aliases":["turtleheaded sea snake","egg-eating sea snake","Emydocephalus annulatus"],"kind":"creature","group":"reptiles","fact":"The turtle-headed sea snake has almost no teeth and feeds only on fish eggs, which it scrapes from the reef."},"tusk-shell":{"id":"tusk-shell","name":"Tusk shell","aliases":["scaphopod","tooth shell","dentalium"],"kind":"creature","group":"molluscs","fact":"Tusk shells are molluscs with a tapering tubular shell open at both ends, living head-down in sand."},"tuvalu":{"id":"tuvalu","name":"Tuvalu","aliases":["Ellice Islands","Funafuti"],"kind":"place","group":"islands","fact":"Tuvalu is a nation of nine low coral atolls in the Pacific whose highest point is only a few metres above sea level."},"two-banded-anemonefish":{"id":"two-banded-anemonefish","name":"Two-banded anemonefish","aliases":["Red Sea clownfish","Amphiprion bicinctus","Red Sea anemonefish","twoband anemonefish"],"kind":"creature","group":"fish","fact":"The Red Sea clownfish, with two white bars on an orange body, is found only in the Red Sea and the Gulf of Aden."},"tylosaurus":{"id":"tylosaurus","name":"Tylosaurus","aliases":[],"kind":"creature","group":"reptiles","fact":"Tylosaurus, a mosasaur up to about 13 metres long, rammed prey with its bony snout in the shallow sea that once covered Kansas."},"tyrrhenian-sea":{"id":"tyrrhenian-sea","name":"Tyrrhenian Sea","aliases":["Tyrrhenian"],"kind":"place","group":"seas","fact":"The Tyrrhenian Sea, between Italy's west coast, Sardinia, Corsica and Sicily, is named after the Tyrrhenians, the Greek name for the Etruscans."},"umiak":{"id":"umiak","name":"Umiak","aliases":["umiaq","skin boat"],"kind":"vessel","group":"boats","fact":"The umiak is a large open skin boat of the Inuit, rowed or paddled by several people and used for hunting whales and moving families along the coast."},"unicornfish":{"id":"unicornfish","name":"Unicornfish","aliases":["Naso","unicorn fish","bluespine unicornfish"],"kind":"creature","group":"fish","fact":"Unicornfish are large surgeonfish with a horn on the forehead that graze on brown seaweeds on Indo-Pacific reefs."},"upside-down-catfish":{"id":"upside-down-catfish","name":"Upside-down catfish","aliases":["Synodontis nigriventris","blotched upside-down catfish"],"kind":"creature","group":"fish","fact":"The upside-down catfish of the Congo basin habitually swims belly-up to feed at the surface, and its belly is darker than its back as a result."},"upside-down-jellyfish":{"id":"upside-down-jellyfish","name":"Upside-down jellyfish","aliases":["Cassiopea","upside down jelly","mangrove jellyfish"],"kind":"creature","group":"jellies","fact":"The upside-down jellyfish lies on its back in mangrove shallows so the algae in its arms get sunlight, and releases stinging blobs of mucus into the water."},"uss-albatross":{"id":"uss-albatross","name":"Albatross (research ship)","aliases":["USFC Albatross","USS Albatross","Albatross"],"kind":"vessel","group":"vessels","fact":"The Albatross, launched in 1882, is often called the first ship built specifically for marine research, and it dredged up thousands of new species."},"uss-arizona":{"id":"uss-arizona","name":"USS Arizona","aliases":["Arizona","battleship Arizona"],"kind":"vessel","group":"wrecks","fact":"The battleship USS Arizona exploded and sank during the attack on Pearl Harbor in December 1941, and its wreck still leaks oil today."},"uss-hornet":{"id":"uss-hornet","name":"USS Hornet","aliases":["Hornet"],"kind":"vessel","group":"wrecks","fact":"The carrier USS Hornet, which launched the Doolittle Raid, was sunk in 1942 and found in 2019 about 5,300 metres down near the Solomon Islands."},"uss-indianapolis":{"id":"uss-indianapolis","name":"USS Indianapolis","aliases":["Indianapolis"],"kind":"vessel","group":"wrecks","fact":"The USS Indianapolis, sunk by a Japanese submarine in 1945 after delivering atomic bomb parts, was found in 2017 about 5,500 metres down in the Philippine Sea."},"uss-johnston":{"id":"uss-johnston","name":"USS Johnston","aliases":["Johnston"],"kind":"vessel","group":"wrecks","fact":"The destroyer USS Johnston, sunk off Samar in 1944, was surveyed in 2021 at 6,469 metres, briefly the deepest shipwreck ever identified."},"uss-lexington":{"id":"uss-lexington","name":"USS Lexington","aliases":["Lexington","Lady Lex"],"kind":"vessel","group":"wrecks","fact":"The carrier USS Lexington, scuttled after the Battle of the Coral Sea in 1942, was found in 2018 about 3,000 metres down with aircraft still intact on the seabed."},"uss-liberty-wreck":{"id":"uss-liberty-wreck","name":"USS Liberty wreck","aliases":["USS Liberty","Liberty wreck","Tulamben wreck"],"kind":"vessel","group":"wrecks","fact":"The USS Liberty, torpedoed in 1942 and pushed into the sea by a volcanic eruption in 1963, lies just off the beach at Tulamben in Bali."},"uss-maine":{"id":"uss-maine","name":"USS Maine","aliases":["Maine","battleship Maine"],"kind":"vessel","group":"wrecks","fact":"USS Maine exploded and sank in Havana harbour in 1898, helping to spark the Spanish-American War."},"uss-monitor":{"id":"uss-monitor","name":"USS Monitor","aliases":["Monitor"],"kind":"vessel","group":"wrecks","fact":"The Civil War ironclad USS Monitor sank in a storm off Cape Hatteras on the last day of 1862; its turret was raised in 2002."},"uss-samuel-b-roberts":{"id":"uss-samuel-b-roberts","name":"USS Samuel B. Roberts","aliases":["Samuel B. Roberts","Sammy B"],"kind":"vessel","group":"wrecks","fact":"The destroyer escort USS Samuel B. Roberts, sunk off Samar in 1944, was surveyed in 2022 at 6,895 metres, the deepest shipwreck ever identified."},"uss-scorpion":{"id":"uss-scorpion","name":"USS Scorpion","aliases":["Scorpion"],"kind":"vessel","group":"wrecks","fact":"The nuclear submarine USS Scorpion was lost with 99 crew in May 1968 and lies about 3,000 metres down south-west of the Azores."},"uss-thresher":{"id":"uss-thresher","name":"USS Thresher","aliases":["Thresher"],"kind":"vessel","group":"wrecks","fact":"The nuclear submarine USS Thresher was lost with 129 people during deep-diving tests in 1963, and its remains lie about 2,600 metres down off New England."},"uss-yorktown":{"id":"uss-yorktown","name":"USS Yorktown","aliases":["Yorktown"],"kind":"vessel","group":"wrecks","fact":"The aircraft carrier USS Yorktown, sunk at the Battle of Midway in 1942, was found by Robert Ballard in 1998 about 5,000 metres down."},"vampire-squid":{"id":"vampire-squid","name":"Vampire squid","aliases":["Vampyroteuthis infernalis","Vampyroteuthis","vampire squid from hell"],"kind":"creature","group":"cephalopods","fact":"The vampire squid lives in oxygen-poor water around 600 to 900 metres down and, instead of ink, squirts a cloud of glowing mucus at threats."},"vancouver-island":{"id":"vancouver-island","name":"Vancouver Island","aliases":[],"kind":"place","group":"islands","fact":"Vancouver Island off Canada's west coast is the largest island on the Pacific coast of the Americas."},"vanuatu":{"id":"vanuatu","name":"Vanuatu","aliases":["New Hebrides"],"kind":"place","group":"islands","fact":"Vanuatu is a chain of about 80 volcanic islands in the South Pacific, including Tanna with its easily visited active volcano, Mount Yasur."},"vaquita":{"id":"vaquita","name":"Vaquita","aliases":["Gulf of California porpoise","cochito","Phocoena sinus"],"kind":"creature","group":"dolphins","fact":"The vaquita, a tiny porpoise of the upper Gulf of California near the Colorado River delta, is the most endangered marine mammal, with perhaps only about 10 left."},"vasa":{"id":"vasa","name":"Vasa","aliases":["Wasa"],"kind":"vessel","group":"wrecks","fact":"The Swedish warship Vasa sank on its maiden voyage in 1628, minutes after leaving Stockholm, and was raised almost intact in 1961."},"vasco-da-gama":{"id":"vasco-da-gama","name":"Vasco da Gama","aliases":["da Gama"],"kind":"person","group":"people","fact":"Vasco da Gama sailed around the Cape of Good Hope to reach India in 1498, opening the sea route from Europe to Asia."},"veined-rapa-whelk":{"id":"veined-rapa-whelk","name":"Veined rapa whelk","aliases":["rapa whelk","Rapana venosa"],"kind":"creature","group":"molluscs","fact":"The veined rapa whelk, a big predatory snail from Japan, invaded the Black Sea and later Chesapeake Bay, where it eats oysters and clams."},"veined-squid":{"id":"veined-squid","name":"Veined squid","aliases":["Loligo forbesii","long-finned squid","Forbes squid"],"kind":"creature","group":"cephalopods","fact":"The veined squid is one of the main squid caught around Britain and Ireland, and can hover in place and change colour in an instant."},"velvet-belly-lanternshark":{"id":"velvet-belly-lanternshark","name":"Velvet belly lanternshark","aliases":["velvet belly","velvet belly lantern shark","Etmopterus spinax"],"kind":"creature","group":"sharks","fact":"The velvet belly lanternshark glows along its underside and even on its dorsal spines, which may warn predators off."},"velvet-crab":{"id":"velvet-crab","name":"Velvet crab","aliases":["velvet swimming crab","devil crab","Necora puber"],"kind":"creature","group":"crustaceans","fact":"The velvet crab of European shores has red eyes, a furry shell and a famously aggressive temper, and is caught for Spanish markets."},"vent-amphipod":{"id":"vent-amphipod","name":"Vent amphipod","aliases":["Ventiella sulfuris","Ventiella"],"kind":"creature","group":"crustaceans","fact":"Ventiella amphipods swarm in dense clouds around East Pacific vents, feeding on bacterial mats and dead tube worms."},"vent-anemone":{"id":"vent-anemone","name":"Vent anemone","aliases":["Marianactis","hydrothermal vent anemone"],"kind":"creature","group":"cnidarians","fact":"Pale sea anemones fringe the cooler edges of hydrothermal vent fields, catching scraps carried past by the warm, murky water."},"vent-barnacle":{"id":"vent-barnacle","name":"Vent barnacle","aliases":["Vulcanolepas","Neolepas","Vulcanolepas osheai","hydrothermal vent barnacle"],"kind":"creature","group":"crustaceans","fact":"Vent barnacles grow in dense clusters on vent chimneys, with long bristly feeding legs coated in filamentous bacteria that are thought to be part of their diet."},"vent-clam":{"id":"vent-clam","name":"Vent clam","aliases":["giant white clam","Calyptogena magnifica","Calyptogena","giant vent clam","hydrothermal vent clam"],"kind":"creature","group":"molluscs","fact":"The giant white vent clam grows to more than 25 centimetres, has bright red flesh full of haemoglobin, and gets its food from bacteria in its gills."},"vent-copepod":{"id":"vent-copepod","name":"Vent copepod","aliases":["dirivultid copepod","Dirivultidae","Stygiopontius"],"kind":"creature","group":"crustaceans","fact":"Dirivultid copepods are found only at hydrothermal vents, where they are often the most numerous animals crawling over tube worms and mussels."},"vent-crab":{"id":"vent-crab","name":"Vent crab","aliases":["Bythograea","Bythograea thermydron","hydrothermal vent crab"],"kind":"creature","group":"crustaceans","fact":"Bythograea vent crabs are the top scavengers and predators of East Pacific vent fields, picking over tube worms, mussels and dead fish."},"vent-limpet":{"id":"vent-limpet","name":"Vent limpet","aliases":["Lepetodrilus","Lepetodrilus elevatus","hydrothermal vent limpet"],"kind":"creature","group":"molluscs","fact":"Tiny Lepetodrilus limpets carpet tube worms and mussels at vents by the thousand, grazing the bacterial film that coats everything."},"vent-mussel":{"id":"vent-mussel","name":"Vent mussel","aliases":["Bathymodiolus","Bathymodiolus thermophilus","hydrothermal vent mussel","deep-sea mussel"],"kind":"creature","group":"molluscs","fact":"Vent mussels pack their gills with bacteria that feed them from the vent chemicals, forming beds thousands strong around warm vents and seeps."},"vent-octopus":{"id":"vent-octopus","name":"Vent octopus","aliases":["Vulcanoctopus hydrothermalis","Vulcanoctopus","hydrothermal vent octopus"],"kind":"creature","group":"cephalopods","fact":"The vent octopus is a small, pale, nearly blind octopus found only around hydrothermal vents on the East Pacific Rise."},"vent-scale-worm":{"id":"vent-scale-worm","name":"Vent scale worm","aliases":["Branchipolynoe","Branchipolynoe symmytilida","mussel scale worm"],"kind":"creature","group":"worms","fact":"Branchipolynoe scale worms live inside the shells of living vent mussels, with special blood that stores oxygen for when the vent water turns foul."},"vent-sea-spider":{"id":"vent-sea-spider","name":"Vent sea spider","aliases":["Sericosura","hydrothermal vent sea spider"],"kind":"creature","group":"sea spiders","fact":"Sericosura sea spiders cluster by the hundred on vent chimneys, sucking up bacterial mats with a tube-like proboscis."},"vent-shrimp":{"id":"vent-shrimp","name":"Vent shrimp","aliases":["Rimicaris","Rimicaris exoculata","hydrothermal vent shrimp","blind vent shrimp"],"kind":"creature","group":"crustaceans","fact":"Rimicaris vent shrimp swarm in thousands on Mid-Atlantic vent chimneys and have no normal eyes, only a light-sensing patch on the back that detects the vents' faint glow."},"vent-spaghetti-worm":{"id":"vent-spaghetti-worm","name":"Vent spaghetti worm","aliases":["Saxipendium coronatum","spaghetti worm"],"kind":"creature","group":"worms","fact":"Vent spaghetti worms are acorn worms that drape themselves over rocks in tangled strands at the Galápagos Rift vents, mopping bacteria off the surface."},"vent-squat-lobster":{"id":"vent-squat-lobster","name":"Vent squat lobster","aliases":["Munidopsis","Munidopsis squat lobster","galatheid crab"],"kind":"creature","group":"crustaceans","fact":"Munidopsis squat lobsters, pale and nearly blind, crawl in crowds around the cooler fringes of vent fields, scavenging whatever drifts their way."},"vent-tonguefish":{"id":"vent-tonguefish","name":"Vent tonguefish","aliases":["Symphurus thermophilus","hydrothermal vent tonguefish","volcano tonguefish"],"kind":"creature","group":"fish","fact":"Symphurus thermophilus is a flatfish that lives in crowds at volcanic vents of the western Pacific, resting on crusts of solid sulphur beside pools of the molten stuff."},"venus-flower-basket":{"id":"venus-flower-basket","name":"Venus' flower basket","aliases":["Euplectella aspergillum","Euplectella"],"kind":"creature","group":"sponges","fact":"The Venus' flower basket is a lattice-like glass sponge in which a pair of shrimp live trapped for life, which is why dried ones are given as wedding gifts in Japan."},"venus-flytrap-anemone":{"id":"venus-flytrap-anemone","name":"Venus flytrap anemone","aliases":["Actinoscyphia","Actinoscyphia aurelia"],"kind":"creature","group":"cnidarians","fact":"The deep-sea Venus flytrap anemone folds its tentacled disc shut around prey, like the plant it is named after."},"venus-girdle":{"id":"venus-girdle","name":"Venus girdle","aliases":["Cestum veneris","Venus's girdle","Venus belt"],"kind":"creature","group":"jellies","fact":"The Venus girdle is a ribbon-shaped, transparent comb jelly up to about 1.5 metres long that ripples through the water like a strip of glass."},"vermilion-snapper":{"id":"vermilion-snapper","name":"Vermilion snapper","aliases":["beeliner","Rhomboplites aurorubens","mingo"],"kind":"creature","group":"fish","fact":"The vermilion snapper, or beeliner, is a slim red snapper relative of the southeastern US that often ends up sold as red snapper."},"victor-vescovo":{"id":"victor-vescovo","name":"Victor Vescovo","aliases":[],"kind":"person","group":"people","fact":"Victor Vescovo became the first person to reach the deepest point of all five oceans, completing the Five Deeps Expedition in 2019."},"vigo":{"id":"vigo","name":"Vigo","aliases":[],"kind":"place","group":"ports","fact":"Vigo, in Galicia, is one of the biggest fishing ports in the world, landing fish from fleets that work the Atlantic as far away as the Falklands."},"violet-sea-snail":{"id":"violet-sea-snail","name":"Violet sea snail","aliases":["Janthina","Janthina janthina","purple sea snail","bubble raft snail","violet snail"],"kind":"creature","group":"molluscs","fact":"The violet sea snail cannot swim: it hangs upside down from a raft of mucus bubbles and drifts until it bumps into a by-the-wind sailor to eat."},"viper-dogfish":{"id":"viper-dogfish","name":"Viper dogfish","aliases":["viper shark","Trigonognathus kabeyai"],"kind":"creature","group":"sharks","fact":"The viper dogfish has needle-like fangs on jaws it can thrust forward, and it glows along its belly in the deep waters off Japan."},"viperfish":{"id":"viperfish","name":"Viperfish","aliases":["Sloane's viperfish","Chauliodus","Chauliodus sloani","Pacific viperfish"],"kind":"creature","group":"fish","fact":"The viperfish's fangs are so long they do not fit inside its mouth, and it has been recorded deeper than 4,000 metres."},"vityaz-trench":{"id":"vityaz-trench","name":"Vityaz Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Vityaz Trench north of Fiji is named after the Soviet research ship Vityaz, which surveyed the Pacific's deepest trenches in the 1950s."},"viviparous-eelpout":{"id":"viviparous-eelpout","name":"Viviparous eelpout","aliases":["eelpout","viviparous blenny","Zoarces viviparus"],"kind":"creature","group":"fish","fact":"The viviparous eelpout of the North and Baltic seas gives birth to fully formed live young, rare among bony fish."},"wadden-sea":{"id":"wadden-sea","name":"Wadden Sea","aliases":[],"kind":"place","group":"seas","fact":"The Wadden Sea is a shallow, tidal stretch of the North Sea with the world's largest unbroken system of intertidal sand and mud flats."},"wahoo":{"id":"wahoo","name":"Wahoo","aliases":["ono","Acanthocybium solandri","peto"],"kind":"creature","group":"fish","fact":"The wahoo is a long, razor-toothed member of the mackerel family and one of the fastest fish in the sea; Hawaiians call it ono, meaning delicious."},"wakame":{"id":"wakame","name":"Wakame","aliases":["Undaria pinnatifida","Undaria","Asian kelp"],"kind":"plant","group":"plants","fact":"Wakame is the brown seaweed in miso soup and seaweed salad; outside Asia it is an invasive species that spread on the hulls of ships."},"walking-catfish":{"id":"walking-catfish","name":"Walking catfish","aliases":["Clarias batrachus"],"kind":"creature","group":"fish","fact":"The walking catfish can breathe air and wriggle across land between ponds, which helped it spread as an invasive species in Florida."},"wallago":{"id":"wallago","name":"Wallago","aliases":["Wallago attu","boal","helicopter catfish","freshwater shark"],"kind":"creature","group":"fish","fact":"The wallago, or freshwater shark of South Asia, is a long, big-mouthed predatory catfish that can exceed 1.5 metres."},"walleye":{"id":"walleye","name":"Walleye","aliases":["Sander vitreus","walleyed pike","pickerel"],"kind":"creature","group":"fish","fact":"Walleye is the most popular eating fish of the Great Lakes region and the state fish of Minnesota."},"walrus":{"id":"walrus","name":"Walrus","aliases":["Odobenus rosmarus"],"kind":"creature","group":"seals","fact":"Walruses use their tusks to haul themselves onto ice, and a big male can weigh over 1,500 kilograms."},"walter-munk":{"id":"walter-munk","name":"Walter Munk","aliases":[],"kind":"person","group":"people","fact":"Walter Munk, called the Einstein of the oceans, predicted surf conditions for the D-Day landings and explained how ocean waves travel across whole oceans."},"walvis-bay":{"id":"walvis-bay","name":"Walvis Bay","aliases":[],"kind":"place","group":"bays","fact":"Walvis Bay on the coast of Namibia is a natural deep-water harbour whose name means whale bay in Afrikaans."},"walvis-ridge":{"id":"walvis-ridge","name":"Walvis Ridge","aliases":[],"kind":"place","group":"features","fact":"The Walvis Ridge is a long volcanic ridge running from the Namibian coast towards Tristan da Cunha, formed by a hotspot as the South Atlantic opened."},"wandering-albatross":{"id":"wandering-albatross","name":"Wandering albatross","aliases":["Diomedea exulans"],"kind":"creature","group":"seabirds","fact":"The wandering albatross has the longest wingspan of any living bird, up to about 3.5 metres, and can circle the Southern Ocean on a single foraging trip."},"warsaw-grouper":{"id":"warsaw-grouper","name":"Warsaw grouper","aliases":["Hyporthodus nigritus","Epinephelus nigritus"],"kind":"creature","group":"fish","fact":"The Warsaw grouper is a huge grouper of deep rocky ledges in the western Atlantic, reaching over 2 metres, with an unusually tall second dorsal spine."},"weakfish":{"id":"weakfish","name":"Weakfish","aliases":["squeteague","grey sea trout","Cynoscion regalis"],"kind":"creature","group":"fish","fact":"The weakfish is a drum of the US Atlantic coast that drums loudly during spawning; its name refers to its tender mouth, which tears on hooks."},"weather-loach":{"id":"weather-loach","name":"Weather loach","aliases":["weatherfish","pond loach","dojo loach","Misgurnus","Misgurnus anguillicaudatus","oriental weatherfish"],"kind":"creature","group":"fish","fact":"The weather loach burrows into mud to survive drought and gets its name from becoming restless when the air pressure drops before a storm."},"weddell-sea":{"id":"weddell-sea","name":"Weddell Sea","aliases":[],"kind":"place","group":"seas","fact":"The Weddell Sea off Antarctica is named after the British sealer James Weddell, who sailed into it in 1823, and its pack ice crushed Shackleton's ship Endurance in 1915."},"weddell-seal":{"id":"weddell-seal","name":"Weddell seal","aliases":["Leptonychotes weddellii"],"kind":"creature","group":"seals","fact":"Weddell seals live further south than any other mammal, under the fast ice of Antarctica, and can dive for over an hour."},"weedy-sea-dragon":{"id":"weedy-sea-dragon","name":"Weedy sea dragon","aliases":["weedy seadragon","common sea dragon","common seadragon","Phyllopteryx taeniolatus"],"kind":"creature","group":"fish","fact":"The male weedy sea dragon carries the pink eggs stuck to the underside of his tail, and the species is the marine emblem of the Australian state of Victoria."},"weever-fish":{"id":"weever-fish","name":"Weever fish","aliases":["weever","lesser weever","greater weever","Echiichthys vipera","Trachinus draco","weeverfish"],"kind":"creature","group":"fish","fact":"The weever fish buries itself in sand with only its venomous black dorsal fin showing, and is the most common cause of fish stings on British beaches."},"wels-catfish":{"id":"wels-catfish","name":"Wels catfish","aliases":["wels","sheatfish","Silurus glanis","European catfish"],"kind":"creature","group":"fish","fact":"The wels catfish of European rivers can grow to over 2.5 metres and has been filmed lunging onto the bank to snatch pigeons."},"west-african-manatee":{"id":"west-african-manatee","name":"West African manatee","aliases":["African manatee","Trichechus senegalensis"],"kind":"creature","group":"mammals","fact":"The West African manatee lives in coastal lagoons and rivers from Senegal to Angola and is the least-studied of the sirenians."},"west-australian-current":{"id":"west-australian-current","name":"West Australian Current","aliases":[],"kind":"place","group":"currents","fact":"The West Australian Current is the cold northward flow on the eastern side of the Indian Ocean gyre, offshore of the warm Leeuwin Current."},"whale":{"id":"whale","name":"Whale","aliases":["baleen whale","great whale"],"kind":"creature","group":"whales","fact":"Baleen whales have no teeth; they gulp or skim water and strain out krill and small fish through fringed plates of keratin in their jaws."},"whale-barnacle":{"id":"whale-barnacle","name":"Whale barnacle","aliases":["Coronula","Coronula diadema"],"kind":"creature","group":"crustaceans","fact":"Whale barnacles grow embedded in the skin of humpback and grey whales, riding along for a free supply of plankton-rich water."},"whale-louse":{"id":"whale-louse","name":"Whale louse","aliases":["cyamid","Cyamidae"],"kind":"creature","group":"crustaceans","fact":"Whale lice are not lice but crustaceans that cling to the skin folds and rough patches of whales, especially right whales."},"whale-shark":{"id":"whale-shark","name":"Whale shark","aliases":["Rhincodon typus"],"kind":"creature","group":"sharks","fact":"The whale shark is the largest fish alive, growing to over 12 metres while feeding on plankton and small fish."},"whaleship-essex":{"id":"whaleship-essex","name":"Essex","aliases":["whaleship Essex"],"kind":"vessel","group":"wrecks","fact":"The whaleship Essex was rammed and sunk by a sperm whale in the Pacific in 1820, inspiring Herman Melville's Moby-Dick."},"whelk":{"id":"whelk","name":"Whelk","aliases":["common whelk","Buccinum undatum","bulot"],"kind":"creature","group":"molluscs","fact":"Common whelks are scavenging and predatory sea snails of the North Atlantic, and their spongy egg masses wash up as 'sea wash balls'."},"whip-coral-goby":{"id":"whip-coral-goby","name":"Whip coral goby","aliases":["wire coral goby","Bryaninops yongei"],"kind":"creature","group":"fish","fact":"The whip coral goby is a tiny fish that spends its whole life clinging to a single strand of whip coral."},"whiplash-squid":{"id":"whiplash-squid","name":"Whip-lash squid","aliases":["Mastigoteuthis","whiplash squid","mastigoteuthid squid"],"kind":"creature","group":"cephalopods","fact":"Whip-lash squid hover over the deep seabed and trail two long, sticky tentacles covered in tiny suckers to catch small prey."},"white-abalone":{"id":"white-abalone","name":"White abalone","aliases":["Haliotis sorenseni"],"kind":"creature","group":"molluscs","fact":"The white abalone of California was the first marine invertebrate listed as endangered in the USA after divers stripped it from the reefs."},"white-bass":{"id":"white-bass","name":"White bass","aliases":["Morone chrysops"],"kind":"creature","group":"fish","fact":"White bass are silver schooling fish of North American lakes and rivers that boil at the surface when chasing shad."},"white-beaked-dolphin":{"id":"white-beaked-dolphin","name":"White-beaked dolphin","aliases":["Lagenorhynchus albirostris"],"kind":"creature","group":"dolphins","fact":"The white-beaked dolphin is a robust cold-water dolphin that ranges north into Arctic waters off Greenland, Svalbard and Norway."},"white-bonnet-anemonefish":{"id":"white-bonnet-anemonefish","name":"White-bonnet anemonefish","aliases":["whitebonnet anemonefish","Amphiprion leucokranos","white-bonnet clownfish"],"kind":"creature","group":"fish","fact":"The white-bonnet anemonefish, with a white cap on its head, is a natural hybrid between the orange skunk clownfish and the orange-fin anemonefish."},"white-clawed-crayfish":{"id":"white-clawed-crayfish","name":"White-clawed crayfish","aliases":["Austropotamobius pallipes"],"kind":"creature","group":"crustaceans","fact":"The white-clawed crayfish, Britain's only native crayfish, is being wiped out by a fungal plague carried by invasive American signal crayfish."},"white-cloud-mountain-minnow":{"id":"white-cloud-mountain-minnow","name":"White Cloud Mountain minnow","aliases":["white cloud","Tanichthys albonubes","White Cloud minnow","poor man's neon tetra"],"kind":"creature","group":"fish","fact":"The White Cloud Mountain minnow is a 4-centimetre fish discovered in 1932 on a mountain near Guangzhou, now almost extinct in the wild while thriving in aquariums."},"white-marlin":{"id":"white-marlin","name":"White marlin","aliases":["Kajikia albida","Tetrapturus albidus"],"kind":"creature","group":"fish","fact":"The white marlin is the smallest Atlantic marlin, a fast, acrobatic billfish prized by anglers off the US east coast."},"white-seabass":{"id":"white-seabass","name":"White seabass","aliases":["white sea bass","Atractoscion nobilis"],"kind":"creature","group":"fish","fact":"The white seabass of the Californian coast is a large drum, not a bass, and is a prize for kayak anglers in the kelp beds."},"white-spotted-octopus":{"id":"white-spotted-octopus","name":"White-spotted octopus","aliases":["Callistoctopus macropus","Atlantic white-spotted octopus","grass octopus","grass scuttle"],"kind":"creature","group":"cephalopods","fact":"The white-spotted octopus hunts at night, flushing bright red with white spots and reaching its long arms deep into coral crevices."},"white-spotted-puffer":{"id":"white-spotted-puffer","name":"White-spotted puffer","aliases":["stars and stripes puffer","Arothron hispidus"],"kind":"creature","group":"fish","fact":"The white-spotted puffer is a common Indo-Pacific puffer with white spots on a grey body and white stripes on the belly."},"white-sturgeon":{"id":"white-sturgeon","name":"White sturgeon","aliases":["Acipenser transmontanus"],"kind":"creature","group":"fish","fact":"The white sturgeon of the Fraser and Columbia rivers is North America's largest freshwater fish, reaching about 6 metres."},"white-tailed-eagle":{"id":"white-tailed-eagle","name":"White-tailed eagle","aliases":["sea eagle","white-tailed sea eagle","erne","Haliaeetus albicilla"],"kind":"creature","group":"birds","fact":"The white-tailed eagle, one of Europe's largest birds of prey, snatches fish from the sea surface and was reintroduced to Scotland in the 1970s."},"whiteleg-shrimp":{"id":"whiteleg-shrimp","name":"Whiteleg shrimp","aliases":["Pacific white shrimp","Litopenaeus vannamei","Penaeus vannamei","vannamei"],"kind":"creature","group":"crustaceans","fact":"The whiteleg shrimp is the most farmed shrimp in the world, raised in ponds from Ecuador to Vietnam and sold by the million as supermarket prawns."},"whites-seahorse":{"id":"whites-seahorse","name":"White's seahorse","aliases":["Sydney seahorse","Hippocampus whitei"],"kind":"creature","group":"fish","fact":"White's seahorse, or Sydney seahorse, lives in New South Wales estuaries and clings to the shark nets of Sydney's swimming enclosures."},"whitetip-reef-shark":{"id":"whitetip-reef-shark","name":"Whitetip reef shark","aliases":["Triaenodon obesus","white tip reef shark"],"kind":"creature","group":"sharks","fact":"Whitetip reef sharks can pump water over their gills while resting, so they spend the day lying motionless in reef caves."},"whiting":{"id":"whiting","name":"Whiting","aliases":["Merlangius merlangus","European whiting"],"kind":"creature","group":"fish","fact":"Whiting is a small, soft-fleshed relative of cod that has long been a cheap staple of British chip shops."},"whydah-gally":{"id":"whydah-gally","name":"Whydah Gally","aliases":["Whydah"],"kind":"vessel","group":"wrecks","fact":"The pirate ship Whydah Gally sank in a storm off Cape Cod in 1717; its wreck, found in 1984, was the first authenticated pirate shipwreck."},"wide-band-anemonefish":{"id":"wide-band-anemonefish","name":"Wide-band anemonefish","aliases":["wide-band clownfish","Amphiprion latezonatus","wideband anemonefish"],"kind":"creature","group":"fish","fact":"The wide-band anemonefish lives only around Lord Howe Island and eastern Australia, with wide white bars that merge on some fish."},"wigeon":{"id":"wigeon","name":"Wigeon","aliases":["Eurasian wigeon","American wigeon","widgeon","Mareca penelope"],"kind":"creature","group":"seabirds","fact":"The wigeon is a dabbling duck that grazes on eelgrass in estuaries in winter, often alongside brant geese."},"wilhelm-gustloff":{"id":"wilhelm-gustloff","name":"Wilhelm Gustloff","aliases":["MV Wilhelm Gustloff"],"kind":"vessel","group":"wrecks","fact":"The German liner Wilhelm Gustloff was torpedoed in the Baltic in January 1945; with roughly 9,000 dead, it is the deadliest sinking in history."},"william-beebe":{"id":"william-beebe","name":"William Beebe","aliases":[],"kind":"person","group":"people","fact":"William Beebe descended more than 900 metres off Bermuda in the bathysphere in 1934 and was the first scientist to watch deep-sea animals alive in their own world."},"wilsons-storm-petrel":{"id":"wilsons-storm-petrel","name":"Wilson's storm petrel","aliases":["Oceanites oceanicus"],"kind":"creature","group":"seabirds","fact":"Wilson's storm petrel patters across the water on dangling feet, picking krill and oil from the surface, and may be the most numerous wild bird on Earth."},"windowpane-flounder":{"id":"windowpane-flounder","name":"Windowpane flounder","aliases":["Scophthalmus aquosus","windowpane","sand flounder"],"kind":"creature","group":"fish","fact":"The windowpane flounder is so thin that light passes through its body when it is held up to the sun."},"windward-passage":{"id":"windward-passage","name":"Windward Passage","aliases":[],"kind":"place","group":"straits","fact":"The Windward Passage between Cuba and Haiti connects the Atlantic to the Caribbean and is the main shipping route from the US east coast to the Panama Canal."},"winged-kelp":{"id":"winged-kelp","name":"Winged kelp","aliases":["alaria","Alaria esculenta","dabberlocks","Atlantic wakame"],"kind":"plant","group":"plants","fact":"Winged kelp, or alaria, has a long blade with a midrib and is farmed in the North Atlantic and eaten as 'Atlantic wakame'."},"winghead-shark":{"id":"winghead-shark","name":"Winghead shark","aliases":["winghead","Eusphyra blochii"],"kind":"creature","group":"sharks","fact":"The winghead shark has the widest head of any hammerhead, nearly half as wide as the shark is long."},"winter-flounder":{"id":"winter-flounder","name":"Winter flounder","aliases":["blackback flounder","Pseudopleuronectes americanus","black back"],"kind":"creature","group":"fish","fact":"Winter flounder move inshore in winter and carry antifreeze proteins in their blood to survive icy New England waters."},"witch":{"id":"witch","name":"Witch","aliases":["witch flounder","Torbay sole","grey sole","Glyptocephalus cynoglossus","gray sole"],"kind":"creature","group":"fish","fact":"The witch is a long, thin, right-eyed flounder of deep muddy seabeds, sold as Torbay sole in Britain and grey sole in North America."},"wobbegong":{"id":"wobbegong","name":"Wobbegong","aliases":["wobbegong shark","carpet shark","Orectolobidae","spotted wobbegong","tasselled wobbegong"],"kind":"creature","group":"sharks","fact":"Wobbegongs are flattened, carpet-patterned sharks that lie in wait on reefs, with a fringe of skin flaps hiding their mouths."},"wolf-eel":{"id":"wolf-eel","name":"Wolf eel","aliases":["Anarrhichthys ocellatus"],"kind":"creature","group":"fish","fact":"Wolf eel pairs share a den for life, and both parents coil around their egg mass, guarding it for months."},"wolffish":{"id":"wolffish","name":"Wolffish","aliases":["Atlantic wolffish","wolf fish","sea wolf","Anarhichas lupus","seawolf","ocean catfish"],"kind":"creature","group":"fish","fact":"The Atlantic wolffish has a mouthful of fangs for crushing crabs and sea urchins, and makes its own antifreeze to live in near-freezing water."},"wrasse":{"id":"wrasse","name":"Wrasse","aliases":["Labridae"],"kind":"creature","group":"fish","fact":"Many wrasses dive into the sand to sleep at night, and most species start life as females and later change into males."},"wreckfish":{"id":"wreckfish","name":"Wreckfish","aliases":["Atlantic wreckfish","stone bass","Polyprion americanus","bass groper"],"kind":"creature","group":"fish","fact":"The Atlantic wreckfish, or stone bass, is a big deep-water sea bass whose young shelter under floating wreckage and driftwood."},"wunderpus":{"id":"wunderpus","name":"Wunderpus","aliases":["Wunderpus photogenicus","wonderpus","wunderpus octopus"],"kind":"creature","group":"cephalopods","fact":"The wunderpus of Indonesian sand flats has a pattern of white bands so individual that scientists can identify each animal by its markings."},"xenophyophore":{"id":"xenophyophore","name":"Xenophyophore","aliases":["Xenophyophorea"],"kind":"creature","group":"microbes","fact":"Xenophyophores are single cells up to about 10 centimetres across that build mud shells on the seabed, and were found at 10,641 metres in the Mariana Trench."},"xiphactinus":{"id":"xiphactinus","name":"Xiphactinus","aliases":[],"kind":"creature","group":"fish","fact":"Xiphactinus was a 5-metre fanged fish of the Cretaceous, and one famous fossil contains a whole 2-metre fish swallowed just before it died."},"yabby":{"id":"yabby","name":"Yabby","aliases":["common yabby","Cherax destructor"],"kind":"creature","group":"crustaceans","fact":"The yabby of Australian creeks and farm dams digs so deep into mud to survive drought that its scientific name means 'destroyer'."},"yacht":{"id":"yacht","name":"Yacht","aliases":["sailing yacht","motor yacht"],"kind":"vessel","group":"boats","fact":"The word yacht comes from the Dutch 'jacht', meaning hunt, from the fast, light ships once used to chase pirates."},"yamato":{"id":"yamato","name":"Yamato","aliases":["battleship Yamato"],"kind":"vessel","group":"wrecks","fact":"The Yamato, the largest battleship ever built, was sunk by US aircraft in April 1945 and lies in two main pieces about 340 metres down off Kyushu."},"yangtze-finless-porpoise":{"id":"yangtze-finless-porpoise","name":"Yangtze finless porpoise","aliases":["Yangtze porpoise","Neophocaena asiaeorientalis"],"kind":"creature","group":"dolphins","fact":"The Yangtze finless porpoise is the only porpoise that lives entirely in fresh water and numbers only around a thousand."},"yap-trench":{"id":"yap-trench","name":"Yap Trench","aliases":[],"kind":"place","group":"trenches","fact":"The Yap Trench lies south-west of the Mariana Trench near the island of Yap and reaches about 8,500 metres deep."},"yellow-bellied-sea-snake":{"id":"yellow-bellied-sea-snake","name":"Yellow-bellied sea snake","aliases":["pelagic sea snake","yellowbelly sea snake","Hydrophis platurus","Pelamis platura"],"kind":"creature","group":"reptiles","fact":"The yellow-bellied sea snake is the most widespread snake on Earth, drifting across the Pacific and Indian Oceans and never coming ashore."},"yellow-boxfish":{"id":"yellow-boxfish","name":"Yellow boxfish","aliases":["Ostracion cubicus"],"kind":"creature","group":"fish","fact":"Young yellow boxfish are bright yellow cubes with black spots, and Mercedes-Benz modelled a concept car on their boxy shape in 2005."},"yellow-clown-goby":{"id":"yellow-clown-goby","name":"Yellow clown goby","aliases":["clown goby","Okinawa goby","Gobiodon okinawae","yellow coral goby"],"kind":"creature","group":"fish","fact":"The yellow clown goby is a 3.5-centimetre reef fish that lives among the branches of Acropora corals and produces a bitter skin mucus to deter predators."},"yellow-perch":{"id":"yellow-perch","name":"Yellow perch","aliases":["perch","Perca flavescens"],"kind":"creature","group":"fish","fact":"The yellow perch, with its dark vertical bars, is the fish most children in North America catch first from a lake."},"yellow-sea":{"id":"yellow-sea","name":"Yellow Sea","aliases":[],"kind":"place","group":"seas","fact":"The Yellow Sea between China and Korea takes its name from the yellow silt carried into it by the Yellow River."},"yellow-stingray":{"id":"yellow-stingray","name":"Yellow stingray","aliases":["Urobatis jamaicensis"],"kind":"creature","group":"rays","fact":"The yellow stingray is a small, speckled ray of the Caribbean that can change its colour to blend in with the sand."},"yellow-tang":{"id":"yellow-tang","name":"Yellow tang","aliases":["Zebrasoma flavescens"],"kind":"creature","group":"fish","fact":"The yellow tang is a bright lemon-yellow surgeonfish from Hawaii, one of the most popular marine aquarium fish; Hawaii now breeds them in captivity."},"yelloweye-rockfish":{"id":"yelloweye-rockfish","name":"Yelloweye rockfish","aliases":["Sebastes ruberrimus","rasphead rockfish"],"kind":"creature","group":"fish","fact":"The yelloweye rockfish of the North Pacific grows slowly and can live for more than 100 years, which makes it very easy to overfish."},"yellowfin-sole":{"id":"yellowfin-sole","name":"Yellowfin sole","aliases":["Limanda aspera"],"kind":"creature","group":"fish","fact":"The yellowfin sole of the Bering Sea supports the largest flatfish fishery in the world by weight."},"yellowfin-tuna":{"id":"yellowfin-tuna","name":"Yellowfin tuna","aliases":["ahi","Thunnus albacares","yellowfin"],"kind":"creature","group":"fish","fact":"Yellowfin tuna, sold as ahi, is a fast, warm-water tuna with long yellow fins that is the common tuna in poke and sushi outside Japan."},"yellowhead-jawfish":{"id":"yellowhead-jawfish","name":"Yellowhead jawfish","aliases":["jawfish","Opistognathus aurifrons"],"kind":"creature","group":"fish","fact":"The male yellowhead jawfish holds the eggs in his mouth for over a week, spitting them out briefly to turn them, and cannot eat until they hatch."},"yellowmargin-triggerfish":{"id":"yellowmargin-triggerfish","name":"Yellowmargin triggerfish","aliases":["Pseudobalistes flavimarginatus"],"kind":"creature","group":"fish","fact":"The yellowmargin triggerfish digs large nest pits in sand and guards them as fiercely as its cousin the titan triggerfish."},"yellowtail":{"id":"yellowtail","name":"Yellowtail","aliases":["hamachi","buri","Japanese amberjack","Seriola quinqueradiata"],"kind":"creature","group":"fish","fact":"Yellowtail, or hamachi, is a fast-swimming Japanese amberjack farmed in large numbers in Japan and served raw for its buttery flesh."},"yellowtail-amberjack":{"id":"yellowtail-amberjack","name":"Yellowtail amberjack","aliases":["yellowtail","yellowtail kingfish","Seriola lalandi","hiramasa"],"kind":"creature","group":"fish","fact":"The yellowtail amberjack is a prized game fish off California, Baja and Australia and is served as hiramasa in sushi bars, distinct from the Japanese yellowtail sold as hamachi."},"yellowtail-blue-damsel":{"id":"yellowtail-blue-damsel","name":"Yellowtail blue damsel","aliases":["Chrysiptera parasema","goldtail demoiselle","yellowtail damsel","yellowtail blue damselfish"],"kind":"creature","group":"fish","fact":"The yellowtail blue damsel is a deep blue damselfish with a bright yellow tail, one of the most popular and peaceful damselfish for aquariums."},"yellowtail-damselfish":{"id":"yellowtail-damselfish","name":"Yellowtail damselfish","aliases":["jewel damselfish","Microspathodon chrysurus"],"kind":"creature","group":"fish","fact":"The juvenile yellowtail damselfish of the Caribbean is dark blue sprinkled with electric-blue spots, earning it the name jewelfish."},"yellowtail-snapper":{"id":"yellowtail-snapper","name":"Yellowtail snapper","aliases":["Ocyurus chrysurus","Lutjanus chrysurus"],"kind":"creature","group":"fish","fact":"The yellowtail snapper of the Caribbean has a yellow stripe running into a deeply forked yellow tail and often hovers in midwater above the reef."},"yeti-crab":{"id":"yeti-crab","name":"Yeti crab","aliases":["Kiwa hirsuta","Kiwa"],"kind":"creature","group":"crustaceans","fact":"The yeti crab, discovered in 2005 at vents south of Easter Island, has hairy arms coated in bacteria that it is thought to feed on."},"yucatan-channel":{"id":"yucatan-channel","name":"Yucatán Channel","aliases":["Yucatan Strait"],"kind":"place","group":"straits","fact":"The Yucatán Channel between Mexico and Cuba links the Caribbean Sea to the Gulf of Mexico and carries the current that becomes the Gulf Stream."},"zander":{"id":"zander","name":"Zander","aliases":["pikeperch","pike-perch","Sander lucioperca"],"kind":"creature","group":"fish","fact":"The zander is Europe's largest perch relative and lives in rivers, lakes and the brackish Baltic Sea."},"zealandia":{"id":"zealandia","name":"Zealandia","aliases":["Te Riu-a-Māui"],"kind":"place","group":"features","fact":"Zealandia is a continent-sized block of crust around New Zealand of which about 94 percent lies underwater, drowned after it split from Gondwana."},"zebra-moray":{"id":"zebra-moray","name":"Zebra moray","aliases":["Gymnomuraena zebra","zebra moray eel"],"kind":"creature","group":"fish","fact":"The zebra moray, banded in dark brown and white, has flat crushing teeth and feeds almost entirely on crabs and sea urchins."},"zebra-mussel":{"id":"zebra-mussel","name":"Zebra mussel","aliases":["Dreissena polymorpha"],"kind":"creature","group":"molluscs","fact":"Zebra mussels arrived in the Great Lakes in ships' ballast water from the Black and Caspian seas in the 1980s and now clog pipes across North America."},"zebra-pleco":{"id":"zebra-pleco","name":"Zebra pleco","aliases":["Hypancistrus zebra","L046","L-046","imperial pleco"],"kind":"creature","group":"fish","fact":"The zebra pleco, a striking black-and-white striped catfish, lives only in a stretch of Brazil's Xingu River and is threatened by the Belo Monte dam."},"zebra-seahorse":{"id":"zebra-seahorse","name":"Zebra seahorse","aliases":["Hippocampus zebra"],"kind":"creature","group":"fish","fact":"The zebra seahorse, striped black and white, is known only from the waters of northern Australia."},"zebra-shark":{"id":"zebra-shark","name":"Zebra shark","aliases":["Stegostoma tigrinum","Stegostoma fasciatum","leopard shark"],"kind":"creature","group":"sharks","fact":"Zebra sharks are born with dark stripes that break up into leopard-like spots as they grow, so adults are often called leopard sharks in Australia."},"zebra-urchin-crab":{"id":"zebra-urchin-crab","name":"Zebra urchin crab","aliases":["zebra crab","Zebrida adamsii"],"kind":"creature","group":"crustaceans","fact":"The zebra crab lives among the spines of sea urchins, where its bold black and white stripes hide it from predators."},"zebrafish":{"id":"zebrafish","name":"Zebrafish","aliases":["zebra danio","Danio rerio","zebra fish","danio"],"kind":"creature","group":"fish","fact":"The zebrafish, a striped minnow about 3 to 4 centimetres long, is one of science's favourite lab animals because its transparent embryos develop in full view."},"zheng-he":{"id":"zheng-he","name":"Zheng He","aliases":["Cheng Ho"],"kind":"person","group":"people","fact":"Zheng He commanded huge Chinese treasure fleets on seven voyages across the Indian Ocean between 1405 and 1433."},"zombie-worm":{"id":"zombie-worm","name":"Zombie worm","aliases":["Osedax","bone-eating worm","bone worm","bone-eating snot flower"],"kind":"creature","group":"worms","fact":"Zombie worms have no mouth or stomach; they bore roots into whale bones on the seabed and let bacteria digest the fat, and the dwarf males live inside the females."},"zooplankton":{"id":"zooplankton","name":"Zooplankton","aliases":[],"kind":"creature","group":"plankton","fact":"Zooplankton are the animal drifters of the sea, from copepods to jellyfish, and each night they rise towards the surface in the largest migration on Earth."}};
